import React from "react";
import { AutoBind } from "../AutoBind";
import { LogCategory, Logger } from "../Logger";
import { Profiler } from "../Profiler";
import { StateManager } from "./StateManager";

export class ObserveState extends React.Component<{
    key?: string; // RECOMMENDED: Unique identifier to prevent React reconciliation issues
    profilerName?: string; // Optional: Custom name for profiler tracking (defaults to key)
    listenTo: object | null | undefined;
    control: (changedProperties?: string[]) => React.JSX.Element | React.ReactNode;
    properties?: string[];
    shouldRender?: (changedProperties: string[]) => boolean; // Optional: Return false to skip re-render
    onWillUnmount?: () => void;
}, { updateCounter: number }> {
    private lastChangedProperties?: string[];

    constructor(props: any) {
        super(props);
        this.state = { updateCounter: 0 };
    }

    render() {
        const profilerName = this.props.profilerName || this.props.key || 'ObserveState';
        Profiler.Instance.captureStart(`${profilerName}-render`);
        const result = this.props.control(this.lastChangedProperties);
        Profiler.Instance.captureEnd(`${profilerName}-render`);
        return result;
    }

    componentDidMount() {
        if (this.props.listenTo) {
            if (Array.isArray(this.props.listenTo)) {
                // Create detailed error message with array contents
                const arrayContents = (this.props.listenTo as any[])
                    .map((obj, index) => {
                        if (obj === null) return `[${index}]: null`;
                        if (obj === undefined) return `[${index}]: undefined`;
                        const constructorName = obj?.constructor?.name || 'Unknown';
                        const instanceInfo = obj?.Instance ? ` (has .Instance property)` : '';
                        const className = obj?.__proto__?.constructor?.name || constructorName;
                        return `[${index}]: ${className}${instanceInfo}`;
                    })
                    .join(', ');

                const keyInfo = this.props.key ? ` Key: "${this.props.key}"` : ' (missing key prop)';
                const error = `ObserveState.listenTo cannot be an array.${keyInfo} Array contains: ${arrayContents}. Use ObserveMultiState for multiple objects or map array elements individually with ObserveMultiProperties.`;
                Logger.Instance.logError(LogCategory.StateManager, error);
                throw new Error(error);
            }
            StateManager.addObserver(this.props.listenTo, this, this.props.properties || []);
        }
    }

    componentDidUpdate(prevProps: {
        key?: string;
        listenTo: object | null | undefined;
        control: () => React.JSX.Element | React.ReactNode;
        properties?: string[];
        onWillUnmount?: () => void;
    }) {
        if (prevProps.listenTo !== this.props.listenTo) {
            if (prevProps.listenTo) StateManager.removeObserver(prevProps.listenTo, this);

            if (this.props.listenTo) {
                if (Array.isArray(this.props.listenTo)) {
                    const error = 'ObserveState.listenTo cannot be an array. Use ObserveMultiState for multiple objects or map array elements individually with ObserveMultiProperties.';
                    Logger.Instance.logError(LogCategory.StateManager, error);
                    throw new Error(error);
                }
                StateManager.addObserver(this.props.listenTo, this, this.props.properties || []);
            }
        }
    }

    componentWillUnmount() {
        if (this.props.listenTo) StateManager.removeObserver(this.props.listenTo, this);

        if (this.props.onWillUnmount) {
            this.props.onWillUnmount();
        }
    }

    @AutoBind
    updateFromStateManager(changedProperties?: string[]) {
        // Call optional shouldRender to allow component to skip unnecessary re-renders
        if (this.props.shouldRender && !this.props.shouldRender(changedProperties || [])) {
            return; // Skip re-render
        }

        this.lastChangedProperties = changedProperties;
        this.setState(prevState => ({ updateCounter: prevState.updateCounter + 1 }));
        this.forceUpdate();
    }
}
