import { GCodeExecutionCallback, ICNCProgram } from '../machine/ICNCProgram';
import { RunGCodeResponse } from '../machine/Machine';
import { CNCProgramApi } from '../services/src/apis/CNCProgramApi';
import { MachinePoint, RunGCodeCommandRequest, RunGCodeRequest } from '../services/src/models';
import { CoordinateUtil } from '../utils/CoordinateUtil';
import { JobCallbackManager } from '../utils/JobCallbackManager';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';
import { ConfigurationState } from '../data/ConfigurationState';

export class CentroidCNCProgram implements ICNCProgram {
  private readonly api: CNCProgramApi;

  constructor() {
    const config = MachineInterfaceManager.Instance.getServiceConfiguration();
    this.api = new CNCProgramApi(config || undefined);
  }

  async Stop(): Promise<void> {
    try {
      await this.api.apiCNCProgramStopPost();
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to stop program:', error);
      throw error;
    }
  }

  async Resume(): Promise<void> {
    try {
      await this.api.apiCNCProgramResumePost();
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to resume program:', error);
      throw error;
    }
  }

  async ResumeAt(lineNumber: number): Promise<void> {
    try {
      await this.api.apiCNCProgramResumeAtLineNumberPost({ lineNumber });
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to resume at line:', error);
      throw error;
    }
  }

  async GetCurrentGCode(): Promise<string[]> {
    try {
      const response = await this.api.apiCNCProgramGetCurrentGCodeGet();
      return (response as any).data || [];
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get current G-code:', error);
      throw error;
    }
  }

  async GetCurrentLineNumber(): Promise<number> {
    try {
      const response = await this.api.apiCNCProgramGetCurrentLineNumberGet();
      return (response as any).data || 0;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get current line number:', error);
      throw error;
    }
  }

  async RunGCode(gcode: string[], startImmediately: boolean = true, gcodeParameterString?: string, callback?: GCodeExecutionCallback): Promise<void> {
    try {
      // Set command running flag if starting immediately
      if (startImmediately) {
        ConfigurationState.Instance.isCommandRunning = true;
      }

      // Get proposed fixture point from CoordinateUtil (API fixture offset format)
      const proposedFixturePoint = CoordinateUtil.toAPIFixtureOffset();

      // Create MachinePoint for fixture offset
      const fixturePoint: MachinePoint = {
        x: proposedFixturePoint.x,
        y: proposedFixturePoint.y,
        z: proposedFixturePoint.z
      };

      // Create RunGCodeRequest
      const request: RunGCodeRequest = {
        gCodeLines: gcode,
        startImmediately: startImmediately,
        gcodeParameterString: gcodeParameterString,
        fixturePoint: fixturePoint
      };

      const response = await this.api.apiCNCProgramRunGCodePost({
        runGCodeRequest: request
      });

      // Register callback with JobCallbackManager if provided
      if (callback && response.jobId) {
        JobCallbackManager.Instance.registerCallback(response.jobId, callback);
      }

    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to run G-code:', error);

      // Clear command running flag on error
      ConfigurationState.Instance.isCommandRunning = false;

      // Log detailed error information
      if (error && typeof error === 'object') {
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - type:', typeof error);
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - name:', (error as any).name);
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - message:', (error as any).message);
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - status:', (error as any).status);
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - statusText:', (error as any).statusText);
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - response:', (error as any).response);
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - response.status:', (error as any).response?.status);
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - response.statusText:', (error as any).response?.statusText);
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - response.data:', (error as any).response?.data);
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - url:', (error as any).url);
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - config:', (error as any).config);
        Logger.Instance.logError(LogCategory.System, 'RunGCode error - stack:', (error as any).stack);
      }

      throw error;
    }
  }

  async StartStepRun(gcode: string[], gcodeParameterString?: string): Promise<RunGCodeResponse> {
    try {
      const response = await this.api.apiCNCProgramStartStepRunPost({
        requestBody: gcode,
        gcodeParameterString: gcodeParameterString
      });
      return response;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to start step run:', error);
      throw error;
    }
  }

  async EndStepRun(): Promise<void> {
    try {
      await this.api.apiCNCProgramEndStepRunPost();
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to end step run:', error);
      throw error;
    }
  }

  async StepRunNext(): Promise<void> {
    try {
      await this.api.apiCNCProgramStepRunNextPost();
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to execute next step:', error);
      throw error;
    }
  }

  async RunFromCurrentStep(): Promise<void> {
    try {
      await this.api.apiCNCProgramRunFromCurrentStepPost();
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to run from current step:', error);
      throw error;
    }
  }

  async RunGCodeCommand(gcode: string): Promise<void> {
    try {
      // Get proposed fixture point from CoordinateUtil (API fixture offset format)
      const proposedFixturePoint = CoordinateUtil.toAPIFixtureOffset();

      const request: RunGCodeCommandRequest = {
        gCode: gcode,
        fixturePoint: {
          x: proposedFixturePoint.x,
          y: proposedFixturePoint.y,
          z: proposedFixturePoint.z
        }
      };

      await this.api.apiCNCProgramRunGCodeCommandPost({ runGCodeCommandRequest: request });
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to run G-code command:', error);
      throw error;
    }
  }

  async IsJobRunning(): Promise<boolean> {
    try {
      const isRunning = await this.api.apiCNCProgramIsJobRunningGet();
      return isRunning;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to check if job is running:', error);
      throw error;
    }
  }
}