import { Box, Button, Typography } from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { Declaration } from '../data/Declaration';
import { PLCRenderMode, PLCValidationIssue } from '../data/IPLCElement';
import { PLCProgramType, PLCUtilities } from '../data/PLCUtilities';
import { BasePLCStatement } from './BasePLCStatement';
import { DataElementPiece, NewLinePiece, ScriptPiece, TextPiece } from './ScriptPiece';
import { ScriptStatementDialog } from './ScriptStatementDialog';

/**
 * Script Statement - for one-off custom logic
 * Contains a series of text, newline, and data element pieces
 * Used for handling special cases that don't fit standard statement types
 */
export class ScriptStatement extends BasePLCStatement {
    private _pieces: ScriptPiece[] = [];
    private _statementId: string;

    constructor(plcSource?: any) {
        super();
        this._statementId = `script_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        if (plcSource) {
            this._plcSource = plcSource;
        }
        // Start with a single text piece
        this._pieces = [new TextPiece('')];

        // Set up cache invalidation listener
        PLCUtilities.setupCacheInvalidationListener(this);
    }

    /**
     * Get the script pieces
     */
    public get pieces(): ScriptPiece[] {
        return this._pieces;
    }

    /**
     * Set the script pieces
     */
    public set pieces(value: ScriptPiece[]) {
        this._pieces = value;

        // Set parent element for all data element pieces
        for (const piece of this._pieces) {
            if (piece instanceof DataElementPiece) {
                piece.setParentElement(this);
            }
        }

        StateManager.propertyChanged(this, 'pieces');
    }

    /**
     * Get all text as a single string (for display/editing)
     */
    public getFullText(): string {
        return this._pieces.map(p => p.getText()).join('');
    }

    /**
     * Set content from plain text (splits into pieces)
     */
    public setFromText(text: string): void {
        this._pieces = this.parseTextToPieces(text);
        StateManager.propertyChanged(this, 'pieces');
    }

    /**
     * Set content from plain text with auto-matching of declaration names
     * Parses text and automatically inserts DataElementPiece objects where declaration names are found
     */
    public setFromTextWithMatching(text: string): void {
        this._pieces = this.parseTextToPiecesWithMatching(text);
        StateManager.propertyChanged(this, 'pieces');
    }

    /**
     * Parse plain text into script pieces (text and newlines)
     */
    private parseTextToPieces(text: string): ScriptPiece[] {
        const pieces: ScriptPiece[] = [];
        const lines = text.split('\n');

        for (let i = 0; i < lines.length; i++) {
            // Always add text piece, even if empty (to preserve structure)
            pieces.push(new TextPiece(lines[i]));
            // Add newline between lines (but not after the last line)
            if (i < lines.length - 1) {
                pieces.push(new NewLinePiece());
            }
        }

        // If we end up with no pieces, add an empty text piece
        if (pieces.length === 0) {
            pieces.push(new TextPiece(''));
        }

        return pieces;
    }

    /**
     * Parse plain text into script pieces with auto-matching of declaration names
     * Automatically inserts DataElementPiece objects where declaration names are found
     */
    private parseTextToPiecesWithMatching(text: string): ScriptPiece[] {
        if (!this.plcSource) {
            // No PLC source available, fall back to simple parsing
            return this.parseTextToPieces(text);
        }

        const pieces: ScriptPiece[] = [];
        const lines = text.split('\n');

        // Get all available declarations (system + program)
        const allDeclarations = this.plcSource.getAllDeclarations();

        // Build a map of declaration names (case-insensitive) for fast lookup
        // Include both name and displayName for matching
        const declarationMap = new Map<string, Declaration>();
        for (const decl of allDeclarations) {
            if (decl.name) {
                declarationMap.set(decl.name.toLowerCase(), decl);
            }
            if (decl.displayName && decl.displayName !== decl.name) {
                declarationMap.set(decl.displayName.toLowerCase(), decl);
            }
        }

        // Sort declaration names by length (longest first) to match longer names before shorter ones
        // This prevents "myVar" from matching before "myVarLonger"
        const sortedNames = Array.from(declarationMap.keys()).sort((a, b) => b.length - a.length);

        for (let lineIndex = 0; lineIndex < lines.length; lineIndex++) {
            const line = lines[lineIndex];

            // Parse the line and find all declaration matches
            const linePieces = this.parseLineWithMatching(line, sortedNames, declarationMap);
            pieces.push(...linePieces);

            // Add newline between lines (but not after the last line)
            if (lineIndex < lines.length - 1) {
                pieces.push(new NewLinePiece());
            }
        }

        // If we end up with no pieces, add an empty text piece
        if (pieces.length === 0) {
            pieces.push(new TextPiece(''));
        }

        return pieces;
    }

    /**
     * Get all available declarations for auto-matching
     * Returns sorted names (longest first) and declaration map
     */
    public getDeclarationsForMatching(): {
        sortedNames: string[];
        declarationMap: Map<string, Declaration>;
    } {
        if (!this.plcSource) {
            return { sortedNames: [], declarationMap: new Map() };
        }

        // Get all available declarations (system + program)
        const allDeclarations = this.plcSource.getAllDeclarations();

        // Build a map of declaration names (case-insensitive) for fast lookup
        const declarationMap = new Map<string, Declaration>();
        for (const decl of allDeclarations) {
            if (decl.name) {
                declarationMap.set(decl.name.toLowerCase(), decl);
            }
            if (decl.displayName && decl.displayName !== decl.name) {
                declarationMap.set(decl.displayName.toLowerCase(), decl);
            }
        }

        // Sort declaration names by length (longest first)
        const sortedNames = Array.from(declarationMap.keys()).sort((a, b) => b.length - a.length);

        return { sortedNames, declarationMap };
    }

    /**
     * Parse a single line of text and match declaration names
     * Returns an array of TextPiece and DataElementPiece objects
     */
    public parseLineWithMatching(
        line: string,
        sortedNames: string[],
        declarationMap: Map<string, Declaration>
    ): ScriptPiece[] {
        const pieces: ScriptPiece[] = [];
        let remainingText = line;
        let searchOffset = 0;

        while (remainingText.length > 0) {
            let bestMatch: { name: string; index: number; declaration: Declaration } | null = null;

            // Find the earliest match in the remaining text
            for (const declName of sortedNames) {
                const index = remainingText.toLowerCase().indexOf(declName, searchOffset);
                if (index !== -1) {
                    // Check if this match is earlier than our current best match
                    if (!bestMatch || index < bestMatch.index) {
                        const declaration = declarationMap.get(declName);
                        if (declaration) {
                            bestMatch = { name: declName, index, declaration };
                        }
                    }
                }
            }

            if (bestMatch) {
                // Add text before the match (if any)
                if (bestMatch.index > 0) {
                    pieces.push(new TextPiece(remainingText.substring(0, bestMatch.index)));
                }

                // Add the data element piece
                const dataElementPiece = new DataElementPiece();
                dataElementPiece.setParentElement(this);
                dataElementPiece.declaration = bestMatch.declaration;
                pieces.push(dataElementPiece);

                // Move past the match
                remainingText = remainingText.substring(bestMatch.index + bestMatch.name.length);
                searchOffset = 0;
            } else {
                // No more matches, add the remaining text
                pieces.push(new TextPiece(remainingText));
                break;
            }
        }

        // If no pieces were added, add an empty text piece
        if (pieces.length === 0) {
            pieces.push(new TextPiece(''));
        }

        return pieces;
    }

    /**
     * Insert a data element at a specific piece index and text offset
     */
    public insertDataElement(pieceIndex: number, textOffset: number, declaration: Declaration): void {
        if (pieceIndex < 0 || pieceIndex >= this._pieces.length) return;

        const piece = this._pieces[pieceIndex];
        if (!(piece instanceof TextPiece)) return;

        const text = piece.text;
        const beforeText = text.substring(0, textOffset);
        const afterText = text.substring(textOffset);

        const newPieces: ScriptPiece[] = [];

        // Add everything before the insertion point
        for (let i = 0; i < pieceIndex; i++) {
            newPieces.push(this._pieces[i]);
        }

        // Add the split pieces with data element in between
        newPieces.push(new TextPiece(beforeText));
        const dataElementPiece = new DataElementPiece();
        dataElementPiece.setParentElement(this);
        dataElementPiece.declaration = declaration;
        newPieces.push(dataElementPiece);
        newPieces.push(new TextPiece(afterText));

        // Add everything after the insertion point
        for (let i = pieceIndex + 1; i < this._pieces.length; i++) {
            newPieces.push(this._pieces[i]);
        }

        this._pieces = newPieces;
        StateManager.propertyChanged(this, 'pieces');
    }

    /**
     * Remove a piece at the specified index
     */
    public removePiece(index: number): void {
        if (index < 0 || index >= this._pieces.length) return;

        this._pieces.splice(index, 1);

        // Ensure we always have at least one piece
        if (this._pieces.length === 0) {
            this._pieces.push(new TextPiece(''));
        }

        StateManager.propertyChanged(this, 'pieces');
    }

    /**
     * Merge piece at index with previous piece (for backspace at beginning)
     */
    public mergePieceWithPrevious(index: number): void {
        if (index <= 0 || index >= this._pieces.length) return;

        const currentPiece = this._pieces[index];
        const previousPiece = this._pieces[index - 1];

        // Can only merge text pieces
        if (currentPiece instanceof TextPiece && previousPiece instanceof TextPiece) {
            previousPiece.text = previousPiece.text + currentPiece.text;
            this._pieces.splice(index, 1);
            StateManager.propertyChanged(this, 'pieces');
        } else if (previousPiece instanceof NewLinePiece) {
            // Remove the newline
            this._pieces.splice(index - 1, 1);
            StateManager.propertyChanged(this, 'pieces');
        } else if (previousPiece instanceof DataElementPiece) {
            // Remove the data element
            this._pieces.splice(index - 1, 1);
            StateManager.propertyChanged(this, 'pieces');
        }
    }

    /**
     * Convert to PLC code
     */
    public toCode(): string[] {
        const lines: string[] = [];
        let currentLine = '';

        for (const piece of this._pieces) {
            if (piece instanceof NewLinePiece) {
                lines.push(currentLine);
                currentLine = '';
            } else if (piece instanceof TextPiece) {
                currentLine += piece.text;
            } else if (piece instanceof DataElementPiece) {
                // Output the effective name for PLC code
                // effectiveName returns either the declaration name or the reference name
                const effectiveName = piece.dataElement.effectiveName;
                if (effectiveName) {
                    currentLine += effectiveName;
                } else {
                    // No declaration name means variable not selected yet
                    currentLine += '/* missing variable */';
                }
            }
        }

        // Add the last line if there's content
        if (currentLine.length > 0) {
            lines.push(currentLine);
        }

        return lines;
    }

    /**
     * Get a short, single-line description for display in tree views
     * @returns A human-readable summary of the script
     */
    public getShortDescription(): string {
        const text = this.getFullText();
        const preview = text.substring(0, 50);
        return 'Script: ' + (preview || '(empty)') + (text.length > 50 ? '...' : '');
    }

    /**
     * Get human-readable description
     */
    public getDescription(): string {
        const text = this.getFullText();
        const preview = text.substring(0, 50);
        return preview + (text.length > 50 ? '...' : '');
    }

    /**
     * Get unique element ID
     */
    public getElementId(): string {
        return this._statementId;
    }

    /**
     * Validate the statement
     */
    public validate(): string | undefined {
        // Check if we have any content
        if (this._pieces.length === 0) {
            return 'Script statement is empty';
        }

        // Check if all pieces are empty text
        const hasContent = this._pieces.some(p => {
            if (p instanceof TextPiece) {
                return p.text.trim().length > 0;
            }
            return true; // NewLine and DataElement count as content
        });

        if (!hasContent) {
            return 'Script statement is empty';
        }

        // Validate data element references
        for (const piece of this._pieces) {
            if (piece instanceof DataElementPiece) {
                if (!piece.declaration && !piece.declarationName) {
                    return 'Script contains undefined data element reference';
                }
            }
        }

        return undefined;
    }

    /**
     * Get validation issues
     */
    public getValidationIssues(): PLCValidationIssue[] {
        const issues: PLCValidationIssue[] = [];

        const error = this.validate();
        if (error) {
            issues.push(new PLCValidationIssue(this, error));
        }

        // Also collect validation issues from DataElementPieces
        for (const piece of this._pieces) {
            if (piece instanceof DataElementPiece) {
                const pieceIssues = piece.getValidationIssues();
                issues.push(...pieceIssues);
            }
        }

        return issues;
    }

    /**
     * Get declarations added by this statement
     * Returns any inline declarations defined in DataElementPieces
     */
    public getAddedDeclarations(): Declaration[] {
        const declarations: Declaration[] = [];
        for (const piece of this._pieces) {
            if (piece instanceof DataElementPiece) {
                // If piece has an inline declaration (allowNew with embedded declaration object)
                if (piece.declaration) {
                    declarations.push(piece.declaration);
                }
            }
        }
        return declarations;
    }

    /**
     * Get PLC logic code for this statement
     */
    public getPLCLogic(availableDeclarations: string[]): string[] {
        if (this.isDisabled(PLCRenderMode.Edit, PLCProgramType.System)) {
            return [];
        }
        const code = this.toCode();
        return code;
    }

    /**
     * Get all data elements used by this statement
     */
    public getDataElements(): any[] {
        const dataElements: any[] = [];
        for (const piece of this._pieces) {
            if (piece instanceof DataElementPiece) {
                dataElements.push(piece.dataElement);
            }
        }
        return dataElements;
    }

    /**
     * Get used declarations
     */
    public getUsedDeclarations(): Declaration[] {
        const declarations: Declaration[] = [];
        const seen = new Set<string>();

        for (const piece of this._pieces) {
            if (piece instanceof DataElementPiece) {
                // Delegate to DataElementPiece which delegates to DataElement
                const pieceDecls = piece.getUsedDeclarations();
                for (const decl of pieceDecls) {
                    // Deduplicate by name (case-insensitive)
                    const key = decl.name?.toLowerCase();
                    if (key && !seen.has(key)) {
                        seen.add(key);
                        declarations.push(decl);
                    }
                }
            }
        }
        return declarations;
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): any {
        return {
            type: 'ScriptStatement',
            comment: this._comment,
            enabled: this._enabled,
            pieces: this._pieces.map(p => p.toJSON())
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        // Support both old (_comment) and new (comment) formats
        const comment = data.comment !== undefined ? data.comment : data._comment;
        const enabled = data.enabled !== undefined ? data.enabled : data._enabled;

        if (comment !== undefined) this._comment = comment;
        if (enabled !== undefined) this._enabled = enabled;

        if (data.pieces && Array.isArray(data.pieces)) {
            this._pieces = data.pieces
                .map((pieceData: any) => ScriptPiece.fromJSONFactory(pieceData))
                .filter((p: ScriptPiece | undefined): p is ScriptPiece => p !== undefined);

            // Validate deserialization count (comparing filtered result with original array)
            if (this._pieces.length !== data.pieces.length) {
                const error = `ScriptStatement: Expected ${data.pieces.length} pieces but got ${this._pieces.length}`;
                console.error(error, '\nJSON data:', JSON.stringify(data, null, 2));
                throw new Error(error);
            }

            // Resolve declaration references and set parent elements
            for (const piece of this._pieces) {
                if (piece instanceof DataElementPiece) {
                    // Set parent element
                    piece.setParentElement(this);

                    // Resolve declaration reference
                    if (piece.declarationName && !piece.declaration) {
                        const decl = this.plcSource ? PLCUtilities.getDeclarationByName(this.plcSource, piece.declarationName) : undefined;
                        if (decl) {
                            piece.declaration = decl;
                        }
                    }
                }
            }
        }

        if (this._pieces.length === 0) {
            this._pieces = [new TextPiece('')];
        }
    }

    /**
     * Clone the statement
     */
    public clone(): ScriptStatement {
        const cloned = new ScriptStatement(this.plcSource);
        cloned._comment = this._comment;
        cloned._enabled = this._enabled;
        cloned._pieces = this._pieces.map(p => p.clone());
        return cloned;
    }

    /**
     * Render the statement
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        return <ScriptStatementRenderer statement={this} renderMode={mode} targetProgramType={targetProgramType} />;
    }
}

/**
 * Functional component for rendering ScriptStatement with edit link
 */
function ScriptStatementRenderer({ statement, renderMode, targetProgramType }: { statement: ScriptStatement; renderMode?: PLCRenderMode; targetProgramType: PLCProgramType }) {
    const [showDialog, setShowDialog] = useState(false);
    const colors = ConfigurationDataColors.Instance;

    const hasContent = statement.pieces.some(p =>
        p instanceof TextPiece ? p.text.trim().length > 0 : true
    );

    // Determine effective mode: if parent says Disabled or ReadOnly, use that
    // Otherwise, if statement is disabled, use Disabled mode
    let effectiveMode = renderMode || PLCRenderMode.Edit;
    if (renderMode === PLCRenderMode.Edit && statement.isDisabled(renderMode, targetProgramType)) {
        effectiveMode = PLCRenderMode.Disabled;
    }

    const isEditable = effectiveMode === PLCRenderMode.Edit;
    const isDisabled = effectiveMode === PLCRenderMode.Disabled;

    const handleEditScript = () => {
        setShowDialog(true);
    };

    const handleCloseDialog = () => {
        setShowDialog(false);
    };

    const handleSaveDialog = () => {
        StateManager.propertyChanged(statement, 'pieces');
        setShowDialog(false);
    };

    const content = (
        <Box
            sx={{
                display: 'flex',
                alignItems: 'center',
                gap: '50px'
            }}
        >
            <Box
                sx={{
                    fontFamily: 'monospace',
                    fontSize: '0.9em',
                    whiteSpace: 'pre-wrap',
                    wordBreak: 'break-word',
                    lineHeight: 1.5
                }}
            >
                {hasContent ? (
                    <>
                        {statement.pieces.map((piece) => (
                            <React.Fragment key={piece.id}>
                                {piece.render(effectiveMode, targetProgramType)}
                            </React.Fragment>
                        ))}
                    </>
                ) : (
                    <Typography variant="body2" component="span" sx={{ color: 'text.secondary', fontStyle: 'italic' }}>
                        (empty script)
                    </Typography>
                )}
            </Box>
            {isEditable && (
                <Button
                    variant="outlined"
                    size="small"
                    onClick={handleEditScript}
                    sx={{
                        color: colors.infoColor,
                        borderColor: colors.infoColor,
                        textTransform: 'none',
                        fontSize: '12px',
                        minWidth: 'auto',
                        '&:hover': {
                            backgroundColor: `${colors.infoColor}1A`,
                            borderColor: colors.infoColor
                        }
                    }}
                >
                    Edit Script
                </Button>
            )}
        </Box>
    );

    return (
        <>
            {isDisabled ? (
                <div style={{
                    textDecoration: 'line-through',
                    textDecorationLine: 'line-through',
                    opacity: 0.6
                }}>
                    {content}
                </div>
            ) : (
                content
            )}

            {showDialog && (
                <ScriptStatementDialog
                    open={showDialog}
                    statement={statement}
                    onClose={handleCloseDialog}
                    onSave={handleSaveDialog}
                />
            )}
        </>
    );
}
