import { PLCProgram } from '../../centroid/plc/data/PLCProgram';
import { PLCProgramType } from '../../centroid/plc/data/PLCUtilities';
import { StateManager } from '../../utils/statemanager/StateManager';
import { PLCInputName } from '../PLCIONames';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Inputs Checklist Item
 * Manual confirmation + Auto-validation for PLC inputs configuration
 * Validates:
 * 1. At least one input is configured
 * 2. E-Stop (ESTOPOK_I) input exists
 */
export class InputsChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Inputs Configuration',
            'Verify PLC inputs are configured with at least one input and E-Stop defined'
        );

        // Listen for changes to System PLC inputs
        const systemPLC = PLCProgram.Instance(PLCProgramType.System);
        StateManager.addObserver(systemPLC, () => {
            StateManager.propertyChanged(this, 'manuallyConfirmed');
        }, ['inputs']);
    }

    /**
     * This requires manual confirmation
     */
    public needsManualConfirmation(): boolean {
        return true;
    }

    /**
     * Auto-validation check: At least one input AND E-Stop input exists
     */
    public completionCheck(): boolean {
        const systemPLC = PLCProgram.Instance(PLCProgramType.System);

        // Check if there's at least one input
        if (systemPLC.inputs.length === 0) {
            return false;
        }

        // Check if E-Stop input (ESTOPOK_I) exists
        const hasEStop = systemPLC.inputs.some(
            input => input.centroidName === PLCInputName.EStopOk
        );

        return hasEStop;
    }

    public clone(): InputsChecklistItem {
        const cloned = new InputsChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
