import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import {
    Accordion,
    AccordionDetails,
    AccordionSummary,
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    FormControl,
    IconButton,
    InputLabel,
    List,
    ListItemButton,
    ListItemText,
    MenuItem,
    Paper,
    PaperProps,
    Select,
    Stack,
    Tab,
    Tabs,
    TextField,
    ToggleButton,
    ToggleButtonGroup,
    Typography
} from '@mui/material';
import { useEffect, useState } from 'react';
import { SystemIcons } from '../../../SystemIcons';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { LogCategory, Logger } from '../../../utils/Logger';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { DataElement } from './DataElement';
import { DataElementPickerDialogController } from './DataElementPickerDialogController';
import { DataType, Declaration, Visibility } from './Declaration';
import { DeclarationScope, PLCUtilities } from './PLCUtilities';

interface DataElementPickerDialogProps {
    open: boolean;
    onClose: () => void;
    onSelect: (dataElement: DataElement) => void;
    controller: DataElementPickerDialogController;
    allowNew?: boolean;
    requiresType?: DataType;
}

/**
 * Dialog for picking an existing data element or defining a new one
 */
export function DataElementPickerDialog({
    open,
    onClose,
    onSelect,
    controller,
    allowNew = true,
    requiresType
}: DataElementPickerDialogProps) {
    const colors = ConfigurationDataColors.Instance;

    // Get the program from controller
    const program = controller.program;

    // Log warning if program is not found
    if (!program) {
        Logger.Instance.logError(LogCategory.UserInterface, '[DataElementPickerDialog] No program found for data element');
    }

    // Draggable dialog state (keep this as local React state since it's pure UI)
    const [isDragging, setIsDragging] = useState(false);
    const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
    const [position, setPosition] = useState({ x: 0, y: 0 });

    // Helper functions - compute directly without memoization
    const getAllDeclarations = () => {
        if (!program) return [];
        return controller.getFilteredDeclarations();
    };

    const getRootCategories = () => {
        if (!program) return [];
        const categories = PLCUtilities.getRootCategories(program, {
            scope: controller.scope,
            scopeContext: undefined,
            includeHidden: false
        });
        return categories;
    };

    const getFilteredDeclarations = () => {
        return controller.getFilteredDeclarations();
    };

    const getUncategorizedDeclarations = () => {
        const allDeclarations = getAllDeclarations();
        const uncategorized = allDeclarations.filter(d => !d.category || d.category.length === 0);
        return uncategorized;
    };

    // Category tree component that lazy-loads subcategories on expand
    const CategoryTreeNode = ({ categoryPath }: { categoryPath: string[] }) => {
        const [expanded, setExpanded] = useState(false);
        const pathString = categoryPath.join('/');

        // Get subcategories and declarations for this category
        const subCategories = program ? PLCUtilities.getSubCategories(program, pathString, {
            scope: controller.scope,
            scopeContext: undefined,
            includeHidden: false
        }) : [];
        const declarationsInCategory = program ? PLCUtilities.getDeclarationsByCategory(program, pathString, {
            scope: controller.scope,
            scopeContext: undefined,
            requiresType,
            needsWrite: false,
            includeHidden: false
        }) : [];

        // Filter by search
        let filteredDecls = declarationsInCategory;
        if (controller.searchText) {
            const search = controller.searchText.toLowerCase();
            filteredDecls = filteredDecls.filter(d =>
                d.name.toLowerCase().includes(search) ||
                d.description?.toLowerCase().includes(search)
            );
        }

        const hasDeclarations = filteredDecls.length > 0;
        const hasSubCategories = subCategories.length > 0;

        // Don't show if no declarations and no subcategories
        if (!hasDeclarations && !hasSubCategories) {
            return null;
        }

        // Show subcategory count if no direct declarations, otherwise show declaration count
        const countDisplay = hasSubCategories && !hasDeclarations
            ? `${subCategories.length} subcategories`
            : hasSubCategories && hasDeclarations
                ? `${filteredDecls.length} + subcategories`
                : `${filteredDecls.length}`;

        return (
            <Accordion
                disableGutters
                elevation={0}
                expanded={expanded}
                onChange={(_, isExpanded) => setExpanded(isExpanded)}
                sx={{
                    '&:before': { display: 'none' },
                    backgroundColor: 'transparent'
                }}
            >
                <AccordionSummary
                    expandIcon={<ExpandMoreIcon />}
                    sx={{ minHeight: 36, py: 0.5 }}
                >
                    <Typography variant="body2" sx={{ fontSize: '0.875rem', fontWeight: 500 }}>
                        {categoryPath[categoryPath.length - 1]} ({countDisplay})
                    </Typography>
                </AccordionSummary>
                <AccordionDetails sx={{ pl: 2, py: 0.5 }}>
                    <Stack spacing={0.5}>
                        {/* Declarations in this category */}
                        {filteredDecls.length > 0 && (
                            <List dense sx={{ py: 0 }}>
                                {filteredDecls.map((decl, idx) => (
                                    <ListItemButton
                                        key={idx}
                                        onClick={() => handlePickDeclaration(decl)}
                                        sx={{
                                            border: `1px solid ${colors.borderColor}`,
                                            borderRadius: 1,
                                            mb: 0.5,
                                            py: 0.5,
                                            minHeight: 'auto'
                                        }}
                                    >
                                        <ListItemText
                                            primary={decl.name}
                                            secondary={decl.description || `${decl.dataType}`}
                                            primaryTypographyProps={{ variant: 'body2', fontSize: '0.875rem' }}
                                            secondaryTypographyProps={{ variant: 'caption', fontSize: '0.75rem' }}
                                        />
                                    </ListItemButton>
                                ))}
                            </List>
                        )}

                        {/* Subcategories - only render when expanded */}
                        {expanded && subCategories.map(subCat => (
                            <CategoryTreeNode key={subCat} categoryPath={[...categoryPath, subCat]} />
                        ))}
                    </Stack>
                </AccordionDetails>
            </Accordion>
        );
    };

    const handlePickDeclaration = (declaration: Declaration) => {
        controller.selectDeclaration(declaration);
        controller.apply();
        onSelect(controller.dataElement);

        // Invalidate program cache when picking a declaration
        PLCUtilities.invalidateProgramCache();

        onClose();
    };

    const handleDefineNew = () => {
        if (!controller.isValid()) {
            return;
        }

        // Always call apply() to save changes to the declaration
        // This includes name, description, category, dataType, visibility, etc.
        controller.apply();

        onSelect(controller.dataElement);

        // Invalidate program cache when creating/updating a declaration
        PLCUtilities.invalidateProgramCache();

        onClose();
    };

    const handleCancel = () => {
        controller.cancel();
        controller.searchText = '';
        controller.editName = '';
        controller.editCategory = ['User Defined'];
        controller.editDescription = '';
        onClose();
    };

    const handlePickAnother = () => {
        controller.returnToPick();
    };

    // Draggable functionality
    const handleMouseDown = (e: React.MouseEvent) => {
        // Only start dragging if clicking on the title itself, not child buttons
        if ((e.target as HTMLElement).closest('button')) {
            return;
        }
        setIsDragging(true);
        setDragStart({
            x: e.clientX - position.x,
            y: e.clientY - position.y
        });
    };

    const handleMouseMove = (e: MouseEvent) => {
        if (isDragging) {
            setPosition({
                x: e.clientX - dragStart.x,
                y: e.clientY - dragStart.y
            });
        }
    };

    const handleMouseUp = () => {
        setIsDragging(false);
    };

    useEffect(() => {
        if (isDragging) {
            document.addEventListener('mousemove', handleMouseMove);
            document.addEventListener('mouseup', handleMouseUp);
            return () => {
                document.removeEventListener('mousemove', handleMouseMove);
                document.removeEventListener('mouseup', handleMouseUp);
            };
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isDragging]);

    // Reset position when dialog opens
    useEffect(() => {
        if (open) {
            setPosition({ x: 0, y: 0 });
        }
    }, [open]);

    // Custom Paper component for draggable dialog
    const DraggablePaper = (props: PaperProps) => {
        return (
            <Paper
                {...props}
                sx={{
                    ...props.sx,
                    transform: `translate(${position.x}px, ${position.y}px)`,
                    cursor: isDragging ? 'grabbing' : 'default'
                }}
            />
        );
    };

    return (
        <ObserveState
            key="data-element-picker-dialog"
            listenTo={controller}
            properties={['mode', 'tabIndex', 'searchText', 'scope', 'editName', 'editDataType', 'editVisibility', 'editCategory', 'editDescription', 'editIsSetText', 'editIsResetText', 'workingDeclaration']}
            control={() => (
                <Dialog
                    open={open}
                    onClose={handleCancel}
                    maxWidth="md"
                    fullWidth
                    PaperComponent={DraggablePaper}
                    PaperProps={{
                        sx: {
                            height: '90vh',
                            maxHeight: '1000px'
                        }
                    }}
                >
                    <DialogTitle
                        sx={{
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                            backgroundColor: colors.primaryColor,
                            color: colors.lightTextColor,
                            cursor: 'grab',
                            userSelect: 'none',
                            '&:active': {
                                cursor: 'grabbing'
                            }
                        }}
                        onMouseDown={handleMouseDown}
                    >
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            {SystemIcons.layers}
                            <Box>
                                <Typography variant="h6" component="div" sx={{ color: colors.lightTextColor }}>
                                    {controller.mode === 'pick' ? 'Select Data Element' :
                                        controller.mode === 'edit' ? `Edit: ${controller.dataElement.effectiveName}` :
                                            `View: ${controller.dataElement.effectiveName}`}
                                </Typography>
                                <Typography variant="caption" sx={{ color: `${colors.lightTextColor}CC` }}>
                                    {/* Declaration counts removed - use search/filter to find what you need */}
                                </Typography>
                            </Box>
                        </Box>
                        <IconButton
                            onClick={handleCancel}
                            sx={{ color: colors.lightTextColor }}
                        >
                            {SystemIcons.close}
                        </IconButton>
                    </DialogTitle>

                    {controller.mode === 'pick' ? (
                        <Tabs
                            value={controller.tabIndex}
                            onChange={(_, newValue) => controller.tabIndex = newValue}
                            sx={{ borderBottom: 1, borderColor: 'divider', px: 3 }}
                        >
                            <Tab label="Pick Existing" />
                            {allowNew && <Tab label="Define New" />}
                        </Tabs>
                    ) : (
                        <Tabs
                            value={0}
                            sx={{ borderBottom: 1, borderColor: 'divider', px: 3 }}
                        >
                            <Tab label={controller.mode === 'edit' ? 'Edit Declaration' : 'View Declaration'} />
                        </Tabs>
                    )}

                    <DialogContent sx={{ minHeight: 400, display: 'flex', flexDirection: 'column' }}>
                        {controller.mode === 'pick' && controller.tabIndex === 0 && (
                            <Box sx={{ display: 'flex', flexDirection: 'column', flex: 1 }}>
                                {/* Scope Selector */}
                                <Box sx={{ mb: 2 }}>
                                    <Typography variant="caption" color="text.secondary" sx={{ mb: 0.5, display: 'block' }}>
                                        Scope
                                    </Typography>
                                    <ToggleButtonGroup
                                        value={controller.scope}
                                        exclusive
                                        onChange={(_, newScope) => {
                                            if (newScope !== null) {
                                                controller.scope = newScope;
                                            }
                                        }}
                                        size="small"
                                        fullWidth
                                    >
                                        <ToggleButton value={DeclarationScope.All}>
                                            All
                                        </ToggleButton>
                                        <ToggleButton value={DeclarationScope.Program}>
                                            Program
                                        </ToggleButton>
                                        <ToggleButton value={DeclarationScope.Stage}>
                                            Stage
                                        </ToggleButton>
                                        <ToggleButton value={DeclarationScope.Block}>
                                            Block
                                        </ToggleButton>
                                    </ToggleButtonGroup>
                                </Box>

                                {/* Search Field */}
                                <TextField
                                    fullWidth
                                    size="small"
                                    placeholder="Search declarations..."
                                    value={controller.searchText}
                                    onChange={(e) => controller.searchText = e.target.value}
                                    sx={{ mb: 2 }}
                                />

                                {requiresType && (
                                    <Typography variant="caption" color="textSecondary" sx={{ mb: 1, display: 'block' }}>
                                        Filtered to type: {requiresType}
                                    </Typography>
                                )}

                                {/* Declarations Tree/List */}
                                <Box sx={{ flex: 1, overflow: 'auto' }}>
                                    {controller.searchText ? (
                                        // Search mode: Show flat filtered list with category paths
                                        getFilteredDeclarations().length === 0 ? (
                                            <Typography variant="body2" color="textSecondary" sx={{ p: 2, textAlign: 'center' }}>
                                                No declarations found
                                            </Typography>
                                        ) : (
                                            <List dense sx={{ py: 0 }}>
                                                {getFilteredDeclarations().map((decl, idx) => (
                                                    <ListItemButton
                                                        key={idx}
                                                        onClick={() => handlePickDeclaration(decl)}
                                                        sx={{
                                                            border: `1px solid ${colors.borderColor}`,
                                                            borderRadius: 1,
                                                            mb: 0.5,
                                                            py: 0.5,
                                                            minHeight: 'auto'
                                                        }}
                                                    >
                                                        <ListItemText
                                                            primary={decl.name}
                                                            secondary={
                                                                <Stack direction="row" spacing={1}>
                                                                    {decl.category && decl.category.length > 0 && (
                                                                        <Typography variant="caption" color="textSecondary" sx={{ fontSize: '0.75rem' }}>
                                                                            {decl.category.join(' / ')}
                                                                        </Typography>
                                                                    )}
                                                                    <Typography variant="caption" color="textSecondary" sx={{ fontSize: '0.75rem' }}>
                                                                        {decl.description || decl.dataType}
                                                                    </Typography>
                                                                </Stack>
                                                            }
                                                            primaryTypographyProps={{ variant: 'body2', fontSize: '0.875rem' }}
                                                        />
                                                    </ListItemButton>
                                                ))}
                                            </List>
                                        )
                                    ) : (
                                        // Browse mode: Show tree structure
                                        getRootCategories().length === 0 && getUncategorizedDeclarations().length === 0 ? (
                                            <Typography variant="body2" color="textSecondary" sx={{ p: 2, textAlign: 'center' }}>
                                                No declarations found
                                            </Typography>
                                        ) : (
                                            <Stack spacing={0.5}>
                                                {/* Categorized declarations */}
                                                {getRootCategories().map(rootCat => (
                                                    <CategoryTreeNode key={rootCat} categoryPath={[rootCat]} />
                                                ))}

                                                {/* Uncategorized declarations */}
                                                {getUncategorizedDeclarations().length > 0 && (
                                                    <Accordion disableGutters elevation={0}>
                                                        <AccordionSummary
                                                            expandIcon={<ExpandMoreIcon />}
                                                            sx={{ minHeight: 36, py: 0.5 }}
                                                        >
                                                            <Typography variant="body2" sx={{ fontSize: '0.875rem', fontWeight: 500 }}>
                                                                Uncategorized ({getUncategorizedDeclarations().length})
                                                            </Typography>
                                                        </AccordionSummary>
                                                        <AccordionDetails sx={{ py: 0.5 }}>
                                                            <List dense sx={{ py: 0 }}>
                                                                {getUncategorizedDeclarations().map((decl, idx) => (
                                                                    <ListItemButton
                                                                        key={idx}
                                                                        onClick={() => handlePickDeclaration(decl)}
                                                                        sx={{
                                                                            border: `1px solid ${colors.borderColor}`,
                                                                            borderRadius: 1,
                                                                            mb: 0.5,
                                                                            py: 0.5,
                                                                            minHeight: 'auto'
                                                                        }}
                                                                    >
                                                                        <ListItemText
                                                                            primary={decl.name}
                                                                            secondary={decl.description || `${decl.dataType}`}
                                                                            primaryTypographyProps={{ variant: 'body2', fontSize: '0.875rem' }}
                                                                            secondaryTypographyProps={{ variant: 'caption', fontSize: '0.75rem' }}
                                                                        />
                                                                    </ListItemButton>
                                                                ))}
                                                            </List>
                                                        </AccordionDetails>
                                                    </Accordion>
                                                )}
                                            </Stack>
                                        )
                                    )}
                                </Box>
                            </Box>
                        )}

                        {controller.mode === 'pick' && controller.tabIndex === 1 && allowNew && (
                            <Box sx={{ pt: 2 }}>
                                <Stack spacing={2}>
                                    <TextField
                                        fullWidth
                                        label="Name"
                                        value={controller.editName}
                                        onChange={(e) => controller.editName = e.target.value}
                                        placeholder="Enter variable name"
                                        required
                                    />

                                    <FormControl fullWidth>
                                        <InputLabel>Data Type</InputLabel>
                                        <Select
                                            value={controller.editDataType}
                                            label="Data Type"
                                            onChange={(e) => controller.editDataType = e.target.value as DataType}
                                            disabled={requiresType !== undefined}
                                        >
                                            <MenuItem value={DataType.MemoryBit}>Memory Bit</MenuItem>
                                            <MenuItem value={DataType.Word}>Word</MenuItem>
                                            <MenuItem value={DataType.DoubleWord}>Double Word</MenuItem>
                                            <MenuItem value={DataType.FloatingPointWord}>Floating-point Word</MenuItem>
                                        </Select>
                                    </FormControl>

                                    <FormControl fullWidth>
                                        <InputLabel>Visibility</InputLabel>
                                        <Select
                                            value={controller.editVisibility}
                                            label="Visibility"
                                            onChange={(e) => controller.editVisibility = e.target.value as Visibility}
                                        >
                                            <MenuItem value={Visibility.Hidden}>Hidden</MenuItem>
                                            <MenuItem value={Visibility.Visible}>Visible</MenuItem>
                                            <MenuItem value={Visibility.Block}>Block</MenuItem>
                                        </Select>
                                    </FormControl>

                                    <TextField
                                        fullWidth
                                        label="Category"
                                        value={controller.editCategory.join('\n')}
                                        onChange={(e) => controller.editCategory = e.target.value.split('\n')}
                                        placeholder="One category per line"
                                        helperText="Enter one category per line (e.g., 'User Defined' or 'My Variables/Counters')"
                                        multiline
                                        rows={2}
                                    />

                                    <TextField
                                        fullWidth
                                        label="Description"
                                        value={controller.editDescription}
                                        onChange={(e) => controller.editDescription = e.target.value}
                                        placeholder="Optional description"
                                        multiline
                                        rows={2}
                                    />

                                    {controller.editDataType === DataType.MemoryBit && (
                                        <>
                                            <TextField
                                                fullWidth
                                                label="Set Text"
                                                value={controller.editIsSetText}
                                                onChange={(e) => controller.editIsSetText = e.target.value}
                                                placeholder="Text when set/true"
                                                helperText="Text to display when the memory bit is set (active/true)"
                                            />
                                            <TextField
                                                fullWidth
                                                label="Reset Text"
                                                value={controller.editIsResetText}
                                                onChange={(e) => controller.editIsResetText = e.target.value}
                                                placeholder="Text when reset/false"
                                                helperText="Text to display when the memory bit is reset (inactive/false)"
                                            />
                                        </>
                                    )}
                                </Stack>
                            </Box>
                        )}

                        {controller.mode === 'edit' && (
                            <Box sx={{ pt: 2 }}>
                                <Stack spacing={2}>
                                    <TextField
                                        fullWidth
                                        label="Name"
                                        value={controller.editName}
                                        onChange={(e) => controller.editName = e.target.value}
                                        required
                                    />

                                    <FormControl fullWidth>
                                        <InputLabel>Data Type</InputLabel>
                                        <Select
                                            value={controller.editDataType}
                                            label="Data Type"
                                            onChange={(e) => controller.editDataType = e.target.value as DataType}
                                        >
                                            <MenuItem value={DataType.MemoryBit}>Memory Bit</MenuItem>
                                            <MenuItem value={DataType.Word}>Word</MenuItem>
                                            <MenuItem value={DataType.DoubleWord}>Double Word</MenuItem>
                                            <MenuItem value={DataType.FloatingPointWord}>Floating-point Word</MenuItem>
                                        </Select>
                                    </FormControl>

                                    <FormControl fullWidth>
                                        <InputLabel>Visibility</InputLabel>
                                        <Select
                                            value={controller.editVisibility}
                                            label="Visibility"
                                            onChange={(e) => controller.editVisibility = e.target.value as Visibility}
                                        >
                                            <MenuItem value={Visibility.Hidden}>Hidden</MenuItem>
                                            <MenuItem value={Visibility.Visible}>Visible</MenuItem>
                                            <MenuItem value={Visibility.Block}>Block</MenuItem>
                                        </Select>
                                    </FormControl>

                                    <TextField
                                        fullWidth
                                        label="Category"
                                        value={controller.editCategory.join('\n')}
                                        onChange={(e) => controller.editCategory = e.target.value.split('\n')}
                                        placeholder="One category per line"
                                        helperText="Enter one category per line (e.g., 'User Defined' or 'My Variables/Counters')"
                                        multiline
                                        rows={2}
                                    />

                                    <TextField
                                        fullWidth
                                        label="Description"
                                        value={controller.editDescription}
                                        onChange={(e) => controller.editDescription = e.target.value}
                                        placeholder="Optional description"
                                        multiline
                                        rows={2}
                                    />

                                    {controller.editDataType === DataType.MemoryBit && (
                                        <>
                                            <TextField
                                                fullWidth
                                                label="Set Text"
                                                value={controller.editIsSetText}
                                                onChange={(e) => controller.editIsSetText = e.target.value}
                                                placeholder="Text when set/true"
                                                helperText="Text to display when the memory bit is set (active/true)"
                                            />
                                            <TextField
                                                fullWidth
                                                label="Reset Text"
                                                value={controller.editIsResetText}
                                                onChange={(e) => controller.editIsResetText = e.target.value}
                                                placeholder="Text when reset/false"
                                                helperText="Text to display when the memory bit is reset (inactive/false)"
                                            />
                                        </>
                                    )}
                                </Stack>
                            </Box>
                        )}

                        {controller.mode === 'display' && controller.workingDeclaration && (
                            <Box sx={{ pt: 2 }}>
                                <Stack spacing={2}>
                                    <Box>
                                        <Typography variant="caption" color="text.secondary">Name</Typography>
                                        <Typography variant="body1">{controller.workingDeclaration.name}</Typography>
                                    </Box>

                                    <Box>
                                        <Typography variant="caption" color="text.secondary">Data Type</Typography>
                                        <Typography variant="body1">{controller.workingDeclaration.dataType}</Typography>
                                    </Box>

                                    <Box>
                                        <Typography variant="caption" color="text.secondary">Visibility</Typography>
                                        <Typography variant="body1">{controller.workingDeclaration.visibility}</Typography>
                                    </Box>

                                    {controller.workingDeclaration.category && controller.workingDeclaration.category.length > 0 && (
                                        <Box>
                                            <Typography variant="caption" color="text.secondary">Category</Typography>
                                            <Typography variant="body1">{controller.workingDeclaration.category.join(' > ')}</Typography>
                                        </Box>
                                    )}

                                    {controller.workingDeclaration.description && (
                                        <Box>
                                            <Typography variant="caption" color="text.secondary">Description</Typography>
                                            <Typography variant="body1">{controller.workingDeclaration.description}</Typography>
                                        </Box>
                                    )}

                                    {controller.workingDeclaration.dataType === DataType.MemoryBit && (
                                        <>
                                            <Box>
                                                <Typography variant="caption" color="text.secondary">Set Text</Typography>
                                                <Typography variant="body1">{controller.workingDeclaration.isSetText}</Typography>
                                            </Box>
                                            <Box>
                                                <Typography variant="caption" color="text.secondary">Reset Text</Typography>
                                                <Typography variant="body1">{controller.workingDeclaration.isResetText}</Typography>
                                            </Box>
                                        </>
                                    )}
                                </Stack>
                            </Box>
                        )}
                    </DialogContent>

                    <DialogActions>
                        {controller.mode !== 'pick' && (
                            <Button
                                onClick={handlePickAnother}
                                variant="contained"
                                sx={{
                                    backgroundColor: colors.primaryColor,
                                    mr: 'auto'
                                }}
                            >
                                Pick Another
                            </Button>
                        )}
                        <Button onClick={handleCancel}>Cancel</Button>
                        {controller.mode === 'pick' ? (
                            <>
                                {controller.tabIndex === 1 && (
                                    <Button
                                        onClick={handleDefineNew}
                                        variant="contained"
                                        disabled={!controller.isValid()}
                                        sx={{ backgroundColor: colors.primaryColor }}
                                    >
                                        Create Declaration
                                    </Button>
                                )}
                            </>
                        ) : controller.mode === 'edit' ? (
                            <Button
                                onClick={handleDefineNew}
                                variant="contained"
                                disabled={!controller.isValid()}
                                sx={{ backgroundColor: colors.primaryColor }}
                            >
                                Save Changes
                            </Button>
                        ) : null}
                    </DialogActions>
                </Dialog>
            )}
        />
    );
}
