import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for Homing configuration
 * Requires manual confirmation that homing is properly configured
 */
export class HomingChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Homing Configuration',
            'Confirm homing directions and speeds are properly configured'
        );
    }

    public needsManualConfirmation(): boolean {
        return true; // Requires manual confirmation
    }

    public completionCheck(): boolean {
        // Always requires manual confirmation
        return true;
    }

    public clone(): HomingChecklistItem {
        const cloned = new HomingChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
