import { Transform as FixtureIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { FixtureSelectionDialog } from '../../components/Common/FixtureSelectionDialog';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { ModalManager } from '../ModalManager';
import { ObserveState } from '../statemanager/ObserveState';
import { IUserAction } from './IUserAction';

export class ChangeFixtureUserAction implements IUserAction {
    public readonly id = 'home_page_change_fixture';
    public readonly category = 'Machine Actions';
    public readonly isDefaultHomeAction = true;

    public isAvailable(): boolean {
        const config = ConfigurationState.Instance;
        return config.isHomed && !config.isJobRunning;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        return (
            <ObserveState
                key="change-fixture-user-action"
                listenTo={MachineStateData.Instance}
                properties={['currentFixtureNumber', 'currentWorkZero']}
                control={() => {
                    const machineState = MachineStateData.Instance;
                    const fixtureNumber = machineState.currentFixtureNumber || 'None';
                    const isCustom = machineState.isWorkZeroCustom();
                    const displayText = isCustom ? 'Custom' : fixtureNumber;

                    if (asLink) {
                        return (
                            <React.Fragment>
                                <FixtureIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                                <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                                    Use WCS ({displayText})
                                </Typography>
                            </React.Fragment>
                        );
                    } else {
                        return (
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <FixtureIcon />
                                <Typography>Use WCS ({displayText})</Typography>
                            </Box>
                        );
                    }
                }}
            />
        );
    }

    public run(): void {
        const modalId = 'fixture-selection-dialog';
        ModalManager.Instance.showModal({
            id: modalId,
            render: () => {
                return (
                    <FixtureSelectionDialog
                        open
                        onClose={() => {
                            ModalManager.Instance.closeModal(modalId);
                        }}
                    />
                );
            }
        });
    }
}
