import {
    Box,
    Button,
    Divider,
    Link,
    Menu,
    MenuItem,
    Typography
} from '@mui/material';
import { useEffect, useRef, useState } from 'react';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { LogicStructureDialog } from '../../../components/PLC/LogicStructureDialog';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { TooltipManager } from '../../../utils/TooltipManager';
import { PLCRenderMode } from '../data/IPLCElement';
import { PLCProgramType } from '../data/PLCUtilities';
import { BasePLCPredicate } from '../predicates/BasePLCPredicate';
import { PredicateType, PredicateUtilities } from '../predicates/PredicateUtilities';
import { LogicStatement } from '../statements/LogicStatement';
import { ConditionGroupEditor } from './ConditionGroupEditor';

interface LogicStatementEditorProps {
    logicStatement: LogicStatement;
    onChanged?: () => void;
    renderMode?: PLCRenderMode;
    targetProgramType: PLCProgramType;  // REQUIRED: Which program context we're rendering in (System vs SystemDefault UI)
}

/**
 * LogicStatementEditor - UI component for editing logic statements
 * Code-like minimal UI: if ( [conditions] ) then { [actions] }
 */
export function LogicStatementEditor(props: LogicStatementEditorProps) {
    const { logicStatement, onChanged, renderMode = PLCRenderMode.Edit, targetProgramType } = props;
    const [addPredicateMenuAnchor, setAddPredicateMenuAnchor] = useState<null | HTMLElement>(null);
    const [addElsePredicateMenuAnchor, setAddElsePredicateMenuAnchor] = useState<null | HTMLElement>(null);
    const [addNestedIfThenMenuAnchor, setAddNestedIfThenMenuAnchor] = useState<null | HTMLElement>(null);
    const [addNestedIfElseMenuAnchor, setAddNestedIfElseMenuAnchor] = useState<null | HTMLElement>(null);
    const [addNestedElseThenMenuAnchor, setAddNestedElseThenMenuAnchor] = useState<null | HTMLElement>(null);
    const [addNestedElseElseMenuAnchor, setAddNestedElseElseMenuAnchor] = useState<null | HTMLElement>(null);
    const [structureDialogOpen, setStructureDialogOpen] = useState(false);
    const anchorRef = useRef<HTMLElement | null>(null);
    const menuCloseTimeoutRef = useRef<NodeJS.Timeout | null>(null);
    const colors = ConfigurationDataColors.Instance;

    const isDisabled = renderMode === PLCRenderMode.Disabled;
    const isEditable = renderMode === PLCRenderMode.Edit;

    // Cleanup timeout on unmount
    useEffect(() => {
        return () => {
            if (menuCloseTimeoutRef.current) {
                clearTimeout(menuCloseTimeoutRef.current);
            }
        };
    }, []);

    const scheduleMenuClose = (setMenuAnchor: (anchor: null | HTMLElement) => void) => {
        // Clear any existing timeout
        if (menuCloseTimeoutRef.current) {
            clearTimeout(menuCloseTimeoutRef.current);
        }
        // Schedule close after delay
        menuCloseTimeoutRef.current = setTimeout(() => {
            setMenuAnchor(null);
        }, 300);
    };

    const cancelMenuClose = () => {
        if (menuCloseTimeoutRef.current) {
            clearTimeout(menuCloseTimeoutRef.current);
            menuCloseTimeoutRef.current = null;
        }
    };

    const handleConditionChanged = () => {
        onChanged?.();
    };

    const handleAddPredicate = (predicateType: PredicateType) => {
        // Create predicate based on type
        let newPredicate: BasePLCPredicate | null = null;

        // Get predicate type info to determine if it can be created
        const predicateTypes = PredicateUtilities.getPredicateTypes();
        const typeInfo = predicateTypes.find(pt => pt.type === predicateType);

        if (typeInfo) {
            // Use PredicateUtilities factory to create the predicate
            try {
                newPredicate = PredicateUtilities.createPredicate(predicateType);
            } catch (error) {
                console.warn(`Predicate type ${predicateType} not yet implemented for creation:`, error);
            }
        }

        if (newPredicate) {
            logicStatement.addPredicate(newPredicate);
            onChanged?.();
        }

        setAddPredicateMenuAnchor(null);
    };

    const handleRemovePredicate = (predicate: BasePLCPredicate) => {
        logicStatement.removePredicate(predicate);
        onChanged?.();
    };

    const handleMovePredicateUp = (predicate: BasePLCPredicate) => {
        const index = logicStatement.predicates.indexOf(predicate);
        if (index > 0) {
            logicStatement.predicates.splice(index, 1);
            logicStatement.predicates.splice(index - 1, 0, predicate);
            StateManager.propertyChanged(logicStatement, 'predicates');
            onChanged?.();
        }
    };

    const handleMovePredicateDown = (predicate: BasePLCPredicate) => {
        const index = logicStatement.predicates.indexOf(predicate);
        if (index >= 0 && index < logicStatement.predicates.length - 1) {
            logicStatement.predicates.splice(index, 1);
            logicStatement.predicates.splice(index + 1, 0, predicate);
            StateManager.propertyChanged(logicStatement, 'predicates');
            onChanged?.();
        }
    };

    const handleAddElsePredicate = (predicateType: PredicateType) => {
        // Create predicate based on type
        let newPredicate: BasePLCPredicate | null = null;

        // Get predicate type info to determine if it can be created
        const predicateTypes = PredicateUtilities.getPredicateTypes();
        const typeInfo = predicateTypes.find(pt => pt.type === predicateType);

        if (typeInfo) {
            // Use PredicateUtilities factory to create the predicate
            try {
                newPredicate = PredicateUtilities.createPredicate(predicateType);
            } catch (error) {
                console.warn(`Predicate type ${predicateType} not yet implemented for creation:`, error);
            }
        }

        if (newPredicate) {
            logicStatement.addElsePredicate(newPredicate);
            onChanged?.();
        }

        setAddElsePredicateMenuAnchor(null);
    };

    const handleRemoveElsePredicate = (predicate: BasePLCPredicate) => {
        logicStatement.removeElsePredicate(predicate);
        onChanged?.();
    };

    // ==================== Nested IF Handlers ====================

    const handleAddNestedIfThenPredicate = (predicateType: PredicateType) => {
        const newPredicate = PredicateUtilities.createPredicate(predicateType);
        if (newPredicate) {
            logicStatement.addNestedIfThenPredicate(newPredicate);
            onChanged?.();
        }
        setAddNestedIfThenMenuAnchor(null);
    };

    const handleRemoveNestedIfThenPredicate = (predicate: BasePLCPredicate) => {
        logicStatement.removeNestedIfThenPredicate(predicate);
        onChanged?.();
    };

    const handleAddNestedIfElsePredicate = (predicateType: PredicateType) => {
        const newPredicate = PredicateUtilities.createPredicate(predicateType);
        if (newPredicate) {
            logicStatement.addNestedIfElsePredicate(newPredicate);
            onChanged?.();
        }
        setAddNestedIfElseMenuAnchor(null);
    };

    const handleRemoveNestedIfElsePredicate = (predicate: BasePLCPredicate) => {
        logicStatement.removeNestedIfElsePredicate(predicate);
        onChanged?.();
    };

    // ==================== Nested ELSE Handlers ====================

    const handleAddNestedElseThenPredicate = (predicateType: PredicateType) => {
        const newPredicate = PredicateUtilities.createPredicate(predicateType);
        if (newPredicate) {
            logicStatement.addNestedElseThenPredicate(newPredicate);
            onChanged?.();
        }
        setAddNestedElseThenMenuAnchor(null);
    };

    const handleRemoveNestedElseThenPredicate = (predicate: BasePLCPredicate) => {
        logicStatement.removeNestedElseThenPredicate(predicate);
        onChanged?.();
    };

    const handleAddNestedElseElsePredicate = (predicateType: PredicateType) => {
        const newPredicate = PredicateUtilities.createPredicate(predicateType);
        if (newPredicate) {
            logicStatement.addNestedElseElsePredicate(newPredicate);
            onChanged?.();
        }
        setAddNestedElseElseMenuAnchor(null);
    };

    const handleRemoveNestedElseElsePredicate = (predicate: BasePLCPredicate) => {
        logicStatement.removeNestedElseElsePredicate(predicate);
        onChanged?.();
    };

    // Get available predicate types for the menu
    const availablePredicateTypes = PredicateUtilities.getPredicateTypes();

    // Helper to check if all predicates in an array are disabled
    const areAllPredicatesDisabled = (predicates: BasePLCPredicate[]): boolean => {
        if (predicates.length === 0) return false;
        return predicates.every(p => p.isDisabled(PLCRenderMode.Edit, targetProgramType));
    };

    // Helper to check if entire nested IF is disabled (all predicates in THEN and ELSE branches are disabled)
    const isNestedIfDisabled = (): boolean => {
        if (!logicStatement.hasNestedIf) return false;

        // If nested IF condition itself is disabled, the whole thing is disabled
        if (logicStatement.nestedIfCondition?.isDisabled(PLCRenderMode.Edit, targetProgramType)) return true;

        // Check THEN branch
        const thenDisabled = logicStatement.nestedIfThenPredicates.length > 0 &&
            areAllPredicatesDisabled(logicStatement.nestedIfThenPredicates);

        // If no ELSE, just check THEN
        if (!logicStatement.hasNestedIfElse) {
            return thenDisabled;
        }

        // If has ELSE, both THEN and ELSE must be all disabled
        const elseDisabled = logicStatement.nestedIfElsePredicates.length > 0 &&
            areAllPredicatesDisabled(logicStatement.nestedIfElsePredicates);

        return thenDisabled && elseDisabled;
    };

    // Helper to check if entire nested ELSE is disabled (all predicates in THEN and ELSE branches are disabled)
    const isNestedElseDisabled = (): boolean => {
        if (!logicStatement.hasNestedElse) return false;

        // If nested ELSE condition itself is disabled, the whole thing is disabled
        if (logicStatement.nestedElseCondition?.isDisabled(PLCRenderMode.Edit, targetProgramType)) return true;

        // Check THEN branch
        const thenDisabled = logicStatement.nestedElseThenPredicates.length > 0 &&
            areAllPredicatesDisabled(logicStatement.nestedElseThenPredicates);

        // If no ELSE, just check THEN
        if (!logicStatement.hasNestedElseElse) {
            return thenDisabled;
        }

        // If has ELSE, both THEN and ELSE must be all disabled
        const elseDisabled = logicStatement.nestedElseElsePredicates.length > 0 &&
            areAllPredicatesDisabled(logicStatement.nestedElseElsePredicates);

        return thenDisabled && elseDisabled;
    };

    // Style for disabled mode - strikethrough text and reduced opacity
    // Use textDecorationLine which is harder to override than textDecoration
    const containerStyle = isDisabled ? {
        opacity: 0.6,
        textDecorationLine: 'line-through',
        '& *, & *::before, & *::after': {
            textDecorationLine: 'line-through !important',
            textDecoration: 'line-through !important'
        }
    } : {};

    // Helper to render a predicate section (THEN/ELSE/nested)
    const renderPredicateSection = (
        predicates: BasePLCPredicate[],
        onAddPredicate: (type: PredicateType) => void,
        onRemovePredicate: (p: BasePLCPredicate) => void,
        addMenuAnchor: HTMLElement | null,
        setAddMenuAnchor: (anchor: HTMLElement | null) => void,
        emptyText: string = "+ Add Action",
        parentConditionDisabled: boolean = false
    ) => {
        if (predicates.length === 0) {
            return (
                <Button
                    size="small"
                    onClick={(e) => {
                        setAddMenuAnchor(e.currentTarget);
                    }}
                    sx={{
                        color: colors.mutedTextColor,
                        fontStyle: 'italic',
                        fontSize: '14px',
                        textTransform: 'none',
                        minHeight: '28px',
                        alignSelf: 'flex-start',
                        '&:hover': {
                            color: colors.primaryColor,
                            backgroundColor: `${colors.primaryColor}10`
                        }
                    }}
                >
                    {emptyText}
                </Button>
            );
        }

        return (
            <Box>
                {predicates.map((predicate, index) => (
                    <Box
                        key={index}
                        onMouseDown={(e) => {
                            const target = e.target as HTMLElement;
                            if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.closest('button')) {
                                TooltipManager.Instance.hideTooltip();
                            }
                        }}
                        onMouseEnter={(e) => {
                            if (isEditable) {
                                anchorRef.current = e.currentTarget;
                                const rect = e.currentTarget.getBoundingClientRect();
                                const predicateTypeName = predicate.constructor.name.replace('Predicate', '');
                                TooltipManager.Instance.showTooltip(
                                    <Box sx={{
                                        display: 'flex',
                                        flexDirection: 'column',
                                        minWidth: 150,
                                        bgcolor: 'background.paper',
                                        borderRadius: 1,
                                        boxShadow: 2,
                                        border: `1px solid ${colors.borderColor}`
                                    }}>
                                        <MenuItem
                                            onClick={() => {
                                                if (anchorRef.current) {
                                                    setAddMenuAnchor(anchorRef.current);
                                                    TooltipManager.Instance.hideTooltip();
                                                }
                                            }}
                                            sx={{
                                                py: 1,
                                                px: 2,
                                                fontSize: '14px',
                                                '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                            }}
                                        >
                                            Add Action
                                        </MenuItem>
                                        <MenuItem
                                            onClick={() => {
                                                onRemovePredicate(predicate);
                                                TooltipManager.Instance.hideTooltip();
                                            }}
                                            sx={{
                                                py: 1,
                                                px: 2,
                                                fontSize: '14px',
                                                color: 'error.main',
                                                '&:hover': {
                                                    backgroundColor: 'error.main',
                                                    color: colors.lightTextColor
                                                }
                                            }}
                                        >
                                            Delete {predicateTypeName}
                                        </MenuItem>
                                        <Divider />
                                        <MenuItem
                                            onClick={() => {
                                                handleMovePredicateUp(predicate);
                                                TooltipManager.Instance.hideTooltip();
                                            }}
                                            disabled={logicStatement.predicates.indexOf(predicate) === 0}
                                            sx={{
                                                py: 1,
                                                px: 2,
                                                fontSize: '14px',
                                                '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                            }}
                                        >
                                            Move Up
                                        </MenuItem>
                                        <MenuItem
                                            onClick={() => {
                                                handleMovePredicateDown(predicate);
                                                TooltipManager.Instance.hideTooltip();
                                            }}
                                            disabled={logicStatement.predicates.indexOf(predicate) === logicStatement.predicates.length - 1}
                                            sx={{
                                                py: 1,
                                                px: 2,
                                                fontSize: '14px',
                                                '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                            }}
                                        >
                                            Move Down
                                        </MenuItem>
                                    </Box>,
                                    { top: rect.top, left: rect.right + 5 }
                                );
                            }
                        }}
                        onMouseLeave={() => {
                            if (isEditable) {
                                TooltipManager.Instance.hideTooltipWithDelay(300);
                            }
                        }}
                        sx={{
                            mb: 0.5,
                            '&:hover': isEditable ? {
                                backgroundColor: `${colors.primaryColor}10`,
                                borderRadius: 1
                            } : {}
                        }}
                    >
                        {predicate.render(parentConditionDisabled ? PLCRenderMode.Disabled : renderMode, targetProgramType)}
                    </Box>
                ))}
            </Box>
        );
    };

    return (
        <ObserveState
            key="logic-statement-editor"
            listenTo={logicStatement}
            properties={['conditionGroup', 'predicates', 'hasElse', 'elsePredicates', 'hasNestedIf', 'nestedIfCondition', 'nestedIfThenPredicates', 'hasNestedIfElse', 'nestedIfElsePredicates', 'hasNestedElse', 'nestedElseCondition', 'nestedElseThenPredicates', 'hasNestedElseElse', 'nestedElseElsePredicates', 'hideSimpleActions', 'hideElseActions']}
            control={() => (
                <Box sx={{ fontFamily: 'monospace', fontSize: '14px', py: 1, ...containerStyle }}>
                    {/* IF ( condition ) with Configure Structure button */}
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Typography sx={{
                            color: colors.primaryColor,
                            fontWeight: 'bold',
                            fontFamily: 'monospace',
                            width: '45px',
                            textDecoration: (logicStatement.conditionGroup?.isDisabled(PLCRenderMode.Edit, targetProgramType)) ? 'line-through' : 'none'
                        }}>
                            if
                        </Typography>
                        <ConditionGroupEditor
                            conditionGroup={logicStatement.conditionGroup}
                            onChanged={handleConditionChanged}
                            isRoot={false}
                            renderMode={renderMode}
                            targetProgramType={targetProgramType}
                        />
                        {isEditable && (
                            <Link
                                component="button"
                                onClick={() => setStructureDialogOpen(true)}
                                sx={{
                                    color: colors.primaryColor,
                                    ml: 1,
                                    textDecoration: 'none',
                                    fontFamily: 'monospace',
                                    fontSize: '14px',
                                    cursor: 'pointer',
                                    '&:hover': {
                                        textDecoration: 'underline'
                                    }
                                }}
                                title="Configure IF statement structure"
                            >
                                edit branches
                            </Link>
                        )}
                    </Box>

                    {/* IF Branch: THEN actions (conditionally shown) */}
                    {!logicStatement.hideSimpleActions && (
                        <Box sx={{ display: 'flex', alignItems: 'stretch', gap: 1, mt: 1 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, width: '45px' }}>
                                <Typography sx={{
                                    color: colors.primaryColor,
                                    fontWeight: 'bold',
                                    fontFamily: 'monospace',
                                    mt: 0.5,
                                    textDecoration: (logicStatement.conditionGroup?.isDisabled(PLCRenderMode.Edit, targetProgramType) || areAllPredicatesDisabled(logicStatement.predicates)) ? 'line-through' : 'none'
                                }}>
                                    then
                                </Typography>
                            </Box>
                            <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                                <Box sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '24px',
                                    mr: 0.5,
                                    width: '10px',
                                    borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderBottom: `1.5px solid ${colors.secondaryBorderColor}`
                                }}></Box>
                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 0.5, flex: 1 }}>
                                    {renderPredicateSection(
                                        logicStatement.predicates,
                                        handleAddPredicate,
                                        handleRemovePredicate,
                                        addPredicateMenuAnchor,
                                        setAddPredicateMenuAnchor
                                    )}
                                </Box>
                                <Box sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '24px',
                                    ml: 0.5,
                                    width: '10px',
                                    borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderBottom: `1.5px solid ${colors.secondaryBorderColor}`
                                }}></Box>
                            </Box>
                        </Box>
                    )}

                    {/* Nested IF structure (shown when hasNestedIf is true) */}
                    {logicStatement.hasNestedIf && (
                        <Box sx={{ pl: 4, mt: 1 }}>
                            {/* Nested IF condition */}
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <Typography sx={{
                                    color: colors.primaryColor,
                                    fontWeight: 'bold',
                                    fontFamily: 'monospace',
                                    width: '45px',
                                    textDecoration: isNestedIfDisabled() ? 'line-through' : 'none'
                                }}>
                                    if
                                </Typography>
                                {logicStatement.nestedIfCondition && (
                                    <ConditionGroupEditor
                                        conditionGroup={logicStatement.nestedIfCondition}
                                        onChanged={handleConditionChanged}
                                        isRoot={false}
                                        renderMode={isNestedIfDisabled() ? PLCRenderMode.Disabled : renderMode}
                                        targetProgramType={targetProgramType}
                                    />
                                )}
                            </Box>

                            {/* Nested IF THEN */}
                            <Box sx={{ display: 'flex', alignItems: 'stretch', gap: 1, mt: 1, pl: 4 }}>
                                <Typography sx={{
                                    color: colors.primaryColor,
                                    fontWeight: 'bold',
                                    fontFamily: 'monospace',
                                    mt: 0.5,
                                    width: '45px',
                                    textDecoration: (logicStatement.nestedIfCondition?.isDisabled(PLCRenderMode.Edit, targetProgramType) || areAllPredicatesDisabled(logicStatement.nestedIfThenPredicates)) ? 'line-through' : 'none'
                                }}>
                                    then
                                </Typography>
                                <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                                    <Box sx={{
                                        fontFamily: 'monospace',
                                        fontSize: '24px',
                                        mr: 0.5,
                                        width: '10px',
                                        borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                        borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                        borderBottom: `1.5px solid ${colors.secondaryBorderColor}`
                                    }}></Box>
                                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 0.5, flex: 1 }}>
                                        {renderPredicateSection(
                                            logicStatement.nestedIfThenPredicates,
                                            handleAddNestedIfThenPredicate,
                                            handleRemoveNestedIfThenPredicate,
                                            addNestedIfThenMenuAnchor,
                                            setAddNestedIfThenMenuAnchor,
                                            "+ Add Action",
                                            logicStatement.nestedIfCondition?.isDisabled(PLCRenderMode.Edit, targetProgramType) ?? false
                                        )}
                                    </Box>
                                    <Box sx={{
                                        fontFamily: 'monospace',
                                        fontSize: '24px',
                                        ml: 0.5,
                                        width: '10px',
                                        borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                        borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                        borderBottom: `1.5px solid ${colors.secondaryBorderColor}`
                                    }}></Box>
                                </Box>
                            </Box>

                            {/* Nested IF ELSE (optional) - or "+ add else" link */}
                            {logicStatement.hasNestedIfElse ? (
                                <Box sx={{ display: 'flex', alignItems: 'stretch', gap: 1, mt: 1, pl: 4 }}>
                                    <Typography sx={{
                                        color: colors.primaryColor,
                                        fontWeight: 'bold',
                                        fontFamily: 'monospace',
                                        mt: 0.5,
                                        width: '45px',
                                        textDecoration: (logicStatement.nestedIfCondition?.isDisabled(PLCRenderMode.Edit, targetProgramType) || areAllPredicatesDisabled(logicStatement.nestedIfElsePredicates)) ? 'line-through' : 'none'
                                    }}>
                                        else
                                    </Typography>
                                    <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                                        <Box sx={{
                                            fontFamily: 'monospace',
                                            fontSize: '24px',
                                            mr: 0.5,
                                            width: '10px',
                                            borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                            borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                            borderBottom: `1.5px solid ${colors.secondaryBorderColor}`
                                        }}></Box>
                                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 0.5, flex: 1 }}>
                                            {renderPredicateSection(
                                                logicStatement.nestedIfElsePredicates,
                                                handleAddNestedIfElsePredicate,
                                                handleRemoveNestedIfElsePredicate,
                                                addNestedIfElseMenuAnchor,
                                                setAddNestedIfElseMenuAnchor,
                                                "+ Add Action",
                                                logicStatement.nestedIfCondition?.isDisabled(PLCRenderMode.Edit, targetProgramType) ?? false
                                            )}
                                        </Box>
                                        <Box sx={{
                                            fontFamily: 'monospace',
                                            fontSize: '24px',
                                            ml: 0.5,
                                            width: '10px',
                                            borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                            borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                            borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                        }}></Box>
                                    </Box>
                                </Box>
                            ) : null}

                        </Box>
                    )}

                    {/* ELSE section or "add else" link */}
                    {logicStatement.hasElse && (
                        /* ELSE Branch: simple or Nested ELSE */
                        !logicStatement.hasNestedElse ? (
                            /* Simple ELSE - no nesting */
                            <Box sx={{ display: 'flex', alignItems: 'stretch', gap: 1, mt: 1 }}>
                                <Typography sx={{
                                    color: colors.primaryColor,
                                    fontWeight: 'bold',
                                    fontFamily: 'monospace',
                                    mt: 0.5,
                                    width: '45px',
                                    textDecoration: (logicStatement.conditionGroup?.isDisabled(PLCRenderMode.Edit, targetProgramType) || areAllPredicatesDisabled(logicStatement.elsePredicates)) ? 'line-through' : 'none'
                                }}>
                                    else
                                </Typography>
                                <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                                    <Box sx={{
                                        fontFamily: 'monospace',
                                        fontSize: '24px',
                                        mr: 0.5,
                                        width: '10px',
                                        borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                        borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                        borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                    }}></Box>
                                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 0.5, flex: 1 }}>
                                        {renderPredicateSection(
                                            logicStatement.elsePredicates,
                                            handleAddElsePredicate,
                                            handleRemoveElsePredicate,
                                            addElsePredicateMenuAnchor,
                                            setAddElsePredicateMenuAnchor
                                        )}
                                    </Box>
                                    <Box sx={{
                                        fontFamily: 'monospace',
                                        fontSize: '24px',
                                        ml: 0.5,
                                        width: '10px',
                                        borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                        borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                        borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                    }}></Box>
                                </Box>
                            </Box>
                        ) : (
                            /* ELSE Branch: simple ELSE (conditionally shown) + Nested ELSE (when hasNestedElse) */
                            <>
                                {/* Simple ELSE section - show label always, actions only when not hidden */}
                                <Box sx={{ display: 'flex', alignItems: 'stretch', gap: 1, mt: 1 }}>
                                    <Typography sx={{
                                        color: colors.primaryColor,
                                        fontWeight: 'bold',
                                        fontFamily: 'monospace',
                                        mt: 0.5,
                                        width: '45px',
                                        textDecoration: (logicStatement.conditionGroup?.isDisabled(PLCRenderMode.Edit, targetProgramType) || areAllPredicatesDisabled(logicStatement.elsePredicates)) ? 'line-through' : 'none'
                                    }}>
                                        else
                                    </Typography>
                                    {!logicStatement.hideElseActions && (
                                        <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                                            <Box sx={{
                                                fontFamily: 'monospace',
                                                fontSize: '24px',
                                                mr: 0.5,
                                                width: '10px',
                                                borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                                borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                                borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                            }}></Box>
                                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 0.5, flex: 1 }}>
                                                {renderPredicateSection(
                                                    logicStatement.elsePredicates,
                                                    handleAddElsePredicate,
                                                    handleRemoveElsePredicate,
                                                    addElsePredicateMenuAnchor,
                                                    setAddElsePredicateMenuAnchor
                                                )}
                                            </Box>
                                            <Box sx={{
                                                fontFamily: 'monospace',
                                                fontSize: '24px',
                                                ml: 0.5,
                                                width: '10px',
                                                borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                                borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                                borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                            }}></Box>
                                        </Box>
                                    )}
                                </Box>

                                {/* Nested ELSE structure - shown when hasNestedElse is true */}
                                {logicStatement.hasNestedElse && (
                                    <Box sx={{ pl: 4, mt: 1 }}>
                                        {/* Nested ELSE condition */}
                                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                            <Typography sx={{
                                                color: colors.primaryColor,
                                                fontWeight: 'bold',
                                                fontFamily: 'monospace',
                                                width: '45px',
                                                textDecoration: isNestedElseDisabled() ? 'line-through' : 'none'
                                            }}>
                                                if
                                            </Typography>
                                            {logicStatement.nestedElseCondition && (
                                                <ConditionGroupEditor
                                                    conditionGroup={logicStatement.nestedElseCondition}
                                                    onChanged={handleConditionChanged}
                                                    isRoot={false}
                                                    renderMode={isNestedElseDisabled() ? PLCRenderMode.Disabled : renderMode}
                                                    targetProgramType={targetProgramType}
                                                />
                                            )}
                                        </Box>

                                        {/* Nested ELSE THEN */}
                                        <Box sx={{ display: 'flex', alignItems: 'stretch', gap: 1, mt: 1, pl: 4 }}>
                                            <Typography sx={{
                                                color: colors.primaryColor,
                                                fontWeight: 'bold',
                                                fontFamily: 'monospace',
                                                mt: 0.5,
                                                width: '45px',
                                                textDecoration: (logicStatement.nestedElseCondition?.isDisabled(PLCRenderMode.Edit, targetProgramType) || areAllPredicatesDisabled(logicStatement.nestedElseThenPredicates)) ? 'line-through' : 'none'
                                            }}>
                                                then
                                            </Typography>
                                            <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                                                <Box sx={{
                                                    fontFamily: 'monospace',
                                                    fontSize: '24px',
                                                    mr: 0.5,
                                                    width: '10px',
                                                    borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                                    borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                                    borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                                }}></Box>
                                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 0.5, flex: 1 }}>
                                                    {renderPredicateSection(
                                                        logicStatement.nestedElseThenPredicates,
                                                        handleAddNestedElseThenPredicate,
                                                        handleRemoveNestedElseThenPredicate,
                                                        addNestedElseThenMenuAnchor,
                                                        setAddNestedElseThenMenuAnchor,
                                                        "+ Add Action",
                                                        logicStatement.nestedElseCondition?.isDisabled(PLCRenderMode.Edit, targetProgramType) ?? false
                                                    )}
                                                </Box>
                                                <Box sx={{
                                                    fontFamily: 'monospace',
                                                    fontSize: '24px',
                                                    ml: 0.5,
                                                    width: '10px',
                                                    borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                                    borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                                    borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                                }}></Box>
                                            </Box>
                                        </Box>

                                        {/* Nested ELSE ELSE (optional) - or "+ add else" link */}
                                        {logicStatement.hasNestedElseElse ? (
                                            <Box sx={{ display: 'flex', alignItems: 'stretch', gap: 1, mt: 1, pl: 4 }}>
                                                <Typography sx={{
                                                    color: colors.primaryColor,
                                                    fontWeight: 'bold',
                                                    fontFamily: 'monospace',
                                                    mt: 0.5,
                                                    width: '45px',
                                                    textDecoration: (logicStatement.nestedElseCondition?.isDisabled(PLCRenderMode.Edit, targetProgramType) || areAllPredicatesDisabled(logicStatement.nestedElseElsePredicates)) ? 'line-through' : 'none'
                                                }}>
                                                    else
                                                </Typography>
                                                <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                                                    <Box sx={{
                                                        fontFamily: 'monospace',
                                                        fontSize: '24px',
                                                        mr: 0.5,
                                                        width: '10px',
                                                        borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                                        borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                                        borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                                    }}></Box>
                                                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 0.5, flex: 1 }}>
                                                        {renderPredicateSection(
                                                            logicStatement.nestedElseElsePredicates,
                                                            handleAddNestedElseElsePredicate,
                                                            handleRemoveNestedElseElsePredicate,
                                                            addNestedElseElseMenuAnchor,
                                                            setAddNestedElseElseMenuAnchor,
                                                            "+ Add Action",
                                                            logicStatement.nestedElseCondition?.isDisabled(PLCRenderMode.Edit, targetProgramType) ?? false
                                                        )}
                                                    </Box>
                                                    <Box sx={{
                                                        fontFamily: 'monospace',
                                                        fontSize: '24px',
                                                        ml: 0.5,
                                                        width: '10px',
                                                        borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                                        borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                                        borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                                    }}></Box>
                                                </Box>
                                            </Box>
                                        ) : null}
                                    </Box>
                                )}
                            </>
                        )
                    )}

                    {/* Add Action Menu */}
                    <Menu
                        anchorEl={addPredicateMenuAnchor}
                        open={Boolean(addPredicateMenuAnchor)}
                        onClose={() => {
                            setAddPredicateMenuAnchor(null);
                        }}
                        slotProps={{
                            paper: {
                                onMouseEnter: cancelMenuClose,
                                onMouseLeave: () => scheduleMenuClose(setAddPredicateMenuAnchor)
                            }
                        }}
                        anchorOrigin={{
                            vertical: 'bottom',
                            horizontal: 'left',
                        }}
                        transformOrigin={{
                            vertical: 'top',
                            horizontal: 'left',
                        }}
                    >
                        {availablePredicateTypes.map((typeInfo) => (
                            <MenuItem
                                key={typeInfo.type}
                                onClick={() => handleAddPredicate(typeInfo.type)}
                            >
                                <Box>
                                    <Typography variant="body2">{typeInfo.displayName}</Typography>
                                    {typeInfo.description && (
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                            {typeInfo.description}
                                        </Typography>
                                    )}
                                </Box>
                            </MenuItem>
                        ))}
                    </Menu>

                    {/* Add Else Action Menu */}
                    <Menu
                        anchorEl={addElsePredicateMenuAnchor}
                        open={Boolean(addElsePredicateMenuAnchor)}
                        onClose={() => {
                            setAddElsePredicateMenuAnchor(null);
                        }}
                        slotProps={{
                            paper: {
                                onMouseEnter: cancelMenuClose,
                                onMouseLeave: () => scheduleMenuClose(setAddElsePredicateMenuAnchor)
                            }
                        }}
                        anchorOrigin={{
                            vertical: 'bottom',
                            horizontal: 'left',
                        }}
                        transformOrigin={{
                            vertical: 'top',
                            horizontal: 'left',
                        }}
                    >
                        {availablePredicateTypes.map((typeInfo) => (
                            <MenuItem
                                key={typeInfo.type}
                                onClick={() => handleAddElsePredicate(typeInfo.type)}
                            >
                                <Box>
                                    <Typography variant="body2">{typeInfo.displayName}</Typography>
                                    {typeInfo.description && (
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                            {typeInfo.description}
                                        </Typography>
                                    )}
                                </Box>
                            </MenuItem>
                        ))}
                    </Menu>

                    {/* Nested IF THEN Action Menu */}
                    <Menu
                        anchorEl={addNestedIfThenMenuAnchor}
                        open={Boolean(addNestedIfThenMenuAnchor)}
                        onClose={() => setAddNestedIfThenMenuAnchor(null)}
                        slotProps={{
                            paper: {
                                onMouseEnter: cancelMenuClose,
                                onMouseLeave: () => scheduleMenuClose(setAddNestedIfThenMenuAnchor)
                            }
                        }}
                        anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
                        transformOrigin={{ vertical: 'top', horizontal: 'left' }}
                    >
                        {availablePredicateTypes.map((typeInfo) => (
                            <MenuItem key={typeInfo.type} onClick={() => handleAddNestedIfThenPredicate(typeInfo.type)}>
                                <Box>
                                    <Typography variant="body2">{typeInfo.displayName}</Typography>
                                    {typeInfo.description && (
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                            {typeInfo.description}
                                        </Typography>
                                    )}
                                </Box>
                            </MenuItem>
                        ))}
                    </Menu>

                    {/* Nested IF ELSE Action Menu */}
                    <Menu
                        anchorEl={addNestedIfElseMenuAnchor}
                        open={Boolean(addNestedIfElseMenuAnchor)}
                        onClose={() => setAddNestedIfElseMenuAnchor(null)}
                        slotProps={{
                            paper: {
                                onMouseEnter: cancelMenuClose,
                                onMouseLeave: () => scheduleMenuClose(setAddNestedIfElseMenuAnchor)
                            }
                        }}
                        anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
                        transformOrigin={{ vertical: 'top', horizontal: 'left' }}
                    >
                        {availablePredicateTypes.map((typeInfo) => (
                            <MenuItem key={typeInfo.type} onClick={() => handleAddNestedIfElsePredicate(typeInfo.type)}>
                                <Box>
                                    <Typography variant="body2">{typeInfo.displayName}</Typography>
                                    {typeInfo.description && (
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                            {typeInfo.description}
                                        </Typography>
                                    )}
                                </Box>
                            </MenuItem>
                        ))}
                    </Menu>

                    {/* Nested ELSE THEN Action Menu */}
                    <Menu
                        anchorEl={addNestedElseThenMenuAnchor}
                        open={Boolean(addNestedElseThenMenuAnchor)}
                        onClose={() => setAddNestedElseThenMenuAnchor(null)}
                        slotProps={{
                            paper: {
                                onMouseEnter: cancelMenuClose,
                                onMouseLeave: () => scheduleMenuClose(setAddNestedElseThenMenuAnchor)
                            }
                        }}
                        anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
                        transformOrigin={{ vertical: 'top', horizontal: 'left' }}
                    >
                        {availablePredicateTypes.map((typeInfo) => (
                            <MenuItem key={typeInfo.type} onClick={() => handleAddNestedElseThenPredicate(typeInfo.type)}>
                                <Box>
                                    <Typography variant="body2">{typeInfo.displayName}</Typography>
                                    {typeInfo.description && (
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                            {typeInfo.description}
                                        </Typography>
                                    )}
                                </Box>
                            </MenuItem>
                        ))}
                    </Menu>

                    {/* Nested ELSE ELSE Action Menu */}
                    <Menu
                        anchorEl={addNestedElseElseMenuAnchor}
                        open={Boolean(addNestedElseElseMenuAnchor)}
                        onClose={() => setAddNestedElseElseMenuAnchor(null)}
                        slotProps={{
                            paper: {
                                onMouseEnter: cancelMenuClose,
                                onMouseLeave: () => scheduleMenuClose(setAddNestedElseElseMenuAnchor)
                            }
                        }}
                        anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
                        transformOrigin={{ vertical: 'top', horizontal: 'left' }}
                    >
                        {availablePredicateTypes.map((typeInfo) => (
                            <MenuItem key={typeInfo.type} onClick={() => handleAddNestedElseElsePredicate(typeInfo.type)}>
                                <Box>
                                    <Typography variant="body2">{typeInfo.displayName}</Typography>
                                    {typeInfo.description && (
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                            {typeInfo.description}
                                        </Typography>
                                    )}
                                </Box>
                            </MenuItem>
                        ))}
                    </Menu>

                    {/* Logic Structure Configuration Dialog */}
                    <LogicStructureDialog
                        open={structureDialogOpen}
                        onClose={() => {
                            setStructureDialogOpen(false);
                            onChanged?.();
                        }}
                        statement={logicStatement}
                    />
                </Box>
            )}
        />
    );
}
