import { IMachineCallback } from "../../machine/IMachineCallback";
import { StateManager } from "../../utils/statemanager/StateManager";
import { WizardStep } from "./WizardStep";

// Generic Wizard class with strongly-typed state management
export class Wizard<TState extends object = any> {
    private _state: TState;
    firstStep: WizardStep;
    currentStep: WizardStep;
    canClose: boolean;
    clickAwayClose: boolean;
    width: string | number;
    height: string | number;
    callback?: IMachineCallback;

    constructor(
        firstStep: WizardStep,
        initialState: TState,
        canClose: boolean = true,
        clickAwayClose: boolean = false,
        width: string | number = '80%',
        height: string | number = '80%'
    ) {
        this._state = initialState;
        this.firstStep = firstStep;
        this.currentStep = firstStep;
        this.canClose = canClose;
        this.clickAwayClose = clickAwayClose;
        this.width = width;
        this.height = height;
    }

    // State getter and setter with StateManager integration
    public get state(): TState {
        return this._state;
    }

    public set state(value: TState) {
        this._state = value;
        StateManager.propertyChanged(this, 'state');
    }

    // Helper method to update state properties
    public updateState(updates: Partial<TState>): void {
        this._state = { ...this._state, ...updates };
        StateManager.propertyChanged(this, 'state');
    }

    advanceToNextStep(): void {
        const nextStep = this.currentStep.nextStep();
        if (nextStep) {
            this.currentStep = nextStep;
            StateManager.propertyChanged(this, 'currentStep');
        } else {
            // No next step, wizard completed successfully
            this.completeWizard();
        }
    }

    goToPreviousStep(): void {
        const previousStep = this.currentStep.backStep();
        if (previousStep) {
            this.currentStep = previousStep;
            StateManager.propertyChanged(this, 'currentStep');
        }
    }

    completeWizard(): void {
        // Wizard completed successfully
        this.callback?.onComplete?.();
    }

    cancelWizard(): void {
        // Wizard was cancelled by user
        this.callback?.onCancel?.();
    }

    errorWizard(error: Error | string): void {
        // Wizard encountered an error
        this.callback?.onError?.(error);
    }

    closeWizard(): void {
        // Generic close - calls cancelWizard by default
        // This is called when user clicks X button or cancels
        this.cancelWizard();
    }
}