import { StateManager } from '../../utils/statemanager/StateManager';
import { Wizard } from './Wizard';

export class WizardManager {
  private static _instance: WizardManager;
  private _wizardStack: Wizard[] = [];

  public static get Instance(): WizardManager {
    if (!WizardManager._instance) {
      WizardManager._instance = new WizardManager();
    }
    return WizardManager._instance;
  }

  private constructor() {
    // Private constructor for singleton pattern
  }

  /**
   * Get the current (top-most) wizard
   */
  public get currentWizard(): Wizard | null {
    return this._wizardStack.length > 0 ? this._wizardStack[this._wizardStack.length - 1] : null;
  }

  /**
   * Get all open wizards (bottom to top)
   */
  public get wizards(): Wizard[] {
    return [...this._wizardStack];
  }

  public get isWizardOpen(): boolean {
    return this._wizardStack.length > 0;
  }

  /**
   * Start a new wizard. Wizards stack like dialogs - new wizards appear on top.
   * Note: If you want to replace an existing wizard instead of stacking, close it first.
   */
  public start(wizard: Wizard): void {
    // CRITICAL: Each wizard instance should only appear once in the stack
    // If somehow the same instance is already in the stack, remove it first
    const existingIndex = this._wizardStack.indexOf(wizard);
    if (existingIndex !== -1) {
      this._wizardStack.splice(existingIndex, 1);
    }

    this._wizardStack.push(wizard);
    this._setupWizardCallbacks(wizard);
    StateManager.propertyChanged(this, 'currentWizard');
    StateManager.propertyChanged(this, 'wizards');
  }

  /**
   * Close the top-most wizard.
   */
  public close(): void {
    if (this._wizardStack.length > 0) {
      this._wizardStack.pop();
      StateManager.propertyChanged(this, 'currentWizard');
      StateManager.propertyChanged(this, 'wizards');
    }
  }

  /**
   * Close a specific wizard (removes it from the stack)
   */
  public closeWizard(wizard: Wizard): void {
    const index = this._wizardStack.indexOf(wizard);
    if (index !== -1) {
      this._wizardStack.splice(index, 1);
      StateManager.propertyChanged(this, 'currentWizard');
      StateManager.propertyChanged(this, 'wizards');
    }
  }

  /**
   * Setup callbacks for a wizard to handle completion, cancellation, and errors
   */
  private _setupWizardCallbacks(wizard: Wizard): void {
    // Store original callbacks if they exist
    const originalCallback = wizard.callback;

    // Wrap the callbacks to also handle wizard manager cleanup
    wizard.callback = {
      onComplete: async () => {
        // Remove this wizard from stack BEFORE calling original callback
        // This allows the callback to start a new wizard immediately
        this.closeWizard(wizard);
        await originalCallback?.onComplete?.();
      },
      onCancel: async () => {
        this.closeWizard(wizard);
        await originalCallback?.onCancel?.();
      },
      onError: async (error: Error | string) => {
        this.closeWizard(wizard);
        await originalCallback?.onError?.(error);
      }
    };
  }
}
