import { JobCompletedEvent, JobInfoEvent, JobStartedEvent, StepExecutionEvent } from '../data/SignalR/SignalREventTypes';
import { GCodeExecutionCallback } from '../machine/ICNCProgram';
import { LogCategory, Logger } from './Logger';
import { SignalRManager } from './SignalRManager';

/**
 * JobCallbackManager - Singleton class that manages job execution callbacks
 * Listens to SignalR events and routes them to the current job callback
 * Since only one job runs at a time, we track a single callback
 */
export class JobCallbackManager {
    private static _instance: JobCallbackManager;
    private _currentJobCallback: GCodeExecutionCallback | null = null;  // Only one job runs at a time
    private _isListening: boolean = false;

    private constructor() {
        // Private constructor for singleton pattern
    }

    /**
     * Get the singleton instance
     */
    public static get Instance(): JobCallbackManager {
        if (!JobCallbackManager._instance) {
            JobCallbackManager._instance = new JobCallbackManager();
        }
        return JobCallbackManager._instance;
    }

    /**
     * Initialize the manager and start listening to SignalR events
     * Should be called once during application startup
     */
    public initialize(): void {
        if (this._isListening) {
            return;
        }

        const signalR = SignalRManager.Instance;

        // Register listeners for job-related events
        signalR.addEventListener('JobStartedEvent', this._handleJobStartedEvent.bind(this));
        signalR.addEventListener('JobInfoEvent', this._handleJobInfoEvent.bind(this));
        signalR.addEventListener('StepExecutionEvent', this._handleStepExecutionEvent.bind(this));
        signalR.addEventListener('JobCompletedEvent', this._handleJobCompletedEvent.bind(this));

        this._isListening = true;
    }

    /**
     * Register a callback for the current job
     * Since only one job runs at a time, this replaces any previous callback
     * @param jobId The unique job identifier from RunGCode response (ignored, for API compatibility)
     * @param callback The callback object with onComplete, onError, onExecuteLine methods
     */
    public registerCallback(jobId: string, callback: GCodeExecutionCallback): void {
        this._currentJobCallback = callback;
    }

    /**
     * Unregister the current job callback
     * @param jobId The unique job identifier (ignored, for API compatibility)
     */
    public unregisterCallback(jobId: string): void {
        this._currentJobCallback = null;
    }

    /**
     * Get the number of currently tracked jobs
     */
    public get trackedJobCount(): number {
        return this._currentJobCallback ? 1 : 0;
    }

    /**
     * Get all tracked job IDs (for debugging)
     */
    public getTrackedJobIds(): string[] {
        return this._currentJobCallback ? ['current'] : [];
    }

    /**
     * Handle JobStartedEvent from SignalR
     */
    private _handleJobStartedEvent(event: JobStartedEvent): void {
        // JobStartedEvent doesn't trigger a callback method
        // The callback methods are triggered by JobInfoEvent and JobCompletedEvent
    }

    /**
     * Handle JobInfoEvent from SignalR (legacy event without jobId)
     * Since only one job runs at a time, route to current callback
     */
    private _handleJobInfoEvent(event: JobInfoEvent): void {
        if (!this._currentJobCallback) {
            return;
        }

        try {
            // JobInfoEvent has lineNumber but no other details like currentLine text or totalLines
            // We'll use what we have and set defaults for missing fields
            this._currentJobCallback.onExecuteLine(
                event.data.jobName || 'current',
                event.data.lineNumber,
                '', // JobInfoEvent doesn't have currentLine text
                0,  // JobInfoEvent doesn't have totalLines
                false // JobInfoEvent doesn't have isLastStep
            );
        } catch (error) {
            Logger.Instance.logError(
                LogCategory.System,
                `Error in job callback onExecuteLine:`,
                error
            );
        }
    }

    /**
     * Handle StepExecutionEvent from SignalR
     * Calls the registered callback's onExecuteLine method
     */
    private _handleStepExecutionEvent(event: StepExecutionEvent): void {
        if (!this._currentJobCallback) {
            return;
        }

        try {
            this._currentJobCallback.onExecuteLine(
                event.data.jobId,
                event.data.lineNumber,
                event.data.currentLine,
                event.data.totalLines,
                event.data.isLastStep
            );
        } catch (error) {
            Logger.Instance.logError(
                LogCategory.System,
                `Error in job callback onExecuteLine:`,
                error
            );
        }
    }

    /**
     * Handle JobCompletedEvent from SignalR
     * Calls the registered callback's onComplete or onError methods
     * Automatically unregisters the callback after handling
     */
    private _handleJobCompletedEvent(event: JobCompletedEvent): void {
        if (!this._currentJobCallback) {
            return;
        }

        try {
            if (event.data.success) {
                // Job completed successfully
                this._currentJobCallback.onComplete(
                    event.data.jobId,
                    true,
                    undefined,
                    event.data.linesExecuted,
                    event.data.duration
                );
            } else {
                // Job failed - call both onError and onComplete
                this._currentJobCallback.onError(event.data.jobId, event.data.errorMessage || 'Unknown error');
                this._currentJobCallback.onComplete(
                    event.data.jobId,
                    false,
                    event.data.errorMessage,
                    event.data.linesExecuted,
                    event.data.duration
                );
            }
        } catch (error) {
            Logger.Instance.logError(
                LogCategory.System,
                `Error in job callback handlers:`,
                error
            );
        } finally {
            // Always unregister callback after job completion
            this._currentJobCallback = null;
        }
    }

    /**
     * Log debug information about tracked jobs
     */
    public logDebugInfo(): void {
        // Debug information removed - use breakpoints or external logging if needed
    }
}
