import { CNCOffset } from '../data/CNCOffset';
import { MachineStateData } from '../data/MachineStateData';
import { Tool } from '../data/Common/Tool';
import { ToolLibrary } from '../data/Common/ToolLibrary';

/**
 * Utility class for tool-related operations
 * Provides centralized methods for tool lookup and offset calculation
 */
export class ToolUtils {
  /**
   * Get the current tool from the tool library based on machine state
   * @returns The current tool, or undefined if no tool is loaded
   */
  public static getCurrentTool(): Tool | undefined {
    const machineState = MachineStateData.Instance;
    const currentToolNumber = machineState.currentToolNumber;
    
    if (!currentToolNumber) {
      return undefined;
    }
    
    return ToolLibrary.Instance.getToolByNumber(currentToolNumber);
  }

  /**
   * Get current tool offsets for the loaded tool
   * Uses measured length if available, otherwise falls back to length below holder
   * @returns CNCOffset containing the current tool offsets (X, Y, Z)
   */
  public static getCurrentToolOffsets(): CNCOffset {
    const tool = ToolUtils.getCurrentTool();
    
    if (!tool) {
      return new CNCOffset(0, 0, 0);
    }
    
    // Use measured length if available, otherwise use length below holder
    // Tool lengths are stored as positive values (extending downward from spindle)
    const zOffset = tool.measuredLength || tool.lengthBelowHolder || 0;
    
    return new CNCOffset(
      tool.toolOffsetX || 0,
      tool.toolOffsetY || 0,
      zOffset
    );
  }

  /**
   * Get tool offsets for a specific tool number
   * @param toolNumber The tool number to get offsets for
   * @returns CNCOffset containing the tool offsets (X, Y, Z)
   */
  public static getToolOffsets(toolNumber: number): CNCOffset {
    const tool = ToolLibrary.Instance.getToolByNumber(toolNumber);
    
    if (!tool) {
      return new CNCOffset(0, 0, 0);
    }
    
    const zOffset = tool.measuredLength || tool.lengthBelowHolder || 0;
    
    return new CNCOffset(
      tool.toolOffsetX || 0,
      tool.toolOffsetY || 0,
      zOffset
    );
  }
}
