import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import RefreshIcon from '@mui/icons-material/Refresh';
import {
    Box,
    Button,
    Checkbox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Divider,
    FormControlLabel,
    Grid,
    IconButton,
    MenuItem,
    Paper,
    Select,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    TextField,
    Typography
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { SetupChecklistIndicator } from '../../../components/Common/SetupChecklistIndicator';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { IOStateData } from '../../../data/IOStateData';
import { MachineData } from '../../../data/Machine/MachineData';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { Machine } from '../../../machine/Machine';
import { ConfirmDialogManager } from '../../../utils/ConfirmDialogManager';
import { getAvailableIONumbers } from '../../../utils/IONumberCalculator';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { SymbolNameWithUsageTooltip } from '../components/SymbolNameWithUsageTooltip';
import { PLCProgram } from '../data/PLCProgram';
import { PLCProgramType } from '../data/PLCUtilities';
import { DefaultPLCInputs } from '../data/io/DefaultPLCInputs';
import { PLCInput } from '../data/io/PLCInput';

interface InputDialogProps {
    open: boolean;
    input: PLCInput | null;
    availableInputs: number[];
    onClose: () => void;
    onSave: (input: PLCInput, inputNumber: number | null) => void;
}

function InputDialog({ open, input, availableInputs, onClose, onSave }: InputDialogProps) {
    const plcProgram = PLCProgram.Instance(PLCProgramType.System);
    const [selectedInputs, setSelectedInputs] = useState<Set<string>>(new Set());
    const [showCustomDialog, setShowCustomDialog] = useState(false);
    const defaultInputs = DefaultPLCInputs.getDefaults();

    useEffect(() => {
        if (open && !input) {
            // When opening for add, initialize selectedInputs with current program inputs
            const currentNames = new Set(plcProgram.inputs.map(i => i.centroidName));
            setSelectedInputs(currentNames);
            setShowCustomDialog(false);
        } else if (input) {
            // Editing a single input - show custom dialog directly
            setShowCustomDialog(true);
        }
    }, [open, input, plcProgram.inputs]);

    const handleToggleInput = (centroidName: string) => {
        const newSelected = new Set(selectedInputs);
        if (newSelected.has(centroidName)) {
            newSelected.delete(centroidName);
        } else {
            newSelected.add(centroidName);
        }
        setSelectedInputs(newSelected);
    };

    const handleSaveMultiple = () => {
        if (!plcProgram) return;

        // Get all default and custom inputs by centroidName
        const defaultInputMap = new Map(defaultInputs.map(di => [di.centroidName, di]));

        // Remove inputs that were deselected (both default and custom)
        const toRemove = plcProgram.inputs.filter(input => !selectedInputs.has(input.centroidName));
        toRemove.forEach(input => {
            const index = plcProgram.inputs.indexOf(input);
            if (index > -1) {
                plcProgram.inputs.splice(index, 1);
            }
        });

        // Add newly selected default inputs that aren't already in the list
        const existingNames = new Set(plcProgram.inputs.map(i => i.centroidName));
        selectedInputs.forEach(centroidName => {
            if (!existingNames.has(centroidName) && defaultInputMap.has(centroidName)) {
                const defaultInput = defaultInputMap.get(centroidName)!;
                plcProgram.inputs.push(defaultInput.clone());
            }
        });

        StateManager.propertyChanged(plcProgram, 'inputs');
        onClose();
    };

    // Get currently used inputs (in the program) - both default and custom
    const defaultInputNames = new Set(defaultInputs.map(di => di.centroidName));
    const currentCustomInputs = plcProgram.inputs.filter(i => !defaultInputNames.has(i.centroidName));

    // Group default inputs by category
    const inputsByCategory = defaultInputs.reduce((acc, input) => {
        const category = input.category || 'General';
        if (!acc[category]) {
            acc[category] = [];
        }
        acc[category].push(input);
        return acc;
    }, {} as Record<string, typeof defaultInputs>);

    // Sort categories alphabetically
    const sortedCategories = Object.keys(inputsByCategory).sort();

    return (
        <>
            <Dialog open={open && !showCustomDialog} onClose={onClose} maxWidth="md" fullWidth>
                <DialogTitle>Manage Inputs</DialogTitle>
                <Box sx={{ px: 3, pt: 2, pb: 1, borderBottom: '1px solid', borderColor: 'divider', display: 'flex', justifyContent: 'flex-end' }}>
                    <Button
                        variant="outlined"
                        color="primary"
                        onClick={() => setShowCustomDialog(true)}
                        sx={{ textTransform: 'none' }}
                    >
                        + Add Custom Input
                    </Button>
                </Box>
                <DialogContent>
                    <Box>
                        <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold', mt: 2 }}>
                            Default Inputs (click to toggle)
                        </Typography>

                        {sortedCategories.map(category => (
                            <Box key={category} sx={{ mb: 3 }}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: 'text.secondary', mb: 1 }}>
                                    {category}
                                </Typography>
                                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                                    {inputsByCategory[category].map((di) => {
                                        const isSelected = selectedInputs.has(di.centroidName);
                                        return (
                                            <Button
                                                key={di.centroidName}
                                                variant={isSelected ? 'contained' : 'outlined'}
                                                color={isSelected ? 'primary' : 'inherit'}
                                                onClick={() => handleToggleInput(di.centroidName)}
                                                sx={{ textTransform: 'none' }}
                                            >
                                                {di.name}
                                            </Button>
                                        );
                                    })}
                                </Box>
                            </Box>
                        ))}

                        {currentCustomInputs.length > 0 && (
                            <>
                                <Divider sx={{ my: 2 }} />
                                <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold' }}>
                                    Custom Inputs (click to remove)
                                </Typography>
                                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
                                    {currentCustomInputs.map((ci) => (
                                        <Button
                                            key={ci.centroidName}
                                            variant="contained"
                                            color="secondary"
                                            onClick={() => handleToggleInput(ci.centroidName)}
                                            sx={{ textTransform: 'none' }}
                                        >
                                            {ci.name} (Custom)
                                        </Button>
                                    ))}
                                </Box>
                            </>
                        )}
                    </Box>
                </DialogContent>
                <DialogActions>
                    <Button onClick={onClose}>Cancel</Button>
                    <Button
                        onClick={handleSaveMultiple}
                        variant="contained"
                        color="primary"
                    >
                        Save
                    </Button>
                </DialogActions>
            </Dialog>

            <CustomInputDialog
                open={showCustomDialog}
                input={input}
                availableInputs={availableInputs}
                onClose={() => {
                    setShowCustomDialog(false);
                    if (input) {
                        onClose(); // Close parent dialog when editing
                    }
                }}
                onSave={(customInput, number) => {
                    // Add the custom input to the program and select it
                    const existingIndex = plcProgram.inputs.findIndex(i => i.centroidName === customInput.centroidName);
                    if (existingIndex > -1) {
                        // Update existing
                        plcProgram.inputs[existingIndex] = customInput;
                        plcProgram.inputs[existingIndex].number = number;
                    } else {
                        // Add new
                        customInput.number = number;
                        plcProgram.inputs.push(customInput);
                    }
                    StateManager.propertyChanged(plcProgram, 'inputs');

                    // Add to selected set
                    const newSelected = new Set(selectedInputs);
                    newSelected.add(customInput.centroidName);
                    setSelectedInputs(newSelected);

                    setShowCustomDialog(false);

                    if (input) {
                        // If editing, close parent dialog too
                        onClose();
                    }
                }}
            />
        </>
    );
}

function CustomInputDialog({ open, input, availableInputs, onClose, onSave }: InputDialogProps) {
    const [workingInput, setWorkingInput] = useState<PLCInput>(new PLCInput());
    const [editingCentroidName, setEditingCentroidName] = useState('');
    const [inputNumber, setInputNumber] = useState<number | null>(null);
    const plcProgram = PLCProgram.Instance(PLCProgramType.System);
    const config = ConfigurationData.Instance;
    const colors = ConfigurationDataColors.Instance;

    useEffect(() => {
        if (open) {
            if (input) {
                setWorkingInput(input.clone());
                // Remove _I suffix for editing
                let name = input.centroidName;
                if (name.endsWith('_I')) {
                    name = name.slice(0, -2);
                }
                setEditingCentroidName(name);
                setInputNumber(input.number);
            } else {
                setWorkingInput(new PLCInput());
                setEditingCentroidName('');
                setInputNumber(null);
            }
        }
    }, [open, input]);

    const handleCentroidNameFocus = () => {
        // Remove _I suffix when focusing
        let name = editingCentroidName;
        if (name.endsWith('_I')) {
            name = name.slice(0, -2);
        }
        setEditingCentroidName(name);
    };

    const handleCentroidNameBlur = () => {
        // Add _I suffix and uppercase when leaving field
        let name = editingCentroidName.trim();
        if (name) {
            name = name.toUpperCase();
            if (!name.endsWith('_I')) {
                name = name + '_I';
            }
            workingInput.centroidName = name;
            setEditingCentroidName(name);
        }
    };

    const handleSave = () => {
        if (!workingInput.name.trim()) {
            return;
        }
        if (!editingCentroidName.trim()) {
            return;
        }
        // Ensure centroid name has _I suffix
        let finalName = editingCentroidName.trim().toUpperCase();
        if (!finalName.endsWith('_I')) {
            finalName = finalName + '_I';
        }
        workingInput.centroidName = finalName;
        onSave(workingInput, inputNumber);
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle>{input ? 'Edit Custom Input' : 'Add Custom Input'}</DialogTitle>
            <ObserveState
                key="custom-input-dialog-form"
                listenTo={workingInput}
                properties={['centroidName', 'name', 'activeText', 'inactiveText', 'isInverted']}
                control={() => (
                    <>
                        <DialogContent>
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
                                <TextField
                                    label="Centroid Name"
                                    value={editingCentroidName}
                                    onChange={(e) => setEditingCentroidName(e.target.value)}
                                    onFocus={handleCentroidNameFocus}
                                    onBlur={handleCentroidNameBlur}
                                    fullWidth
                                    required
                                    helperText="PLC variable name. _I suffix will be added automatically."
                                />

                                <TextField
                                    label="Display Name"
                                    value={workingInput.name}
                                    onChange={(e) => workingInput.name = e.target.value}
                                    fullWidth
                                    required
                                />

                                <TextField
                                    label="Active Text"
                                    value={workingInput.activeText}
                                    onChange={(e) => workingInput.activeText = e.target.value}
                                    fullWidth
                                />

                                <TextField
                                    label="Inactive Text"
                                    value={workingInput.inactiveText}
                                    onChange={(e) => workingInput.inactiveText = e.target.value}
                                    fullWidth
                                />

                                <FormControlLabel
                                    control={
                                        <Checkbox
                                            checked={workingInput.isInverted}
                                            onChange={(e) => workingInput.isInverted = e.target.checked}
                                        />
                                    }
                                    label="Inverted"
                                />

                                <Box>
                                    <Typography variant="body2" gutterBottom>
                                        Assign Input Number:
                                    </Typography>
                                    <Select
                                        fullWidth
                                        value={inputNumber ?? ''}
                                        displayEmpty
                                        onChange={(e) => setInputNumber(e.target.value === '' ? null : Number(e.target.value))}
                                    >
                                        <MenuItem value="">
                                            <em>Unassigned</em>
                                        </MenuItem>
                                        {availableInputs.map((num) => {
                                            const isAssigned = plcProgram.inputs.some(
                                                i => i.number === num && i.centroidName !== input?.centroidName
                                            );
                                            return (
                                                <MenuItem
                                                    key={num}
                                                    value={num}
                                                    sx={{
                                                        color: isAssigned ? 'text.disabled' : 'text.primary',
                                                        fontStyle: isAssigned ? 'italic' : 'normal'
                                                    }}
                                                >
                                                    {num}{isAssigned ? ' (in use)' : ''}
                                                </MenuItem>
                                            );
                                        })}
                                    </Select>
                                </Box>
                            </Box>
                        </DialogContent>
                        <DialogActions>
                            <Button onClick={onClose}>Cancel</Button>
                            <Button
                                onClick={handleSave}
                                variant="contained"
                                sx={{
                                    backgroundColor: colors.primaryColor,
                                    '&:hover': {
                                        backgroundColor: colors.primaryColor,
                                        opacity: 0.9,
                                    },
                                }}
                            >
                                Save
                            </Button>
                        </DialogActions>
                    </>
                )}
            />
        </Dialog>
    );
}

export function InputsTab(): React.ReactElement {
    const [dialogOpen, setDialogOpen] = useState(false);
    const [editingInput, setEditingInput] = useState<PLCInput | null>(null);
    const availableInputs = getAvailableIONumbers(
        MachineData.Instance.boardType,
        MachineData.Instance.expansionBoardCount
    );
    const [bulkIOStates, setBulkIOStates] = useState<{ inputs: Record<number, boolean>, outputs: Record<number, boolean>, readAt: Date } | null>(null);
    const [isRefreshing, setIsRefreshing] = useState(false);

    useEffect(() => {
        loadBulkIOStates();
    }, []);

    const loadBulkIOStates = async () => {
        setIsRefreshing(true);
        try {
            const machine = Machine.getInstance();
            const states = await machine.io.GetBulkIOStates();
            setBulkIOStates(states);

            // Update IOStateData with the bulk states
            const ioStateData = IOStateData.Instance;
            Object.entries(states.inputs).forEach(([num, isOn]) => {
                const input = ioStateData.getInputByNumber(parseInt(num));
                if (input) {
                    input.isActive = isOn;
                }
            });
            Object.entries(states.outputs).forEach(([num, isOn]) => {
                const output = ioStateData.getOutputByNumber(parseInt(num));
                if (output) {
                    output.isActive = isOn;
                }
            });

        } catch (error) {
            UserMessageQueue.Instance.addMessage('❌ Failed to load I/O states');
        } finally {
            setIsRefreshing(false);
        }
    };

    const plcProgram = PLCProgram.Instance(PLCProgramType.System);

    const handleAddInput = () => {
        setEditingInput(null);
        setDialogOpen(true);
    };

    const handleDeleteInput = async (input: PLCInput) => {
        const confirmed = await ConfirmDialogManager.Instance.showDeleteConfirm(
            `input "${input.name}"`
        );
        if (confirmed && plcProgram) {
            const index = plcProgram.inputs.indexOf(input);
            if (index > -1) {
                plcProgram.inputs.splice(index, 1);
                StateManager.propertyChanged(plcProgram, 'inputs');
            }
        }
    };

    const getAssignedInputs = () => {
        if (!plcProgram) return [];
        return plcProgram.inputs
            .filter((input: PLCInput) => input.number !== null)
            .sort((a, b) => (a.number ?? 0) - (b.number ?? 0));
    };

    const getUnassignedInputs = () => {
        if (!plcProgram) return [];
        return plcProgram.inputs.filter((input: PLCInput) => input.number === null);
    };

    const isNumberAssigned = (num: number, currentInputCentroidName?: string) => {
        if (!plcProgram) return false;
        return plcProgram.inputs.some(
            input => input.number === num && input.centroidName !== currentInputCentroidName
        );
    };

    return (
        <ObserveState
            key="plc-inputs-tab"
            listenTo={plcProgram}
            properties={['inputs']}
            control={() => {
                const assignedInputs = getAssignedInputs();
                const unassignedInputs = getUnassignedInputs();

                return (
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                        <Grid container spacing={2}>
                            <Grid item xs={12}>
                                <SetupChecklistIndicator name="Inputs Configuration" />
                            </Grid>
                            <Grid item xs={12}>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <Typography variant="h6">PLC Inputs</Typography>
                                    <Box sx={{ display: 'flex', gap: 2 }}>
                                        <Button
                                            variant="outlined"
                                            color="primary"
                                            startIcon={<RefreshIcon />}
                                            onClick={loadBulkIOStates}
                                            disabled={isRefreshing}
                                        >
                                            {isRefreshing ? 'Refreshing...' : 'Refresh I/O States'}
                                        </Button>
                                        <Button
                                            variant="contained"
                                            color="primary"
                                            startIcon={<AddIcon />}
                                            onClick={handleAddInput}
                                        >
                                            Add Input
                                        </Button>
                                    </Box>
                                </Box>
                            </Grid>
                        </Grid>

                        {/* Unassigned Inputs */}
                        <Box>
                            <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold' }}>
                                Unassigned Inputs ({unassignedInputs.length})
                            </Typography>
                            <TableContainer component={Paper}>
                                <Table size="small">
                                    <TableHead>
                                        <TableRow>
                                            <TableCell sx={{ width: '150px' }}>Assign Number</TableCell>
                                            <TableCell>Centroid Name</TableCell>
                                            <TableCell>Display Name</TableCell>
                                            <TableCell>Active Text</TableCell>
                                            <TableCell>Inactive Text</TableCell>
                                            <TableCell align="right">Actions</TableCell>
                                        </TableRow>
                                    </TableHead>
                                    <TableBody>
                                        {unassignedInputs.length === 0 ? (
                                            <TableRow>
                                                <TableCell colSpan={6} align="center">
                                                    <Typography variant="body2" color="textSecondary">
                                                        No unassigned inputs
                                                    </Typography>
                                                </TableCell>
                                            </TableRow>
                                        ) : (
                                            unassignedInputs.map((input: PLCInput) => (
                                                <TableRow key={input.centroidName}>
                                                    <TableCell>
                                                        <Select
                                                            size="small"
                                                            displayEmpty
                                                            value={input.number ?? ''}
                                                            onChange={(e) => {
                                                                const value = e.target.value;
                                                                if (value === '') {
                                                                    input.number = null;
                                                                } else {
                                                                    const num = Number(value);
                                                                    // Check if this number is already assigned
                                                                    const existingInput = plcProgram.inputs.find(
                                                                        i => i.number === num && i.centroidName !== input.centroidName
                                                                    );
                                                                    if (existingInput) {
                                                                        existingInput.number = null;
                                                                    }
                                                                    input.number = num;
                                                                }
                                                                StateManager.propertyChanged(plcProgram, 'inputs');
                                                            }}
                                                            sx={{ width: '120px' }}
                                                        >
                                                            <MenuItem value="">
                                                                <em>Unassigned</em>
                                                            </MenuItem>
                                                            {availableInputs.map((num) => {
                                                                const isAssigned = isNumberAssigned(num, input.centroidName);
                                                                return (
                                                                    <MenuItem
                                                                        key={num}
                                                                        value={num}
                                                                        sx={{
                                                                            color: isAssigned ? 'text.disabled' : 'text.primary',
                                                                            fontStyle: isAssigned ? 'italic' : 'normal'
                                                                        }}
                                                                    >
                                                                        {num}{isAssigned ? ' (in use)' : ''}
                                                                    </MenuItem>
                                                                );
                                                            })}
                                                        </Select>
                                                    </TableCell>
                                                    <TableCell>{input.centroidName}</TableCell>
                                                    <TableCell>{input.name}</TableCell>
                                                    <TableCell>{input.activeText}</TableCell>
                                                    <TableCell>{input.inactiveText}</TableCell>
                                                    <TableCell align="right">
                                                        <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
                                                            <IconButton
                                                                size="small"
                                                                onClick={() => {
                                                                    setEditingInput(input);
                                                                    setDialogOpen(true);
                                                                }}
                                                                title="Edit input"
                                                            >
                                                                <EditIcon fontSize="small" />
                                                            </IconButton>
                                                            <IconButton
                                                                size="small"
                                                                onClick={() => handleDeleteInput(input)}
                                                                title="Delete input"
                                                            >
                                                                <DeleteIcon fontSize="small" />
                                                            </IconButton>
                                                        </Box>
                                                    </TableCell>
                                                </TableRow>
                                            ))
                                        )}
                                    </TableBody>
                                </Table>
                            </TableContainer>
                        </Box>

                        {/* Assigned Inputs */}
                        <Box>
                            <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold' }}>
                                Assigned Inputs ({assignedInputs.length})
                            </Typography>
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                                {assignedInputs.length === 0 ? (
                                    <Paper sx={{ p: 3 }}>
                                        <Typography variant="body2" color="textSecondary" align="center">
                                            No assigned inputs
                                        </Typography>
                                    </Paper>
                                ) : (
                                    assignedInputs.map((input: PLCInput) => {
                                        // Get current state from bulk I/O states
                                        const rawState = bulkIOStates?.inputs[input.number || 0] ?? false;
                                        // Apply inversion logic - if inverted, flip the display
                                        const displayState = input.isInverted ? !rawState : rawState;

                                        return (
                                            <Paper
                                                key={input.centroidName}
                                                sx={{
                                                    p: 2,
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    gap: 2
                                                }}
                                            >
                                                {/* Input Number Dropdown (Editable) */}
                                                <Box sx={{ width: 120 }}>
                                                    <Select
                                                        size="small"
                                                        displayEmpty
                                                        value={input.number ?? ''}
                                                        onChange={(e) => {
                                                            const value = e.target.value;
                                                            if (value === '') {
                                                                input.number = null;
                                                            } else {
                                                                const num = Number(value);
                                                                // Check if this number is already assigned
                                                                const existingInput = plcProgram.inputs.find(
                                                                    i => i.number === num && i.centroidName !== input.centroidName
                                                                );
                                                                if (existingInput) {
                                                                    existingInput.number = null;
                                                                }
                                                                input.number = num;
                                                            }
                                                            StateManager.propertyChanged(plcProgram, 'inputs');
                                                        }}
                                                        sx={{
                                                            width: '100%',
                                                            '& .MuiSelect-select': {
                                                                fontWeight: 'bold',
                                                                fontSize: '1.1rem',
                                                                backgroundColor: displayState ? 'success.main' : 'grey.400',
                                                                color: ConfigurationDataColors.Instance.lightTextColor,
                                                                display: 'flex',
                                                                alignItems: 'center',
                                                                justifyContent: 'center',
                                                                '&:focus': {
                                                                    backgroundColor: displayState ? 'success.main' : 'grey.400',
                                                                }
                                                            }
                                                        }}
                                                    >
                                                        <MenuItem value="">
                                                            <em>Unassigned</em>
                                                        </MenuItem>
                                                        {availableInputs.map((num) => {
                                                            const isAssigned = isNumberAssigned(num, input.centroidName);
                                                            return (
                                                                <MenuItem
                                                                    key={num}
                                                                    value={num}
                                                                    sx={{
                                                                        color: isAssigned ? 'text.disabled' : 'text.primary',
                                                                        fontStyle: isAssigned ? 'italic' : 'normal'
                                                                    }}
                                                                >
                                                                    {num}{isAssigned ? ' (in use)' : ''}
                                                                </MenuItem>
                                                            );
                                                        })}
                                                    </Select>
                                                </Box>

                                                {/* Input Name */}
                                                <Box sx={{ flex: '0 0 250px' }}>
                                                    <SymbolNameWithUsageTooltip
                                                        centroidName={input.centroidName}
                                                        programType={PLCProgramType.System}
                                                    >
                                                        <Typography variant="body1" sx={{ fontWeight: 500 }}>
                                                            {input.name}
                                                        </Typography>
                                                    </SymbolNameWithUsageTooltip>
                                                </Box>

                                                {/* Current State */}
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flex: '0 0 200px' }}>
                                                    <Typography variant="body2" color="textSecondary">
                                                        Current:
                                                    </Typography>
                                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                                        {/* Status Circle */}
                                                        <Box
                                                            sx={{
                                                                width: 10,
                                                                height: 10,
                                                                borderRadius: '50%',
                                                                backgroundColor: displayState ? ConfigurationDataColors.Instance.successColor : ConfigurationDataColors.Instance.errorColor
                                                            }}
                                                        />
                                                        <Typography
                                                            variant="body2"
                                                            sx={{
                                                                fontWeight: 'bold',
                                                                color: displayState ? 'success.main' : 'error.main'
                                                            }}
                                                        >
                                                            {displayState ? 'Active' : 'Inactive'}
                                                        </Typography>
                                                    </Box>
                                                    {input.isInverted && (
                                                        <Typography variant="body2" color="textSecondary" sx={{ fontStyle: 'italic' }}>
                                                            (inverted)
                                                        </Typography>
                                                    )}
                                                </Box>

                                                {/* Equals Sign */}
                                                <Typography variant="body2" color="textSecondary">
                                                    =
                                                </Typography>

                                                {/* State Text Dropdown */}
                                                <Select
                                                    size="small"
                                                    value={displayState ? 'active' : 'inactive'}
                                                    onChange={(e) => {
                                                        // When user changes the dropdown, toggle the inverted flag
                                                        // If current display is active and they select inactive text, invert it
                                                        // If current display is inactive and they select active text, invert it
                                                        const selectedValue = e.target.value;
                                                        const shouldBeActive = selectedValue === 'active';

                                                        // If the desired display state doesn't match current display state,
                                                        // we need to toggle inversion
                                                        if (shouldBeActive !== displayState) {
                                                            input.isInverted = !input.isInverted;
                                                            StateManager.propertyChanged(plcProgram, 'inputs');
                                                        }
                                                    }}
                                                    sx={{ flex: 1, minWidth: 200 }}
                                                >
                                                    <MenuItem value="active">{input.activeText}</MenuItem>
                                                    <MenuItem value="inactive">{input.inactiveText}</MenuItem>
                                                </Select>

                                                {/* Actions */}
                                                <Box sx={{ display: 'flex', gap: 1 }}>
                                                    <IconButton
                                                        size="small"
                                                        onClick={() => {
                                                            setEditingInput(input);
                                                            setDialogOpen(true);
                                                        }}
                                                        title="Edit input"
                                                    >
                                                        <EditIcon fontSize="small" />
                                                    </IconButton>
                                                    <IconButton
                                                        size="small"
                                                        onClick={() => handleDeleteInput(input)}
                                                        title="Delete input"
                                                    >
                                                        <DeleteIcon fontSize="small" />
                                                    </IconButton>
                                                </Box>
                                            </Paper>
                                        );
                                    })
                                )}
                            </Box>
                        </Box>

                        <InputDialog
                            open={dialogOpen}
                            input={editingInput}
                            availableInputs={availableInputs}
                            onClose={() => {
                                setDialogOpen(false);
                                setEditingInput(null);
                            }}
                            onSave={() => {
                                setEditingInput(null);
                            }}
                        />
                    </Box>
                );
            }}
        />
    );
}
