import { ArrowDownward, ArrowUpward } from '@mui/icons-material';
import { Box, Button, FormControl, FormControlLabel, Grid, InputLabel, MenuItem, Select, Switch, ToggleButton, ToggleButtonGroup, Typography } from '@mui/material';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { HomingDirection } from '../../../../data/Machine/HomingDirection';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';

export function HomingSection() {
    const machine = MachineData.Instance;

    // Parse homing order string into array
    const getHomingOrderArray = (machine: MachineData): string[] => {
        return machine.homingOrder.split(',').map(s => s.trim().toUpperCase()).filter(s => s.length > 0);
    };

    // Get homing direction for a specific axis
    const getAxisHomingDirection = (machine: MachineData, axis: string): HomingDirection => {
        switch (axis.toUpperCase()) {
            case 'X': return machine.xHomingDirection;
            case 'Y': return machine.yHomingDirection;
            case 'Z': return machine.zHomingDirection;
            default: return HomingDirection.Negative;
        }
    };

    // Set homing direction for a specific axis
    const setAxisHomingDirection = (machine: MachineData, axis: string, direction: HomingDirection) => {
        switch (axis.toUpperCase()) {
            case 'X': machine.xHomingDirection = direction; break;
            case 'Y': machine.yHomingDirection = direction; break;
            case 'Z': machine.zHomingDirection = direction; break;
        }
    };

    // Update homing order from array
    const setHomingOrderArray = (machine: MachineData, order: string[]) => {
        machine.homingOrder = order.join(',');
    };

    // Move axis up in homing order
    const moveAxisUp = (machine: MachineData, index: number) => {
        if (index <= 0) return;
        const order = getHomingOrderArray(machine);
        [order[index - 1], order[index]] = [order[index], order[index - 1]];
        setHomingOrderArray(machine, order);
    };

    // Move axis down in homing order
    const moveAxisDown = (machine: MachineData, index: number) => {
        const order = getHomingOrderArray(machine);
        if (index >= order.length - 1) return;
        [order[index], order[index + 1]] = [order[index + 1], order[index]];
        setHomingOrderArray(machine, order);
    };

    return (
        <Grid container spacing={3}>
            <Grid item xs={12}>
                <SetupChecklistIndicator name="Homing Configuration" />
            </Grid>

            {/* Homing Order */}
            <Grid item xs={12}>
                <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Homing Order</Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    Specify the order in which axes are homed. Use up/down buttons to reorder.
                </Typography>
            </Grid>

            <Grid item xs={12}>
                <ObserveState
                    key="homing-order-list"
                    listenTo={machine}
                    properties={['homingOrder', 'xHomingDirection', 'yHomingDirection', 'zHomingDirection']}
                    control={() => (
                        <>
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, maxWidth: 600 }}>
                                {getHomingOrderArray(machine).map((axis, index) => (
                                    <Box
                                        key={index}
                                        sx={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: 2,
                                            p: 2,
                                            backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor,
                                            borderRadius: 1,
                                            border: `1px solid ${ConfigurationDataColors.Instance.borderColor}`
                                        }}
                                    >
                                        <Typography sx={{ fontWeight: 'bold', minWidth: 30 }}>
                                            {index + 1}.
                                        </Typography>
                                        <Typography sx={{ flex: 1, fontSize: '1.1rem', fontWeight: 'bold' }}>
                                            {axis} Axis
                                        </Typography>
                                        <Box sx={{ display: 'flex', gap: 1 }}>
                                            <Button
                                                size="small"
                                                variant="outlined"
                                                onClick={() => moveAxisUp(machine, index)}
                                                disabled={index === 0}
                                                sx={{ minWidth: 40 }}
                                            >
                                                <ArrowUpward fontSize="small" />
                                            </Button>
                                            <Button
                                                size="small"
                                                variant="outlined"
                                                onClick={() => moveAxisDown(machine, index)}
                                                disabled={index === getHomingOrderArray(machine).length - 1}
                                                sx={{ minWidth: 40 }}
                                            >
                                                <ArrowDownward fontSize="small" />
                                            </Button>
                                        </Box>
                                        <ToggleButtonGroup
                                            value={getAxisHomingDirection(machine, axis)}
                                            exclusive
                                            onChange={(e, value) => { if (value !== null) setAxisHomingDirection(machine, axis, value); }}
                                            size="small"
                                        >
                                            <ToggleButton
                                                value={HomingDirection.Negative}
                                                sx={{
                                                    px: 2,
                                                    '&.Mui-selected': {
                                                        backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                                                        color: ConfigurationDataColors.Instance.lightTextColor,
                                                        '&:hover': {
                                                            backgroundColor: ConfigurationDataColors.Instance.primaryColor
                                                        }
                                                    }
                                                }}
                                            >
                                                Minus (-)
                                            </ToggleButton>
                                            <ToggleButton
                                                value={HomingDirection.Positive}
                                                sx={{
                                                    px: 2,
                                                    '&.Mui-selected': {
                                                        backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                                                        color: ConfigurationDataColors.Instance.lightTextColor,
                                                        '&:hover': {
                                                            backgroundColor: ConfigurationDataColors.Instance.primaryColor
                                                        }
                                                    }
                                                }}
                                            >
                                                Plus (+)
                                            </ToggleButton>
                                        </ToggleButtonGroup>
                                    </Box>
                                ))}
                            </Box>
                            <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                                Default: Z first for safety (prevents collisions)
                            </Typography>
                        </>
                    )}
                />
            </Grid>

            {/* Homing Speeds */}
            <Grid item xs={12}>
                <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Homing Speeds</Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    Configure homing speeds for XY and Z axes (in/min or mm/min depending on unit setting)
                </Typography>
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="homing-xy-speed"
                    listenTo={machine}
                    properties={['xyHomingSpeed']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="XY Homing Speed"
                                value={machine.xyHomingSpeed}
                                onChange={(value) => machine.xyHomingSpeed = value}
                                margin="normal"
                                precision={0}
                                min={1}
                                max={500}
                            />
                            <Typography variant="caption" color="text.secondary">
                                Homing speed for X and Y axes (default: 100 in/min)
                            </Typography>
                        </>
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="homing-z-speed"
                    listenTo={machine}
                    properties={['zHomingSpeed']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="Z Homing Speed"
                                value={machine.zHomingSpeed}
                                onChange={(value) => machine.zHomingSpeed = value}
                                margin="normal"
                                precision={0}
                                min={1}
                                max={500}
                            />
                            <Typography variant="caption" color="text.secondary">
                                Homing speed for Z axis (default: 50 in/min)
                            </Typography>
                        </>
                    )}
                />
            </Grid>

            {/* Auto-Square Configuration */}
            <Grid item xs={12}>
                <Typography variant="subtitle1" sx={{ mt: 3, mb: 1 }}>Auto-Square Configuration</Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    For gantry machines with paired/slaved axes (e.g., dual Y motors), enable auto-squaring to ensure both sides home accurately
                </Typography>
            </Grid>

            <Grid item xs={12}>
                <ObserveState
                    key="homing-auto-square-enabled"
                    listenTo={machine}
                    properties={['enableAutoSquare']}
                    control={() => (
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={machine.enableAutoSquare}
                                    onChange={(e) => machine.enableAutoSquare = e.target.checked}
                                />
                            }
                            label="Enable Auto-Square for Paired Axes"
                        />
                    )}
                />
            </Grid>

            {machine.enableAutoSquare && (
                <>
                    <Grid item xs={12} md={6}>
                        <ObserveState
                            key="homing-auto-square-axis"
                            listenTo={machine}
                            properties={['autoSquareMasterAxis']}
                            control={() => (
                                <>
                                    <FormControl fullWidth margin="normal">
                                        <InputLabel>Auto-Square Master Axis</InputLabel>
                                        <Select
                                            value={machine.autoSquareMasterAxis}
                                            onChange={(e) => machine.autoSquareMasterAxis = e.target.value}
                                        >
                                            <MenuItem value="X">X Axis (Dual X motors)</MenuItem>
                                            <MenuItem value="Y">Y Axis (Dual Y motors - most common)</MenuItem>
                                            <MenuItem value="Z">Z Axis (Dual Z motors)</MenuItem>
                                        </Select>
                                    </FormControl>
                                    <Typography variant="caption" color="text.secondary">
                                        Select which axis has paired/slaved motors that need squaring
                                    </Typography>
                                </>
                            )}
                        />
                    </Grid>

                    <Grid item xs={12} md={6}>
                        <ObserveState
                            key="homing-auto-square-distance"
                            listenTo={machine}
                            properties={['autoSquareDistance']}
                            control={() => (
                                <>
                                    <NumberInput
                                        fullWidth
                                        label="Auto-Square Distance"
                                        value={machine.autoSquareDistance}
                                        onChange={(value) => machine.autoSquareDistance = value}
                                        margin="normal"
                                        precision={3}
                                        min={0.1}
                                        max={2.0}
                                    />
                                    <Typography variant="caption" color="text.secondary">
                                        Distance to back off for squaring operation (default: 0.5 inches)
                                    </Typography>
                                </>
                            )}
                        />
                    </Grid>
                </>
            )}
        </Grid>
    );
}
