import React from 'react';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { Condition } from './Condition';
import { ConditionFactory } from './ConditionFactory';
import { DataElement } from './DataElement';
import { Declaration } from './Declaration';
import { IPLCElement, PLCRenderMode, PLCValidationIssue } from './IPLCElement';
import { PLCProgramType, PLCSerializationHelper, PLCUtilities } from './PLCUtilities';

/**
 * Group type enum for combining conditions
 */
export enum GroupType {
    And = 'AND',
    Or = 'OR',
    Xor = 'XOR'
}

/**
 * ConditionGroup class - A condition that contains multiple conditions
 * Supports logical AND, OR, and XOR operations
 */
export class ConditionGroup extends Condition {
    private _groupType: GroupType = GroupType.And;
    private _conditions: Condition[] = [];

    constructor(groupType: GroupType = GroupType.And) {
        super();
        this._groupType = groupType;

        // Set up cache invalidation listener
        PLCUtilities.setupCacheInvalidationListener(this);
    }

    /**
     * Get the type of condition
     */
    public get conditionType(): string {
        return 'ConditionGroup';
    }

    /**
     * Check if this condition group is disabled
     * A ConditionGroup is disabled if:
     * 1. Its enabled property is false, OR
     * 2. ALL of its child conditions are disabled (no enabled conditions)
     */
    public isDisabled(mode: PLCRenderMode, targetProgramType: PLCProgramType): boolean {
        // 1. Check enabled property
        if (!this.enabled) {
            return true;
        }

        // 2. Check if all child conditions are disabled
        // NOTE: An EMPTY group is NOT disabled - it's just empty
        // The parent (LogicStatement) will decide if empty is a problem
        if (this._conditions.length === 0) {
            return false; // Empty group is not disabled
        }

        // If ANY condition is enabled, the group is enabled (not disabled)
        const hasEnabledCondition = this._conditions.some(condition => !condition.isDisabled(mode, targetProgramType));
        return !hasEnabledCondition; // Disabled if NO conditions are enabled
    }

    /**
     * Override getElementType to return 'condition-group' instead of 'condition'
     */
    public getElementType(): 'condition-group' {
        return 'condition-group';
    }

    /**
     * Type of logical grouping (AND, OR, XOR)
     */
    public get groupType(): GroupType {
        return this._groupType;
    }

    public set groupType(value: GroupType) {
        this._groupType = value;
        StateManager.propertyChanged(this, 'groupType');
    }

    /**
     * Array of conditions in this group
     */
    public get conditions(): Condition[] {
        return [...this._conditions];
    }

    /**
     * Add a condition to the group
     */
    public addCondition(condition: Condition): void {
        this._conditions.push(condition);
        condition.setParentElement(this);
        StateManager.propertyChanged(this, 'conditions');
    }

    /**
     * Remove a condition from the group
     */
    public removeCondition(condition: Condition): void {
        const index = this._conditions.indexOf(condition);
        if (index !== -1) {
            this._conditions.splice(index, 1);
            StateManager.propertyChanged(this, 'conditions');
        }
    }

    /**
     * Insert a condition at a specific index
     */
    public insertCondition(index: number, condition: Condition): void {
        if (index >= 0 && index <= this._conditions.length) {
            this._conditions.splice(index, 0, condition);
            condition.setParentElement(this);
            StateManager.propertyChanged(this, 'conditions');
        }
    }

    /**
     * Clear all conditions from the group
     */
    public clearConditions(): void {
        this._conditions = [];
        StateManager.propertyChanged(this, 'conditions');
    }

    /**
     * Get condition at index
     */
    public getCondition(index: number): Condition | undefined {
        return this._conditions[index];
    }

    /**
     * Get number of conditions in the group
     */
    public get conditionCount(): number {
        return this._conditions.length;
    }

    /**
     * Render the condition group to JSX
     * @param mode Rendering mode (Edit, ReadOnly, or Disabled)
     * @param targetProgramType The program type context for rendering
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        return (
            <div className="plc-condition-group">
                <div className="condition-group-header">
                    <span className="group-type">{this._groupType}</span>
                    {this.comment && <span className="comment"> - {this.comment}</span>}
                </div>
                <div className="condition-group-content">
                    {this._conditions.map((condition, index) => (
                        <div key={index} className="condition-item">
                            {condition.render(mode, targetProgramType)}
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    /**
     * Get declarations that are used/referenced by this group and its conditions
     */
    public getUsedDeclarations(): Declaration[] {
        const allDeclarations = this._conditions.flatMap(condition => condition.getUsedDeclarations());
        // Remove duplicates by name
        const uniqueMap = new Map<string, Declaration>();
        for (const decl of allDeclarations) {
            uniqueMap.set(decl.name, decl);
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Get declarations that are added/defined by this group and its conditions
     */
    public getAddedDeclarations(): Declaration[] {
        const allDeclarations = this._conditions.flatMap(condition => condition.getAddedDeclarations());
        // Remove duplicates by name
        const uniqueMap = new Map<string, Declaration>();
        for (const decl of allDeclarations) {
            uniqueMap.set(decl.name, decl);
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Get the PLC logic code for this condition group
     * Returns a boolean expression string with proper grouping
     * @param availableDeclarations Not used for conditions - required by IPLCElement interface
     */
    public getPLCLogic(availableDeclarations: string[]): string[] {
        // PLC logic generation is ALWAYS for System.plc context
        const targetProgramType = PLCProgramType.System;

        // Check if this group is disabled in the target program type context
        if (this.isDisabled(PLCRenderMode.Edit, targetProgramType)) {
            return []; // Disabled groups don't contribute
        }

        // Get expressions from all enabled conditions
        const conditionExpressions: string[] = [];
        for (const condition of this._conditions.filter(c => !c.isDisabled(PLCRenderMode.Edit, targetProgramType))) {
            const logic = condition.getPLCLogic(availableDeclarations);
            if (logic.length > 0) {
                conditionExpressions.push(logic.join(' '));
            }
        }

        // If no conditions, return empty
        if (conditionExpressions.length === 0) {
            return [];
        }

        // Single condition - just return it (no extra parens needed)
        if (conditionExpressions.length === 1) {
            return [conditionExpressions[0]];
        }

        // Multiple conditions - join with appropriate operator
        let operator: string;
        switch (this._groupType) {
            case GroupType.And:
                operator = ' && ';
                break;
            case GroupType.Or:
                operator = ' || ';
                break;
            case GroupType.Xor:
                // XOR is not directly supported in boolean expressions
                // Use: (A || B) && !(A && B) pattern for two conditions
                if (conditionExpressions.length === 2) {
                    return [`(${conditionExpressions[0]} || ${conditionExpressions[1]}) && !(${conditionExpressions[0]} && ${conditionExpressions[1]})`];
                }
                // For more than 2, fall back to OR with comment
                operator = ' || '; // TODO: XOR with multiple conditions
                break;
            default:
                operator = ' && ';
        }

        // Join expressions with operator and wrap in parentheses
        const joined = conditionExpressions.join(operator);
        return [`(${joined})`];
    }

    /**
     * Get all data elements used by conditions in this group
     */
    public getDataElements(): DataElement[] {
        const elements: DataElement[] = [];
        for (const condition of this._conditions) {
            elements.push(...condition.getDataElements());
        }
        return elements;
    }

    /**
     * Get validation issues for this group and its conditions
     */
    public getValidationIssues(): PLCValidationIssue[] {
        const issues: PLCValidationIssue[] = [];

        // Validate group-level issues
        if (this._conditions.length === 0) {
            issues.push(new PLCValidationIssue(this, 'Condition group has no conditions'));
        }

        // Condition groups with one statement are valid - removed invalid validation

        // Collect validation issues from conditions with context
        for (let i = 0; i < this._conditions.length; i++) {
            const condition = this._conditions[i];
            const conditionIssues = condition.getValidationIssues();
            conditionIssues.forEach(issue => {
                const prefix = this._conditions.length > 1 ? `[Condition ${i + 1}] ` : '[Condition] ';
                issues.push(new PLCValidationIssue(issue.element, `${prefix}${issue.message}`));
            });
        }

        return issues;
    }

    /**
     * Override setParentElement to cascade to all child conditions
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        super.setParentElement(parent);
        // Cascade to all child conditions
        for (const condition of this._conditions) {
            condition.setParentElement(this);
        }
    }

    /**
     * Get a short, single-line description of this condition group for display in tree views
     * Example: "(havenreset is set AND spindle_speed > 100)" or "(input1 is set OR input2 is set)"
     * @returns A human-readable summary of the condition group
     */
    public getShortDescription(): string {
        // Get descriptions from all enabled conditions
        const conditionDescriptions = this._conditions
            .filter(c => c.enabled)
            .map(c => c.getShortDescription())
            .filter(desc => desc.length > 0);

        // If no conditions, return placeholder
        if (conditionDescriptions.length === 0) {
            return '(empty group)';
        }

        // Single condition - just return it (no extra parens needed)
        if (conditionDescriptions.length === 1) {
            return conditionDescriptions[0];
        }

        // Multiple conditions - join with appropriate operator
        let operator: string;
        switch (this._groupType) {
            case GroupType.And:
                operator = ' AND ';
                break;
            case GroupType.Or:
                operator = ' OR ';
                break;
            case GroupType.Xor:
                operator = ' XOR ';
                break;
            default:
                operator = ' AND ';
        }

        // Join descriptions with operator and wrap in parentheses
        const joined = conditionDescriptions.join(operator);
        return `(${joined})`;
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): any {
        const data: any = PLCSerializationHelper.getStorageData(this, ['_conditions']);
        data.conditionType = this.conditionType;
        data.conditions = this._conditions.map(condition => condition.toJSON());
        return data;
    }
    /**
     * Load from JSON
     */
    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['_conditions', 'conditions', 'conditionType']);

        // Use ConditionFactory to deserialize conditions - support both old and new property names
        const conditionsData = data._conditions || data.conditions;
        if (conditionsData && Array.isArray(conditionsData)) {
            this._conditions = [];
            conditionsData.forEach((conditionData) => {
                // Create instance
                const condition = ConditionFactory.createConditionFromJSON(conditionData);
                // Deserialize
                condition.fromJSON(conditionData);
                // Set parent (parent chain handles plcSource resolution)
                condition.setParentElement(this);
                this._conditions.push(condition);
            });

            // Validate deserialization count
            if (this._conditions.length !== conditionsData.length) {
                const error = `ConditionGroup deserialization error: Expected ${conditionsData.length} conditions but got ${this._conditions.length}`;
                console.error(error, '\nJSON data:', JSON.stringify(data, null, 2));
                throw new Error(error);
            }
        }
    }
}
