import {
    Box,
    Button,
    FormControl,
    FormControlLabel,
    Grid,
    InputLabel,
    MenuItem,
    Paper,
    Select,
    Switch,
    TextField,
    ToggleButton,
    ToggleButtonGroup,
    Typography
} from '@mui/material';
import { useEffect, useState } from 'react';
import { MachineNameAndBoardChecklistItem } from '../../../../data/Checklist/MachineNameAndBoardChecklistItem';
import { SetupChecklistLibrary } from '../../../../data/Checklist/SetupChecklistLibrary';
import { UnitOfMeasure } from '../../../../data/Common/UnitOfMeasure';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { DataManager } from '../../../../data/DataManager';
import { BoardType } from '../../../../data/Machine/BoardType';
import { MachineData } from '../../../../data/Machine/MachineData';
import { XDirection } from '../../../../data/Machine/XDirection';
import { ZZeroLocation } from '../../../../data/Machine/ZZeroLocation';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { Machine } from '../../../../machine/Machine';
import { ConfirmDialogManager } from '../../../../utils/ConfirmDialogManager';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';

export function GeneralSection() {
    const colors = ConfigurationDataColors.Instance;
    // Machine selection state
    const [availableMachines, setAvailableMachines] = useState<string[]>([]);
    const [currentMachine, setCurrentMachine] = useState<string>('');
    const [customMachineName, setCustomMachineName] = useState<string>('');
    const [isCustomMachine, setIsCustomMachine] = useState(false);
    const [loadingMachines, setLoadingMachines] = useState(false);
    const [machineNameError, setMachineNameError] = useState<string>('');

    // Initialize checklist item on mount
    useEffect(() => {
        const library = SetupChecklistLibrary.Instance;
        const checklistItemName = 'Machine Name and Board Type';

        // Only add if not already present
        if (!library.getItemByName(checklistItemName)) {
            const checklistItem = new MachineNameAndBoardChecklistItem();
            library.addItem(checklistItem);
        }
    }, []);

    // Load available machines on mount
    useEffect(() => {
        const loadMachines = async () => {
            try {
                const machines = await Machine.getInstance().setup.GetMachineNames();
                const current = await Machine.getInstance().setup.GetCurrentMachineName();
                setAvailableMachines(machines);
                setCurrentMachine(current || '');

                // If no current machine set, show error
                if (!current || current.trim() === '') {
                    setMachineNameError('Machine name is required');
                }
            } catch (error) {
                Logger.Instance.logError(LogCategory.System, 'Failed to load machine names:', error);
            }
        };
        loadMachines();
    }, []);

    // Handle machine selection change
    const handleMachineChange = async (machineName: string, isNewMachine: boolean = false) => {
        if (loadingMachines) return;

        const operation = ConfigurationState.Instance.startLongRunningOperation(
            isNewMachine ? 'Initializing New Machine' : 'Switching Machine',
            `Setting machine to "${machineName}"...`
        );

        try {
            setLoadingMachines(true);
            setMachineNameError('');

            await Machine.getInstance().setup.SetCurrentMachine(machineName);

            // Refresh the machine names list so new machines appear in the dropdown immediately
            const updatedMachines = await Machine.getInstance().setup.GetMachineNames();
            setAvailableMachines(updatedMachines);

            // New machine: reset all manually-confirmed checklist items so the
            // checklist starts fresh for the new machine's configuration.
            if (isNewMachine) {
                SetupChecklistLibrary.Instance.resetAllManualConfirmations();
            }

            ConfigurationState.Instance.updateLongRunningOperationMessage('Reloading all data from backend...');
            await DataManager.Instance.reloadAllData();

            setCurrentMachine(machineName);
            setIsCustomMachine(false);
            setCustomMachineName('');

            const action = isNewMachine ? 'initialized' : 'loaded';
            UserMessageQueue.Instance.addMessage(
                `✓ Machine "${machineName}" ${action}. To reset data for this machine, go to Settings → Data Reset.`
            );
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to change machine:', error);
            UserMessageQueue.Instance.addMessage(`❌ Failed to switch machine: ${error}`);
        } finally {
            ConfigurationState.Instance.completeLongRunningOperation();
            setLoadingMachines(false);
        }
    };

    // Handle custom machine name save
    const handleSaveCustomMachine = async () => {
        const machineName = customMachineName.trim();

        if (!machineName) {
            setMachineNameError('Machine name cannot be empty');
            return;
        }

        if (machineName.length < 3) {
            setMachineNameError('Machine name must be at least 3 characters');
            return;
        }

        const confirmed = await ConfirmDialogManager.Instance.showConfirm({
            title: 'Initialize New Machine',
            message: `Creating a new machine "${machineName}" will initialize a fresh configuration and reload all data from the backend.\n\nTo reset specific data (PLC programs, tools, fixtures, materials, etc.), go to Settings → Data Reset after initialization.\n\nThis cannot be undone.`,
            confirmText: 'Initialize Machine',
            severity: 'warning',
        });

        if (!confirmed) return;

        await handleMachineChange(machineName, true);
    };

    // Toggle between dropdown and custom input
    const handleToggleCustomMachine = () => {
        setIsCustomMachine(!isCustomMachine);
        setCustomMachineName('');
        setMachineNameError('');
    };

    return (
        <Grid container spacing={3}>
            {/* Checklist Indicators */}
            <Grid item xs={12}>
                <SetupChecklistIndicator name="Machine Name and Board Type" />
            </Grid>
            <Grid item xs={12}>
                <SetupChecklistIndicator name="Turn Off Test Mode" />
            </Grid>

            {/* Left: Machine Name */}
            <Grid item xs={12} md={6}>
                <Paper sx={{ p: 3, height: '100%' }}>
                    <Typography variant="h6" gutterBottom>Machine Name</Typography>

                    {!isCustomMachine ? (
                        <>
                            <FormControl
                                fullWidth
                                disabled={loadingMachines}
                                error={!!machineNameError && !currentMachine}
                            >
                                <InputLabel>Select Machine</InputLabel>
                                <Select
                                    value={currentMachine}
                                    onChange={(e) => handleMachineChange(e.target.value)}
                                    label="Select Machine"
                                >
                                    {availableMachines.map(machine => (
                                        <MenuItem key={machine} value={machine}>{machine}</MenuItem>
                                    ))}
                                </Select>
                            </FormControl>
                            {machineNameError && !currentMachine && (
                                <Typography variant="caption" color="error" sx={{ mt: 1, display: 'block' }}>
                                    {machineNameError}
                                </Typography>
                            )}
                        </>
                    ) : (
                        <>
                            <TextField
                                fullWidth
                                label="New Machine Name"
                                value={customMachineName}
                                onChange={(e) => {
                                    setCustomMachineName(e.target.value);
                                    setMachineNameError('');
                                }}
                                onKeyPress={(e) => {
                                    if (e.key === 'Enter') {
                                        handleSaveCustomMachine();
                                    }
                                }}
                                error={!!machineNameError}
                                helperText={machineNameError || 'Enter a name for the new machine configuration'}
                                disabled={loadingMachines}
                            />
                            <Button
                                variant="contained"
                                onClick={handleSaveCustomMachine}
                                disabled={loadingMachines || !customMachineName.trim()}
                                fullWidth
                                sx={{ mt: 2 }}
                            >
                                Save New Machine
                            </Button>
                        </>
                    )}

                    <Button
                        variant="text"
                        onClick={handleToggleCustomMachine}
                        disabled={loadingMachines}
                        fullWidth
                        sx={{ mt: 2 }}
                    >
                        {isCustomMachine ? 'Select Existing Machine' : 'Create New Machine'}
                    </Button>

                    <Typography variant="caption" color="text.secondary" sx={{ mt: 2, display: 'block' }}>
                        {isCustomMachine
                            ? 'Enter a unique name for this machine configuration.'
                            : 'Select from existing machines or create a new one. Changing machines will reload all data.'
                        }
                    </Typography>
                </Paper>
            </Grid>

            {/* Right: Board Configuration */}
            <Grid item xs={12} md={6}>
                <Paper sx={{ p: 3, height: '100%' }}>
                    <Typography variant="h6" gutterBottom>Control Board Setup</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                        Configure the CNC control board type and expansion boards.
                        This determines available I/O ports and features.
                    </Typography>

                    <ObserveState
                        key="board-configuration-observer"
                        listenTo={MachineData.Instance}
                        properties={['boardType', 'expansionBoardCount']}
                        control={() => {
                            const machine = MachineData.Instance;
                            return (
                                <Box>
                                    <FormControl fullWidth sx={{ mb: 2 }}>
                                        <InputLabel>Board Type</InputLabel>
                                        <Select
                                            value={machine.boardType}
                                            onChange={(e) => machine.boardType = e.target.value as BoardType}
                                            label="Board Type"
                                        >
                                            <MenuItem value={BoardType.Acorn}>Acorn</MenuItem>
                                            <MenuItem value={BoardType.Acorn6}>Acorn6</MenuItem>
                                            <MenuItem value={BoardType.Oak}>Oak</MenuItem>
                                            <MenuItem value={BoardType.Hickory}>Hickory</MenuItem>
                                            <MenuItem value={BoardType.Allin1DC}>Allin1DC</MenuItem>
                                        </Select>
                                    </FormControl>

                                    <Box>
                                        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                                            Expansion Boards
                                        </Typography>
                                        <ToggleButtonGroup
                                            value={machine.expansionBoardCount}
                                            exclusive
                                            onChange={(e, value) => {
                                                if (value !== null) {
                                                    machine.expansionBoardCount = value;
                                                }
                                            }}
                                            fullWidth
                                            sx={{
                                                mb: 0.5,
                                                '& .MuiToggleButton-root.Mui-selected': {
                                                    backgroundColor: colors.primaryColor,
                                                    color: colors.lightTextColor,
                                                    '&:hover': {
                                                        backgroundColor: colors.primaryColor,
                                                        opacity: 0.9
                                                    }
                                                }
                                            }}
                                        >
                                            <ToggleButton value={0}>0</ToggleButton>
                                            <ToggleButton value={1}>1</ToggleButton>
                                            <ToggleButton value={2}>2</ToggleButton>
                                            <ToggleButton value={3}>3</ToggleButton>
                                            <ToggleButton value={4}>4</ToggleButton>
                                        </ToggleButtonGroup>
                                        <Typography variant="caption" color="text.secondary">
                                            Number of expansion boards connected
                                        </Typography>
                                    </Box>
                                </Box>
                            );
                        }}
                    />
                </Paper>
            </Grid>

            {/* Bottom: Coordinate System Settings */}
            <Grid item xs={12}>
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>Coordinate System Settings</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        General machine configuration settings that apply globally to all machine operations.
                        These settings define the fundamental coordinate system orientation and units of measurement.
                    </Typography>

                    <Grid container spacing={3}>
                        <Grid item xs={12} md={6}>
                            <ObserveState
                                key="general-unit-of-measure"
                                listenTo={MachineData.Instance}
                                properties={['unitOfMeasure']}
                                control={() => (
                                    <FormControl fullWidth margin="normal">
                                        <InputLabel>Unit of Measure</InputLabel>
                                        <Select
                                            value={MachineData.Instance.unitOfMeasure}
                                            onChange={(e) => MachineData.Instance.unitOfMeasure = e.target.value as UnitOfMeasure}
                                        >
                                            <MenuItem value={UnitOfMeasure.Inches}>Inches</MenuItem>
                                            <MenuItem value={UnitOfMeasure.Millimeters}>Millimeters</MenuItem>
                                        </Select>
                                    </FormControl>
                                )}
                            />

                            <ObserveState
                                key="general-z-location"
                                listenTo={MachineData.Instance}
                                properties={['zLocation']}
                                control={() => (
                                    <FormControl fullWidth margin="normal">
                                        <InputLabel>Z Zero Location</InputLabel>
                                        <Select
                                            value={MachineData.Instance.zLocation}
                                            onChange={(e) => MachineData.Instance.zLocation = e.target.value as ZZeroLocation}
                                        >
                                            <MenuItem value={ZZeroLocation.Top}>Top</MenuItem>
                                            <MenuItem value={ZZeroLocation.Bed}>Bed</MenuItem>
                                        </Select>
                                    </FormControl>
                                )}
                            />
                        </Grid>

                        <Grid item xs={12} md={6}>
                            <ObserveState
                                key="general-x-direction"
                                listenTo={MachineData.Instance}
                                properties={['xDirection']}
                                control={() => (
                                    <FormControl fullWidth margin="normal">
                                        <InputLabel>X Direction</InputLabel>
                                        <Select
                                            value={MachineData.Instance.xDirection}
                                            onChange={(e) => MachineData.Instance.xDirection = e.target.value as XDirection}
                                        >
                                            <MenuItem value={XDirection.Across}>Across</MenuItem>
                                            <MenuItem value={XDirection.Side}>Side</MenuItem>
                                        </Select>
                                    </FormControl>
                                )}
                            />
                        </Grid>
                    </Grid>
                </Paper>
            </Grid>

            {/* G-Code Settings */}
            <Grid item xs={12}>
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>G-Code Settings</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Configure how G-code programs are handled and executed.
                    </Typography>

                    <ObserveState
                        key="general-preview-gcode"
                        listenTo={ConfigurationData.Instance}
                        properties={['previewGCode']}
                        control={() => (
                            <FormControlLabel
                                control={
                                    <Switch
                                        checked={ConfigurationData.Instance.previewGCode}
                                        onChange={(e) => ConfigurationData.Instance.previewGCode = e.target.checked}
                                    />
                                }
                                label="Preview G-Code Before Execution"
                            />
                        )}
                    />
                    <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                        When enabled, displays a preview dialog before running G-code programs, allowing you to review the code and make any necessary adjustments.
                    </Typography>
                </Paper>
            </Grid>
        </Grid>
    );
}
