  async IsConnectedToServer(): Promise<boolean> {
    try {

      // Check both API connection and SignalR connection
      const apiResponse = await this.api.apiCNCSystemIsConnectedToCentroidGet();

      // The API might return the boolean directly or wrapped in .data
      const isApiConnected = apiResponse === true || (apiResponse as any).data === true;

      const isSignalRConnected = SignalRStateData.Instance.isConnected;

      const bothConnected = isApiConnected && isSignalRConnected;

      // Return true only if both connections are established
      return bothConnected;
    } catch (error) {
      Logger.Instance.logError(LogCategory.Network, 'Error checking server connection:', error);

      // Log detailed error information
      if (error && typeof error === 'object') {
        Logger.Instance.logError(LogCategory.Network, 'Error details:', {
          message: (error as any).message,
          status: (error as any).status,
          response: (error as any).response
        });
      }

      // If API call fails, we're definitely not connected
      return false;
    }
  }

