import { Grid, Typography } from '@mui/material';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';

export function BedSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
                <ObserveState
                    key="bed-width"
                    listenTo={machine}
                    properties={['bedWidth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Bed Width"
                            value={machine.bedWidth}
                            onChange={(value) => machine.bedWidth = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />

                <ObserveState
                    key="bed-length"
                    listenTo={machine}
                    properties={['bedLength']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Bed Length"
                            value={machine.bedLength}
                            onChange={(value) => machine.bedLength = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />

                <ObserveState
                    key="bed-height"
                    listenTo={machine}
                    properties={['bedHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Bed Height"
                            value={machine.bedHeight}
                            onChange={(value) => machine.bedHeight = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="bed-offset-x"
                    listenTo={machine}
                    properties={['bedOffsetX']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="Bed Offset X"
                                value={machine.bedOffsetX}
                                onChange={(value) => machine.bedOffsetX = value}
                                margin="normal"
                                precision={3}
                            />
                            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
                                X-axis offset for bed positioning relative to base
                            </Typography>
                        </>
                    )}
                />

                <ObserveState
                    key="bed-offset-y"
                    listenTo={machine}
                    properties={['bedOffsetY']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="Bed Offset Y"
                                value={machine.bedOffsetY}
                                onChange={(value) => machine.bedOffsetY = value}
                                margin="normal"
                                precision={3}
                            />
                            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
                                Y-axis offset for bed positioning relative to base
                            </Typography>
                        </>
                    )}
                />
            </Grid>
        </Grid>
    );
}
