import { CameraTarget, CNCViewType } from '../components/MachineViewer/CNCViewer';
import { SimulatorView } from '../data/Common/SimulatorView';
import { SimulatorViewData } from '../data/Common/SimulatorViewData';
import { ViewStyle } from '../data/Common/ViewStyle';

/**
 * Centralized view names - single source of truth for all viewer contexts
 */
export const ViewNames = {
    HOME: 'home',
    MATERIAL_EDITOR: 'materialEditor',
    CLAMP_EDITOR: 'clampEditor',
    GCODE_STAGE: 'gcodeStage',
    CONFIRM_RUN_STAGE: 'confirmRunStage',
    SETUP_JOB_STAGE: 'setupJobStage',
    SIMULATOR_DIALOG: 'simulatorDialog',
    MACHINE_SETTINGS: 'machineSettings',
    SPINDLE_WIZARD: 'spindleWizard',
    FIXTURE_SELECTION: 'fixtureSelection',
    FLOATING_VIEWER: 'floatingViewer',
    CLAMP_TOP_EDITOR: 'clampTopEditor',
    JOB_RUN_DIALOG: 'jobRunDialog'
} as const;

/**
 * Factory for creating SimulatorViewData instances with appropriate configuration
 * Each factory method configures behavior properties and optionally loads saved camera/visibility settings
 */
export class ViewDataFactory {
    /**
     * Create view data for a specific context
     */
    static createForContext(viewName: string): SimulatorViewData {
        switch (viewName) {
            case ViewNames.HOME:
                return this.createHomeView();
            case ViewNames.MATERIAL_EDITOR:
                return this.createMaterialEditorView();
            case ViewNames.CLAMP_EDITOR:
                return this.createClampEditorView();
            case ViewNames.GCODE_STAGE:
                return this.createGCodeStageView();
            case ViewNames.CONFIRM_RUN_STAGE:
                return this.createConfirmRunStageView();
            case ViewNames.SETUP_JOB_STAGE:
                return this.createSetupJobStageView();
            case ViewNames.SIMULATOR_DIALOG:
                return this.createSimulatorDialogView();
            case ViewNames.MACHINE_SETTINGS:
                return this.createMachineSettingsView();
            case ViewNames.SPINDLE_WIZARD:
                return this.createSpindleWizardView();
            case ViewNames.FIXTURE_SELECTION:
                return this.createFixtureSelectionView();
            case ViewNames.FLOATING_VIEWER:
                return this.createFloatingViewerView();
            case ViewNames.CLAMP_TOP_EDITOR:
                return this.createClampTopEditorView();
            case ViewNames.JOB_RUN_DIALOG:
                return this.createJobRunDialogView();
            default:
                return this.createDefaultView();
        }
    }

    /**
     * Home - Main home page viewer
     * - Full control with view type buttons and settings
     * - Can save settings (with callback)
     * - Loads saved camera/visibility if available
     */
    static createHomeView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = true;
        view.showSettingsButton = true;
        view.enableOrbit = true;
        view.enableClampDragging = false;
        view.enableSpindleDrag = true;
        view.isHardcodedSettings = false;
        view.shareVisibilitySettings = false; // Home view keeps independent settings per perspective

        // Default camera/visibility
        view.currentViewType = CNCViewType.Perspective;
        view.cameraTargetMode = CameraTarget.MachineCenter;

        return view;
    }

    /**
     * Material Editor - Material configuration dialog
     * - Simple viewer focused on material
     * - No view switching or settings
     * - Cannot save (always fresh defaults)
     */
    static createMaterialEditorView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = false;
        view.showSettingsButton = false;
        view.enableOrbit = true;
        view.enableClampDragging = false;
        view.enableSpindleDrag = false;
        view.isHardcodedSettings = true;

        // Default camera
        view.currentViewType = CNCViewType.Perspective;
        view.cameraTargetMode = CameraTarget.MachineCenter;

        // Material-focused visibility
        view.perspectiveView.material = ViewStyle.Show;
        view.perspectiveView.spoilBoard = ViewStyle.Show;
        view.perspectiveView.gantry = ViewStyle.SemiTransparent;

        // No save callback - always reset to defaults

        return view;
    }

    /**
     * Clamp Editor - Top-down clamp positioning
     * - Locked to top view
     * - Clamp dragging enabled
     * - Cannot save (always fresh defaults)
     */
    static createClampEditorView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = false;
        view.showSettingsButton = false;
        view.enableOrbit = false;
        view.enableClampDragging = true;
        view.enableSpindleDrag = false;
        view.isHardcodedSettings = true;

        // Top view only
        view.currentViewType = CNCViewType.Top;
        view.cameraTargetMode = CameraTarget.MachineCenter;

        // Top view visibility
        view.topView.gantry = ViewStyle.SemiTransparent;
        view.topView.spindle = ViewStyle.SemiTransparent;

        // No save callback

        return view;
    }

    /**
     * G-Code Stage - Workflow stage 1
     * - Top view for G-code preview
     * - Simple viewer, no settings
     * - Cannot save (always fresh defaults)
     */
    static createGCodeStageView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = false;
        view.showSettingsButton = false;
        view.enableOrbit = true;
        view.enableClampDragging = false;
        view.enableSpindleDrag = false;
        view.isHardcodedSettings = true;

        // Top view
        view.currentViewType = CNCViewType.Top;
        view.cameraTargetMode = CameraTarget.GCodeCenter;

        // G-code focused visibility
        view.topView.toolpaths = true;
        view.topView.gantry = ViewStyle.SemiTransparent;

        // No save callback

        return view;
    }

    /**
     * Confirm Run Stage - Workflow stage 2 (Material & Clamps)
     * - View switching enabled for material/clamp positioning
     * - Settings and clamp dragging enabled
     * - Cannot save (always fresh defaults)
     */
    static createConfirmRunStageView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = true;
        view.showSettingsButton = true;
        view.enableOrbit = true;
        view.enableClampDragging = true;
        view.enableSpindleDrag = false;
        view.isHardcodedSettings = false;

        // Perspective view
        view.currentViewType = CNCViewType.Perspective;
        view.cameraTargetMode = CameraTarget.MachineCenter;

        // No save callback - always reset

        return view;
    }

    /**
     * Setup Job Stage - Workflow stage 3 (Analysis)
     * - View switching for analysis
     * - Settings enabled
     * - Cannot save (always fresh defaults)
     */
    static createSetupJobStageView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = true;
        view.showSettingsButton = true;
        view.enableOrbit = true;
        view.enableClampDragging = false;
        view.enableSpindleDrag = false;
        view.isHardcodedSettings = false;

        // Perspective view
        view.currentViewType = CNCViewType.Perspective;
        view.cameraTargetMode = CameraTarget.GCodeCenter;

        // No save callback

        return view;
    }

    /**
     * Simulator Dialog - Standalone simulator popup
     * - Full control similar to home
     * - Cannot save (temporary dialog)
     */
    static createSimulatorDialogView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = true;
        view.showSettingsButton = true;
        view.enableOrbit = true;
        view.enableClampDragging = false;
        view.enableSpindleDrag = true;
        view.isHardcodedSettings = true;

        // Perspective view
        view.currentViewType = CNCViewType.Perspective;
        view.cameraTargetMode = CameraTarget.MachineCenter;

        // No save callback

        return view;
    }

    /**
     * Machine Settings - Settings tab viewer
     * - Full control for machine preview
     * - Can save settings (with callback)
     * - Loads saved camera/visibility if available
     */
    static createMachineSettingsView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = true;
        view.showSettingsButton = true;
        view.enableOrbit = true;
        view.enableClampDragging = false;
        view.enableSpindleDrag = false;
        view.isHardcodedSettings = false;

        // Perspective view
        view.currentViewType = CNCViewType.Perspective;
        view.cameraTargetMode = CameraTarget.MachineCenter;

        return view;
    }

    /**
     * Spindle Wizard - Spindle warmup wizard
     * - Simple viewer, no controls
     * - Cannot save (temporary wizard)
     */
    static createSpindleWizardView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = false;
        view.showSettingsButton = false;
        view.enableOrbit = true;
        view.enableClampDragging = false;
        view.enableSpindleDrag = false;
        view.isHardcodedSettings = true;

        // Perspective view
        view.currentViewType = CNCViewType.Perspective;
        view.cameraTargetMode = CameraTarget.MachineCenter;

        // No save callback

        return view;
    }

    /**
     * Fixture Selection - Fixture picker dialog
     * - Simple preview
     * - Cannot save (temporary dialog)
     */
    static createFixtureSelectionView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = false;
        view.showSettingsButton = false;
        view.enableOrbit = true;
        view.enableClampDragging = false;
        view.enableSpindleDrag = false;
        view.isHardcodedSettings = true;

        // Perspective view
        view.currentViewType = CNCViewType.Perspective;
        view.cameraTargetMode = CameraTarget.MachineCenter;

        // No save callback

        return view;
    }

    /**
     * Floating Viewer - Detached viewer window
     * - Full control, independent window
     * - Cannot save (temporary window)
     */
    static createFloatingViewerView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = true;
        view.showSettingsButton = true;
        view.enableOrbit = true;
        view.enableClampDragging = true;
        view.enableSpindleDrag = true;
        view.isHardcodedSettings = true;

        // Perspective view
        view.currentViewType = CNCViewType.Perspective;
        view.cameraTargetMode = CameraTarget.MachineCenter;

        // No save callback

        return view;
    }

    /**
     * Clamp Top Editor - Legacy clamp editor
     * - Top view only, compact mode
     * - Cannot save (legacy/unused)
     */
    static createClampTopEditorView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = false;
        view.showSettingsButton = false;
        view.enableOrbit = false;
        view.enableClampDragging = false;
        view.enableSpindleDrag = false;
        view.isHardcodedSettings = true;

        // Top view only
        view.currentViewType = CNCViewType.Top;
        view.cameraTargetMode = CameraTarget.MachineCenter;

        // No save callback

        return view;
    }

    /**
     * Job Run Dialog - Live job execution viewer
     * - Top view centered on spindle/toolpaths
     * - Full controls with view switching and settings
     * - Cannot save (temporary execution dialog)
     */
    static createJobRunDialogView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Behavior configuration
        view.showViewTypeButtons = true;
        view.showSettingsButton = true;
        view.enableOrbit = true;
        view.enableClampDragging = false;
        view.enableSpindleDrag = false;
        view.isHardcodedSettings = true;

        // Top view centered on toolpaths/spindle
        view.currentViewType = CNCViewType.Top;
        view.cameraTargetMode = CameraTarget.Spindle;

        // Configure visibility for all views to match settings
        const configureView = (simView: SimulatorView) => {
            // Machine Components
            simView.base = ViewStyle.Hide;
            simView.bed = ViewStyle.Hide;
            simView.gantry = ViewStyle.SemiTransparent;
            simView.spindle = ViewStyle.SemiTransparent;
            simView.tool = ViewStyle.Show;
            simView.atc = ViewStyle.Hide;

            // Work Area & Equipment
            simView.spoilBoard = ViewStyle.Show;
            simView.material = ViewStyle.Show;
            simView.clamps = ViewStyle.Show;
            simView.verticalTable = ViewStyle.Show;
            simView.rotary = ViewStyle.Show;

            // Display Options
            simView.workHome = true;
            simView.toolpaths = true;
        };

        // Apply settings to all view types
        configureView(view.topView);
        configureView(view.perspectiveView);
        configureView(view.frontView);
        configureView(view.sideView);

        // No save callback - temporary execution view

        return view;
    }

    /**
     * Default view - Fallback for unknown contexts
     */
    private static createDefaultView(): SimulatorViewData {
        const view = new SimulatorViewData();

        // Safe defaults
        view.showViewTypeButtons = false;
        view.showSettingsButton = false;
        view.enableOrbit = true;
        view.enableClampDragging = false;
        view.enableSpindleDrag = false;
        view.isHardcodedSettings = true;

        view.currentViewType = CNCViewType.Perspective;
        view.cameraTargetMode = CameraTarget.MachineCenter;

        return view;
    }
}
