import { IStorable } from '../../../common/IStorable';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { BasePLCStatement } from '../statements/BasePLCStatement';
import { StatementUtilities } from '../statements/StatementUtilities';
import { Declaration } from './Declaration';
import { IPLCElement, OutputState, OutputType, PLCRenderMode, PLCValidationIssue } from './IPLCElement';
import { PLCStage } from './PLCStage';
import { IPLCSource, PLCProgramType, PLCSerializationHelper, PLCUtilities } from './PLCUtilities';

/**
 * Block type enum for PLC program organization
 */
/**
 * Represents a block in a PLC program stage
 * A block contains multiple actions that form a logical unit (e.g., a rung)
 */
export class PLCBlock implements IStorable, IPLCElement {
    private _name: string;
    private _actions: BasePLCStatement[];
    private _subBlocks: PLCBlock[];  // Nested sub-blocks
    private _comment: string;       // Block-level comment
    private _enabled: boolean;      // Whether this block is enabled/active (manual toggle)
    private _collapsed: boolean;    // UI state: whether block is collapsed in editor
    private _plcSource: IPLCSource | undefined;
    private _parentElement: IPLCElement | undefined;  // Parent stage or parent block that contains this block
    private _ordinal: number;       // Sort order for blocks and statements combined
    private _requiredInputs: string[];   // Required input centroidNames - block auto-disables if missing
    private _requiredOutputs: string[];  // Required output centroidNames - block auto-disables if missing
    private _requiredBoardTypes: string[];  // Required board types - block only renders for these boards (empty = all boards)

    constructor(name: string = '') {
        this._plcSource = undefined;
        this._name = name;
        this._actions = [];
        this._subBlocks = [];
        this._comment = '';
        this._enabled = true;
        this._collapsed = false;
        this._ordinal = 0;
        this._requiredInputs = [];
        this._requiredOutputs = [];
        this._requiredBoardTypes = [];

        // Set up cache invalidation listener
        PLCUtilities.setupCacheInvalidationListener(this);
    }

    public get name(): string {
        return this._name;
    }

    public set name(value: string) {
        this._name = value;
        StateManager.propertyChanged(this, 'name');
        this.notifyProgramValidationChanged();
    }

    public get actions(): BasePLCStatement[] {
        return this._actions;
    }

    public set actions(value: BasePLCStatement[]) {
        this._actions = value;
        // Set parent on all actions - they'll resolve plcSource from parent chain
        for (const action of this._actions) {
            action.setParentElement(this);
        }
        StateManager.propertyChanged(this, 'actions');
    }

    public get subBlocks(): PLCBlock[] {
        return this._subBlocks;
    }

    public set subBlocks(value: PLCBlock[]) {
        this._subBlocks = value;
        // Set parent on all sub-blocks - they'll resolve plcSource from parent chain
        for (const subBlock of this._subBlocks) {
            subBlock.setParentElement(this);
        }
        StateManager.propertyChanged(this, 'subBlocks');
    }

    public get comment(): string {
        return this._comment;
    }

    public set comment(value: string) {
        this._comment = value;
        StateManager.propertyChanged(this, 'comment');
    }

    public get enabled(): boolean {
        return this._enabled;
    }

    public set enabled(value: boolean) {
        this._enabled = value;
        StateManager.propertyChanged(this, 'enabled');
        this.notifyProgramValidationChanged();
    }

    public get requiredInputs(): string[] {
        return this._requiredInputs;
    }

    public set requiredInputs(value: string[]) {
        this._requiredInputs = value;
        StateManager.propertyChanged(this, 'requiredInputs');
    }

    public get requiredOutputs(): string[] {
        return this._requiredOutputs;
    }

    public set requiredOutputs(value: string[]) {
        this._requiredOutputs = value;
        StateManager.propertyChanged(this, 'requiredOutputs');
    }

    public get requiredBoardTypes(): string[] {
        return this._requiredBoardTypes;
    }

    public set requiredBoardTypes(value: string[]) {
        this._requiredBoardTypes = value;
        StateManager.propertyChanged(this, 'requiredBoardTypes');
    }

    public get collapsed(): boolean {
        return this._collapsed;
    }

    public set collapsed(value: boolean) {
        this._collapsed = value;
        StateManager.propertyChanged(this, 'collapsed');
    }

    public get plcSource(): IPLCSource | undefined {
        const resolved = PLCUtilities.resolvePLCSource(this, false);
        return resolved !== null ? resolved : undefined;
    }

    /**
     * Get the type of this PLC element
     */
    public getElementType(): 'block' {
        return 'block';
    }

    /**
     * Reset cached state in this block and all child elements
     */
    public preRenderReset(): void {
        for (const action of this._actions) {
            action.preRenderReset();
        }
        for (const subBlock of this._subBlocks) {
            subBlock.preRenderReset();
        }
    }

    /**
     * Get unique identifier for this block
     */
    public getElementId(): string {
        return this._name;
    }

    /**
     * Get the parent element (stage) that contains this block
     */
    public getParentElement(): IPLCElement | undefined {
        return this._parentElement;
    }

    /**
     * Set the parent element (stage or parent block) that contains this block
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        this._parentElement = parent;
        // Clear cached plcSource so it gets resolved from new parent chain
        this._plcSource = undefined;
        // Cascade to all child actions to ensure complete parent chain
        for (const action of this._actions) {
            action.setParentElement(this);
        }
        // Cascade to all sub-blocks
        for (const subBlock of this._subBlocks) {
            subBlock.setParentElement(this);
        }
    }

    public get ordinal(): number {
        return this._ordinal;
    }

    public set ordinal(value: number) {
        this._ordinal = value;
        StateManager.propertyChanged(this, 'ordinal');
    }

    /**
     * Check if this block is inherited from SystemDefault
     * A block is inherited if its plcSource.type is SystemDefault
     * @returns true if the block is from SystemDefault program
     */
    public IsInheritedFromSystemDefault(): boolean {
        // Check if plcSource exists and its type is SystemDefault
        if (!this.plcSource) {
            return false;
        }

        return this.plcSource.getProgramType() === PLCProgramType.SystemDefault;
    }

    /**
     * Check if this block is enabled considering manual toggle, I/O requirements, and board type
     * In SystemDefault program: only checks manual enabled state and board type
     * In System/Test programs: checks manual enabled AND required I/O availability AND board type
     * @param targetProgramType Program type context for evaluation (important for mirrored blocks)
     * @returns true if block should be enabled
     */
    public isEnabled(targetProgramType: PLCProgramType): boolean {
        // Manual disable always wins
        if (!this._enabled) {
            return false;
        }

        // Check board type requirement (applies to all program types)
        if (!this.hasRequiredBoardType()) {
            return false;
        }

        // SystemDefault blocks don't check I/O requirements (they define the defaults)
        if (targetProgramType === PLCProgramType.SystemDefault) {
            return true;
        }

        // For System and Test programs, check if required I/O exists
        return this.hasRequiredIO();
    }

    /**
     * Check if current board type matches required board types
     * @returns true if board type is compatible, false otherwise
     */
    private hasRequiredBoardType(): boolean {
        // No requirement = always enabled
        if (this._requiredBoardTypes.length === 0) {
            return true;
        }

        // Get current board type from MachineData
        // WORKAROUND: Breaking circular dependency between PLCBlock and MachineData
        const MachineData = require('../../../data/Machine/MachineData').MachineData;
        const currentBoardType = MachineData.Instance.boardType;

        // Check if current board type is in the required list
        return this._requiredBoardTypes.includes(currentBoardType);
    }

    /**
     * Check if all required inputs and outputs are present in the System PLC program
     * @returns true if all required I/O is available, false if any are missing
     */
    private hasRequiredIO(): boolean {
        // No requirements = always enabled
        if (this._requiredInputs.length === 0 && this._requiredOutputs.length === 0) {
            return true;
        }

        // Get the System program to check against
        // WORKAROUND: Breaking circular dependency between PLCBlock and PLCProgram
        // PLCBlock -> PLCProgram -> PLCStage -> PLCBlock creates cycle, so we require at usage point
        const PLCProgram = require('./PLCProgram').PLCProgram;
        const systemProgram = PLCProgram.Instance(PLCProgramType.System);

        // Check all required inputs exist
        for (const requiredInput of this._requiredInputs) {
            const exists = systemProgram.inputs.some((input: any) =>
                input.centroidName === requiredInput
            );
            if (!exists) {
                return false;
            }
        }

        // Check all required outputs exist
        for (const requiredOutput of this._requiredOutputs) {
            const exists = systemProgram.outputs.some((output: any) =>
                output.centroidName === requiredOutput
            );
            if (!exists) {
                return false;
            }
        }

        return true;
    }

    /**
     * Get list of missing required inputs
     * @returns Array of centroidNames for inputs that are required but not present
     */
    public getMissingInputs(): string[] {
        // WORKAROUND: Breaking circular dependency between PLCBlock and PLCProgram
        const PLCProgram = require('./PLCProgram').PLCProgram;
        const systemProgram = PLCProgram.Instance(PLCProgramType.System);

        return this._requiredInputs.filter(requiredInput =>
            !systemProgram.inputs.some((input: any) => input.centroidName === requiredInput)
        );
    }

    /**
     * Get list of missing required outputs
     * @returns Array of centroidNames for outputs that are required but not present
     */
    public getMissingOutputs(): string[] {
        // WORKAROUND: Breaking circular dependency between PLCBlock and PLCProgram
        const PLCProgram = require('./PLCProgram').PLCProgram;
        const systemProgram = PLCProgram.Instance(PLCProgramType.System);

        return this._requiredOutputs.filter(requiredOutput =>
            !systemProgram.outputs.some((output: any) => output.centroidName === requiredOutput)
        );
    }

    /**
     * Add an action to this block
     */
    public addAction(action: BasePLCStatement): void {
        action.setParentElement(this);
        // Set ordinal to be after all existing items
        action.ordinal = this.getMaxOrdinal() + 1;
        this._actions.push(action);
        StateManager.propertyChanged(this, 'actions');
        // Invalidate cache since declarations may have been added
        PLCUtilities.invalidateProgramCache();
        // Notify program that validation state may have changed
        this.notifyProgramValidationChanged();
    }

    /**
     * Add an action at a specific ordinal position
     * Used for moving/reordering items - does not auto-assign ordinal
     * Inserts at the correct array position to maintain sorted order
     */
    public addActionAt(action: BasePLCStatement, ordinal: number): void {
        action.setParentElement(this);
        action.ordinal = ordinal;

        // Find the correct insertion index by counting actions with lower ordinals
        // Note: We only count within _actions array since that's where we're inserting
        let insertIndex = 0;
        for (const existing of this._actions) {
            if (existing.ordinal < ordinal) {
                insertIndex++;
            }
        }

        this._actions.splice(insertIndex, 0, action);
        StateManager.propertyChanged(this, 'actions');
        PLCUtilities.invalidateProgramCache();
        this.notifyProgramValidationChanged();
    }

    /**
     * Add a sub-block to this block
     */
    public addSubBlock(subBlock: PLCBlock): void {
        subBlock.setParentElement(this);
        // Set ordinal to be after all existing items
        subBlock.ordinal = this.getMaxOrdinal() + 1;
        this._subBlocks.push(subBlock);
        StateManager.propertyChanged(this, 'subBlocks');
        // Invalidate cache since declarations may have been added
        PLCUtilities.invalidateProgramCache();
        // Notify program that validation state may have changed
        this.notifyProgramValidationChanged();
    }

    /**
     * Add a sub-block at a specific ordinal position
     * Used for moving/reordering items - does not auto-assign ordinal
     * Inserts at the correct array position to maintain sorted order
     */
    public addSubBlockAt(subBlock: PLCBlock, ordinal: number): void {
        subBlock.setParentElement(this);
        subBlock.ordinal = ordinal;

        // Find the correct insertion index by counting sub-blocks with lower ordinals
        // Note: We only count within _subBlocks array since that's where we're inserting
        let insertIndex = 0;
        for (const existing of this._subBlocks) {
            if (existing.ordinal < ordinal) {
                insertIndex++;
            }
        }

        this._subBlocks.splice(insertIndex, 0, subBlock);
        StateManager.propertyChanged(this, 'subBlocks');
        PLCUtilities.invalidateProgramCache();
        this.notifyProgramValidationChanged();
    }

    /**
     * Get the maximum ordinal from all statements and sub-blocks
     */
    private getMaxOrdinal(): number {
        let max = -1;
        for (const action of this._actions) {
            if (action.ordinal > max) max = action.ordinal;
        }
        for (const subBlock of this._subBlocks) {
            if (subBlock.ordinal > max) max = subBlock.ordinal;
        }
        return max;
    }

    /**
     * Get all items (statements and sub-blocks) sorted by ordinal
     */
    public getItemsSorted(): Array<BasePLCStatement | PLCBlock> {
        const items: Array<BasePLCStatement | PLCBlock> = [...this._actions, ...this._subBlocks];
        return items.sort((a, b) => a.ordinal - b.ordinal);
    }

    /**
     * Remove an action from this block
     */
    public removeAction(action: BasePLCStatement): void {
        const index = this._actions.indexOf(action);
        if (index > -1) {
            action.setParentElement(undefined);
            this._actions.splice(index, 1);

            // Renumber all items (actions and sub-blocks share ordinal space)
            const allItems = this.getItemsSorted();
            allItems.forEach((item, idx) => {
                item.ordinal = idx;
            });

            StateManager.propertyChanged(this, 'actions');
            // Invalidate cache since declarations may have been removed
            PLCUtilities.invalidateProgramCache();
            // Notify program that validation state may have changed
            this.notifyProgramValidationChanged();
        }
    }

    /**
     * Remove a sub-block from this block
     */
    public removeSubBlock(subBlock: PLCBlock): void {
        const index = this._subBlocks.indexOf(subBlock);
        if (index > -1) {
            subBlock.setParentElement(undefined);
            this._subBlocks.splice(index, 1);

            // Renumber all items (actions and sub-blocks share ordinal space)
            const allItems = this.getItemsSorted();
            allItems.forEach((item, idx) => {
                item.ordinal = idx;
            });

            StateManager.propertyChanged(this, 'subBlocks');
            // Invalidate cache since declarations may have been removed
            PLCUtilities.invalidateProgramCache();
            // Notify program that validation state may have changed
            this.notifyProgramValidationChanged();
        }
    }

    /**
     * Insert an action at a specific index
     */
    public insertAction(index: number, action: BasePLCStatement): void {
        action.setParentElement(this);
        this._actions.splice(index, 0, action);
        StateManager.propertyChanged(this, 'actions');
        // Notify program that validation state may have changed
        this.notifyProgramValidationChanged();
    }

    /**
     * Move an action up in the list (decrease index)
     * @param action The action to move up
     * @returns true if moved, false if already at top
     */
    public moveActionUp(action: BasePLCStatement): boolean {
        const index = this._actions.indexOf(action);
        if (index <= 0) return false; // Already at top or not found

        // Swap with previous action
        [this._actions[index - 1], this._actions[index]] = [this._actions[index], this._actions[index - 1]];
        StateManager.propertyChanged(this, 'actions');
        this.notifyProgramValidationChanged();
        return true;
    }

    /**
     * Move an action down in the list (increase index)
     * @param action The action to move down
     * @returns true if moved, false if already at bottom
     */
    public moveActionDown(action: BasePLCStatement): boolean {
        const index = this._actions.indexOf(action);
        if (index < 0 || index >= this._actions.length - 1) return false; // Already at bottom or not found

        // Swap with next action
        [this._actions[index], this._actions[index + 1]] = [this._actions[index + 1], this._actions[index]];
        StateManager.propertyChanged(this, 'actions');
        this.notifyProgramValidationChanged();
        return true;
    }

    /**
     * Blocks are never disabled - only their child elements (actions/statements) can be
     */
    public isDisabled(mode: PLCRenderMode, targetProgramType: PLCProgramType): boolean {
        return false;
    }

    /**
     * Render the block to JSX
     * @param mode Rendering mode (Edit, ReadOnly, or Disabled)
     * @param targetProgramType The program type context for rendering
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        // Determine effective mode:
        // - If parent says Disabled or ReadOnly, use that (propagate down)
        // - Otherwise, if this block is disabled (manual or I/O requirements), use Disabled mode
        let effectiveMode = mode;
        if (mode === PLCRenderMode.Edit && !this.isEnabled(targetProgramType)) {
            effectiveMode = PLCRenderMode.Disabled;
        }

        const blockStyle: React.CSSProperties = {
            textDecoration: effectiveMode === PLCRenderMode.Disabled ? 'line-through' : 'none',
            opacity: effectiveMode === PLCRenderMode.Disabled ? 0.6 : 1,
            marginBottom: '1.5rem'
        };

        const config = ConfigurationData.Instance;
        const colors = ConfigurationDataColors.Instance;

        return (
            <div style={blockStyle}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.5rem 0' }}>
                    <span style={{ fontWeight: 500 }}>{this._name}</span>
                </div>
                {this._comment && <div style={{ padding: '0.25rem 0.5rem', fontSize: '0.8125rem', color: colors.mutedTextColor, fontStyle: 'italic', opacity: 0.7 }}>{this._comment}</div>}
                <div style={{ padding: 0 }}>
                    {this._actions.map((action, index) => (
                        <div
                            key={index}
                            style={{
                                padding: '0.75rem 0.5rem',
                                borderBottom: index < this._actions.length - 1 ? `2px solid ${colors.borderColor}` : 'none'
                            }}
                        >
                            {action.render(effectiveMode, targetProgramType)}
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    /**
     * Get declarations that are used/referenced by this block and its actions
     */
    public getUsedDeclarations(): Declaration[] {
        const allDeclarations = [
            ...this._actions.flatMap(action => action.getUsedDeclarations()),
            ...this._subBlocks.flatMap(subBlock => subBlock.getUsedDeclarations())
        ];
        // Remove duplicates by name
        const uniqueMap = new Map<string, Declaration>();
        for (const decl of allDeclarations) {
            uniqueMap.set(decl.name, decl);
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Get declarations that are added/defined by this block and its actions
     */
    public getAddedDeclarations(): Declaration[] {
        const allDeclarations = [
            ...this._actions.flatMap(action => action.getAddedDeclarations()),
            ...this._subBlocks.flatMap(subBlock => subBlock.getAddedDeclarations())
        ];
        // Remove duplicates by name
        const uniqueMap = new Map<string, Declaration>();
        for (const decl of allDeclarations) {
            uniqueMap.set(decl.name, decl);
        }
        const result = Array.from(uniqueMap.values());
        return result;
    }

    /**
     * Get the PLC logic code for this block
     * @param availableDeclarations Array of declaration names that are available/defined
     */
    public getPLCLogic(availableDeclarations: string[]): string[] {
        // Check if block should be enabled (manual toggle + I/O requirements)
        // PLC output is always for System PLC, so always evaluate against System context
        const blockEnabled = this.isEnabled(PLCProgramType.System);

        if (!blockEnabled) {
            const lines: string[] = [];
            lines.push(`; Block disabled: ${this._name}`);

            // If manually disabled, just show that
            if (!this._enabled) {
                lines.push(`;   Reason: Manually disabled`);
            } else if (!this.hasRequiredBoardType()) {
                // Disabled due to board type mismatch
                const MachineData = require('../../../data/Machine/MachineData').MachineData;
                const currentBoardType = MachineData.Instance.boardType;
                lines.push(`;   Reason: Board type '${currentBoardType}' not compatible`);
                lines.push(`;   Required board types: ${this._requiredBoardTypes.join(', ')}`);
            } else {
                // Must be disabled due to missing I/O
                const missingInputs = this.getMissingInputs();
                const missingOutputs = this.getMissingOutputs();

                if (missingInputs.length > 0) {
                    lines.push(`;   Missing inputs: ${missingInputs.join(', ')}`);
                }
                if (missingOutputs.length > 0) {
                    lines.push(`;   Missing outputs: ${missingOutputs.join(', ')}`);
                }
            }

            return lines;
        }

        const logic: string[] = [];

        // Block name header with system default indicator
        const isFromSystemDefault = this.plcSource?.getProgramType() === PLCProgramType.SystemDefault;
        if (isFromSystemDefault) {
            logic.push(`; **** ${this._name} (from system defaults) ****`);
        } else {
            logic.push(`; **** ${this._name} ****`);
        }

        // Optional comment
        if (this._comment) {
            const commentLines = this._comment.split('\n');
            for (const line of commentLines) {
                logic.push(`; ${line}`);
            }
        }

        logic.push('');

        // Get all items (statements and sub-blocks) sorted by ordinal
        const items = this.getItemsSorted();

        for (let i = 0; i < items.length; i++) {
            const item = items[i];

            // Check if it's a sub-block or a statement
            if (item instanceof PLCBlock) {
                // Sub-block: recursively get its logic
                logic.push(...item.getPLCLogic(availableDeclarations));
            } else {
                // Statement: add comment if present
                if (item.comment) {
                    const commentLines = item.comment.split('\n');
                    for (const line of commentLines) {
                        logic.push(`; ${line}`);
                    }
                }
                logic.push(...item.getPLCLogic(availableDeclarations));
            }

            // Add blank line between items (but not after the last one)
            if (i < items.length - 1) {
                logic.push('');
            }
        }

        return logic;
    }

    /**
     * Get validation issues for this block and its actions
     */
    public getValidationIssues(): PLCValidationIssue[] {
        // Disabled elements cannot be invalid (use isEnabled() to check both manual and I/O requirements)
        const programType = this.plcSource?.getProgramType() ?? PLCProgramType.System;
        if (!this.isEnabled(programType)) {
            return [];
        }

        const issues: PLCValidationIssue[] = [];

        // Validate block-level issues
        if (!this._name || this._name.trim() === '') {
            issues.push(new PLCValidationIssue(this, 'Block name is required'));
        }

        // Check for duplicate block name (including mirrored blocks)
        // Walk up parent chain to find the stage
        let stage: PLCStage | undefined;
        let current: IPLCElement | undefined = this.getParentElement();
        while (current) {
            if (current.getElementType() === 'stage') {
                stage = current as PLCStage;
                break;
            }
            current = current.getParentElement();
        }

        if (stage && this._name && !PLCUtilities.isBlockNameUnique(this._name, stage, this)) {
            issues.push(new PLCValidationIssue(this, 'Block name must be unique within this stage (including mirrored SystemDefault blocks)'));
        }

        if (this._actions.length === 0 && this._subBlocks.length === 0) {
            issues.push(new PLCValidationIssue(this, 'Block has no statements or sub-blocks'));
        }

        // Get all items sorted
        const items = this.getItemsSorted();

        // Collect validation issues from items with context
        for (let i = 0; i < items.length; i++) {
            const item = items[i];
            const itemIssues = item.getValidationIssues();

            if (item instanceof PLCBlock) {
                // Sub-block
                itemIssues.forEach(issue => {
                    issues.push(new PLCValidationIssue(issue.element, `[Sub-block ${i + 1}: ${item.name}] ${issue.message}`));
                });
            } else {
                // Statement
                const statementType = item.constructor.name.replace('Statement', '').replace(/([A-Z])/g, ' $1').trim();
                itemIssues.forEach(issue => {
                    issues.push(new PLCValidationIssue(issue.element, `[Statement ${i + 1}: ${statementType}] ${issue.message}`));
                });
            }
        }

        return issues;
    }

    /**
     * Determine whether this block should be output
     * @param outputType The type of output (Render or PLCCode)
     * @param availableDeclarations Optional array of available declaration names
     * @returns OutputState indicating how this block should be handled
     */
    public shouldOutput(outputType: OutputType, availableDeclarations?: string[]): OutputState {
        // TODO: Define proper output logic later
        return OutputState.Output;
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        const baseData = PLCSerializationHelper.getStorageData(this, ['_actions', '_subBlocks', '_collapsed']);
        const actionsJson: any[] = [];
        const subBlocksJson: any[] = [];

        this._actions.forEach((action, index) => {
            try {
                actionsJson.push(action.toJSON());
            } catch (error) {
                console.error(
                    `Failed to serialize action ${index} in block ${this._name}:`,
                    error,
                    '\nAction type:',
                    action.constructor.name
                );
                throw error;
            }
        });

        this._subBlocks.forEach((subBlock, index) => {
            try {
                subBlocksJson.push(subBlock.toJSON());
            } catch (error) {
                console.error(
                    `Failed to serialize sub-block ${index} in block ${this._name}:`,
                    error
                );
                throw error;
            }
        });

        return {
            ...baseData,
            actions: actionsJson,
            subBlocks: subBlocksJson
        };
    }

    /**
     * Load from JSON
     */
    public fromJSON(data: any): void {
        if (!data) return;

        // FIRST: Load this block's own properties (including plcSource from parent)
        // This must happen BEFORE creating child statements so we can propagate plcSource to them
        DataUtilities.loadStorageData(this, data, ['_actions', 'actions', '_subBlocks', 'subBlocks']);

        // NOW create statements and propagate plcSource to them

        // Load actions using StatementUtilities factory - support both underscore and non-underscore formats for backward compatibility
        const actionsData = data.actions || data._actions;
        if (actionsData && Array.isArray(actionsData)) {
            this._actions = [];
            actionsData.forEach((actionData: any, index: number) => {
                try {
                    // Factory now only creates the statement instance, doesn't call fromJSON
                    const action = StatementUtilities.createStatementFromJSON(actionData);
                    // Deserialize first
                    action.fromJSON(actionData);
                    // THEN set parent (which will set plcSource via parent chain)
                    action.setParentElement(this);
                    this._actions.push(action);
                } catch (error) {
                    // Log error but continue loading other statements
                    console.error(
                        `Failed to deserialize statement ${index} in block ${this._name}:`,
                        error,
                        '\nStatement data:',
                        JSON.stringify(actionData, null, 2)
                    );
                }
            });

            // Validate deserialization count
            if (this._actions.length !== actionsData.length) {
                const error = `PLCBlock '${this._name}' deserialization error: Expected ${actionsData.length} statements but got ${this._actions.length}`;
                console.error(error, '\nJSON data:', JSON.stringify(data, null, 2));
                throw new Error(error);
            }
        }

        // Load sub-blocks
        const subBlocksData = data.subBlocks || data._subBlocks;
        if (subBlocksData && Array.isArray(subBlocksData)) {
            this._subBlocks = [];
            subBlocksData.forEach((subBlockData: any, index: number) => {
                try {
                    const subBlock = new PLCBlock();
                    subBlock.fromJSON(subBlockData);
                    subBlock.setParentElement(this);
                    this._subBlocks.push(subBlock);
                } catch (error) {
                    console.error(
                        `Failed to deserialize sub-block ${index} in block ${this._name}:`,
                        error,
                        '\nSub-block data:',
                        JSON.stringify(subBlockData, null, 2)
                    );
                }
            });

            // Validate deserialization count
            if (this._subBlocks.length !== subBlocksData.length) {
                const error = `PLCBlock '${this._name}' deserialization error: Expected ${subBlocksData.length} sub-blocks but got ${this._subBlocks.length}`;
                console.error(error, '\nJSON data:', JSON.stringify(data, null, 2));
                throw new Error(error);
            }
        }

        // ALWAYS default to collapsed = true to prevent flashing when opening PLC editor
        this._collapsed = true;
    }

    /**
     * Notify the parent program that validation state may have changed
     * This propagates validation changes up to the program level so sidebar indicators update
     */
    private notifyProgramValidationChanged(): void {
        // Walk up parent chain: Block -> Stage -> Program
        let current: IPLCElement | undefined = this._parentElement;
        while (current) {
            if ('notifyValidationChanged' in current) {
                // WORKAROUND: Dynamic method check requires 'as any' since notifyValidationChanged is not on IPLCElement interface
                (current as any).notifyValidationChanged();
                break;
            }
            current = current.getParentElement();
        }
    }
}
