import {
  Box,
  FormControlLabel,
  Grid,
  Paper,
  Slider,
  Switch,
  Typography
} from '@mui/material';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';

export function DelaysSection() {
  const config = ConfigurationData.Instance;

  return (
    <Grid container spacing={3}>
      <Grid item xs={12}>
        <Paper sx={{ p: 3 }}>
          <Typography variant="h6" gutterBottom>Delay Settings</Typography>

          <ObserveState
            key="delays-settings"
            listenTo={config}
            properties={[
              'simulatorMoveDelay',
              'jogPadMoveDelay',
              'coordinateMoveDelay',
              'mdiToolDelay',
              'messageDisplayTime',
              'machineModeDuration'
            ]}
            control={() => (
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, mt: 2 }}>
                <Box>
                  <Typography gutterBottom>Simulator Move Delay: {(config.simulatorMoveDelay / 1000).toFixed(1)}s</Typography>
                  <Slider
                    value={config.simulatorMoveDelay / 1000}
                    onChange={(_, value) => config.simulatorMoveDelay = (value as number) * 1000}
                    min={0}
                    max={10}
                    step={0.1}
                    valueLabelDisplay="auto"
                    valueLabelFormat={(value) => `${value.toFixed(1)}s`}
                  />
                </Box>

                <Box>
                  <Typography gutterBottom>Jog Pad Move Delay: {(config.jogPadMoveDelay / 1000).toFixed(1)}s</Typography>
                  <Slider
                    value={config.jogPadMoveDelay / 1000}
                    onChange={(_, value) => config.jogPadMoveDelay = (value as number) * 1000}
                    min={0}
                    max={10}
                    step={0.1}
                    valueLabelDisplay="auto"
                    valueLabelFormat={(value) => `${value.toFixed(1)}s`}
                  />
                </Box>

                <Box>
                  <Typography gutterBottom>Coordinate Move Delay: {(config.coordinateMoveDelay / 1000).toFixed(1)}s</Typography>
                  <Slider
                    value={config.coordinateMoveDelay / 1000}
                    onChange={(_, value) => config.coordinateMoveDelay = (value as number) * 1000}
                    min={0}
                    max={10}
                    step={0.1}
                    valueLabelDisplay="auto"
                    valueLabelFormat={(value) => `${value.toFixed(1)}s`}
                  />
                </Box>

                <Box>
                  <Typography gutterBottom>MDI Tool Delay: {(config.mdiToolDelay / 1000).toFixed(1)}s</Typography>
                  <Slider
                    value={config.mdiToolDelay / 1000}
                    onChange={(_, value) => config.mdiToolDelay = (value as number) * 1000}
                    min={0}
                    max={10}
                    step={0.1}
                    valueLabelDisplay="auto"
                    valueLabelFormat={(value) => `${value.toFixed(1)}s`}
                  />
                </Box>

                <Box>
                  <Typography gutterBottom>Message Display Time: {(config.messageDisplayTime / 1000).toFixed(1)}s</Typography>
                  <Slider
                    value={config.messageDisplayTime / 1000}
                    onChange={(_, value) => config.messageDisplayTime = (value as number) * 1000}
                    min={0}
                    max={10}
                    step={0.1}
                    valueLabelDisplay="auto"
                    valueLabelFormat={(value) => `${value.toFixed(1)}s`}
                  />
                </Box>

                <Box>
                  <Typography gutterBottom>Machine Mode Duration: {config.machineModeDuration.toFixed(0)}s</Typography>
                  <Slider
                    value={config.machineModeDuration}
                    onChange={(_, value) => config.machineModeDuration = value as number}
                    min={5}
                    max={120}
                    step={5}
                    valueLabelDisplay="auto"
                    valueLabelFormat={(value) => `${value.toFixed(0)}s`}
                  />
                </Box>
              </Box>
            )}
          />
        </Paper>
      </Grid>

      {/* Safety Settings */}
      <Grid item xs={12}>
        <Paper sx={{ p: 3 }}>
          <Typography variant="h6" gutterBottom>Safety</Typography>

          <ObserveState
            key="safe-mode-enabled"
            listenTo={ConfigurationState.Instance}
            properties={['isHomed']}
            control={() => (
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={ConfigurationState.Instance.isHomed}
                      onChange={(e) => ConfigurationState.Instance.isHomed = e.target.checked}
                    />
                  }
                  label="Safe Mode"
                />
              </Box>
            )}
          />

          <ObserveState
            key="safe-mode-timeout"
            listenTo={config}
            properties={['safeModeTimeout']}
            control={() => (
              <>
                <Typography variant="body2" gutterBottom>
                  Safe Mode Timeout (minutes):
                </Typography>
                <Slider
                  value={config.safeModeTimeout / 60000}
                  onChange={(_, value) => config.safeModeTimeout = (value as number) * 60000}
                  min={0}
                  max={15}
                  step={1}
                  marks={[
                    { value: 0, label: '0' },
                    { value: 5, label: '5' },
                    { value: 10, label: '10' },
                    { value: 15, label: '15' }
                  ]}
                  valueLabelDisplay="auto"
                  valueLabelFormat={(value) => `${value} min`}
                />
              </>
            )}
          />

          <ObserveState
            key="soft-limits-enabled"
            listenTo={ConfigurationState.Instance}
            properties={['isHomed']}
            control={() => (
              <Box sx={{ display: 'flex', alignItems: 'center', mt: 3, mb: 3 }}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={ConfigurationState.Instance.isHomed}
                      onChange={(e) => ConfigurationState.Instance.isHomed = e.target.checked}
                    />
                  }
                  label="Soft Limits"
                />
              </Box>
            )}
          />

          <ObserveState
            key="soft-limits-timeout"
            listenTo={config}
            properties={['safeModeTimeout']}
            control={() => (
              <>
                <Typography variant="body2" gutterBottom>
                  Soft Limits Timeout (minutes):
                </Typography>
                <Slider
                  value={config.safeModeTimeout / 60000}
                  onChange={(_, value) => config.safeModeTimeout = (value as number) * 60000}
                  min={0}
                  max={15}
                  step={1}
                  marks={[
                    { value: 0, label: '0' },
                    { value: 5, label: '5' },
                    { value: 10, label: '10' },
                    { value: 15, label: '15' }
                  ]}
                  valueLabelDisplay="auto"
                  valueLabelFormat={(value) => `${value} min`}
                />
              </>
            )}
          />
        </Paper>
      </Grid>
    </Grid>
  );
}
