import {
    Box,
    Grid,
    Paper,
    Typography
} from '@mui/material';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { ColorPicker } from '../../../Common/ColorPicker';

export function UIConfigurationSection() {
    const colors = ConfigurationDataColors.Instance;

    return (
        <Grid container spacing={3}>

            {/* App Theme Colors - Primary Section */}
            <Grid item xs={12}>
                <Paper sx={{ p: 3, mb: 2, backgroundColor: colors.lightBackgroundColor }}>
                    <Typography variant="h5" gutterBottom sx={{ color: 'primary.main', fontWeight: 'bold' }}>
                        App Theme Colors
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                        These are the main colors that define your application's visual identity and branding.
                    </Typography>

                    <Grid container spacing={4}>
                        <Grid item xs={12} md={6}>
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', p: 2 }}>
                                <Typography variant="h6" gutterBottom sx={{ fontWeight: 'bold' }}>
                                    Primary Color
                                </Typography>
                                <Box sx={{ width: '100%', maxWidth: 300 }}>
                                    <ObserveState
                                        key="ui-primary-color"
                                        listenTo={colors}
                                        properties={['primaryColor']}
                                        control={() => (
                                            <ColorPicker
                                                label="Primary Color"
                                                value={colors.primaryColor}
                                                onChange={(color) => colors.primaryColor = color}
                                            />
                                        )}
                                    />
                                </Box>
                                <Typography variant="caption" color="text.secondary" sx={{ mt: 1, textAlign: 'center' }}>
                                    Main brand color used for buttons, highlights, and accents
                                </Typography>
                            </Box>
                        </Grid>

                        <Grid item xs={12} md={6}>
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', p: 2 }}>
                                <Typography variant="h6" gutterBottom sx={{ fontWeight: 'bold' }}>
                                    Secondary Color
                                </Typography>
                                <Box sx={{ width: '100%', maxWidth: 300 }}>
                                    <ObserveState
                                        key="ui-secondary-color"
                                        listenTo={colors}
                                        properties={['secondaryColor']}
                                        control={() => (
                                            <ColorPicker
                                                label="Secondary Color"
                                                value={colors.secondaryColor}
                                                onChange={(color) => colors.secondaryColor = color}
                                            />
                                        )}
                                    />
                                </Box>
                                <Typography variant="caption" color="text.secondary" sx={{ mt: 1, textAlign: 'center' }}>
                                    Complementary color for secondary elements and contrast
                                </Typography>
                            </Box>
                        </Grid>
                    </Grid>
                </Paper>
            </Grid>

            {/* UI/Interface Colors */}
            <Grid item xs={12} md={6}>
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>UI/Interface Colors</Typography>

                    <ObserveState
                        key="ui-interface-colors"
                        listenTo={colors}
                        properties={['lightBackgroundColor', 'borderColor', 'lightTextColor', 'darkTextColor', 'secondaryBorderColor', 'mutedTextColor']}
                        control={() => (
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
                                <ColorPicker
                                    label="Light Background Color"
                                    value={colors.lightBackgroundColor}
                                    onChange={(color) => colors.lightBackgroundColor = color}
                                />

                                <ColorPicker
                                    label="Border Color"
                                    value={colors.borderColor}
                                    onChange={(color) => colors.borderColor = color}
                                />

                                <ColorPicker
                                    label="Light Text Color"
                                    value={colors.lightTextColor}
                                    onChange={(color) => colors.lightTextColor = color}
                                />

                                <ColorPicker
                                    label="Dark Text Color"
                                    value={colors.darkTextColor}
                                    onChange={(color) => colors.darkTextColor = color}
                                />

                                <ColorPicker
                                    label="Secondary Border Color"
                                    value={colors.secondaryBorderColor}
                                    onChange={(color) => colors.secondaryBorderColor = color}
                                />

                                <ColorPicker
                                    label="Muted Text Color"
                                    value={colors.mutedTextColor}
                                    onChange={(color) => colors.mutedTextColor = color}
                                />
                            </Box>
                        )}
                    />
                </Paper>
            </Grid>

            {/* Status Colors */}
            <Grid item xs={12} md={6}>
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>Status Colors</Typography>

                    <ObserveState
                        key="ui-status-colors"
                        listenTo={colors}
                        properties={['warningColor', 'successColor', 'errorColor', 'limitsWarningColor', 'collisionErrorColor', 'infoColor', 'selectionColor', 'hoverColor']}
                        control={() => (
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
                                <ColorPicker
                                    label="Warning Color"
                                    value={colors.warningColor}
                                    onChange={(color) => colors.warningColor = color}
                                />

                                <ColorPicker
                                    label="Success Color"
                                    value={colors.successColor}
                                    onChange={(color) => colors.successColor = color}
                                />

                                <ColorPicker
                                    label="Error Color"
                                    value={colors.errorColor}
                                    onChange={(color) => colors.errorColor = color}
                                />

                                <ColorPicker
                                    label="Limits Warning Color"
                                    value={colors.limitsWarningColor}
                                    onChange={(color) => colors.limitsWarningColor = color}
                                />

                                <ColorPicker
                                    label="Collision Error Color"
                                    value={colors.collisionErrorColor}
                                    onChange={(color) => colors.collisionErrorColor = color}
                                />

                                <ColorPicker
                                    label="Info Color"
                                    value={colors.infoColor}
                                    onChange={(color) => colors.infoColor = color}
                                />

                                <ColorPicker
                                    label="Selection Color"
                                    value={colors.selectionColor}
                                    onChange={(color) => colors.selectionColor = color}
                                />

                                <ColorPicker
                                    label="Hover Color"
                                    value={colors.hoverColor}
                                    onChange={(color) => colors.hoverColor = color}
                                />
                            </Box>
                        )}
                    />
                </Paper>
            </Grid>

            {/* Overlay Colors */}
            <Grid item xs={12} md={6}>
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>Overlay Colors</Typography>

                    <ObserveState
                        key="ui-overlay-colors"
                        listenTo={colors}
                        properties={['darkOverlayPaused', 'darkOverlay', 'modalBackdrop', 'lightOverlay', 'shadowColor']}
                        control={() => (
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
                                <ColorPicker
                                    label="Dark Overlay Paused"
                                    value={colors.darkOverlayPaused}
                                    onChange={(color) => colors.darkOverlayPaused = color}
                                />

                                <ColorPicker
                                    label="Dark Overlay"
                                    value={colors.darkOverlay}
                                    onChange={(color) => colors.darkOverlay = color}
                                />

                                <ColorPicker
                                    label="Modal Backdrop"
                                    value={colors.modalBackdrop}
                                    onChange={(color) => colors.modalBackdrop = color}
                                />

                                <ColorPicker
                                    label="Light Overlay"
                                    value={colors.lightOverlay}
                                    onChange={(color) => colors.lightOverlay = color}
                                />

                                <ColorPicker
                                    label="Shadow Color"
                                    value={colors.shadowColor}
                                    onChange={(color) => colors.shadowColor = color}
                                />
                            </Box>
                        )}
                    />
                </Paper>
            </Grid>

            {/* Development/Demo Colors */}
            <Grid item xs={12} md={6}>
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>Development/Demo Colors</Typography>

                    <ObserveState
                        key="ui-dev-colors"
                        listenTo={colors}
                        properties={['darkBackgroundColor', 'veryDarkColor']}
                        control={() => (
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
                                <ColorPicker
                                    label="Dark Background Color"
                                    value={colors.darkBackgroundColor}
                                    onChange={(color) => colors.darkBackgroundColor = color}
                                />

                                <ColorPicker
                                    label="Very Dark Color"
                                    value={colors.veryDarkColor}
                                    onChange={(color) => colors.veryDarkColor = color}
                                />
                            </Box>
                        )}
                    />
                </Paper>
            </Grid>
        </Grid>
    );
}
