import {
    Delete as DeleteIcon,
    Description as FileIcon,
    Label as LabelIcon,
    MoreHoriz as MoreHorizIcon,
    DriveFileRenameOutline as RenameIcon,
    AccessTime as TimeIcon
} from '@mui/icons-material';
import CloseIcon from '@mui/icons-material/Close';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    ListItemIcon,
    ListItemText,
    Menu,
    MenuItem,
    Paper,
    TextField,
    Typography
} from '@mui/material';
import { useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { JobMetadata } from '../../../machine/ICNCJobStorage';

interface JobCategoryBrowseDialogProps {
    open: boolean;
    category: string;
    jobs: JobMetadata[];
    onClose: () => void;
    onJobSelect: (job: JobMetadata) => void;
    onSetCategory?: (job: JobMetadata) => void;
    onDelete?: (job: JobMetadata) => void;
    onRename?: (job: JobMetadata, newName: string) => Promise<void>;
}

function formatFileAge(lastModified?: Date): string {
    if (!lastModified) return 'Unknown';
    const now = new Date();
    const diffMs = now.getTime() - lastModified.getTime();
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    if (diffMinutes < 1) return 'Just now';
    if (diffMinutes < 60) return `${diffMinutes} min ago`;
    if (diffHours < 24) return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
    if (diffDays === 1) return 'Yesterday';
    if (diffDays < 7) return `${diffDays} days ago`;
    return lastModified.toLocaleDateString();
}

export function JobCategoryBrowseDialog({
    open, category, jobs, onClose, onJobSelect,
    onSetCategory, onDelete, onRename
}: JobCategoryBrowseDialogProps) {
    const config = ConfigurationDataColors.Instance;

    const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
    const [menuAnchorEl, setMenuAnchorEl] = useState<HTMLElement | null>(null);
    const [menuMeta, setMenuMeta] = useState<JobMetadata | null>(null);
    const [renameOpen, setRenameOpen] = useState(false);
    const [renameValue, setRenameValue] = useState('');
    const [renaming, setRenaming] = useState(false);

    const handleOpenMenu = (e: React.MouseEvent<HTMLElement>, meta: JobMetadata) => {
        e.stopPropagation();
        setMenuAnchorEl(e.currentTarget);
        setMenuMeta(meta);
    };

    const handleCloseMenu = () => {
        setMenuAnchorEl(null);
        setMenuMeta(null);
    };

    const handleRenameClick = () => {
        if (!menuMeta) return;
        setRenameValue(menuMeta.name);
        setMenuAnchorEl(null); // close popover, keep menuMeta for rename dialog
        setRenameOpen(true);
    };

    const handleRenameConfirm = async () => {
        if (!menuMeta || !onRename) return;
        const trimmed = renameValue.trim();
        if (!trimmed || trimmed === menuMeta.name) { setRenameOpen(false); setMenuMeta(null); return; }
        setRenaming(true);
        await onRename(menuMeta, trimmed);
        setRenaming(false);
        setRenameOpen(false);
        setMenuMeta(null);
    };

    const handleRenameClose = () => {
        setRenameOpen(false);
        setMenuMeta(null);
    };

    return (
        <>
            <Dialog open={open} onClose={onClose} maxWidth="lg" fullWidth PaperProps={{ sx: { minHeight: '60vh' } }}>
                <DialogTitle sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: config.primaryColor,
                    color: 'white',
                    py: 2,
                    px: 3
                }}>
                    Category: {category}
                    <IconButton
                        onClick={onClose}
                        sx={{ color: 'white', '&:hover': { backgroundColor: 'rgba(255, 255, 255, 0.1)' } }}
                    >
                        <CloseIcon />
                    </IconButton>
                </DialogTitle>

                <DialogContent>
                    <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 2 }}>
                        <Typography variant="body2" color="text.secondary">
                            Select a job to preview and load it.
                        </Typography>
                        <Box sx={{
                            display: 'grid',
                            gridTemplateColumns: 'repeat(3, minmax(0, 1fr))',
                            gap: 2
                        }}>
                            {jobs.map((meta, index) => (
                                <Paper
                                    key={meta.id}
                                    sx={{
                                        p: 2,
                                        cursor: 'pointer',
                                        transition: 'all 0.2s',
                                        minWidth: 0,
                                        overflow: 'hidden',
                                        position: 'relative',
                                        '&:hover': {
                                            borderColor: 'primary.main',
                                            boxShadow: 3,
                                            transform: 'translateY(-2px)'
                                        }
                                    }}
                                    onClick={() => { onJobSelect(meta); onClose(); }}
                                    onMouseEnter={() => setHoveredIndex(index)}
                                    onMouseLeave={() => setHoveredIndex(null)}
                                >
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1, minWidth: 0 }}>
                                        <FileIcon color="action" sx={{ fontSize: 24, flexShrink: 0 }} />
                                        <Typography variant="subtitle2" noWrap sx={{ flex: 1, minWidth: 0 }}>
                                            {meta.name}
                                        </Typography>
                                        <IconButton
                                            size="small"
                                            onClick={(e) => handleOpenMenu(e, meta)}
                                            sx={{
                                                flexShrink: 0,
                                                opacity: hoveredIndex === index ? 1 : 0,
                                                transition: 'opacity 0.15s',
                                                pointerEvents: hoveredIndex === index ? 'auto' : 'none'
                                            }}
                                        >
                                            <MoreHorizIcon fontSize="small" />
                                        </IconButton>
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                                        <Typography variant="caption" color="text.secondary">
                                            {formatFileAge(meta.lastModified)}
                                        </Typography>
                                        <Typography variant="caption" color="text.secondary">•</Typography>
                                        <Typography variant="caption" color="text.secondary">
                                            {meta.executionCount} run{meta.executionCount !== 1 ? 's' : ''}
                                        </Typography>
                                        {meta.estimatedTime && (
                                            <>
                                                <Typography variant="caption" color="text.secondary">•</Typography>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                                    <TimeIcon fontSize="small" color="action" />
                                                    <Typography variant="caption">{meta.estimatedTime}</Typography>
                                                </Box>
                                            </>
                                        )}
                                    </Box>
                                </Paper>
                            ))}
                        </Box>
                    </Box>
                </DialogContent>
                <DialogActions sx={{ p: 2, justifyContent: 'flex-end', borderTop: `1px solid ${config.borderColor}` }}>
                    <Button onClick={onClose} variant="outlined">Close</Button>
                </DialogActions>
            </Dialog>

            {/* Per-job context menu */}
            <Menu
                anchorEl={menuAnchorEl}
                open={Boolean(menuAnchorEl)}
                onClose={handleCloseMenu}
                onClick={(e) => e.stopPropagation()}
            >
                {onSetCategory && (
                    <MenuItem onClick={() => { if (menuMeta) onSetCategory(menuMeta); handleCloseMenu(); }}>
                        <ListItemIcon><LabelIcon fontSize="small" /></ListItemIcon>
                        <ListItemText>Set Category</ListItemText>
                    </MenuItem>
                )}
                {onRename && (
                    <MenuItem onClick={handleRenameClick}>
                        <ListItemIcon><RenameIcon fontSize="small" /></ListItemIcon>
                        <ListItemText>Rename</ListItemText>
                    </MenuItem>
                )}
                {onDelete && (
                    <MenuItem onClick={() => { if (menuMeta) onDelete(menuMeta); handleCloseMenu(); }} sx={{ color: 'error.main' }}>
                        <ListItemIcon><DeleteIcon fontSize="small" color="error" /></ListItemIcon>
                        <ListItemText>Delete Job</ListItemText>
                    </MenuItem>
                )}
            </Menu>

            {/* Rename dialog */}
            <Dialog open={renameOpen} onClose={handleRenameClose} maxWidth="xs" fullWidth>
                <DialogTitle sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: config.primaryColor,
                    color: 'white',
                    py: 2,
                    px: 3
                }}>
                    Rename Job
                    <IconButton
                        onClick={handleRenameClose}
                        sx={{ color: 'white', '&:hover': { backgroundColor: 'rgba(255,255,255,0.1)' } }}
                    >
                        <CloseIcon />
                    </IconButton>
                </DialogTitle>
                <DialogContent>
                    <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 2 }}>
                        <Typography variant="body2" color="text.secondary">
                            Current name: <strong>{menuMeta?.name}</strong>
                        </Typography>
                        <TextField
                            label="New name"
                            fullWidth
                            value={renameValue}
                            onChange={(e) => setRenameValue(e.target.value)}
                            onKeyDown={(e) => { if (e.key === 'Enter' && !renaming) handleRenameConfirm(); }}
                            autoFocus
                            disabled={renaming}
                        />
                    </Box>
                </DialogContent>
                <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${config.borderColor}` }}>
                    <Button onClick={handleRenameClose} variant="outlined" disabled={renaming}>
                        Cancel
                    </Button>
                    <Button
                        onClick={handleRenameConfirm}
                        variant="contained"
                        disabled={renaming || !renameValue.trim() || renameValue.trim() === menuMeta?.name}
                    >
                        Rename
                    </Button>
                </DialogActions>
            </Dialog>
        </>
    );
}

