import { IStorable } from '../../common/IStorable';
import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { CNCOffset } from '../CNCOffset';
import { ClampShape } from './ClampLibrary';

export class Clamp implements IStorable {
  private _id: string = this.generateId();
  private _clampname: string = "Generic";
  private _clampXWidth: number = 1.5;
  private _clampYWidth: number = 5;
  private _clampHeight: number = 4;
  private _clampShape: ClampShape = ClampShape.Rectangular;
  private _clampColor: string = 'blue';
  private _clampOffset: CNCOffset = new CNCOffset(0, 0, 0);

  private generateId(): string {
    return 'clamp_' + Math.random().toString(36).substr(2, 9) + '_' + Date.now().toString(36);
  }

  public get id(): string {
    return this._id;
  }

  public get clampname(): string {
    return this._clampname;
  }

  public set clampname(value: string) {
    this._clampname = value;
    StateManager.propertyChanged(this, 'clampname');
  }

  public get clampXWidth(): number {
    return this._clampXWidth;
  }

  public set clampXWidth(value: number) {
    this._clampXWidth = value;
    StateManager.propertyChanged(this, 'clampXWidth');
  }

  public get clampYWidth(): number {
    return this._clampYWidth;
  }

  public set clampYWidth(value: number) {
    this._clampYWidth = value;
    StateManager.propertyChanged(this, 'clampYWidth');
  }

  public get clampHeight(): number {
    return this._clampHeight;
  }

  public set clampHeight(value: number) {
    this._clampHeight = value;
    StateManager.propertyChanged(this, 'clampHeight');
  }

  public get clampShape(): ClampShape {
    return this._clampShape;
  }

  public set clampShape(value: ClampShape) {
    this._clampShape = value;
    StateManager.propertyChanged(this, 'clampShape');
  }

  public get clampColor(): string {
    return this._clampColor;
  }

  public set clampColor(value: string) {
    this._clampColor = value;
    StateManager.propertyChanged(this, 'clampColor');
  }

  public get clampOffset(): CNCOffset {
    // Ensure we always return a CNCOffset, even for old data
    if (!this._clampOffset) {
      this._clampOffset = new CNCOffset(0, 0, 0);
    }
    return this._clampOffset;
  }

  public get clampOffsetX(): number {
    return this._clampOffset.x;
  }

  public set clampOffsetX(value: number) {
    this._clampOffset.x = value;
    StateManager.propertyChanged(this, 'clampOffsetX');
  }

  public get clampOffsetY(): number {
    return this._clampOffset.y;
  }

  public set clampOffsetY(value: number) {
    this._clampOffset.y = value;
    StateManager.propertyChanged(this, 'clampOffsetY');
  }

  public get clampOffsetZ(): number {
    return this._clampOffset.z;
  }

  public set clampOffsetZ(value: number) {
    this._clampOffset.z = value;
    StateManager.propertyChanged(this, 'clampOffsetZ');
  }

  /**
   * Creates a deep copy of this Clamp instance
   */
  public clone(): Clamp {
    const cloned = new Clamp();
    cloned.clampname = this.clampname;
    cloned.clampXWidth = this.clampXWidth;
    cloned.clampYWidth = this.clampYWidth;
    cloned.clampHeight = this.clampHeight;
    cloned.clampShape = this.clampShape;
    cloned.clampColor = this.clampColor;
    cloned._clampOffset = this._clampOffset.clone();

    return cloned;
  }

  /**
   * Serialize to JSON using generic DataUtilities approach
   */
  public toJSON(): any {
    const baseData = DataUtilities.getStorageData(this, ['_clampOffset']);
    return {
      ...baseData,
      clampOffset: this._clampOffset.toJSON()
    };
  }

  /**
   * Load from JSON using generic DataUtilities approach
   */
  public fromJSON(data: any): void {
    if (!data) return;

    // Load CNCOffset first - support both underscore and non-underscore formats for backward compatibility
    const clampOffsetData = data.clampOffset || data._clampOffset;
    if (clampOffsetData) {
      this._clampOffset.fromJSON(clampOffsetData);
    }

    // Load remaining properties (excluding _clampOffset)
    DataUtilities.loadStorageData(this, data, ['_clampOffset', 'clampOffset']);
  }
}
