import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for verifying soft limits configuration.
 * This requires manual confirmation as we cannot programmatically verify
 * if the soft limits are correctly set for the physical machine.
 */
export class SoftLimitsChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Soft Limits',
            'Configure software travel limits for all axes to prevent crashes'
        );
    }

    public needsManualConfirmation(): boolean {
        // User must manually confirm they've configured the correct limits
        return true;
    }

    public completionCheck(): boolean {
        // We cannot automatically determine if limits are correct for the machine
        // The user must manually verify and confirm
        return true;
    }

    public clone(): SetupChecklistItem {
        const cloned = new SoftLimitsChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
