import { ICNCSpindle } from '../machine/ICNCSpindle';
import { CNCSpindleApi } from '../services/src/apis/CNCSpindleApi';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';

export class CentroidCNCSpindle implements ICNCSpindle {
  private readonly api: CNCSpindleApi;
  private spindleRunning: boolean = false;

  constructor() {
    const config = MachineInterfaceManager.Instance.getServiceConfiguration();
    this.api = new CNCSpindleApi(config || undefined);
  }

  async WarmUpSpindle(): Promise<void> {
    try {
      await this.api.apiCNCSpindleWarmUpSpindlePost();
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to warm up spindle:', error);
      throw error;
    }
  }

  async GetSpindleSpeed(): Promise<number> {
    try {
      const response = await this.api.apiCNCSpindleGetSpindleSpeedGet();
      return (response as any).data || 0;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get spindle speed:', error);
      throw error;
    }
  }

  async SetSpindleSpeed(speed: number): Promise<void> {
    try {
      await this.api.apiCNCSpindleSetSpindleSpeedPost({ body: speed });
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to set spindle speed:', error);
      throw error;
    }
  }

  async AdjustSpindleSpeed(factor: number): Promise<void> {
    try {
      await this.api.apiCNCSpindleAdjustSpindleSpeedPost({ body: factor });
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to adjust spindle speed:', error);
      throw error;
    }
  }

  async GetCurrentSpindleSpeedFactor(): Promise<number> {
    try {
      const response = await this.api.apiCNCSpindleGetCurrentSpindleSpeedFactorGet();
      return (response as any).data || 0;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get spindle speed factor:', error);
      throw error;
    }
  }

  async ResetSpindleSpeedFactor(): Promise<void> {
    try {
      await this.api.apiCNCSpindleResetSpindleSpeedFactorPost();
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to reset spindle speed factor:', error);
      throw error;
    }
  }

  async StartSpindle(speed?: number): Promise<void> {
    try {
      if (speed !== undefined) {
        await this.api.apiCNCSpindleStartSpindlePost({ body: speed });
      } else {
        await this.api.apiCNCSpindleStartSpindlePost();
      }
      this.spindleRunning = true;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to start spindle:', error);
      throw error;
    }
  }

  async StopSpindle(): Promise<void> {
    try {
      await this.api.apiCNCSpindleStopSpindlePost();
      this.spindleRunning = false;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to stop spindle:', error);
      throw error;
    }
  }

  async IsSpindleRunning(): Promise<boolean> {
    try {
      const response = await this.api.apiCNCSpindleIsSpindleRunningGet();
      const isRunning = (response as any).data === true;
      this.spindleRunning = isRunning; // Update local cache
      return isRunning;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to check spindle running status:', error);
      return this.spindleRunning; // Return cached value on error
    }
  }
}