import { PLCProgram } from '../centroid/plc/data/PLCProgram';
import { PLCProgramType } from '../centroid/plc/data/PLCUtilities';
import { CNCPoint } from '../data/CNCPoint';
import { CoordinateType } from '../data/Common/CoordinateType';
import { ConfigurationData } from '../data/ConfigurationData';
import { ConfigurationState, JogIncrementSpeed } from '../data/ConfigurationState';
import { DataManager } from '../data/DataManager';
import { DROEvent, ServerStatusEvent } from '../data/SignalR/SignalREventTypes';
import { SignalRStateData } from '../data/SignalRStateData';
import { UserMessageQueue } from '../data/UserMessageQueue';
import { Machine } from '../machine/Machine';
import { CoordinateUtil } from './CoordinateUtil';
import { LogCategory, Logger } from './Logger';
import { MachineInterfaceManager } from './MachineInterfaceManager';
import { ConnectionState, SignalRManager } from './SignalRManager';

/**
 * SignalRPositionUpdater - Listens for DRO and ServerStatus events and updates machine position
 * This is used in Centroid mode to keep the UI in sync with actual machine position
 */
export class SignalRPositionUpdater {
    private static _instance: SignalRPositionUpdater;
    private _isListening: boolean = false;
    private _lastConnectionState: ConnectionState = ConnectionState.Disconnected;
    private _tolerance: number = 0.0001; // Tolerance for coordinate comparison (machine units)
    private _hasReceivedFirstPosition: boolean = false; // Track if we've received first position from server status
    private _lastServerStatusTime: Date | null = null; // Last server status timestamp
    private _serverStatusWarningShown: boolean = false; // Flag to prevent spam
    private _serverStatusCheckInterval: NodeJS.Timeout | null = null; // Interval for monitoring

    // DRO polling mechanism
    private _droPollTimer: NodeJS.Timeout | null = null; // Timer for polling API
    private _lastDROEventTime: number | null = null; // Last time a DRO event was received

    // PLC version tracking for staleness detection
    private _lastKnownServerPLCVersion: string = '0.0.0'; // Last PLC version from server
    private _isReloadingData: boolean = false; // Prevent concurrent reloads

    private constructor() {
        // Private constructor for singleton
        // Watch for connection state changes to handle reconnection
        try {
            this._watchConnectionState();
        } catch (error) {
            Logger.Instance.logError(LogCategory.Network, '[SignalRPositionUpdater] Error in _watchConnectionState:', error);
        }
    }

    public static get Instance(): SignalRPositionUpdater {
        if (!SignalRPositionUpdater._instance) {
            SignalRPositionUpdater._instance = new SignalRPositionUpdater();
        }
        return SignalRPositionUpdater._instance;
    }

    /**
     * Start listening for DRO and ServerStatus position updates
     */
    public startListening(): void {
        if (this._isListening) {
            return;
        }

        // Add listeners for DRO and ServerStatus events
        SignalRManager.Instance.addEventListener('DROEvent', this._handleDROEvent);
        SignalRManager.Instance.addEventListener('ServerStatus', this._handleServerStatusEvent);
        this._isListening = true;

        // Start monitoring for missing server status (check every 10 seconds)
        this._serverStatusCheckInterval = setInterval(() => {
            if (!this._lastServerStatusTime) return;

            const timeSinceLastStatus = Date.now() - this._lastServerStatusTime.getTime();
            const expectedInterval = 2000; // 2 seconds between status updates

            if (timeSinceLastStatus > expectedInterval * 3 && !this._serverStatusWarningShown) {
                Logger.Instance.logError(
                    LogCategory.Network,
                    `⚠️ NO SERVER STATUS: Last status was ${Math.floor(timeSinceLastStatus / 1000)}s ago (expected every ${expectedInterval / 1000}s)`
                );
                this._serverStatusWarningShown = true;
            }
        }, 10000);
    }

    /**
     * Compare two version strings numerically
     * Returns: -1 if v1 < v2, 0 if equal, 1 if v1 > v2
     */
    private _compareVersions(v1: string, v2: string): number {
        const parts1 = v1.split('.').map(p => parseInt(p) || 0);
        const parts2 = v2.split('.').map(p => parseInt(p) || 0);

        // Compare major version
        if (parts1[0] !== parts2[0]) return parts1[0] > parts2[0] ? 1 : -1;

        // Compare minor version
        if (parts1[1] !== parts2[1]) return parts1[1] > parts2[1] ? 1 : -1;

        // Compare update version
        if (parts1[2] !== parts2[2]) return parts1[2] > parts2[2] ? 1 : -1;

        return 0; // Equal
    }

    /**
     * Check if local PLC data is stale compared to server version
     * Triggers data reload if server has newer version or local data is missing
     */
    private async _checkPLCVersionStaleness(serverVersionString: string): Promise<void> {
        // Skip if already reloading
        if (this._isReloadingData) {
            return;
        }

        // Skip if server version hasn't changed since last check
        if (serverVersionString === this._lastKnownServerPLCVersion) {
            return;
        }

        try {
            const systemPLC = PLCProgram.Instance(PLCProgramType.System) as any;
            const localVersionString = systemPLC.getVersionString ? systemPLC.getVersionString() : '0.0.0';

            // Check if local data is missing (version is 0.0.0)
            const isLocalDataMissing = localVersionString === '0.0.0';

            // Compare versions
            const comparison = this._compareVersions(serverVersionString, localVersionString);

            // Reload if server is newer OR local data is missing
            if (comparison > 0 || isLocalDataMissing) {
                Logger.Instance.log(
                    LogCategory.DataManager,
                    `⚠ PLC version mismatch detected - Server: ${serverVersionString}, Local: ${localVersionString}. Reloading all data...`
                );

                // Update last known version before reload to prevent multiple triggers
                this._lastKnownServerPLCVersion = serverVersionString;
                this._isReloadingData = true;

                // Reload all data from server
                await DataManager.Instance.initializeOnStartup();

                // Note: DataManager.initializeOnStartup() already calls DataReloadNotifier
                // so we don't need to call it again here

                // Show user notification
                UserMessageQueue.Instance.addMessage(
                    `✓ Data reloaded - Server PLC version: ${serverVersionString}`
                );

                Logger.Instance.log(
                    LogCategory.DataManager,
                    `✓ Data reload complete - updated to server version ${serverVersionString}`
                );

                this._isReloadingData = false;
            } else if (comparison < 0) {
                // Local version is NEWER than server - log warning but don't reload
                // This can happen if user is developing and hasn't installed yet
                Logger.Instance.log(
                    LogCategory.DataManager,
                    `⚠ Local PLC version (${localVersionString}) is newer than server (${serverVersionString}) - not reloading`
                );
                this._lastKnownServerPLCVersion = serverVersionString;
            } else {
                // Versions match - update last known version
                this._lastKnownServerPLCVersion = serverVersionString;
            }
        } catch (error) {
            Logger.Instance.logError(
                LogCategory.DataManager,
                'Failed to check PLC version staleness:',
                error
            );
            this._isReloadingData = false;
        }
    }

    /**
     * Stop listening for DRO and ServerStatus position updates
     */
    public stopListening(): void {
        if (!this._isListening) {
            return;
        }

        SignalRManager.Instance.removeEventListener('DROEvent', this._handleDROEvent);
        SignalRManager.Instance.removeEventListener('ServerStatus', this._handleServerStatusEvent);
        this._isListening = false;

        if (this._serverStatusCheckInterval) {
            clearInterval(this._serverStatusCheckInterval);
            this._serverStatusCheckInterval = null;
        }

        // Clear DRO poll timer
        if (this._droPollTimer) {
            clearTimeout(this._droPollTimer);
            this._droPollTimer = null;
        }

    }

    /**
     * Handle DRO event from SignalR
     */
    private _handleDROEvent = (event: DROEvent): void => {
        try {
            // Log DRO event at debug level (high frequency messages)
            Logger.Instance.logDebug(LogCategory.DataManager, 'DROMessage');

            // Check if DRO polling mode is enabled (but skip polling in simulator mode)
            const isSimulator = MachineInterfaceManager.Instance.isUsingSimulator();
            if (ConfigurationData.Instance.enableDROPolling && !isSimulator) {
                // In polling mode, treat DRO event as a notification to poll API
                this._handleDROEventPolling();
                return;
            }

            // Normal mode: extract position from DRO event data
            const data = event.data;

            // Create CNCPoint from DRO data
            // DRO data comes in MachineHome coordinates from Centroid
            // (relative to machine home corner, not machine zero)
            const machineHomePosition = new CNCPoint(
                data.axis1, // X
                data.axis2, // Y
                data.axis3, // Z
                CoordinateType.MachineHome
            );

            // Convert to MachineZero coordinates (the system currentMachinePoint uses)
            const newPosition = CoordinateUtil.toMachineZero(machineHomePosition);

            // Update position immediately
            this._updatePositionIfDifferent(newPosition);
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Error handling DRO event:', error);
        }
    };

    /**
     * Handle DRO event in polling mode - triggers API poll for position
     */
    private _handleDROEventPolling = (): void => {
        try {
            // Update last DRO event time
            this._lastDROEventTime = Date.now();

            // If poll timer is not running, start polling
            if (!this._droPollTimer) {
                this._startDROPolling();
            }
            // If timer is already running, it will continue polling based on the interval
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Error handling DRO event in polling mode:', error);
        }
    };

    /**
     * Start DRO polling - fetch position from API at configured interval
     */
    private _startDROPolling = async (): Promise<void> => {
        try {
            // Fetch current position from API
            const machine = Machine.getInstance();
            const position = await machine.movement.GetCurrentPosition();

            // Update position if different (with logging for polling mode)
            this._updatePositionIfDifferentPolling(position);

            // Get configured poll interval
            const pollInterval = ConfigurationData.Instance.droPollInterval;

            // Schedule next poll
            this._droPollTimer = setTimeout(async () => {
                // Check if we've received a DRO event recently
                if (this._lastDROEventTime) {
                    const timeSinceLastEvent = Date.now() - this._lastDROEventTime;

                    // If no DRO event in the last poll interval, stop polling
                    if (timeSinceLastEvent > pollInterval) {
                        Logger.Instance.logDebug(LogCategory.DataManager, 'DRO polling stopped - no recent events');
                        this._droPollTimer = null;
                        this._lastDROEventTime = null;
                        return;
                    }
                }

                // Continue polling
                this._droPollTimer = null;
                await this._startDROPolling();
            }, pollInterval);
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Error during DRO polling:', error);
            // Stop polling on error
            this._droPollTimer = null;
            this._lastDROEventTime = null;
        }
    };    /**
     * Handle ServerStatus event from SignalR
     */
    private _handleServerStatusEvent = async (event: ServerStatusEvent): Promise<void> => {
        try {
            const data = event.data;

            // Track server status timing
            const now = new Date();
            this._lastServerStatusTime = now;
            this._serverStatusWarningShown = false; // Reset warning flag

            // Check if isApiRestricted differs from current state
            const isApiRestrictedChanged = data.isApiRestricted !== ConfigurationState.Instance.isApiRestricted;

            // Check if position differs from current machine point
            let hasPositionChange = false;
            if (data.position) {
                const currentPosition = ConfigurationState.Instance.currentMachinePoint;
                const machineHomePosition = new CNCPoint(
                    data.position.x,
                    data.position.y,
                    data.position.z,
                    CoordinateType.MachineHome
                );
                const newPosition = CoordinateUtil.toMachineZero(machineHomePosition);

                const xDifferent = Math.abs(currentPosition.x - newPosition.x) > this._tolerance;
                const yDifferent = Math.abs(currentPosition.y - newPosition.y) > this._tolerance;
                const zDifferent = Math.abs(currentPosition.z - newPosition.z) > this._tolerance;
                hasPositionChange = xDifferent || yDifferent || zDifferent;
            }

            // Only log when something actually changes
            if (isApiRestrictedChanged || hasPositionChange) {
                const reasons = [];
                if (isApiRestrictedChanged) {
                    reasons.push(`isApiRestricted: ${!data.isApiRestricted} → ${data.isApiRestricted}`);
                }
                if (hasPositionChange) {
                    reasons.push(`pos: X:${data.position!.x.toFixed(4)} Y:${data.position!.y.toFixed(4)} Z:${data.position!.z.toFixed(4)}`);
                }
                Logger.Instance.log(
                    LogCategory.DataManager,
                    `ServerStatusMessage: ${reasons.join(', ')}`
                );
            }

            // Update connection state in ConfigurationState
            // Skip in simulator mode - simulator is always connected
            if (!MachineInterfaceManager.Instance.isUsingSimulator()) {
                ConfigurationState.Instance.isConnected = data.isConnected;
            }

            // Update API restricted state in ConfigurationState (independent tracking)
            if (ConfigurationState.Instance.isApiRestricted !== data.isApiRestricted) {
                ConfigurationState.Instance.isApiRestricted = data.isApiRestricted;
                // State change notification and logging is handled by the setter
            }

            // Update installed PLC version if provided
            if (data.plcVersion) {
                ConfigurationState.Instance.installedPLCVersion = data.plcVersion;

                // Check for PLC version staleness and trigger reload if needed
                const serverVersionString = `${data.plcVersion.major}.${data.plcVersion.minor}.${data.plcVersion.update}`;
                await this._checkPLCVersionStaleness(serverVersionString);
            }

            // Update board type if provided (store in MachineData, not ConfigurationState)
            if (data.boardType) {
                // Don't overwrite user configuration - server detection is unreliable
                // MachineData.Instance.boardType = data.boardType;
            }

            // Update expansion board count if provided (store in MachineData, not ConfigurationState)
            if (data.expansionBoardCount !== undefined) {
                // Don't overwrite user configuration - server detection is unreliable
                // MachineData.Instance.expansionBoardCount = data.expansionBoardCount;
            }

            // Update jog mode in ConfigurationState from server status
            // Server sends JogSettings.IsIncremental, we store jogContinuousMode (inverted)
            if (data.JogSettings) {
                const newContinuousMode = !data.JogSettings.IsIncremental;
                if (ConfigurationState.Instance.jogContinuousMode !== newContinuousMode) {
                    ConfigurationState.Instance.jogContinuousMode = newContinuousMode;


                }
            }

            // Update fast jog mode in ConfigurationState from server status
            // Server sends JogSettings.IsSlowMode, we store jogFastMode (inverted)
            if (data.JogSettings) {
                const newFastMode = !data.JogSettings.IsSlowMode;
                if (ConfigurationState.Instance.jogFastMode !== newFastMode) {
                    ConfigurationState.Instance.jogFastMode = newFastMode;

                }
            }

            // Update jog increment speed in ConfigurationState from server status
            // Server sends JogSettings.IncrementSpeed as string ('X1', 'X10', 'X100')
            if (data.JogSettings && data.JogSettings.IncrementSpeed) {
                const newIncrementSpeed = data.JogSettings.IncrementSpeed as JogIncrementSpeed;
                if (ConfigurationState.Instance.jogIncrementSpeed !== newIncrementSpeed) {
                    ConfigurationState.Instance.jogIncrementSpeed = newIncrementSpeed;
                    // State change notification is handled by the setter
                    Logger.Instance.log(
                        LogCategory.DataManager,
                        `Jog increment speed synced from server: ${newIncrementSpeed}`
                    );
                }
            }

            // Update job running state in ConfigurationState from server status
            if (ConfigurationState.Instance.isJobRunning !== data.isJobRunning) {
                ConfigurationState.Instance.isJobRunning = data.isJobRunning;
                // State change notification is handled by the setter
                Logger.Instance.log(
                    LogCategory.DataManager,
                    `Job running state synced from server: ${data.isJobRunning ? 'Running' : 'Stopped'}`
                );
            }

            // Update homed state in ConfigurationState from server status
            // Only sync if CNC12 is connected - otherwise ignore (simulator controls its own homing state)
            if (data.isConnected && ConfigurationState.Instance.isHomed !== data.isHomed) {
                ConfigurationState.Instance.isHomed = data.isHomed;
                // State change notification is handled by the setter
                Logger.Instance.log(
                    LogCategory.DataManager,
                    `Homed state synced from server: ${data.isHomed ? 'Homed' : 'Not Homed'}`
                );
            }

            // Update requiresReset state directly from server status (SV_STOP state)
            if (ConfigurationState.Instance.requiresReset !== data.requiresReset) {
                ConfigurationState.Instance.requiresReset = data.requiresReset;
                // State change notification is handled by the setter
                if (data.requiresReset) {
                    Logger.Instance.logError(
                        LogCategory.System,
                        '⚠️ RESET REQUIRED: Machine requires reset (SV_STOP) before operations can continue'
                    );
                } else {
                    Logger.Instance.log(
                        LogCategory.System,
                        '✓ Reset no longer required - machine ready for operations'
                    );
                }
            }

            // Log when not connected
            if (!data.isConnected) {
                return;
            }

            // Log when position is missing
            if (!data.position) {
                return;
            }

            // Create CNCPoint from server status position data
            // ServerStatus position comes in MachineHome coordinates
            const machineHomePosition = new CNCPoint(
                data.position.x,
                data.position.y,
                data.position.z,
                CoordinateType.MachineHome
            );

            // Convert to MachineZero coordinates (the system currentMachinePoint uses)
            const newPosition = CoordinateUtil.toMachineZero(machineHomePosition);

            // Update position if it's different
            this._updatePositionIfDifferent(newPosition);
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Error handling ServerStatus event:', error);
        }
    };

    /**
     * Update machine position if it differs from current position
     */
    private _updatePositionIfDifferent(newPosition: CNCPoint): void {
        const currentPosition = ConfigurationState.Instance.currentMachinePoint;

        // Compare coordinates with tolerance
        const xDifferent = Math.abs(currentPosition.x - newPosition.x) > this._tolerance;
        const yDifferent = Math.abs(currentPosition.y - newPosition.y) > this._tolerance;
        const zDifferent = Math.abs(currentPosition.z - newPosition.z) > this._tolerance;

        // Only update if at least one coordinate has changed significantly
        if (xDifferent || yDifferent || zDifferent) {
            ConfigurationState.Instance.currentMachinePoint = newPosition;
            // Note: StateManager.propertyChanged is already called in the setter

            // Log first position update from server status
            if (!this._hasReceivedFirstPosition) {
                this._hasReceivedFirstPosition = true;

            }
        }

        // Position updates happen constantly - no logging needed for subsequent updates
    }

    /**
     * Update machine position in polling mode with logging
     */
    private _updatePositionIfDifferentPolling(newPosition: CNCPoint): void {
        const currentPosition = ConfigurationState.Instance.currentMachinePoint;

        // Compare coordinates with tolerance
        const xDifferent = Math.abs(currentPosition.x - newPosition.x) > this._tolerance;
        const yDifferent = Math.abs(currentPosition.y - newPosition.y) > this._tolerance;
        const zDifferent = Math.abs(currentPosition.z - newPosition.z) > this._tolerance;

        // Only update if at least one coordinate has changed significantly
        if (xDifferent || yDifferent || zDifferent) {
            ConfigurationState.Instance.currentMachinePoint = newPosition;
            // Note: StateManager.propertyChanged is already called in the setter

            // Log position update in polling mode at debug level (high frequency messages)
            Logger.Instance.logDebug(
                LogCategory.DataManager,
                `PollingUpdate: X=${newPosition.x.toFixed(4)} Y=${newPosition.y.toFixed(4)} Z=${newPosition.z.toFixed(4)}`
            );
        }
    }

    /**
     * Watch for connection state changes to handle reconnection
     */
    private _watchConnectionState(): void {

        // Check connection state periodically
        setInterval(async () => {
            try {
                // Skip connection state management if machine doesn't require SignalR monitoring (simulator mode)
                const machine = Machine.getInstance();
                const requiresMonitoring = machine.requiresSignalRMonitoring();

                if (!requiresMonitoring) {
                    // Simulator mode - always consider connected (no real machine to connect to)
                    ConfigurationState.Instance.isConnected = true;
                    return;
                }

                const currentState = SignalRStateData.Instance.connectionState;

                // Update ConfigurationState connection state based on SignalR state
                // Skip this in simulator mode - simulator is always "connected"
                if (!MachineInterfaceManager.Instance.isUsingSimulator()) {
                    if (currentState === ConnectionState.Disconnected || currentState === ConnectionState.Reconnecting) {
                        ConfigurationState.Instance.isConnected = false;
                    }
                }

                // Detect when we transition from Reconnecting/Disconnected to Connected
                if (currentState === ConnectionState.Connected &&
                    (this._lastConnectionState === ConnectionState.Reconnecting ||
                        this._lastConnectionState === ConnectionState.Disconnected)) {

                    await this._handleReconnection();
                }

                // When SignalR is connected, verify server is actually responding
                if (currentState === ConnectionState.Connected) {
                    await this._verifyServerConnection();
                }

                this._lastConnectionState = currentState;
            } catch (error) {
                // Log any errors in connection state checking but don't change connection state
                // Always log to console for visibility
                console.error('[SignalRPositionUpdater] Error in _watchConnectionState:', error);
                Logger.Instance.logError(LogCategory.Network, 'Error checking connection state:', error);
            }
        }, 1000); // Check every second
    }

    /**
     * Verify server is actually responding (not just SignalR connected)
     */
    private _verifyServerConnection = async (): Promise<void> => {
        // Skip verification in simulator mode - simulator is always "connected"
        if (MachineInterfaceManager.Instance.isUsingSimulator()) {
            return;
        }

        try {
            const machine = Machine.getInstance();
            const isConnected = await machine.system.IsConnectedToServer();

            // Update connection state
            if (ConfigurationState.Instance.isConnected !== isConnected) {
                ConfigurationState.Instance.isConnected = isConnected;
                if (isConnected) {
                    Logger.Instance.log(LogCategory.Network, 'Server connection verified');
                }
            }
        } catch (error) {
            // API call failed - definitely not connected
            if (ConfigurationState.Instance.isConnected) {
                ConfigurationState.Instance.isConnected = false;
                Logger.Instance.logError(LogCategory.Network, 'Server verification failed:', error);
            }
        }
    };

    /**
     * Handle reconnection - re-establish fixture/work zero with the machine
     */
    private _handleReconnection = async (): Promise<void> => {
        try {
            const machine = Machine.getInstance();

            // Re-establish the fixture point (work zero)
            await machine.movement.SetCurrentFixturePoint();

            Logger.Instance.log(LogCategory.Network, 'Re-established fixture point after reconnection');
        } catch (error) {
            Logger.Instance.logError(LogCategory.Network, 'Failed to re-establish fixture point after reconnection:', error);
        }
    };

    /**
     * Check if currently listening
     */
    public get isListening(): boolean {
        return this._isListening;
    }
}
