import { Box } from '@mui/material';
import { useState } from 'react';
import { ConfigurationState } from '../../data/ConfigurationState';
import { Job } from '../../data/Job';
import { MachineData } from '../../data/Machine/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { ViewDataFactory, ViewNames } from '../../utils/ViewDataFactory';
import { FullSizeCNCViewer } from '../MachineViewer/FullSizeCNCViewer';

interface HomeProps {
  onViewChange?: (view: string) => void;
}

export function Home({ onViewChange }: HomeProps) {
  const [machineState] = useState(() => MachineStateData.Instance);
  const [machineData] = useState(() => MachineData.Instance);
  const [simulatorViewData] = useState(() => ViewDataFactory.createForContext(ViewNames.HOME));

  return (
    <Box sx={{ width: '100%', height: '100%', overflow: 'hidden' }}>
      <FullSizeCNCViewer
        simulatorViewData={simulatorViewData}
        machineState={machineState}
        machineData={machineData}
        job={ConfigurationState.Instance.currentJob || Job.createTestJob()}
      />
    </Box>
  );
}
