import { MaterialType } from '../data/Common/MaterialLibrary';
import { Job } from '../data/Job';
import { GCodeFileData, GCodeFileMetadata, ICNCJobStorage, JobMetadata, ListJobsRequest } from '../machine/ICNCJobStorage';
import { JobStorageApi } from '../services/src/apis/JobStorageApi';
import { BackendAvailabilityChecker } from '../utils/BackendAvailabilityChecker';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';

/**
 * Simulator implementation of ICNCJobStorage
 * - Checks if backend exists (via Machine.setup API)
 * - If backend exists, calls API endpoints
 * - If no backend, stores in localStorage with combined storage
 */
export class SimulatorCNCJobStorage implements ICNCJobStorage {
    private readonly LOCAL_STORAGE_JOBS_KEY = 'havencnc_simulator_jobs';
    private readonly LOCAL_STORAGE_GCODE_KEY = 'havencnc_simulator_gcode';
    private readonly LOCAL_STORAGE_LAST_JOB_KEY = 'havencnc_simulator_lastjob';

    // In-memory cache for localStorage mode
    private jobsCache: Map<string, Job> = new Map();
    private gcodeCache: Map<string, Map<string, GCodeFileData>> = new Map(); // directory -> filename -> file
    private isInitialized = false;
    private readonly jobStorageApi: JobStorageApi;

    constructor() {
        const config = MachineInterfaceManager.Instance.getServiceConfiguration();
        this.jobStorageApi = new JobStorageApi(config);
        this.initializeLocalStorage();
    }

    /**
     * Check if backend API is available
     */
    private async isBackendAvailable(): Promise<boolean> {
        return await BackendAvailabilityChecker.isBackendAvailable();
    }

    /**
     * Initialize localStorage with test data if empty
     */
    private initializeLocalStorage(): void {
        if (this.isInitialized) return;

        try {
            // Load existing data from localStorage
            const jobsJson = localStorage.getItem(this.LOCAL_STORAGE_JOBS_KEY);
            if (jobsJson) {
                const jobsArray = JSON.parse(jobsJson);
                for (const jobData of jobsArray) {
                    const job = new Job();
                    job.fromJSON(jobData);
                    this.jobsCache.set(job.id, job);
                }
            }

            // Load G-code files
            const gcodeJson = localStorage.getItem(this.LOCAL_STORAGE_GCODE_KEY);
            if (gcodeJson) {
                const gcodeData = JSON.parse(gcodeJson);
                for (const [directory, files] of Object.entries(gcodeData)) {
                    const fileMap = new Map<string, GCodeFileData>();
                    for (const file of files as GCodeFileData[]) {
                        fileMap.set(file.name, file);
                    }
                    this.gcodeCache.set(directory, fileMap);
                }
            }

            this.isInitialized = true;
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to initialize SimulatorCNCJobStorage:', error);
        }
    }

    /**
     * Save jobs to localStorage
     */
    private saveJobsToLocalStorage(): void {
        try {
            const jobsArray = Array.from(this.jobsCache.values()).map(job => job.toJSON());
            localStorage.setItem(this.LOCAL_STORAGE_JOBS_KEY, JSON.stringify(jobsArray));
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to save jobs to localStorage:', error);
        }
    }

    /**
     * Save G-code files to localStorage
     */
    private saveGCodeToLocalStorage(): void {
        try {
            const gcodeData: Record<string, GCodeFileData[]> = {};
            for (const [directory, fileMap] of this.gcodeCache.entries()) {
                gcodeData[directory] = Array.from(fileMap.values());
            }
            localStorage.setItem(this.LOCAL_STORAGE_GCODE_KEY, JSON.stringify(gcodeData));
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to save G-code to localStorage:', error);
        }
    }

    // ==================== G-CODE FILE OPERATIONS ====================

    async listGCodeFiles(
        directories: string[],
        fileExtensions: string[]
    ): Promise<GCodeFileMetadata[]> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                const result = await this.jobStorageApi.apiJobStorageGcodeListPost({
                    listGCodeFilesRequest: {
                        directories: directories,
                        fileExtensions: fileExtensions
                    }
                });

                return result.map(item => ({
                    name: item.name || '',
                    directory: item.directory || '',
                    category: item.category || undefined,
                    description: item.description || undefined,
                    materialType: (item.materialType || undefined) as MaterialType | undefined,
                    estimatedTime: item.estimatedTime || undefined,
                    lastModified: item.lastModified ? new Date(item.lastModified) : new Date(),
                    size: item.size || 0,
                    lineCount: item.lineCount || undefined
                }));
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        return this.listGCodeFilesLocal(directories, fileExtensions);
    }

    private listGCodeFilesLocal(
        directories: string[],
        fileExtensions: string[]
    ): GCodeFileMetadata[] {
        const allFiles: GCodeFileMetadata[] = [];
        for (const directory of directories) {
            const fileMap = this.gcodeCache.get(directory);
            if (fileMap) {
                for (const file of fileMap.values()) {
                    const fileExt = file.name.substring(file.name.lastIndexOf('.')).toLowerCase();
                    if (fileExtensions.length === 0 || fileExtensions.some(ext => ext.toLowerCase() === fileExt)) {
                        allFiles.push(this.toMetadata(file));
                    }
                }
            }
        }
        // Sort by lastModified descending
        allFiles.sort((a, b) => b.lastModified.getTime() - a.lastModified.getTime());
        return allFiles;
    }

    private toMetadata(file: GCodeFileData): GCodeFileMetadata {
        return {
            name: file.name,
            directory: file.directory,
            category: file.category,
            description: file.description,
            materialType: file.materialType,
            estimatedTime: file.estimatedTime,
            lastModified: file.lastModified,
            size: file.size
        };
    }

    async fetchGCodeFile(
        directory: string,
        fileName: string
    ): Promise<GCodeFileData | null> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                const result = await this.jobStorageApi.apiJobStorageGcodeGet({
                    directory: directory,
                    fileName: fileName
                });

                if (!result) return null;

                return {
                    name: result.name || fileName,
                    directory: result.directory || directory,
                    content: result.content || '',
                    category: result.category || undefined,
                    description: result.description || undefined,
                    materialType: (result.materialType || undefined) as MaterialType | undefined,
                    estimatedTime: result.estimatedTime || undefined,
                    lastModified: result.lastModified ? new Date(result.lastModified) : new Date(),
                    size: result.size || 0,
                    lineCount: result.lineCount || undefined
                };
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        return this.fetchGCodeFileLocal(directory, fileName);
    }

    private fetchGCodeFileLocal(
        directory: string,
        fileName: string
    ): GCodeFileData | null {
        const fileMap = this.gcodeCache.get(directory);
        return fileMap?.get(fileName) || null;
    }

    async storeGCodeFile(
        directory: string,
        fileData: GCodeFileData
    ): Promise<boolean> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                await this.jobStorageApi.apiJobStorageGcodePost({
                    storeGCodeFileRequest: {
                        fileName: `${directory}\\${fileData.name}`,
                        data: fileData.content,
                        category: fileData.category,
                        description: fileData.description,
                        materialType: fileData.materialType,
                        estimatedTime: fileData.estimatedTime
                    }
                });
                return true;
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        return this.storeGCodeFileLocal(directory, fileData);
    }

    private storeGCodeFileLocal(
        directory: string,
        fileData: GCodeFileData
    ): boolean {
        try {
            let fileMap = this.gcodeCache.get(directory);
            if (!fileMap) {
                fileMap = new Map();
                this.gcodeCache.set(directory, fileMap);
            }

            fileData.lastModified = new Date();
            fileData.size = fileData.content.length;
            fileMap.set(fileData.name, fileData);

            this.saveGCodeToLocalStorage();
            return true;
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to store G-code file:', error);
            return false;
        }
    }

    async deleteGCodeFile(
        directory: string,
        fileName: string
    ): Promise<boolean> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                await this.jobStorageApi.apiJobStorageGcodeDelete({
                    fileId: `${directory}\\${fileName}`
                });
                return true;
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        return this.deleteGCodeFileLocal(directory, fileName);
    }

    private deleteGCodeFileLocal(directory: string, fileName: string): boolean {
        const fileMap = this.gcodeCache.get(directory);
        if (fileMap && fileMap.delete(fileName)) {
            this.saveGCodeToLocalStorage();
            return true;
        }
        return false;
    }

    async setGCodeFileCategory(
        directory: string,
        fileName: string,
        category: string | undefined
    ): Promise<boolean> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                await this.jobStorageApi.apiJobStorageGcodeCategoryPut({
                    updateGCodeCategoryRequest: {
                        directory: directory,
                        fileName: fileName,
                        category: category
                    }
                });
                return true;
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        // Local fallback: update category in cache and persist
        const file = this.fetchGCodeFileLocal(directory, fileName);
        if (file) {
            file.category = category;
            return this.storeGCodeFileLocal(directory, file);
        }
        return false;
    }

    async searchGCodeFiles(
        query: string,
        directories?: string[],
        fileExtensions?: string[]
    ): Promise<GCodeFileMetadata[]> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                const result = await this.jobStorageApi.apiJobStorageGcodeSearchPost({
                    gCodeSearchRequest: {
                        query: query,
                        directories: directories,
                        fileExtensions: fileExtensions
                    }
                });

                return result.map(item => ({
                    name: item.name || '',
                    directory: item.directory || '',
                    category: item.category || undefined,
                    description: item.description || undefined,
                    materialType: (item.materialType || undefined) as MaterialType | undefined,
                    estimatedTime: item.estimatedTime || undefined,
                    lastModified: item.lastModified ? new Date(item.lastModified) : new Date(),
                    size: item.size || 0,
                    lineCount: item.lineCount || undefined
                }));
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        const lowerQuery = query.toLowerCase();
        const allFiles = this.listGCodeFilesLocal(
            directories ?? Array.from(this.gcodeCache.keys()),
            fileExtensions ?? []
        );
        return allFiles.filter(f =>
            f.name.toLowerCase().includes(lowerQuery) ||
            (f.category?.toLowerCase().includes(lowerQuery) ?? false) ||
            (f.description?.toLowerCase().includes(lowerQuery) ?? false)
        );
    }

    async listJobs(request: ListJobsRequest): Promise<JobMetadata[]> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                const result = await this.jobStorageApi.apiJobStorageJobsListPost({
                    listJobsRequest: {
                        maxCount: request.maxCount ?? null,
                        sortBy: request.sortBy ?? null,
                        sortDirection: request.sortDirection ?? null
                    }
                });

                return result.map(item => ({
                    id: item.id || '',
                    name: item.name || '',
                    lastModified: item.lastModified ? new Date(item.lastModified) : new Date(),
                    createdAt: item.createdAt ? new Date(item.createdAt) : new Date(),
                    size: item.size || 0,
                    executionCount: item.executionCount || 0,
                    lastRunDate: item.lastRunDate ? new Date(item.lastRunDate) : undefined,
                    category: item.category || undefined,
                    description: item.description || undefined,
                    materialType: (item.materialType || undefined) as MaterialType | undefined,
                    estimatedTime: item.estimatedTime || undefined
                }));
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        return this.listJobsLocal(request);
    }

    private listJobsLocal(request: ListJobsRequest): JobMetadata[] {
        const allJobs: JobMetadata[] = Array.from(this.jobsCache.values()).map(job =>
            this.jobToMetadata(job)
        );

        const sortBy = request.sortBy || 'lastModified';
        const sortDirection = request.sortDirection || 'desc';
        allJobs.sort((a, b) => {
            let comparison = 0;
            if (sortBy === 'name') {
                comparison = a.name.localeCompare(b.name);
            } else if (sortBy === 'lastModified') {
                comparison = a.lastModified.getTime() - b.lastModified.getTime();
            } else if (sortBy === 'lastRun') {
                comparison = (a.lastRunDate?.getTime() ?? 0) - (b.lastRunDate?.getTime() ?? 0);
            } else if (sortBy === 'executionCount') {
                comparison = a.executionCount - b.executionCount;
            }
            return sortDirection === 'asc' ? comparison : -comparison;
        });

        return request.maxCount !== undefined ? allJobs.slice(0, request.maxCount) : allJobs;
    }

    async searchJobs(
        query: string,
        maxCount?: number
    ): Promise<JobMetadata[]> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                const result = await this.jobStorageApi.apiJobStorageJobsSearchPost({
                    jobSearchRequest: {
                        query: query,
                        maxCount: maxCount
                    }
                });

                return result.map(item => ({
                    id: item.id || '',
                    name: item.name || '',
                    lastModified: item.lastModified ? new Date(item.lastModified) : new Date(),
                    createdAt: item.createdAt ? new Date(item.createdAt) : new Date(),
                    size: item.size || 0,
                    executionCount: item.executionCount || 0,
                    lastRunDate: item.lastRunDate ? new Date(item.lastRunDate) : undefined,
                    category: item.category || undefined,
                    description: item.description || undefined,
                    materialType: (item.materialType || undefined) as MaterialType | undefined,
                    estimatedTime: item.estimatedTime || undefined
                }));
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        const lowerQuery = query.toLowerCase();
        const allJobs = this.listJobsLocal({
            maxCount: maxCount,
            sortBy: 'lastModified',
            sortDirection: 'desc'
        });
        return allJobs.filter(j =>
            j.name.toLowerCase().includes(lowerQuery) ||
            (j.category?.toLowerCase().includes(lowerQuery) ?? false) ||
            (j.description?.toLowerCase().includes(lowerQuery) ?? false) ||
            (j.materialType?.toLowerCase().includes(lowerQuery) ?? false)
        );
    }

    private jobToMetadata(job: Job): JobMetadata {
        const json = JSON.stringify(job.toJSON());
        return {
            id: job.id,
            name: job.name,
            lastModified: new Date(), // TODO: Track in Job class
            createdAt: new Date(), // TODO: Track in Job class
            size: json.length,
            executionCount: job.executionCount,
            lastRunDate: job.runStatistics.length > 0
                ? new Date(Math.max(...job.runStatistics.map(s => s.endTime.getTime())))
                : undefined,
            category: undefined, // TODO: Add to Job class
            description: undefined, // TODO: Add to Job class
            materialType: job.material?.type,
            estimatedTime: undefined // TODO: Calculate from G-code
        };
    }

    async fetchJob(jobId: string): Promise<Job | null> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                const result = await this.jobStorageApi.apiJobStorageJobsIdGet({ id: jobId });
                if (!result) return null;

                const jobData = JSON.parse(result);
                const job = new Job();
                job.fromJSON(jobData);
                return job;
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        return this.fetchJobLocal(jobId);
    }

    private fetchJobLocal(jobId: string): Job | null {
        return this.jobsCache.get(jobId) || null;
    }

    async getLastJob(): Promise<Job | null> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                const result = await this.jobStorageApi.apiJobStorageJobsLastGet();
                if (!result) return null;

                const jobData = JSON.parse(result);
                const job = new Job();
                job.fromJSON(jobData);
                return job;
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        return this.getLastJobLocal();
    }

    private getLastJobLocal(): Job | null {
        try {
            const lastJobId = localStorage.getItem(this.LOCAL_STORAGE_LAST_JOB_KEY);
            if (lastJobId) {
                return this.jobsCache.get(lastJobId) || null;
            }
            return null;
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to get last job:', error);
            return null;
        }
    }

    async saveLastJob(job: Job): Promise<boolean> {
        if (!job.gcode?.trim()) return false;
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                await this.jobStorageApi.apiJobStorageJobsLastPost({
                    saveLastJobRequest: {
                        jobId: job.id
                    }
                });
                return true;
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        return this.saveLastJobLocal(job);
    }

    private saveLastJobLocal(job: Job): boolean {
        try {
            localStorage.setItem(this.LOCAL_STORAGE_LAST_JOB_KEY, job.id);
            return true;
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to save last job:', error);
            return false;
        }
    }

    async storeJob(job: Job): Promise<boolean> {
        if (!job.gcode?.trim()) return false;
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                const jobJson = JSON.stringify(job.toJSON());
                await this.jobStorageApi.apiJobStorageJobsPost({
                    storeJobRequest: {
                        jobId: job.id,
                        data: jobJson
                    }
                });
                return true;
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        return this.storeJobLocal(job);
    }

    private storeJobLocal(job: Job): boolean {
        try {
            this.jobsCache.set(job.id, job);
            this.saveJobsToLocalStorage();
            return true;
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to store job:', error);
            return false;
        }
    }

    async deleteJob(jobId: string): Promise<boolean> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                await this.jobStorageApi.apiJobStorageJobsIdDelete({ id: jobId });
                return true;
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        return this.deleteJobLocal(jobId);
    }

    private deleteJobLocal(jobId: string): boolean {
        if (this.jobsCache.delete(jobId)) {
            this.saveJobsToLocalStorage();
            return true;
        }
        return false;
    }

    async setJobCategory(
        jobId: string,
        category: string | undefined
    ): Promise<boolean> {
        const backendAvailable = await this.isBackendAvailable();

        if (backendAvailable) {
            try {
                await this.jobStorageApi.apiJobStorageJobsIdCategoryPut({
                    id: jobId,
                    updateJobCategoryRequest: {
                        category: category
                    }
                });
                return true;
            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Backend API failed, falling back to localStorage:', error);
            }
        }

        // Local fallback: update category on cached Job and persist
        const job = this.fetchJobLocal(jobId);
        if (job) {
            job.category = category;
            return this.storeJobLocal(job);
        }
        return false;
    }
}
