import {
  Add as AddIcon,
  Close as CloseIcon,
  Delete as DeleteIcon,
  Edit as EditIcon
} from '@mui/icons-material';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  Grid,
  IconButton,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { Material } from '../../../data/Common/Material';
import { GrainDirection, MaterialLibrary, MaterialType } from '../../../data/Common/MaterialLibrary';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { ColorPicker } from '../../Common/ColorPicker';
import { NumberInput } from '../../Common/NumberInput';

interface MaterialDialogProps {
  open: boolean;
  material: Material | null;
  onClose: () => void;
  onSave: (material: Material) => void;
}

const MaterialDialog: React.FC<MaterialDialogProps> = ({ open, material, onClose, onSave }) => {
  const [formData, setFormData] = useState<Material>(() => material || new Material());
  const colors = ConfigurationDataColors.Instance;

  React.useEffect(() => {
    setFormData(material || new Material());
  }, [material]);

  // Helper function to update material properties
  const updateMaterialProperty = (property: keyof Material, value: any) => {
    const newMaterial = new Material();
    // Copy all existing properties
    newMaterial.name = formData.name;
    newMaterial.type = formData.type;
    newMaterial.xLength = formData.xLength;
    newMaterial.yLength = formData.yLength;
    newMaterial.height = formData.height;
    newMaterial.grainDirection = formData.grainDirection;
    newMaterial.materialColor = formData.materialColor;

    // Update the specific property
    (newMaterial as any)[property] = value;
    setFormData(newMaterial);
  };

  const handleSave = () => {
    onSave(formData);
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        backgroundColor: colors.primaryColor,
        color: colors.lightTextColor,
        py: 2,
        px: 3
      }}>
        {material ? 'Edit Material' : 'Add New Material'}
        <IconButton
          onClick={onClose}
          sx={{
            color: colors.lightTextColor,
            '&:hover': {
              backgroundColor: colors.lightOverlay
            }
          }}
        >
          <CloseIcon />
        </IconButton>
      </DialogTitle>
      <DialogContent>
        <Grid container spacing={2} sx={{ mt: 3 }}>
          <Grid item xs={12} md={6}>
            <TextField
              fullWidth
              label="Material Name"
              value={formData.name}
              onChange={(e) => updateMaterialProperty('name', e.target.value)}
            />
          </Grid>

          <Grid item xs={12} md={6}>
            <FormControl fullWidth>
              <InputLabel>Material Type</InputLabel>
              <Select
                value={formData.type}
                onChange={(e) => updateMaterialProperty('type', e.target.value as MaterialType)}
              >
                <MenuItem value={MaterialType.Wood}>Wood</MenuItem>
                <MenuItem value={MaterialType.Metal}>Metal</MenuItem>
                <MenuItem value={MaterialType.Plastic}>Plastic</MenuItem>
                <MenuItem value={MaterialType.Composite}>Composite</MenuItem>
                <MenuItem value={MaterialType.Other}>Other</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} md={4}>
            <NumberInput
              fullWidth
              label="X Length"
              value={formData.xLength}
              onChange={(value) => updateMaterialProperty('xLength', value)}
              precision={1}
            />
          </Grid>

          <Grid item xs={12} md={4}>
            <NumberInput
              fullWidth
              label="Y Length"
              value={formData.yLength}
              onChange={(value) => updateMaterialProperty('yLength', value)}
              precision={1}
            />
          </Grid>

          <Grid item xs={12} md={4}>
            <NumberInput
              fullWidth
              label="Height"
              value={formData.height}
              onChange={(value) => updateMaterialProperty('height', value)}
              precision={1}
            />
          </Grid>

          <Grid item xs={12} md={6}>
            <FormControl fullWidth>
              <InputLabel>Grain Direction</InputLabel>
              <Select
                value={formData.grainDirection}
                onChange={(e) => updateMaterialProperty('grainDirection', e.target.value as GrainDirection)}
              >
                <MenuItem value={GrainDirection.X}>X Direction</MenuItem>
                <MenuItem value={GrainDirection.Y}>Y Direction</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} md={6}>
            <ColorPicker
              label="Material Color"
              value={formData.materialColor}
              onChange={(color) => updateMaterialProperty('materialColor', color)}
            />
          </Grid>
        </Grid>
      </DialogContent>
      <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
        <Button onClick={onClose}>Cancel</Button>
        <Button
          onClick={handleSave}
          variant="contained"
          sx={{
            backgroundColor: colors.primaryColor,
            '&:hover': {
              backgroundColor: colors.primaryColor,
              opacity: 0.9
            }
          }}
        >
          Save
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export const MaterialLibraryTab: React.FC = () => {
  const [library] = useState(() => MaterialLibrary.Instance);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingMaterial, setEditingMaterial] = useState<Material | null>(null);

  const handleAddMaterial = () => {
    setEditingMaterial(null);
    setDialogOpen(true);
  };

  const handleEditMaterial = (material: Material) => {
    setEditingMaterial(material);
    setDialogOpen(true);
  };

  const handleDeleteMaterial = (material: Material) => {
    const index = library.materials.indexOf(material);
    if (index > -1) {
      library.materials.splice(index, 1);
    }
  };

  const handleSaveMaterial = (material: Material) => {
    if (editingMaterial) {
      // Update existing material
      const index = library.materials.indexOf(editingMaterial);
      if (index > -1) {
        library.materials[index] = material;
      }
    } else {
      // Add new material
      library.materials.push(material);
    }
  };

  return (
    <ObserveState
      listenTo={library}
      control={() => (
        <Box sx={{ p: 3 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
            <Typography variant="h6">Material Library</Typography>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={handleAddMaterial}
            >
              Add Material
            </Button>
          </Box>

          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Name</TableCell>
                  <TableCell>Type</TableCell>
                  <TableCell>Dimensions (X × Y × H)</TableCell>
                  <TableCell>Grain Direction</TableCell>
                  <TableCell>Color</TableCell>
                  <TableCell align="right">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {library.materials.map((material, index) => (
                  <TableRow key={index}>
                    <TableCell>{material.name}</TableCell>
                    <TableCell>
                      <Chip
                        label={material.type}
                        size="small"
                        color={material.type === MaterialType.Wood ? 'success' :
                          material.type === MaterialType.Metal ? 'info' :
                            material.type === MaterialType.Plastic ? 'warning' : 'default'}
                      />
                    </TableCell>
                    <TableCell>
                      {material.xLength} × {material.yLength} × {material.height}
                    </TableCell>
                    <TableCell>{material.grainDirection}</TableCell>
                    <TableCell>
                      <Box
                        sx={{
                          width: 24,
                          height: 24,
                          backgroundColor: material.materialColor,
                          border: `1px solid ${ConfigurationDataColors.Instance.secondaryBorderColor}`,
                          borderRadius: 1
                        }}
                      />
                    </TableCell>
                    <TableCell align="right">
                      <IconButton
                        size="small"
                        onClick={() => handleEditMaterial(material)}
                        color="primary"
                      >
                        <EditIcon />
                      </IconButton>
                      <IconButton
                        size="small"
                        onClick={() => handleDeleteMaterial(material)}
                        color="error"
                      >
                        <DeleteIcon />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))}
                {library.materials.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={6} align="center" sx={{ py: 4, color: 'text.secondary' }}>
                      No materials found. Click "Add Material" to create your first material.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>

          <MaterialDialog
            open={dialogOpen}
            material={editingMaterial}
            onClose={() => setDialogOpen(false)}
            onSave={handleSaveMaterial}
          />
        </Box>
      )}
    />
  );
};
