import { IStorable } from '../common/IStorable';
import { StateManager } from '../utils/statemanager/StateManager';
import { DataUtilities } from '../utils/storage/DataUtilities';

/**
 * 3D Offset with state management support
 * Used for tool offsets, fixture offsets, and other coordinate adjustments
 */
export class CNCOffset implements IStorable {
    private _x: number;
    private _y: number;
    private _z: number;

    constructor(x: number = 0, y: number = 0, z: number = 0) {
        this._x = x;
        this._y = y;
        this._z = z;
    }

    public get x(): number {
        return this._x;
    }

    public set x(value: number) {
        if (this._x !== value) {
            this._x = value;
            StateManager.propertyChanged(this, 'x');
        }
    }

    public get y(): number {
        return this._y;
    }

    public set y(value: number) {
        if (this._y !== value) {
            this._y = value;
            StateManager.propertyChanged(this, 'y');
        }
    }

    public get z(): number {
        return this._z;
    }

    public set z(value: number) {
        if (this._z !== value) {
            this._z = value;
            StateManager.propertyChanged(this, 'z');
        }
    }

    /**
     * Set all offset values at once
     * @param x X offset
     * @param y Y offset
     * @param z Z offset
     */
    public setValues(x: number, y: number, z: number): void {
        const changed = this._x !== x || this._y !== y || this._z !== z;
        this._x = x;
        this._y = y;
        this._z = z;
        if (changed) {
            StateManager.propertyChanged(this, 'x');
            StateManager.propertyChanged(this, 'y');
            StateManager.propertyChanged(this, 'z');
        }
    }

    /**
     * Create a copy of this offset
     */
    public clone(): CNCOffset {
        return new CNCOffset(this._x, this._y, this._z);
    }

    /**
     * Check if this offset is zero (all components are zero)
     */
    public isZero(): boolean {
        return this._x === 0 && this._y === 0 && this._z === 0;
    }

    /**
     * IStorable implementation - serialize to JSON
     */
    public toJSON(): object {
        return DataUtilities.getStorageData(this);
    }

    /**
     * IStorable implementation - deserialize from JSON
     */
    public fromJSON(data: any): void {
        if (!data) return;
        DataUtilities.loadStorageData(this, data);
    }
}
