import { Warning as WarningIcon } from '@mui/icons-material';
import { Box, Tooltip, Typography } from '@mui/material';
import { SetupChecklistItem } from '../../data/Checklist/SetupChecklistItem';
import { SetupChecklistLibrary } from '../../data/Checklist/SetupChecklistLibrary';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { SystemIcons } from '../../SystemIcons';
import { ObserveState } from '../../utils/statemanager/ObserveState';

export interface ChecklistValidationIndicatorProps {
    /**
     * Array of checklist item names to validate
     * If empty or undefined, will check all items in library
     */
    checklistItemNames?: string[];

    /**
     * Optional: Show count of incomplete items instead of just icon
     */
    showCount?: boolean;

    /**
     * Optional: Custom styling
     */
    sx?: any;
}

/**
 * ChecklistValidationIndicator Component
 * 
 * Displays validation status for setup checklist items with reactive updates.
 * Shows a warning icon when checklist items are incomplete, with a tooltip
 * listing all incomplete items. Optionally displays the count of incomplete items.
 * 
 * Features:
 * - Reactive updates via ObserveState listening to SetupChecklistLibrary
 * - Warning icon for visibility
 * - Tooltip showing all incomplete items
 * - Optional count display for aggregate views
 * - Configurable styling
 * - Can filter by specific checklist item names
 * 
 * Usage:
 * ```tsx
 * // Check all items in library
 * <ChecklistValidationIndicator />
 * 
 * // Check specific items with count
 * <ChecklistValidationIndicator 
 *   checklistItemNames={['Machine Name and Board Type', 'ATC Configuration']}
 *   showCount={true}
 * />
 * 
 * // In accordion header
 * <AccordionSummary expandIcon={<ExpandMore />}>
 *   <Typography>General</Typography>
 *   <ChecklistValidationIndicator checklistItemNames={['Machine Name and Board Type']} showCount={true} />
 * </AccordionSummary>
 * ```
 */
export function ChecklistValidationIndicator(props: ChecklistValidationIndicatorProps) {
    const { checklistItemNames, showCount = false, sx = {} } = props;
    const library = SetupChecklistLibrary.Instance;
    const colors = ConfigurationDataColors.Instance;

    return (
        <ObserveState
            key={`checklist-validation-${checklistItemNames?.join('-') || 'all'}`}
            listenTo={library}
            properties={['items']}
            control={() => {
                // Get items to check
                let itemsToCheck: SetupChecklistItem[];

                if (checklistItemNames && checklistItemNames.length > 0) {
                    // Filter by specified names and shouldInclude()
                    itemsToCheck = checklistItemNames
                        .map(name => library.getItemByName(name))
                        .filter((item): item is SetupChecklistItem => item !== undefined && item.shouldInclude());
                } else {
                    // Check all items (already filtered by shouldInclude in library.items getter)
                    itemsToCheck = library.items;
                }

                // Get incomplete items
                const incompleteItems = itemsToCheck.filter(item => !item.isCompleted());

                // If all items are complete, don't show indicator
                if (incompleteItems.length === 0) {
                    return null;
                }

                // Build tooltip content
                const tooltipContent = (
                    <Box sx={{
                        maxWidth: 400,
                        minWidth: 300,
                        backgroundColor: colors.lightTextColor,
                        borderRadius: 1,
                        boxShadow: `0 4px 20px ${colors.darkTextColor}26`
                    }}>
                        <Box sx={{
                            p: 2,
                            borderBottom: `1px solid ${colors.borderColor}`,
                            backgroundColor: colors.lightBackgroundColor
                        }}>
                            <Typography
                                variant="subtitle2"
                                sx={{
                                    fontWeight: 600,
                                    fontSize: '0.9rem',
                                    color: colors.darkTextColor
                                }}
                            >
                                Incomplete Setup Items ({incompleteItems.length})
                            </Typography>
                        </Box>
                        <Box sx={{
                            p: 2,
                            maxHeight: 300,
                            overflowY: 'auto',
                            '&::-webkit-scrollbar': {
                                width: '8px'
                            },
                            '&::-webkit-scrollbar-track': {
                                backgroundColor: colors.lightBackgroundColor,
                                borderRadius: '4px'
                            },
                            '&::-webkit-scrollbar-thumb': {
                                backgroundColor: colors.secondaryBorderColor,
                                borderRadius: '4px',
                                '&:hover': {
                                    backgroundColor: colors.mutedTextColor
                                }
                            }
                        }}>
                            {incompleteItems.map((item, index) => (
                                <Box
                                    key={index}
                                    sx={{
                                        mb: 1,
                                        p: 1.5,
                                        border: `1px solid ${colors.errorColor}4D`,
                                        borderRadius: 1,
                                        backgroundColor: `${colors.errorColor}1A`
                                    }}
                                >
                                    <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1 }}>
                                        <Box sx={{ color: colors.errorColor, mt: 0.25, flexShrink: 0 }}>
                                            <WarningIcon fontSize="small" />
                                        </Box>
                                        <Box sx={{ flex: 1, minWidth: 0 }}>
                                            <Typography
                                                variant="body2"
                                                sx={{
                                                    color: colors.darkTextColor,
                                                    fontWeight: 500,
                                                    mb: 0.5,
                                                    wordBreak: 'break-word'
                                                }}
                                            >
                                                {item.name}
                                            </Typography>
                                            {item.description && (
                                                <Typography
                                                    variant="caption"
                                                    sx={{
                                                        display: 'block',
                                                        color: colors.mutedTextColor,
                                                        fontSize: '0.7rem'
                                                    }}
                                                >
                                                    {item.description}
                                                </Typography>
                                            )}
                                        </Box>
                                    </Box>
                                </Box>
                            ))}
                        </Box>
                    </Box>
                );

                return (
                    <Tooltip
                        title={tooltipContent}
                        arrow
                        placement="top"
                        disableInteractive={false}
                        componentsProps={{
                            tooltip: {
                                sx: {
                                    backgroundColor: `${colors.lightTextColor}00`,
                                    padding: 0,
                                    maxWidth: 'none',
                                    pointerEvents: 'auto'
                                }
                            },
                            arrow: {
                                sx: {
                                    color: colors.lightTextColor
                                }
                            }
                        }}
                    >
                        <Box
                            sx={{
                                color: colors.errorColor,
                                display: 'flex',
                                alignItems: 'center',
                                gap: 0.5,
                                cursor: 'help',
                                ...sx
                            }}
                        >
                            {SystemIcons.warning}
                            {showCount && (
                                <Typography
                                    variant="caption"
                                    sx={{
                                        fontWeight: 'bold',
                                        color: colors.errorColor
                                    }}
                                >
                                    {incompleteItems.length}
                                </Typography>
                            )}
                        </Box>
                    </Tooltip>
                );
            }}
        />
    );
}

/**
 * Helper function to get the count of incomplete items for a given set of checklist names
 * This is useful for determining if an indicator should be shown
 */
export function getIncompleteChecklistCount(checklistItemNames?: string[]): number {
    const library = SetupChecklistLibrary.Instance;

    let itemsToCheck: SetupChecklistItem[];

    if (checklistItemNames && checklistItemNames.length > 0) {
        itemsToCheck = checklistItemNames
            .map(name => library.getItemByName(name))
            .filter((item): item is SetupChecklistItem => item !== undefined && item.shouldInclude());
    } else {
        itemsToCheck = library.items;
    }

    return itemsToCheck.filter(item => !item.isCompleted()).length;
}
