import { PLCProgram } from '../../centroid/plc/data/PLCProgram';
import { PLCProgramType } from '../../centroid/plc/data/PLCUtilities';
import { StateManager } from '../../utils/statemanager/StateManager';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Outputs Checklist Item
 * Manual confirmation + Auto-validation for PLC outputs configuration
 * Validates:
 * 1. At least one output is configured
 */
export class OutputsChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Outputs Configuration',
            'Verify PLC outputs are configured with at least one output defined'
        );

        // Listen for changes to System PLC outputs
        const systemPLC = PLCProgram.Instance(PLCProgramType.System);
        StateManager.addObserver(systemPLC, () => {
            StateManager.propertyChanged(this, 'manuallyConfirmed');
        }, ['outputs']);
    }

    /**
     * This requires manual confirmation
     */
    public needsManualConfirmation(): boolean {
        return true;
    }

    /**
     * Auto-validation check: At least one output exists
     */
    public completionCheck(): boolean {
        const systemPLC = PLCProgram.Instance(PLCProgramType.System);

        // Check if there's at least one output
        return systemPLC.outputs.length > 0;
    }

    public clone(): OutputsChecklistItem {
        const cloned = new OutputsChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
