import { IStorable } from '../common/IStorable';
import { DataUtilities } from '../utils/storage/DataUtilities';
import { CNCOffset } from './CNCOffset';
import { CoordinateType } from './Common/CoordinateType';

/**
 * 3D Point with coordinate type information
 * Direct conversion from C# Point3DWithType class (now renamed to CNCPoint)
 */
export class CNCPoint implements IStorable {
  public x: number;
  public y: number;
  public z: number;
  public coordinateType: CoordinateType;

  constructor(x: number, y: number, z: number, coordinateType: CoordinateType) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.coordinateType = coordinateType;
  }

  /**
   * IStorable implementation - serialize to JSON using generic DataUtilities approach
   */
  public toJSON(): object {
    // Simple object with no sub-objects, StateManager observers automatically excluded
    return DataUtilities.getStorageData(this);
  }

  /**
   * IStorable implementation - deserialize from JSON using generic DataUtilities approach
   */
  public fromJSON(data: any): void {
    if (!data) return;

    // Load data directly since CNCPoint has no setters with StateManager notifications
    DataUtilities.loadStorageData(this, data);
  }

  /**
   * Add an offset to a point and return a new point
   * The coordinate type is preserved from the original point
   * @param point The point to offset
   * @param offset The offset to add
   * @returns A new CNCPoint with the offset applied
   */
  public static addOffset(point: CNCPoint, offset: CNCOffset): CNCPoint {
    return new CNCPoint(
      point.x + offset.x,
      point.y + offset.y,
      point.z + offset.z,
      point.coordinateType
    );
  }

  /**
   * Subtract an offset from a point and return a new point
   * The coordinate type is preserved from the original point
   * @param point The point to offset
   * @param offset The offset to subtract
   * @returns A new CNCPoint with the offset subtracted
   */
  public static subtractOffset(point: CNCPoint, offset: CNCOffset): CNCPoint {
    return new CNCPoint(
      point.x - offset.x,
      point.y - offset.y,
      point.z - offset.z,
      point.coordinateType
    );
  }
}
