import { Box } from '@mui/material';
import React from 'react';
import { MachineData } from '../../../../data/Machine/MachineData';
import { SpindleConfigPanel } from './SpindleConfigPanel';

/**
 * Spindle 2 Setup Tab - Secondary spindle configuration
 */
export function Spindle2SetupTab(): React.ReactElement {
    const machineData = MachineData.Instance;

    return (
        <Box sx={{ p: 2 }}>
            <SpindleConfigPanel
                spindleConfig={machineData.secondSpindleConfig}
                spindleName="Secondary Spindle Configuration"
                spindleNumber={2}
            />
        </Box>
    );
}
