import { Button, FormControlLabel, Grid, Switch, Typography } from '@mui/material';
import { useState } from 'react';
import { PLCProgram } from '../../../../centroid/plc/data/PLCProgram';
import { PLCProgramType } from '../../../../centroid/plc/data/PLCUtilities';
import { MachineData } from '../../../../data/Machine/MachineData';
import { PLCInputName } from '../../../../data/PLCIONames';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';
import { FixedTouchPlateTouchOffDialog } from '../FixedTouchPlateTouchOffDialog';

export function FixedTouchPlateSection() {
    const machine = MachineData.Instance;
    const [touchOffDialogOpen, setTouchOffDialogOpen] = useState<boolean>(false);

    // Check if fixed touch plate PLC input is configured
    const isFixedTouchPlateInputConfigured = (): boolean => {
        const systemPLC = PLCProgram.Instance(PLCProgramType.System);
        const plcInput = systemPLC.inputs.find(input => input.centroidName === PLCInputName.FixedToolTouchPlate);
        return plcInput !== undefined && plcInput.number !== null;
    };

    return (
        <>
            <Grid container spacing={3}>
                {/* Has Fixed Touch Plate Switch */}
                <Grid item xs={12}>
                    <ObserveState
                        key="fixed-touch-plate-enabled"
                        listenTo={machine}
                        properties={['hasFixedTouchPlate']}
                        control={() => (
                            <>
                                <FormControlLabel
                                    control={
                                        <Switch
                                            checked={machine.hasFixedTouchPlate}
                                            onChange={(e) => {
                                                if (e.target.checked && !isFixedTouchPlateInputConfigured()) {
                                                    UserMessageQueue.Instance.addMessage('❌ Cannot enable fixed touch plate - PLC input "FixedToolTouchPlate" is not configured');
                                                    return;
                                                }
                                                machine.hasFixedTouchPlate = e.target.checked;
                                            }}
                                        />
                                    }
                                    label="Has Fixed Touch Plate"
                                />
                                {!isFixedTouchPlateInputConfigured() && (
                                    <Typography variant="caption" color="error" sx={{ display: 'block', mt: 0.5, ml: 4 }}>
                                        ⚠️ PLC input "FixedToolTouchPlate" must be configured before enabling
                                    </Typography>
                                )}
                            </>
                        )}
                    />
                </Grid>

                {/* Fixed Touch Plate Configuration - Only show if enabled */}
                <ObserveState
                    key="fixed-touch-plate-config"
                    listenTo={machine}
                    properties={['hasFixedTouchPlate']}
                    control={() => {
                        if (!machine.hasFixedTouchPlate) {
                            return null;
                        }
                        return (
                            <>
                                {/* Checklist Indicator */}
                                <Grid item xs={12}>
                                    <SetupChecklistIndicator name="Fixed Touch Plate Position" />
                                </Grid>

                                {/* Position Coordinates */}
                                <Grid item xs={12}>
                                    <Typography variant="subtitle1" sx={{ mt: 1, mb: 1 }}>Touch Plate Position</Typography>
                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                        X, Y, Z coordinates of the fixed touch plate surface (in machine zero coordinates)
                                    </Typography>
                                </Grid>

                                <Grid item xs={12} md={4}>
                                    <ObserveState
                                        key="fixed-touch-plate-x"
                                        listenTo={machine}
                                        properties={['fixedTouchPlateX']}
                                        control={() => (
                                            <NumberInput
                                                fullWidth
                                                label="X Position"
                                                value={machine.fixedTouchPlateX}
                                                onChange={(value) => machine.fixedTouchPlateX = value}
                                                margin="normal"
                                                precision={3}
                                            />
                                        )}
                                    />
                                </Grid>

                                <Grid item xs={12} md={4}>
                                    <ObserveState
                                        key="fixed-touch-plate-y"
                                        listenTo={machine}
                                        properties={['fixedTouchPlateY']}
                                        control={() => (
                                            <NumberInput
                                                fullWidth
                                                label="Y Position"
                                                value={machine.fixedTouchPlateY}
                                                onChange={(value) => machine.fixedTouchPlateY = value}
                                                margin="normal"
                                                precision={3}
                                            />
                                        )}
                                    />
                                </Grid>

                                <Grid item xs={12} md={4}>
                                    <ObserveState
                                        key="fixed-touch-plate-z"
                                        listenTo={machine}
                                        properties={['fixedTouchPlateZ']}
                                        control={() => (
                                            <NumberInput
                                                fullWidth
                                                label="Z Position"
                                                value={machine.fixedTouchPlateZ}
                                                onChange={(value) => machine.fixedTouchPlateZ = value}
                                                margin="normal"
                                                precision={3}
                                            />
                                        )}
                                    />
                                </Grid>

                                {/* Touch Off Button */}
                                <Grid item xs={12}>
                                    <Button
                                        variant="contained"
                                        onClick={() => setTouchOffDialogOpen(true)}
                                        sx={{ mt: 1 }}
                                    >
                                        Touch Off Spindle to Plate
                                    </Button>
                                </Grid>

                                {/* Probing Speeds */}
                                <Grid item xs={12}>
                                    <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Probing Speeds</Typography>
                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                        Fast and slow probing speeds for accurate touch-off (in/min)
                                    </Typography>
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="fixed-touch-plate-fast-speed"
                                        listenTo={machine}
                                        properties={['fixedTouchPlateFastSpeed']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="Fast Probing Speed"
                                                    value={machine.fixedTouchPlateFastSpeed}
                                                    onChange={(value) => machine.fixedTouchPlateFastSpeed = value}
                                                    margin="normal"
                                                    precision={0}
                                                    min={1}
                                                    max={1000}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    Initial approach speed (default: 100 in/min)
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="fixed-touch-plate-slow-speed"
                                        listenTo={machine}
                                        properties={['fixedTouchPlateSlowSpeed']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="Slow Probing Speed"
                                                    value={machine.fixedTouchPlateSlowSpeed}
                                                    onChange={(value) => machine.fixedTouchPlateSlowSpeed = value}
                                                    margin="normal"
                                                    precision={0}
                                                    min={1}
                                                    max={1000}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    Final precise measurement speed (default: 10 in/min)
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>
                            </>
                        );
                    }}
                />
            </Grid>

            <FixedTouchPlateTouchOffDialog
                open={touchOffDialogOpen}
                onClose={() => setTouchOffDialogOpen(false)}
            />
        </>
    );
}
