import {
  Delete as DeleteIcon,
  Description as FileIcon,
  Label as LabelIcon,
  MoreHoriz as MoreHorizIcon,
  DriveFileRenameOutline as RenameIcon,
  AccessTime as TimeIcon,
  CloudUpload as UploadIcon
} from '@mui/icons-material';
import CloseIcon from '@mui/icons-material/Close';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  ListItemIcon,
  ListItemText,
  Menu,
  MenuItem,
  Paper,
  TextField,
  Typography
} from '@mui/material';
import React, { useCallback, useEffect, useState } from 'react';
import { Material } from '../../../data/Common/Material';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { Job } from '../../../data/Job';
import { JobCache } from '../../../data/JobCache';
import { MillingWorkflowState } from '../../../data/MillingWorkflowState';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { JobMetadata } from '../../../machine/ICNCJobStorage';
import { Machine } from '../../../machine/Machine';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { JobCategoryBrowseDialog } from './JobCategoryBrowseDialog';
import { JobCategoryDialog } from './JobCategoryDialog';

export interface GCodeStageProps {
  onMovingToNext?: () => void;
  getNextStepName?: () => string;
  onPreviewReady?: () => void;
  onPrepareForNext?: () => boolean; // Returns true if ready to proceed
}

export function GCodeStage({ onMovingToNext, getNextStepName, onPreviewReady, onPrepareForNext }: GCodeStageProps = {}) {
  const [hoveredJobIndex, setHoveredJobIndex] = useState<number | null>(null);
  const [, setHoveredFileIndex] = useState<number | null>(null);
  const [menuAnchorEl, setMenuAnchorEl] = useState<HTMLElement | null>(null);
  const [menuJob, setMenuJob] = useState<{ job: JobMetadata; index: number } | null>(null);
  const [categoryDialogJob, setCategoryDialogJob] = useState<JobMetadata | null>(null);
  const [categoryDialogOpen, setCategoryDialogOpen] = useState(false);
  const [categoryBrowseOpen, setCategoryBrowseOpen] = useState(false);
  const [categoryBrowseName, setCategoryBrowseName] = useState<string>('');
  const [categoryBrowseJobs, setCategoryBrowseJobs] = useState<JobMetadata[]>([]);
  const [renameDialogOpen, setRenameDialogOpen] = useState(false);
  const [renameValue, setRenameValue] = useState('');
  const [renaming, setRenaming] = useState(false);

  // Use centralized workflow state
  const workflowState = MillingWorkflowState.Instance;

  // Instance references
  const machine = Machine.getInstance();
  const jobStorage = machine.jobStorage;

  // Kick off initial loads on mount (ObserveState reacts via StateManager when done)
  useEffect(() => {
    JobCache.Instance.getRecentJobs(jobStorage);
    workflowState.refreshGCodeFiles(jobStorage);
  }, [jobStorage]);

  // Existing categories from cache for autocomplete suggestions in the category dialog
  const existingCategories = [...new Set(
    (JobCache.Instance.recentJobs ?? []).map((m: JobMetadata) => m.category).filter((c): c is string => Boolean(c))
  )];

  // Utility function to format file age
  const formatFileAge = (lastModified?: Date): string => {
    if (!lastModified) return 'Unknown';

    const now = new Date();
    const diffMs = now.getTime() - lastModified.getTime();
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    if (diffMinutes < 1) return 'Just now';
    if (diffMinutes < 60) return `${diffMinutes} min ago`;
    if (diffHours < 24) return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
    if (diffDays === 1) return 'Yesterday';
    if (diffDays < 7) return `${diffDays} days ago`;
    return lastModified.toLocaleDateString();
  };

  // Utility function to format file size
  const formatFileSize = (size?: number): string => {
    if (!size) return 'Unknown size';

    const units = ['B', 'KB', 'MB', 'GB'];
    let unitIndex = 0;
    let fileSize = size;

    while (fileSize >= 1024 && unitIndex < units.length - 1) {
      fileSize /= 1024;
      unitIndex++;
    }

    return `${fileSize.toFixed(unitIndex === 0 ? 0 : 1)} ${units[unitIndex]}`;
  };

  // Create a temporary job for preview
  const createPreviewJob = useCallback((gcode: string, filename: string) => {
    let job: Job;

    // Always create a new empty job for G-code preview
    job = new Job();

    // Determine which job to use as base for material/clamps: current job if it has material, otherwise last job
    const baseJob = (ConfigurationState.Instance.currentJob?.material) ? ConfigurationState.Instance.currentJob : ConfigurationState.Instance.lastJob;

    // Copy material from base job if available
    if (baseJob?.material && baseJob.material.xLength > 0) {
      job.material = baseJob.material.clone();
    } else {
      // Create new material with zero size when no base material
      job.material = new Material();
      job.material.xLength = 0;
      job.material.yLength = 0;
      job.material.height = 0;
    }

    // Copy clamps from base job if available
    if (baseJob?.clamps && baseJob.clamps.length > 0) {
      job.clamps = baseJob.clamps.map((clamp: any) => clamp.clone());
    } else {
      // Empty clamps array when no base clamps
      job.clamps = [];
    }

    // Always set the new G-code and name
    job.gcode = gcode;
    job.name = filename;

    return job;
  }, []);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      loadFileContent(file, file.name, 'Uploaded File');
    }
  };

  const loadFileContent = (file: File, fileName: string, jobName: string) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const content = e.target?.result as string;
      previewGCode(content, fileName, jobName);
    };
    reader.readAsText(file);
  };

  const previewJobFromStorage = (job: Job) => {
    // This job IS the current job - set directly
    ConfigurationState.Instance.currentJob = job;
    // Keep proposedJob in sync so PreviewGCodeStage still works
    ConfigurationState.Instance.proposedJob = job;

    if (onPreviewReady) {
      setTimeout(() => onPreviewReady(), 0);
    }
  };

  const previewGCode = (content: string, fileName: string, jobName: string) => {
    // Create job and set as current job directly
    const job = createPreviewJob(content, fileName);
    job.name = jobName;
    ConfigurationState.Instance.currentJob = job;
    // Keep proposedJob in sync so PreviewGCodeStage still works
    ConfigurationState.Instance.proposedJob = job;

    // Call the callback to trigger navigation to preview stage
    if (onPreviewReady) {
      // Use setTimeout to ensure state has propagated
      setTimeout(() => onPreviewReady(), 0);
    }
  };

  const handleDeleteJob = async (job: JobMetadata) => {
    try {
      const success = await jobStorage.deleteJob(job.id);
      if (success) {
        JobCache.Instance.invalidateJobs(); // fires StateManager + kicks re-fetch
        JobCache.Instance.getRecentJobs(jobStorage);
      } else {
        UserMessageQueue.Instance.addMessage(`❌ Failed to delete job: ${job.name}`);
      }
    } catch (error) {
      UserMessageQueue.Instance.addMessage(`❌ Error deleting job: ${job.name}`);
    }
  };

  const handleRenameJob = async (meta: JobMetadata, newName: string) => {
    try {
      const job = await JobCache.Instance.fetchJob(meta.id, jobStorage);
      if (!job) { UserMessageQueue.Instance.addMessage(`❌ Could not load job to rename`); return; }
      job.name = newName;
      const success = await jobStorage.storeJob(job);
      if (success) {
        meta.name = newName; // update metadata in-place
        JobCache.Instance.invalidateJobs();
        JobCache.Instance.getRecentJobs(jobStorage);
        UserMessageQueue.Instance.addMessage(`✓ Renamed to "${newName}"`);
      } else {
        UserMessageQueue.Instance.addMessage(`❌ Failed to rename job`);
      }
    } catch (error) {
      UserMessageQueue.Instance.addMessage(`❌ Error renaming job`);
    }
  };

  const handleConfirmRename = async () => {
    if (!menuJob) return;
    const trimmed = renameValue.trim();
    if (!trimmed || trimmed === menuJob.job.name) { setRenameDialogOpen(false); setMenuJob(null); return; }
    setRenaming(true);
    await handleRenameJob(menuJob.job, trimmed);
    setRenaming(false);
    setRenameDialogOpen(false);
    setMenuJob(null);
  };

  const handleOpenMenu = (event: React.MouseEvent<HTMLElement>, job: JobMetadata, index: number) => {
    event.stopPropagation();
    setMenuAnchorEl(event.currentTarget);
    setMenuJob({ job, index });
  };

  const handleCloseMenu = () => {
    setMenuAnchorEl(null);
    setMenuJob(null);
  };

  const handleOpenCategoryDialog = (event: React.MouseEvent, job: JobMetadata) => {
    event.stopPropagation();
    setCategoryDialogJob(job);
    setCategoryDialogOpen(true);
  };

  const handleSaveCategory = async (category: string | undefined) => {
    if (!categoryDialogJob) return;
    try {
      const success = await jobStorage.setJobCategory(categoryDialogJob.id, category);
      if (success) {
        categoryDialogJob.category = category; // update metadata in-place
        JobCache.Instance.invalidateJobs(); // fires StateManager + kicks re-fetch
        JobCache.Instance.getRecentJobs(jobStorage);
        UserMessageQueue.Instance.addMessage(category ? `✓ Category set to "${category}"` : `✓ Category cleared`);
      } else {
        UserMessageQueue.Instance.addMessage(`❌ Failed to update category`);
      }
    } catch (error) {
      UserMessageQueue.Instance.addMessage(`❌ Error updating category`);
    }
  };

  return (
    <>
      <ObserveState
        key="gcode-stage-tab-selection"
        listenTo={workflowState}
        properties={['selectedTab']}
        control={() => (
          <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            {/* Selection View - Show file/recent/wizards/editor tabs */}
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, flex: 1 }}>
              {/* Top Navigation Buttons */}
              <Box sx={{ display: 'flex', gap: 2 }}>
                <Button
                  variant={workflowState.selectedTab === 'files' ? 'contained' : 'outlined'}
                  onClick={() => {
                    workflowState.selectedTab = 'files';
                    workflowState.refreshGCodeFiles(jobStorage);
                  }}
                  sx={{
                    flex: 1,
                    py: 2,
                    fontSize: '1.1rem',
                    fontWeight: 'bold'
                  }}
                >
                  Files
                </Button>
                <Button
                  variant={workflowState.selectedTab === 'recent' ? 'contained' : 'outlined'}
                  onClick={() => workflowState.selectedTab = 'recent'}
                  sx={{
                    flex: 1,
                    py: 2,
                    fontSize: '1.1rem',
                    fontWeight: 'bold'
                  }}
                >
                  Recent
                </Button>
                <Button
                  variant={workflowState.selectedTab === 'wizards' ? 'contained' : 'outlined'}
                  onClick={() => workflowState.selectedTab = 'wizards'}
                  sx={{
                    flex: 1,
                    py: 2,
                    fontSize: '1.1rem',
                    fontWeight: 'bold'
                  }}
                >
                  Wizards
                </Button>
                <Button
                  variant={workflowState.selectedTab === 'editor' ? 'contained' : 'outlined'}
                  onClick={() => {
                    if (!ConfigurationState.Instance.currentJob) {
                      const newJob = new Job();
                      ConfigurationState.Instance.currentJob = newJob;
                    }
                    workflowState.selectedTab = 'editor';
                  }}
                  sx={{
                    flex: 1,
                    py: 2,
                    fontSize: '1.1rem',
                    fontWeight: 'bold'
                  }}
                >
                  Editor
                </Button>
              </Box>

              {/* Content Area - Three column grid layout */}
              <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: 2, flex: 1, overflow: 'auto', alignContent: 'start' }}>
                {workflowState.selectedTab === 'files' && (
                  <>
                    <Paper sx={{ p: 2, gridColumn: '1 / -1', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <Typography variant="h5">
                        G-Code Files
                      </Typography>
                      <Button
                        variant="contained"
                        component="label"
                        startIcon={<UploadIcon />}
                      >
                        Upload File
                        <input
                          type="file"
                          accept=".gcode,.nc,.cnc,.tap"
                          onChange={handleFileUpload}
                          hidden
                        />
                      </Button>
                    </Paper>

                    <ObserveState
                      key="gcode-files-list"
                      listenTo={workflowState}
                      properties={['gCodeFiles']}
                      control={() => {
                        const availableFiles = workflowState.gCodeFiles;
                        if (availableFiles === null) return null;

                        const lastRunDate = ConfigurationState.Instance.lastJob?.runStatistics && ConfigurationState.Instance.lastJob.runStatistics.length > 0
                          ? ConfigurationState.Instance.lastJob.runStatistics[ConfigurationState.Instance.lastJob.runStatistics.length - 1].endTime
                          : undefined;

                        if (availableFiles.length === 0) {
                          return (
                            <Paper sx={{ p: 4, textAlign: 'center', gridColumn: '1 / -1' }}>
                              <Typography variant="body2" color="text.secondary">
                                No G-Code files found
                              </Typography>
                            </Paper>
                          );
                        }

                        return <>{availableFiles.map((fileMeta, fileIndex) => {
                          const isNew = lastRunDate && fileMeta.lastModified && fileMeta.lastModified > lastRunDate;

                          return (
                            <Paper
                              key={fileIndex}
                              sx={{
                                p: 3,
                                cursor: 'pointer',
                                transition: 'all 0.2s',
                                minWidth: 0,
                                overflow: 'hidden',
                                border: isNew ? '2px solid' : '1px solid',
                                borderColor: isNew ? 'success.main' : 'divider',
                                backgroundColor: isNew ? 'success.light' : 'background.paper',
                                '&:hover': {
                                  borderColor: 'primary.main',
                                  boxShadow: 3,
                                  transform: 'translateY(-2px)'
                                }
                              }}
                              onClick={async () => {
                                try {
                                  const fileData = await jobStorage.fetchGCodeFile(fileMeta.directory, fileMeta.name);
                                  if (fileData) {
                                    previewGCode(fileData.content, fileData.name, fileData.name);
                                  } else {
                                    UserMessageQueue.Instance.addMessage(`❌ Could not load file: ${fileMeta.name}`);
                                  }
                                } catch (error) {
                                  UserMessageQueue.Instance.addMessage(`❌ Error loading file: ${fileMeta.name}`);
                                }
                              }}
                              onMouseEnter={() => setHoveredFileIndex(fileIndex)}
                              onMouseLeave={() => setHoveredFileIndex(null)}
                            >
                              <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1, mb: 2 }}>
                                <FileIcon color="action" sx={{ fontSize: 32 }} />
                                <Box sx={{ flex: 1, minWidth: 0 }}>
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                                    <Typography variant="h6" noWrap sx={{ flex: 1, minWidth: 0 }}>
                                      {fileMeta.name}
                                    </Typography>
                                    {isNew && (
                                      <Chip
                                        label="NEW"
                                        color="success"
                                        size="small"
                                        sx={{ fontWeight: 'bold' }}
                                      />
                                    )}
                                  </Box>
                                  <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
                                    📁 {fileMeta.directory}
                                  </Typography>
                                </Box>
                              </Box>
                              <Typography variant="body2" color="text.secondary">
                                {formatFileAge(fileMeta.lastModified)} • {formatFileSize(fileMeta.size)}
                              </Typography>
                            </Paper>
                          );
                        })}</>;
                      }}
                    />
                  </>
                )}

                {workflowState.selectedTab === 'recent' && (
                  <>
                    {/* Current and Last Job Cards */}
                    <ObserveState
                      key="recent-jobs-special"
                      listenTo={ConfigurationState.Instance}
                      properties={['currentJob', 'lastJob']}
                      control={() => (
                        <>
                          {/* Current Job Card */}
                          {ConfigurationState.Instance.currentJob && (
                            <Box
                              sx={{
                                position: 'relative',
                                pt: 1.5,
                                minWidth: 0,
                                display: 'flex',
                                flexDirection: 'column',
                                cursor: 'pointer',
                                transition: 'all 0.2s',
                                '&:hover': {
                                  transform: 'translateY(-2px)',
                                  '& .current-inner': { backgroundColor: 'rgba(25, 118, 210, 0.12)', boxShadow: 3 }
                                }
                              }}
                              onClick={() => previewJobFromStorage(ConfigurationState.Instance.currentJob!)}
                            >
                              <Box
                                className="current-inner"
                                sx={{
                                  p: 3,
                                  pt: 2.5,
                                  flex: 1,
                                  border: '1px solid',
                                  borderColor: 'primary.main',
                                  borderRadius: 1,
                                  backgroundColor: 'rgba(25, 118, 210, 0.06)',
                                  transition: 'background-color 0.2s, box-shadow 0.2s',
                                  minWidth: 0,
                                  overflow: 'hidden',
                                }}
                              >
                                <Typography
                                  variant="caption"
                                  sx={{
                                    position: 'absolute',
                                    top: 4,
                                    left: 12,
                                    px: 0.5,
                                    backgroundColor: 'background.paper',
                                    color: 'primary.main',
                                    fontWeight: 600,
                                    lineHeight: 1,
                                    letterSpacing: '0.05em',
                                    textTransform: 'uppercase',
                                  }}
                                >
                                  Current
                                </Typography>
                                <Typography variant="h6" noWrap sx={{ minWidth: 0, mb: 1 }}>
                                  {ConfigurationState.Instance.currentJob.name}
                                </Typography>
                                <Typography variant="body2" color="text.secondary" gutterBottom>
                                  {ConfigurationState.Instance.currentJob.material.xLength
                                    ? `${ConfigurationState.Instance.currentJob.material.type}: ${ConfigurationState.Instance.currentJob.material.xLength}" × ${ConfigurationState.Instance.currentJob.material.yLength}" × ${ConfigurationState.Instance.currentJob.material.height}"`
                                    : 'No material'
                                  }
                                </Typography>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mt: 1.5 }}>
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                    <TimeIcon fontSize="small" color="action" />
                                    <Typography variant="caption">
                                      {ConfigurationState.Instance.currentJob.averageRuntimeFormatted} avg
                                    </Typography>
                                  </Box>
                                  <Typography variant="caption">
                                    • {ConfigurationState.Instance.currentJob.executionCount} runs
                                  </Typography>
                                </Box>
                              </Box>
                            </Box>
                          )}

                          {/* Last Job Card */}
                          {ConfigurationState.Instance.lastJob && ConfigurationState.Instance.lastJob !== ConfigurationState.Instance.currentJob && (
                            <Box
                              sx={{
                                position: 'relative',
                                pt: 1.5,
                                minWidth: 0,
                                display: 'flex',
                                flexDirection: 'column',
                                cursor: 'pointer',
                                transition: 'all 0.2s',
                                '&:hover': {
                                  transform: 'translateY(-2px)',
                                  '& .last-inner': { backgroundColor: 'rgba(0, 0, 0, 0.07)', boxShadow: 3 }
                                }
                              }}
                              onClick={() => previewJobFromStorage(ConfigurationState.Instance.lastJob!)}
                            >
                              <Box
                                className="last-inner"
                                sx={{
                                  p: 3,
                                  pt: 2.5,
                                  flex: 1,
                                  border: '1px solid',
                                  borderColor: 'text.disabled',
                                  borderRadius: 1,
                                  backgroundColor: 'rgba(0, 0, 0, 0.03)',
                                  transition: 'background-color 0.2s, box-shadow 0.2s',
                                  minWidth: 0,
                                  overflow: 'hidden',
                                }}
                              >
                                <Typography
                                  variant="caption"
                                  sx={{
                                    position: 'absolute',
                                    top: 4,
                                    left: 12,
                                    px: 0.5,
                                    backgroundColor: 'background.paper',
                                    color: 'text.secondary',
                                    fontWeight: 600,
                                    lineHeight: 1,
                                    letterSpacing: '0.05em',
                                    textTransform: 'uppercase',
                                  }}
                                >
                                  Last
                                </Typography>
                                <Typography variant="h6" noWrap sx={{ minWidth: 0, mb: 1 }}>
                                  {ConfigurationState.Instance.lastJob.name}
                                </Typography>
                                <Typography variant="body2" color="text.secondary" gutterBottom>
                                  {ConfigurationState.Instance.lastJob.material.xLength
                                    ? `${ConfigurationState.Instance.lastJob.material.type}: ${ConfigurationState.Instance.lastJob.material.xLength}" × ${ConfigurationState.Instance.lastJob.material.yLength}" × ${ConfigurationState.Instance.lastJob.material.height}"`
                                    : 'No material'
                                  }
                                </Typography>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mt: 1.5 }}>
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                    <TimeIcon fontSize="small" color="action" />
                                    <Typography variant="caption">
                                      {ConfigurationState.Instance.lastJob.averageRuntimeFormatted} avg
                                    </Typography>
                                  </Box>
                                  <Typography variant="caption">
                                    • {ConfigurationState.Instance.lastJob.executionCount} runs
                                  </Typography>
                                </Box>
                              </Box>
                            </Box>
                          )}
                        </>
                      )}
                    />

                    {/* Recent Jobs — category tiles first, then uncategorized */}
                    <ObserveState
                      key="gcode-recent-jobs-list"
                      listenTo={JobCache.Instance}
                      properties={['recentJobs']}
                      control={() => {
                        const recentJobs = (JobCache.Instance.recentJobs ?? []) as JobMetadata[];

                        // Group by category
                        const categoryMap = new Map<string, JobMetadata[]>();
                        const uncategorized: JobMetadata[] = [];
                        for (const job of recentJobs) {
                          if (job.category) {
                            if (!categoryMap.has(job.category)) categoryMap.set(job.category, []);
                            categoryMap.get(job.category)!.push(job);
                          } else {
                            uncategorized.push(job);
                          }
                        }

                        // Sort each group by lastModified desc
                        for (const jobs of categoryMap.values()) {
                          jobs.sort((a, b) => (b.lastModified?.getTime() ?? 0) - (a.lastModified?.getTime() ?? 0));
                        }
                        // Sort category tiles by their most recent job's lastModified desc
                        const sortedCategories = Array.from(categoryMap.entries()).sort((a, b) =>
                          (b[1][0]?.lastModified?.getTime() ?? 0) - (a[1][0]?.lastModified?.getTime() ?? 0)
                        );
                        // Sort uncategorized by lastModified desc
                        uncategorized.sort((a, b) => (b.lastModified?.getTime() ?? 0) - (a.lastModified?.getTime() ?? 0));

                        return (
                          <>
                            {/* Category tiles */}
                            {sortedCategories.map(([cat, jobs]) => (
                              <Box
                                key={`cat-${cat}`}
                                sx={{
                                  position: 'relative',
                                  pt: 1.5,
                                  minWidth: 0,
                                  display: 'flex',
                                  flexDirection: 'column',
                                  cursor: 'pointer',
                                  transition: 'all 0.2s',
                                  '&:hover': {
                                    transform: 'translateY(-2px)',
                                    '& .cat-inner': { backgroundColor: 'rgba(78, 115, 48, 0.12)', boxShadow: 3 }
                                  }
                                }}
                                onClick={() => {
                                  setCategoryBrowseName(cat);
                                  setCategoryBrowseJobs(jobs);
                                  setCategoryBrowseOpen(true);
                                }}
                              >
                                <Box
                                  className="cat-inner"
                                  sx={{
                                    p: 3,
                                    pt: 2.5,
                                    flex: 1,
                                    border: '1px solid',
                                    borderColor: 'primary.light',
                                    borderRadius: 1,
                                    backgroundColor: 'rgba(78, 115, 48, 0.06)',
                                    transition: 'background-color 0.2s, box-shadow 0.2s',
                                    minWidth: 0,
                                    overflow: 'hidden',
                                    boxSizing: 'border-box',
                                  }}
                                >
                                  <Typography
                                    variant="caption"
                                    sx={{
                                      position: 'absolute',
                                      top: 4,
                                      left: 12,
                                      px: 0.5,
                                      backgroundColor: 'background.paper',
                                      color: 'primary.main',
                                      fontWeight: 600,
                                      lineHeight: 1,
                                      letterSpacing: '0.05em',
                                      textTransform: 'uppercase',
                                    }}
                                  >
                                    Category: {cat}
                                  </Typography>
                                  <Typography variant="h6" noWrap sx={{ minWidth: 0, mb: 1 }}>
                                    {jobs.length} job{jobs.length !== 1 ? 's' : ''}
                                  </Typography>
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1.5 }}>
                                    <Typography variant="caption" color="text.secondary">
                                      Last modified {formatFileAge(jobs[0]?.lastModified)}
                                    </Typography>
                                  </Box>
                                </Box>
                              </Box>
                            ))}

                            {/* Uncategorized jobs */}
                            {uncategorized.map((meta, index) => (
                              <Paper
                                key={meta.id}
                                sx={{
                                  p: 3,
                                  cursor: 'pointer',
                                  transition: 'all 0.2s',
                                  position: 'relative',
                                  minWidth: 0,
                                  overflow: 'hidden',
                                  '&:hover': {
                                    borderColor: 'primary.main',
                                    boxShadow: 3,
                                    transform: 'translateY(-2px)'
                                  }
                                }}
                                onClick={async () => {
                                  const job = await JobCache.Instance.fetchJob(meta.id, jobStorage);
                                  if (job) {
                                    previewJobFromStorage(job);
                                  } else {
                                    UserMessageQueue.Instance.addMessage(`❌ Could not load job: ${meta.name}`);
                                  }
                                }}
                                onMouseEnter={() => setHoveredJobIndex(index)}
                                onMouseLeave={() => setHoveredJobIndex(null)}
                              >
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1, minWidth: 0 }}>
                                  <FileIcon color="action" sx={{ fontSize: 32, flexShrink: 0 }} />
                                  <Typography variant="h6" noWrap sx={{ flex: 1, minWidth: 0 }}>
                                    {meta.name}
                                  </Typography>
                                  <IconButton
                                    size="small"
                                    onClick={(e) => handleOpenMenu(e, meta, index)}
                                    sx={{
                                      flexShrink: 0,
                                      opacity: hoveredJobIndex === index ? 1 : 0,
                                      transition: 'opacity 0.15s',
                                      pointerEvents: hoveredJobIndex === index ? 'auto' : 'none'
                                    }}
                                  >
                                    <MoreHorizIcon fontSize="small" />
                                  </IconButton>
                                </Box>
                                <Typography variant="body2" color="text.secondary" gutterBottom>
                                  {meta.materialType || 'No material'}
                                </Typography>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1.5, flexWrap: 'wrap' }}>
                                  <Typography variant="caption" color="text.secondary">
                                    {formatFileAge(meta.lastModified)}
                                  </Typography>
                                  <Typography variant="caption" color="text.secondary">•</Typography>
                                  <Typography variant="caption" color="text.secondary">
                                    {meta.executionCount} run{meta.executionCount !== 1 ? 's' : ''}
                                  </Typography>
                                  {meta.estimatedTime && (
                                    <>
                                      <Typography variant="caption" color="text.secondary">•</Typography>
                                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                        <TimeIcon fontSize="small" color="action" />
                                        <Typography variant="caption">{meta.estimatedTime}</Typography>
                                      </Box>
                                    </>
                                  )}
                                </Box>
                              </Paper>
                            ))}

                            {recentJobs.length === 0 && (
                              <Paper sx={{ p: 4, textAlign: 'center', gridColumn: '1 / -1' }}>
                                <Typography variant="body2" color="text.secondary">
                                  No recent jobs found
                                </Typography>
                              </Paper>
                            )}
                          </>
                        );
                      }}
                    />
                  </>
                )}

                {workflowState.selectedTab === 'wizards' && (
                  <>
                    <Paper
                      sx={{
                        p: 3,
                        cursor: 'pointer',
                        transition: 'all 0.2s',
                        '&:hover': {
                          boxShadow: 3,
                          transform: 'translateY(-2px)'
                        }
                      }}
                    >
                      <Typography variant="h6" gutterBottom>
                        Surface Spoilboard
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Generate G-Code to surface your spoilboard
                      </Typography>
                    </Paper>

                    <Paper
                      sx={{
                        p: 3,
                        cursor: 'pointer',
                        transition: 'all 0.2s',
                        '&:hover': {
                          boxShadow: 3,
                          transform: 'translateY(-2px)'
                        }
                      }}
                    >
                      <Typography variant="h6" gutterBottom>
                        Dovetail Jig
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Create dovetail joint patterns
                      </Typography>
                    </Paper>

                    <Paper
                      sx={{
                        p: 3,
                        cursor: 'pointer',
                        transition: 'all 0.2s',
                        '&:hover': {
                          boxShadow: 3,
                          transform: 'translateY(-2px)'
                        }
                      }}
                    >
                      <Typography variant="h6" gutterBottom>
                        Pocket Rectangle
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Generate rectangular pocket toolpaths
                      </Typography>
                    </Paper>

                    <Paper
                      sx={{
                        p: 3,
                        cursor: 'pointer',
                        transition: 'all 0.2s',
                        '&:hover': {
                          boxShadow: 3,
                          transform: 'translateY(-2px)'
                        }
                      }}
                    >
                      <Typography variant="h6" gutterBottom>
                        Drill Pattern
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Create custom drilling patterns
                      </Typography>
                    </Paper>

                    <Paper
                      sx={{
                        p: 3,
                        cursor: 'pointer',
                        transition: 'all 0.2s',
                        '&:hover': {
                          boxShadow: 3,
                          transform: 'translateY(-2px)'
                        }
                      }}
                    >
                      <Typography variant="h6" gutterBottom>
                        Text Engraving
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Generate G-Code for text engraving
                      </Typography>
                    </Paper>

                    <Paper
                      sx={{
                        p: 3,
                        cursor: 'pointer',
                        transition: 'all 0.2s',
                        '&:hover': {
                          boxShadow: 3,
                          transform: 'translateY(-2px)'
                        }
                      }}
                    >
                      <Typography variant="h6" gutterBottom>
                        Custom Pattern
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Build your own G-Code pattern
                      </Typography>
                    </Paper>
                  </>
                )}

                {workflowState.selectedTab === 'editor' && (
                  <Box sx={{ gridColumn: '1 / -1', display: 'flex', flexDirection: 'column', gap: 2, height: '100%' }}>
                    <ObserveState
                      key="gcode-editor-current-job"
                      listenTo={ConfigurationState.Instance}
                      properties={['currentJob']}
                      control={() => {
                        const job = ConfigurationState.Instance.currentJob;
                        if (!job) return null;
                        return (
                          <ObserveState
                            key={`gcode-editor-job-content-${job.id}`}
                            listenTo={job}
                            properties={['name', 'gcode']}
                            control={() => (
                              <>
                                <TextField
                                  label="Job Name"
                                  fullWidth
                                  value={job.name}
                                  onChange={(e) => { job.name = e.target.value; }}
                                  variant="outlined"
                                  placeholder="Enter a name for this job"
                                />
                                <TextField
                                  label="G-code"
                                  multiline
                                  fullWidth
                                  value={job.gcode}
                                  onChange={(e) => { job.gcode = e.target.value; }}
                                  minRows={25}
                                  variant="outlined"
                                  placeholder="Enter your G-code here..."
                                  InputProps={{
                                    sx: {
                                      fontFamily: 'monospace',
                                      fontSize: '0.875rem',
                                      backgroundColor: ConfigurationDataColors.Instance.darkBackgroundColor,
                                      color: ConfigurationDataColors.Instance.lightTextColor,
                                      '& .MuiOutlinedInput-notchedOutline': {
                                        borderColor: ConfigurationDataColors.Instance.borderColor
                                      },
                                      '&:hover .MuiOutlinedInput-notchedOutline': {
                                        borderColor: ConfigurationDataColors.Instance.secondaryBorderColor
                                      },
                                      '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                                        borderColor: 'primary.main'
                                      }
                                    }
                                  }}
                                />
                                <Box sx={{ display: 'flex', gap: 2, justifyContent: 'flex-end' }}>
                                  <Button
                                    variant="outlined"
                                    onClick={() => { job.gcode = ''; }}
                                  >
                                    Clear
                                  </Button>
                                  <Button
                                    variant="contained"
                                    onClick={() => {
                                      ConfigurationState.Instance.proposedJob = job;
                                      if (onPreviewReady) setTimeout(() => onPreviewReady(), 0);
                                    }}
                                    disabled={!job.gcode.trim()}
                                  >
                                    Preview
                                  </Button>
                                </Box>
                              </>
                            )}
                          />
                        );
                      }}
                    />
                  </Box>
                )}
              </Box>
            </Box>
          </Box>
        )}
      />
      <Menu
        anchorEl={menuAnchorEl}
        open={Boolean(menuAnchorEl)}
        onClose={handleCloseMenu}
        onClick={(e) => e.stopPropagation()}
      >
        <MenuItem onClick={() => {
          handleCloseMenu();
          if (menuJob) { setCategoryDialogJob(menuJob.job); setCategoryDialogOpen(true); }
        }}>
          <ListItemIcon><LabelIcon fontSize="small" /></ListItemIcon>
          <ListItemText>Set Category</ListItemText>
        </MenuItem>
        <MenuItem onClick={() => {
          if (menuJob) {
            setRenameValue(menuJob.job.name);
          }
          setMenuAnchorEl(null); // close popover but keep menuJob for rename dialog
          setRenameDialogOpen(true);
        }}>
          <ListItemIcon><RenameIcon fontSize="small" /></ListItemIcon>
          <ListItemText>Rename</ListItemText>
        </MenuItem>
        <MenuItem onClick={() => {
          if (menuJob) handleDeleteJob(menuJob.job);
          handleCloseMenu();
        }} sx={{ color: 'error.main' }}>
          <ListItemIcon><DeleteIcon fontSize="small" color="error" /></ListItemIcon>
          <ListItemText>Delete Job</ListItemText>
        </MenuItem>
      </Menu>
      <JobCategoryDialog
        open={categoryDialogOpen}
        job={categoryDialogJob}
        existingCategories={existingCategories}
        onClose={() => setCategoryDialogOpen(false)}
        onSave={handleSaveCategory}
      />
      <Dialog open={renameDialogOpen} onClose={() => { setRenameDialogOpen(false); setMenuJob(null); }} maxWidth="xs" fullWidth>
        <DialogTitle sx={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          backgroundColor: ConfigurationDataColors.Instance.primaryColor, color: 'white', py: 2, px: 3
        }}>
          Rename Job
          <IconButton onClick={() => { setRenameDialogOpen(false); setMenuJob(null); }} sx={{ color: 'white', '&:hover': { backgroundColor: 'rgba(255,255,255,0.1)' } }}>
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent>
          <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 2 }}>
            <Typography variant="body2" color="text.secondary">
              Current name: <strong>{menuJob?.job.name}</strong>
            </Typography>
            <TextField
              label="New name"
              fullWidth
              value={renameValue}
              onChange={(e) => setRenameValue(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !renaming) handleConfirmRename(); }}
              autoFocus
              disabled={renaming}
            />
          </Box>
        </DialogContent>
        <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${ConfigurationDataColors.Instance.borderColor}` }}>
          <Button onClick={() => { setRenameDialogOpen(false); setMenuJob(null); }} variant="outlined" disabled={renaming}>Cancel</Button>
          <Button
            onClick={handleConfirmRename}
            variant="contained"
            disabled={renaming || !renameValue.trim() || renameValue.trim() === menuJob?.job.name}
          >
            Rename
          </Button>
        </DialogActions>
      </Dialog>
      <JobCategoryBrowseDialog
        open={categoryBrowseOpen}
        category={categoryBrowseName}
        jobs={categoryBrowseJobs}
        onClose={() => setCategoryBrowseOpen(false)}
        onJobSelect={async (meta) => {
          const job = await JobCache.Instance.fetchJob(meta.id, jobStorage);
          if (job) {
            previewJobFromStorage(job);
          } else {
            UserMessageQueue.Instance.addMessage(`❌ Could not load job: ${meta.name}`);
          }
        }}
        onSetCategory={(meta) => { setCategoryDialogJob(meta); setCategoryDialogOpen(true); }}
        onDelete={(meta) => handleDeleteJob(meta)}
        onRename={handleRenameJob}
      />
    </>
  );
};
