import { IStorable } from '../../../../common/IStorable';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';

/**
 * Represents a single keybinding entry for a UI trigger
 * UI triggers can have multiple keybindings
 */
export class KeybindingItem implements IStorable {
    private _key: string = '';  // The main key (e.g., 'A', 'F1', 'Enter')
    private _shiftKey: boolean = false;  // Whether Shift modifier is required
    private _ctrlKey: boolean = false;   // Whether Control modifier is required
    private _altKey: boolean = false;    // Whether Alt modifier is required

    constructor(key?: string, ctrlKey?: boolean, shiftKey?: boolean, altKey?: boolean) {
        this._key = key || '';
        this._ctrlKey = ctrlKey || false;
        this._shiftKey = shiftKey || false;
        this._altKey = altKey || false;
    }

    /**
     * Get the main key
     */
    public get key(): string {
        return this._key;
    }

    public set key(value: string) {
        this._key = value;
        StateManager.propertyChanged(this, 'key');
    }

    /**
     * Get whether Shift modifier is required
     */
    public get shiftKey(): boolean {
        return this._shiftKey;
    }

    public set shiftKey(value: boolean) {
        this._shiftKey = value;
        StateManager.propertyChanged(this, 'shiftKey');
    }

    /**
     * Get whether Control modifier is required
     */
    public get ctrlKey(): boolean {
        return this._ctrlKey;
    }

    public set ctrlKey(value: boolean) {
        this._ctrlKey = value;
        StateManager.propertyChanged(this, 'ctrlKey');
    }

    /**
     * Get whether Alt modifier is required
     */
    public get altKey(): boolean {
        return this._altKey;
    }

    public set altKey(value: boolean) {
        this._altKey = value;
        StateManager.propertyChanged(this, 'altKey');
    }

    /**
     * Get a human-readable string representation of the key combination
     * Examples: "Ctrl+A", "Shift+F1", "Ctrl+Shift+Alt+Delete"
     */
    public getKeyString(): string {
        const modifiers: string[] = [];
        if (this._ctrlKey) modifiers.push('Ctrl');
        if (this._shiftKey) modifiers.push('Shift');
        if (this._altKey) modifiers.push('Alt');

        if (this._key) {
            modifiers.push(this._key);
        }

        return modifiers.length > 0 ? modifiers.join('+') : '(No key assigned)';
    }

    /**
     * Get the PLC variable name for this keybinding based on the key combination
     * @returns Variable name like "Ctrl_S_KB", "Shift_F1_KB", "Ctrl_Shift_Delete_KB"
     */
    public getVariableName(): string {
        const parts: string[] = [];

        // Add modifiers
        if (this._ctrlKey) parts.push('Ctrl');
        if (this._shiftKey) parts.push('Shift');
        if (this._altKey) parts.push('Alt');

        // Add key name (convert to word for special characters)
        if (this._key) {
            const keyName = this.getKeyNameForVariable(this._key);
            parts.push(keyName);
        }

        // Join with underscores and add _KB suffix
        return parts.length > 0 ? `${parts.join('_')}_KB` : 'Unknown_KB';
    }

    /**
     * Convert a key to a valid variable name component
     * Special characters are converted to words
     */
    private getKeyNameForVariable(key: string): string {
        // Convert to lowercase for consistent mapping
        const lowerKey = key.toLowerCase();

        // Special character mappings
        const specialChars: Record<string, string> = {
            ' ': 'Space',
            'enter': 'Enter',
            'tab': 'Tab',
            'escape': 'Escape',
            'esc': 'Escape',
            'backspace': 'Backspace',
            'delete': 'Delete',
            'del': 'Delete',
            'insert': 'Insert',
            'ins': 'Insert',
            'home': 'Home',
            'end': 'End',
            'pageup': 'PageUp',
            'pagedown': 'PageDown',
            'arrowup': 'Up',
            'arrowdown': 'Down',
            'arrowleft': 'Left',
            'arrowright': 'Right',
            'up': 'Up',
            'down': 'Down',
            'left': 'Left',
            'right': 'Right',
            '=': 'Equals',
            '-': 'Minus',
            '+': 'Plus',
            '[': 'LeftBracket',
            ']': 'RightBracket',
            '\\': 'Backslash',
            '/': 'Slash',
            ',': 'Comma',
            '.': 'Period',
            ';': 'Semicolon',
            "'": 'Quote',
            '`': 'Backtick',
            '~': 'Tilde',
            '!': 'Exclamation',
            '@': 'At',
            '#': 'Hash',
            '$': 'Dollar',
            '%': 'Percent',
            '^': 'Caret',
            '&': 'Ampersand',
            '*': 'Asterisk',
            '(': 'LeftParen',
            ')': 'RightParen',
            '_': 'Underscore',
            'printscreen': 'PrintScreen',
            'scrolllock': 'ScrollLock',
            'numlock': 'NumLock'
        };

        // Check special characters
        if (specialChars[lowerKey]) {
            return specialChars[lowerKey];
        }

        // Function keys (F1-F12)
        if (/^f([1-9]|1[0-2])$/i.test(key)) {
            return key.toUpperCase();
        }

        // Numpad keys
        if (lowerKey.startsWith('numpad')) {
            return 'Num' + key.substring(6);
        }

        // Regular alphanumeric - capitalize
        return key.toUpperCase();
    }

    /**
     * Check if this keybinding matches a keyboard event
     * @param event The keyboard event to check
     * @returns True if the event matches this keybinding
     */
    public matches(event: KeyboardEvent): boolean {
        if (!this._key) {
            return false;
        }

        return (
            event.key === this._key &&
            event.shiftKey === this._shiftKey &&
            event.ctrlKey === this._ctrlKey &&
            event.altKey === this._altKey
        );
    }

    /**
     * Set the keybinding from a keyboard event
     * @param event The keyboard event to capture
     */
    public captureFromEvent(event: KeyboardEvent): void {
        this._key = event.key;
        this._shiftKey = event.shiftKey;
        this._ctrlKey = event.ctrlKey;
        this._altKey = event.altKey;
        StateManager.propertyChanged(this, 'key');
        StateManager.propertyChanged(this, 'shiftKey');
        StateManager.propertyChanged(this, 'ctrlKey');
        StateManager.propertyChanged(this, 'altKey');
    }

    /**
     * Clear the key assignment
     */
    public clearKey(): void {
        this._key = '';
        this._shiftKey = false;
        this._ctrlKey = false;
        this._altKey = false;
        StateManager.propertyChanged(this, 'key');
        StateManager.propertyChanged(this, 'shiftKey');
        StateManager.propertyChanged(this, 'ctrlKey');
        StateManager.propertyChanged(this, 'altKey');
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        return DataUtilities.getStorageData(this);
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }

    /**
     * Clone this keybinding item
     */
    public clone(): KeybindingItem {
        const cloned = new KeybindingItem();
        cloned.fromJSON(this.toJSON());
        return cloned;
    }
}
