import {
  Add as AddIcon,
  Construction as ClampIcon,
  Close as CloseIcon,
  Delete as DeleteIcon,
  Edit as EditIcon,
  RotateRight as RotateIcon
} from '@mui/icons-material';
import {
  Box,
  Button,
  Card,
  CardContent,
  Collapse,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  Grid,
  IconButton,
  List,
  ListItem,
  ListItemButton,
  ListItemText,
  Typography
} from '@mui/material';
import { Component } from 'react';
import { Clamp } from '../../data/Common/Clamp';
import { ClampLibrary } from '../../data/Common/ClampLibrary';
import { SimulatorView } from '../../data/Common/SimulatorView';
import { ViewStyle } from '../../data/Common/ViewStyle';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { Job } from '../../data/Job';
import { MachineData } from '../../data/Machine/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { StateManager } from '../../utils/statemanager/StateManager';
import { ViewDataFactory, ViewNames } from '../../utils/ViewDataFactory';
import { ColorPicker } from '../Common/ColorPicker';
import { NumberInput } from '../Common/NumberInput';
import { FullSizeCNCViewer } from '../MachineViewer/FullSizeCNCViewer';

interface ClampEditorFormProps {
  onSaveToLibrary?: () => void;
  onLoadFromLibrary?: () => void;
  height?: string | number;
  maxHeight?: string | number;
}

interface ClampEditorFormState {
  libraryDialogOpen: boolean;
  editingClampId: string | null;
}

export class ClampEditorForm extends Component<ClampEditorFormProps, ClampEditorFormState> {
  private simulatorViewData = ViewDataFactory.createForContext(ViewNames.CLAMP_EDITOR);

  constructor(props: ClampEditorFormProps) {
    super(props);
    this.state = {
      libraryDialogOpen: false,
      editingClampId: null
    };
  }

  // Create a simulator view optimized for clamp editing
  createClampEditorSimulatorView(): SimulatorView {
    const view = new SimulatorView();

    // Show essential elements for clamp setup
    view.workHome = true;           // Show work home for reference
    view.spoilBoard = ViewStyle.Show; // Show spoilboard
    view.material = ViewStyle.Show; // Show material  
    view.spindle = ViewStyle.SemiTransparent; // Show spindle transparently
    view.tool = ViewStyle.Show;     // Show tool
    view.clamps = ViewStyle.Show;   // Show clamps (most important for this editor)

    // Hide unnecessary elements for cleaner view
    view.toolpaths = false;         // Hide toolpaths - not relevant for clamp setup
    view.softLimits = false;        // Hide soft limits
    view.machineZero = false;       // Hide machine zero
    view.machineHome = false;       // Hide machine home
    view.gantry = ViewStyle.Hide;   // Hide gantry for cleaner view
    view.base = ViewStyle.Hide;     // Hide base for cleaner view
    view.bed = ViewStyle.Hide;      // Hide bed for focus on work area
    view.railing = ViewStyle.Hide;  // Hide railing
    view.workPiece = ViewStyle.Hide; // Hide work piece
    view.rotary = ViewStyle.Hide;   // Hide rotary
    view.verticalTable = ViewStyle.Hide; // Hide vertical table
    view.laser = ViewStyle.Hide;    // Hide laser
    view.laserPointer = ViewStyle.Hide; // Hide laser pointer
    view.drillHead = ViewStyle.Hide; // Hide drill head
    view.atc = ViewStyle.Hide;      // Hide ATC

    return view;
  }

  handleSaveToLibrary = () => {
    // Implementation for saving current clamps to library
    if (this.props.onSaveToLibrary) {
      this.props.onSaveToLibrary();
    }
  };

  handleLoadFromLibrary = () => {
    // Implementation for loading clamps from library
    if (this.props.onLoadFromLibrary) {
      this.props.onLoadFromLibrary();
    }
  };

  handleClampSelect = (clampId: string) => {
    ConfigurationState.Instance.selectedClampId = clampId;
  };

  handleClampDelete = (clampId: string) => {
    const currentJob = ConfigurationState.Instance.currentJob;
    if (currentJob) {
      const clampIndex = currentJob.clamps.findIndex((clamp: Clamp) => clamp.id === clampId);
      if (clampIndex >= 0) {
        currentJob.clamps.splice(clampIndex, 1);
        StateManager.propertyChanged(ConfigurationState.Instance, 'currentJob');

        // Clear selection if deleted clamp was selected
        if (ConfigurationState.Instance.selectedClampId === clampId) {
          ConfigurationState.Instance.selectedClampId = null;
        }
      }
    }
  };

  handleAddClamp = () => {
    this.setState({ libraryDialogOpen: true });
  };

  handleAddClampFromLibrary = (libraryClamp: Clamp) => {
    const currentJob = ConfigurationState.Instance.currentJob;
    if (currentJob) {
      const newClamp = libraryClamp.clone();
      newClamp.clampOffsetX = 2; // Default position
      newClamp.clampOffsetY = 2; // Default position

      currentJob.clamps.push(newClamp);
      StateManager.propertyChanged(ConfigurationState.Instance, 'currentJob');
      ConfigurationState.Instance.selectedClampId = newClamp.id;
    }
    this.setState({ libraryDialogOpen: false });
  };

  handleClampRotate = (clampId: string) => {
    const currentJob = ConfigurationState.Instance.currentJob;
    if (currentJob) {
      const clamp = currentJob.clamps.find((c: Clamp) => c.id === clampId);
      if (clamp) {
        // Swap X and Y dimensions
        const tempX = clamp.clampXWidth;
        clamp.clampXWidth = clamp.clampYWidth;
        clamp.clampYWidth = tempX;

        // Notify both the clamp object and the job that changes occurred
        StateManager.propertyChanged(clamp, 'clampXWidth');
        StateManager.propertyChanged(clamp, 'clampYWidth');
        StateManager.propertyChanged(ConfigurationState.Instance, 'currentJob');
      }
    }
  };

  handleClampEdit = (clampId: string) => {
    this.setState({ editingClampId: clampId });
  };

  handleClampPropertyChange = (clampId: string, property: string, value: number) => {
    const currentJob = ConfigurationState.Instance.currentJob;
    if (currentJob) {
      const clamp = currentJob.clamps.find((c: Clamp) => c.id === clampId);
      if (clamp) {
        (clamp as any)[property] = value;
        StateManager.propertyChanged(ConfigurationState.Instance, 'currentJob');
      }
    }
  };

  handleClampColorChange = (clampId: string, color: string) => {
    const currentJob = ConfigurationState.Instance.currentJob;
    if (currentJob) {
      const clamp = currentJob.clamps.find((c: Clamp) => c.id === clampId);
      if (clamp) {
        clamp.clampColor = color;
        StateManager.propertyChanged(ConfigurationState.Instance, 'currentJob');
      }
    }
  };

  handleCloseEdit = () => {
    this.setState({ editingClampId: null });
  };

  render() {
    const { height = '100%', maxHeight } = this.props;
    const colors = ConfigurationDataColors.Instance;

    return (
      <Box sx={{
        height,
        maxHeight,
        display: 'flex',
        overflow: 'hidden'
      }}>
        {/* Left Panel - 3D Viewer and Controls */}
        <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', mr: 2 }}>
          <Typography variant="h6" gutterBottom>
            Clamp View
          </Typography>

          <Box sx={{
            flex: 1,
            minHeight: 0,
            mb: 2,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}>
            <FullSizeCNCViewer
              simulatorViewData={this.simulatorViewData}
              machineState={MachineStateData.Instance}
              machineData={MachineData.Instance}
              job={ConfigurationState.Instance.currentJob || Job.createTestJob()}
            />
          </Box>
        </Box>

        {/* Divider */}
        <Divider orientation="vertical" flexItem sx={{ mx: 2 }} />

        {/* Right Panel - Clamp List */}
        <Box sx={{
          width: 350,
          display: 'flex',
          flexDirection: 'column',
          minHeight: 0 // Important for flex children to allow shrinking
        }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
            <Typography variant="h6">
              Clamps
            </Typography>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={this.handleAddClamp}
              size="small"
            >
              Add Clamp
            </Button>
          </Box>

          <ObserveState
            key="clamp-list-observer"
            listenTo={ConfigurationState.Instance}
            properties={['currentJob']}
            control={() => {
              const currentJob = ConfigurationState.Instance.currentJob;
              const selectedClampId = ConfigurationState.Instance.selectedClampId;
              const clamps = currentJob?.clamps || [];

              if (clamps.length === 0) {
                return (
                  <Card sx={{ textAlign: 'center', py: 4 }}>
                    <CardContent>
                      <ClampIcon sx={{ fontSize: 48, color: 'text.secondary', mb: 2 }} />
                      <Typography variant="body2" color="text.secondary">
                        No clamps configured
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        Click "Add Clamp" to get started
                      </Typography>
                    </CardContent>
                  </Card>
                );
              }

              return (
                <Card sx={{
                  flex: 1,
                  display: 'flex',
                  flexDirection: 'column',
                  minHeight: 0,
                  overflow: 'hidden'
                }}>
                  <List
                    dense
                    sx={{
                      flex: 1,
                      overflow: 'auto',
                      '& .MuiListItem-root': {
                        flexShrink: 0
                      }
                    }}
                  >
                    {clamps.map((clamp: Clamp, index: number) => (
                      <Box key={clamp.id}>
                        <ObserveState
                          listenTo={clamp}
                          properties={['clampname', 'clampColor', 'clampOffsetX', 'clampOffsetY', 'clampXWidth', 'clampYWidth', 'clampHeight']}
                          control={() => {
                            const isSelected = selectedClampId === clamp.id;
                            return (
                              <ListItem disablePadding>
                                <ListItemButton
                                  selected={isSelected}
                                  onClick={() => this.handleClampSelect(clamp.id)}
                                  sx={{
                                    '&.Mui-selected': {
                                      backgroundColor: `${ConfigurationDataColors.Instance.primaryColor}15`,
                                      borderLeft: `4px solid ${ConfigurationDataColors.Instance.primaryColor}`,
                                      '&:hover': {
                                        backgroundColor: `${ConfigurationDataColors.Instance.primaryColor}25`,
                                      },
                                    },
                                  }}
                                >
                                  <ListItemText
                                    primary={
                                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                        {isSelected && (
                                          <Typography
                                            variant="caption"
                                            sx={{
                                              backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                                              color: ConfigurationDataColors.Instance.lightTextColor,
                                              px: 1,
                                              py: 0.25,
                                              borderRadius: 1,
                                              fontWeight: 'bold',
                                              fontSize: '0.7rem'
                                            }}
                                          >
                                            CURRENT
                                          </Typography>
                                        )}
                                        <Typography variant="body1">{clamp.clampname}</Typography>
                                      </Box>
                                    }
                                    secondary={
                                      <Typography variant="caption" color="text.secondary">
                                        Position: X{clamp.clampOffsetX.toFixed(2)}", Y{clamp.clampOffsetY.toFixed(2)}"
                                      </Typography>
                                    }
                                  />
                                </ListItemButton>
                              </ListItem>
                            );
                          }}
                        />

                        {/* Action buttons for selected clamp */}
                        <Collapse in={selectedClampId === clamp.id}>
                          <Box sx={{ px: 2, pb: 1, display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
                            <IconButton
                              size="small"
                              onClick={() => this.handleClampRotate(clamp.id)}
                              title="Rotate clamp (swap X/Y dimensions)"
                            >
                              <RotateIcon />
                            </IconButton>
                            <IconButton
                              size="small"
                              onClick={() => this.handleClampEdit(clamp.id)}
                              title="Edit clamp properties"
                            >
                              <EditIcon />
                            </IconButton>
                            <IconButton
                              size="small"
                              onClick={() => this.handleClampDelete(clamp.id)}
                              title="Delete clamp"
                            >
                              <DeleteIcon />
                            </IconButton>
                          </Box>
                        </Collapse>
                      </Box>
                    ))}
                  </List>
                </Card>
              );
            }}
          />
        </Box>

        {/* Add Clamp Dialog */}
        {this.state.libraryDialogOpen && (
          <Box sx={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: ConfigurationDataColors.Instance.modalBackdrop,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1300
          }}>
            <Card sx={{ width: 400, maxHeight: '80vh', overflow: 'auto' }}>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Add Clamp from Library
                </Typography>

                <ObserveState
                  listenTo={ClampLibrary.Instance}
                  control={() => (
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                      {ClampLibrary.Instance.clamps.map((clamp, index) => (
                        <Card key={index} variant="outlined">
                          <CardContent sx={{ pb: 1 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                              <ClampIcon sx={{ color: clamp.clampColor }} />
                              <Typography variant="subtitle2">
                                {clamp.clampname}
                              </Typography>
                            </Box>

                            <Typography variant="body2" color="text.secondary" gutterBottom>
                              {clamp.clampXWidth}" × {clamp.clampYWidth}" × {clamp.clampHeight}"
                            </Typography>

                            <Button
                              size="small"
                              variant="outlined"
                              startIcon={<AddIcon />}
                              onClick={() => this.handleAddClampFromLibrary(clamp)}
                              sx={{ width: '100%' }}
                            >
                              Add to Job
                            </Button>
                          </CardContent>
                        </Card>
                      ))}

                      {ClampLibrary.Instance.clamps.length === 0 && (
                        <Box sx={{ textAlign: 'center', py: 4 }}>
                          <ClampIcon sx={{ fontSize: 48, color: 'text.secondary', mb: 2 }} />
                          <Typography variant="body2" color="text.secondary">
                            No clamps available in library.
                          </Typography>
                        </Box>
                      )}
                    </Box>
                  )}
                />

                <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
                  <Button onClick={() => this.setState({ libraryDialogOpen: false })}>
                    Cancel
                  </Button>
                </Box>
              </CardContent>
            </Card>
          </Box>
        )}

        {/* Edit Clamp Dialog */}
        {this.state.editingClampId && (
          <ObserveState
            key="clamp-editor-dialog"
            listenTo={ConfigurationState.Instance}
            properties={['currentJob']}
            control={() => {
              const currentJob = ConfigurationState.Instance.currentJob;
              const clamp = currentJob?.clamps.find((c: Clamp) => c.id === this.state.editingClampId);
              const colors = ConfigurationDataColors.Instance;

              if (!clamp) {
                return null;
              }

              return (
                <Dialog
                  open={true}
                  onClose={this.handleCloseEdit}
                  maxWidth="sm"
                  fullWidth
                >
                  <DialogTitle sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    py: 2,
                    px: 3
                  }}>
                    Edit Clamp Properties
                    <IconButton
                      onClick={this.handleCloseEdit}
                      sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                          backgroundColor: colors.lightOverlay
                        }
                      }}
                    >
                      <CloseIcon />
                    </IconButton>
                  </DialogTitle>
                  <DialogContent>
                    <ObserveState
                      key="clamp-edit-observe"
                      listenTo={clamp}
                      properties={['clampname', 'clampColor', 'clampOffsetX', 'clampOffsetY', 'clampXWidth', 'clampYWidth', 'clampHeight']}
                      control={() => (
                        <Grid container spacing={2} sx={{ mt: 1 }}>
                          <Grid item xs={6}>
                            <NumberInput
                              fullWidth
                              label="X Position"
                              value={clamp.clampOffsetX}
                              onChange={(value) => this.handleClampPropertyChange(clamp.id, 'clampOffsetX', value)}
                              allowNegative={true}
                              allowPositive={true}
                              allowFractions={true}
                              defaultUnit="in"
                              precision={3}
                              showHelperText={false}
                            />
                          </Grid>
                          <Grid item xs={6}>
                            <NumberInput
                              fullWidth
                              label="Y Position"
                              value={clamp.clampOffsetY}
                              onChange={(value) => this.handleClampPropertyChange(clamp.id, 'clampOffsetY', value)}
                              allowNegative={true}
                              allowPositive={true}
                              allowFractions={true}
                              defaultUnit="in"
                              precision={3}
                              showHelperText={false}
                            />
                          </Grid>
                          <Grid item xs={4}>
                            <NumberInput
                              fullWidth
                              label="X Width"
                              value={clamp.clampXWidth}
                              onChange={(value) => this.handleClampPropertyChange(clamp.id, 'clampXWidth', value)}
                              allowNegative={false}
                              allowPositive={true}
                              allowFractions={true}
                              defaultUnit="in"
                              precision={3}
                              showHelperText={false}
                            />
                          </Grid>
                          <Grid item xs={4}>
                            <NumberInput
                              fullWidth
                              label="Y Width"
                              value={clamp.clampYWidth}
                              onChange={(value) => this.handleClampPropertyChange(clamp.id, 'clampYWidth', value)}
                              allowNegative={false}
                              allowPositive={true}
                              allowFractions={true}
                              defaultUnit="in"
                              precision={3}
                              showHelperText={false}
                            />
                          </Grid>
                          <Grid item xs={4}>
                            <NumberInput
                              fullWidth
                              label="Height"
                              value={clamp.clampHeight}
                              onChange={(value) => this.handleClampPropertyChange(clamp.id, 'clampHeight', value)}
                              allowNegative={false}
                              allowPositive={true}
                              allowFractions={true}
                              defaultUnit="in"
                              precision={3}
                              showHelperText={false}
                            />
                          </Grid>
                          <Grid item xs={12}>
                            <ColorPicker
                              label="Clamp Color"
                              value={clamp.clampColor}
                              onChange={(color) => this.handleClampColorChange(clamp.id, color)}
                            />
                          </Grid>
                        </Grid>
                      )}
                    />
                  </DialogContent>
                  <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                    <Button
                      onClick={this.handleCloseEdit}
                      variant="contained"
                      sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                          backgroundColor: colors.primaryColor,
                          filter: 'brightness(0.9)'
                        }
                      }}
                    >
                      Done
                    </Button>
                  </DialogActions>
                </Dialog>
              );
            }}
          />
        )}
      </Box>
    );
  }
}
