import { FormControlLabel, Grid, Switch, Typography } from '@mui/material';
import { PLCProgram } from '../../../../centroid/plc/data/PLCProgram';
import { PLCProgramType } from '../../../../centroid/plc/data/PLCUtilities';
import { MachineData } from '../../../../data/Machine/MachineData';
import { PLCInputName } from '../../../../data/PLCIONames';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';

export function MovableTouchPlateSection() {
    const machine = MachineData.Instance;

    // Check if movable touch plate PLC input is configured
    const isMovableTouchPlateInputConfigured = (): boolean => {
        const systemPLC = PLCProgram.Instance(PLCProgramType.System);
        const plcInput = systemPLC.inputs.find(input => input.centroidName === PLCInputName.MaterialToolTouchPlate);
        return plcInput !== undefined && plcInput.number !== null;
    };

    return (
        <Grid container spacing={3}>
            {/* Has Movable Touch Plate Switch */}
            <Grid item xs={12}>
                <ObserveState
                    key="movable-touch-plate-enabled"
                    listenTo={machine}
                    properties={['hasMovableTouchPlate']}
                    control={() => (
                        <>
                            <FormControlLabel
                                control={
                                    <Switch
                                        checked={machine.hasMovableTouchPlate}
                                        onChange={(e) => {
                                            if (e.target.checked && !isMovableTouchPlateInputConfigured()) {
                                                UserMessageQueue.Instance.addMessage('❌ Cannot enable movable touch plate - PLC input "MaterialToolTouchPlate" is not configured');
                                                return;
                                            }
                                            machine.hasMovableTouchPlate = e.target.checked;
                                        }}
                                    />
                                }
                                label="Has Movable Touch Plate"
                            />
                            {!isMovableTouchPlateInputConfigured() && (
                                <Typography variant="caption" color="error" sx={{ display: 'block', mt: 0.5, ml: 4 }}>
                                    ⚠️ PLC input "MaterialToolTouchPlate" must be configured before enabling
                                </Typography>
                            )}
                        </>
                    )}
                />
            </Grid>

            {/* Movable Touch Plate Configuration - Only show if enabled */}
            <ObserveState
                key="movable-touch-plate-config"
                listenTo={machine}
                properties={['hasMovableTouchPlate']}
                control={() => {
                    if (!machine.hasMovableTouchPlate) {
                        return null;
                    }
                    return (
                        <>
                            {/* Checklist Indicator */}
                            <Grid item xs={12}>
                                <SetupChecklistIndicator name="Movable Touch Plate Height" />
                            </Grid>

                            {/* Probing Speeds */}
                            <Grid item xs={12}>
                                <Typography variant="subtitle1" sx={{ mt: 1, mb: 1 }}>Probing Speeds</Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                    Fast and slow probing speeds for accurate touch-off (in/min)
                                </Typography>
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <ObserveState
                                    key="movable-touch-plate-fast-speed"
                                    listenTo={machine}
                                    properties={['movableTouchPlateFastSpeed']}
                                    control={() => (
                                        <>
                                            <NumberInput
                                                fullWidth
                                                label="Fast Probing Speed"
                                                value={machine.movableTouchPlateFastSpeed}
                                                onChange={(value) => machine.movableTouchPlateFastSpeed = value}
                                                margin="normal"
                                                precision={0}
                                                min={1}
                                                max={1000}
                                            />
                                            <Typography variant="caption" color="text.secondary">
                                                Initial approach speed (default: 100 in/min)
                                            </Typography>
                                        </>
                                    )}
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <ObserveState
                                    key="movable-touch-plate-slow-speed"
                                    listenTo={machine}
                                    properties={['movableTouchPlateSlowSpeed']}
                                    control={() => (
                                        <>
                                            <NumberInput
                                                fullWidth
                                                label="Slow Probing Speed"
                                                value={machine.movableTouchPlateSlowSpeed}
                                                onChange={(value) => machine.movableTouchPlateSlowSpeed = value}
                                                margin="normal"
                                                precision={0}
                                                min={1}
                                                max={1000}
                                            />
                                            <Typography variant="caption" color="text.secondary">
                                                Final precise measurement speed (default: 10 in/min)
                                            </Typography>
                                        </>
                                    )}
                                />
                            </Grid>

                            {/* Touch Plate Height */}
                            <Grid item xs={12}>
                                <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Touch Plate Height</Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                    Physical height/thickness of the movable touch plate
                                </Typography>
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <ObserveState
                                    key="movable-touch-plate-height"
                                    listenTo={machine}
                                    properties={['movableTouchPlateHeight']}
                                    control={() => (
                                        <>
                                            <NumberInput
                                                fullWidth
                                                label="Touch Plate Height"
                                                value={machine.movableTouchPlateHeight}
                                                onChange={(value) => machine.movableTouchPlateHeight = value}
                                                margin="normal"
                                                precision={3}
                                                min={0}
                                            />
                                            <Typography variant="caption" color="text.secondary">
                                                Height of touch plate block (default: 3.000)
                                            </Typography>
                                        </>
                                    )}
                                />
                            </Grid>
                        </>
                    );
                }}
            />
        </Grid>
    );
}
