import AddIcon from '@mui/icons-material/Add';
import {
    Box,
    Button,
    IconButton,
    Menu,
    MenuItem,
    Typography
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { TooltipManager } from '../../../utils/TooltipManager';
import { Condition } from '../data/Condition';
import { ConditionGroup, GroupType } from '../data/ConditionGroup';
import { DataCondition } from '../data/DataCondition';
import { PLCRenderMode } from '../data/IPLCElement';
import { PLCProgramType } from '../data/PLCUtilities';

interface ConditionGroupEditorProps {
    conditionGroup: ConditionGroup;
    onChanged?: () => void;
    depth?: number; // Track nesting depth for visual hierarchy
    isRoot?: boolean; // Is this the root condition group (no braces needed)
    renderMode?: PLCRenderMode; // Rendering mode (Edit, ReadOnly, Disabled)
    targetProgramType: PLCProgramType; // REQUIRED: Which program context we're rendering in
}

/**
 * ConditionGroupEditor - UI component for editing condition groups
 * Supports recursive nested groups with AND/OR/XOR operations
 */
export function ConditionGroupEditor(props: ConditionGroupEditorProps) {
    const { conditionGroup, onChanged, depth = 0, isRoot = false, renderMode = PLCRenderMode.Edit, targetProgramType } = props;
    const [addMenuAnchor, setAddMenuAnchor] = useState<null | HTMLElement>(null);
    const isReadOnly = renderMode === PLCRenderMode.ReadOnly;
    const [groupTypeMenuAnchor, setGroupTypeMenuAnchor] = useState<null | HTMLElement>(null);
    const colors = ConfigurationDataColors.Instance;

    const handleAddCondition = (type: 'single' | 'group') => {
        let newCondition: Condition;
        if (type === 'single') {
            newCondition = new DataCondition();
        } else {
            const newGroup = new ConditionGroup(GroupType.And);
            // Add a default DataCondition to the new group
            const defaultCondition = new DataCondition();
            newGroup.addCondition(defaultCondition);
            newCondition = newGroup;
        }
        conditionGroup.addCondition(newCondition);
        setAddMenuAnchor(null);
        onChanged?.();
    };

    const handleRemoveCondition = (condition: Condition) => {
        conditionGroup.removeCondition(condition);
        onChanged?.();
    };

    // TODO: Implement condition reordering UI
    // const handleMoveConditionUp = (condition: Condition) => {
    //     const index = conditionGroup.conditions.indexOf(condition);
    //     if (index > 0) {
    //         conditionGroup.conditions.splice(index, 1);
    //         conditionGroup.conditions.splice(index - 1, 0, condition);
    //         onChanged?.();
    //     }
    // };

    // const handleMoveConditionDown = (condition: Condition) => {
    //     const index = conditionGroup.conditions.indexOf(condition);
    //     if (index >= 0 && index < conditionGroup.conditions.length - 1) {
    //         conditionGroup.conditions.splice(index, 1);
    //         conditionGroup.conditions.splice(index + 1, 0, condition);
    //         onChanged?.();
    //     }
    // };

    const handleConditionChanged = () => {
        onChanged?.();
    };

    return (
        <>
            <ObserveState
                key={`condition-group-editor-${depth}`}
                listenTo={conditionGroup}
                properties={['groupType', 'conditions']}
                control={() => {
                    // All groups use flex layout with braces that span content height
                    return (
                        <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                            <Box sx={{
                                fontFamily: 'monospace',
                                fontSize: '24px',
                                mr: 0.5,
                                width: '10px',
                                borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                display: 'flex',
                                flexDirection: 'column',
                                alignItems: 'center',
                                justifyContent: 'center'
                            }}></Box>
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: isRoot ? 0 : 0.5 }}>
                                {conditionGroup.conditions.length === 0 ? (
                                    !isReadOnly ? (
                                        <IconButton
                                            size="small"
                                            onClick={(e) => setAddMenuAnchor(e.currentTarget)}
                                            sx={{
                                                color: colors.primaryColor,
                                                fontSize: '12px',
                                                px: 1,
                                                py: 0.5,
                                                borderRadius: 1,
                                                border: `1px dashed ${colors.borderColor}`,
                                                '&:hover': {
                                                    backgroundColor: `${colors.primaryColor}20`,
                                                    borderColor: colors.primaryColor
                                                }
                                            }}
                                        >
                                            <AddIcon fontSize="small" sx={{ mr: 0.5 }} />
                                            <Typography variant="caption" sx={{ fontFamily: 'monospace' }}>pick</Typography>
                                        </IconButton>
                                    ) : (
                                        <Typography variant="caption" sx={{ fontFamily: 'monospace', fontStyle: 'italic', color: colors.mutedTextColor }}>empty</Typography>
                                    )
                                ) : (
                                    (() => {
                                        // Separate inline conditions from nested groups
                                        const inlineConditions: DataCondition[] = [];
                                        const nestedGroups: ConditionGroup[] = [];

                                        conditionGroup.conditions.forEach((condition) => {
                                            if (condition instanceof ConditionGroup) {
                                                nestedGroups.push(condition);
                                            } else {
                                                inlineConditions.push(condition as DataCondition);
                                            }
                                        });

                                        const rows: React.ReactElement[] = [];

                                        // Render all inline conditions first as a single row
                                        if (inlineConditions.length > 0) {
                                            const inlineElements: React.ReactElement[] = [];
                                            inlineConditions.forEach((condition, idx) => {
                                                const originalIndex = conditionGroup.conditions.indexOf(condition);

                                                if (idx > 0) {
                                                    inlineElements.push(
                                                        <React.Fragment key={`combiner-${originalIndex}`}>
                                                            <Typography component="span" sx={{ mx: 0.5 }}> </Typography>
                                                            <Button
                                                                onClick={isReadOnly ? undefined : (e) => setGroupTypeMenuAnchor(e.currentTarget)}
                                                                size="small"
                                                                disabled={isReadOnly}
                                                                sx={{
                                                                    fontFamily: 'monospace',
                                                                    fontSize: '11px',
                                                                    minWidth: 'auto',
                                                                    px: 1,
                                                                    py: 0.25,
                                                                    textTransform: 'lowercase',
                                                                    fontWeight: 'bold',
                                                                    color: ConfigurationDataColors.Instance.mutedTextColor,
                                                                    border: `1px solid ${ConfigurationDataColors.Instance.mutedTextColor}`,
                                                                    backgroundColor: 'transparent',
                                                                    '&:hover': {
                                                                        backgroundColor: `${colors.secondaryBorderColor}20`,
                                                                        borderColor: ConfigurationDataColors.Instance.mutedTextColor
                                                                    }
                                                                }}
                                                            >
                                                                {conditionGroup.groupType.toLowerCase()}
                                                            </Button>
                                                            <Typography component="span" sx={{ mx: 0.5 }}> </Typography>
                                                        </React.Fragment>
                                                    );
                                                }

                                                inlineElements.push(
                                                    <Box
                                                        key={originalIndex}
                                                        component="span"
                                                        onMouseEnter={(e) => {
                                                            if (!isReadOnly) {
                                                                const rect = e.currentTarget.getBoundingClientRect();
                                                                TooltipManager.Instance.showTooltip(
                                                                    <Box sx={{
                                                                        display: 'flex',
                                                                        flexDirection: 'column',
                                                                        minWidth: 150,
                                                                        bgcolor: 'background.paper',
                                                                        borderRadius: 1,
                                                                        boxShadow: 2,
                                                                        border: `1px solid ${colors.borderColor}`
                                                                    }}>
                                                                        <MenuItem
                                                                            onClick={() => {
                                                                                handleAddCondition('single');
                                                                                TooltipManager.Instance.hideTooltip();
                                                                            }}
                                                                            sx={{
                                                                                py: 1,
                                                                                px: 2,
                                                                                fontSize: '14px',
                                                                                '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                                                            }}
                                                                        >
                                                                            Add Data Element
                                                                        </MenuItem>
                                                                        <MenuItem
                                                                            onClick={() => {
                                                                                handleAddCondition('group');
                                                                                TooltipManager.Instance.hideTooltip();
                                                                            }}
                                                                            sx={{
                                                                                py: 1,
                                                                                px: 2,
                                                                                fontSize: '14px',
                                                                                '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                                                            }}
                                                                        >
                                                                            Add Group
                                                                        </MenuItem>
                                                                        <MenuItem
                                                                            onClick={() => {
                                                                                handleRemoveCondition(condition);
                                                                                TooltipManager.Instance.hideTooltip();
                                                                            }}
                                                                            sx={{
                                                                                py: 1,
                                                                                px: 2,
                                                                                fontSize: '14px',
                                                                                color: 'error.main',
                                                                                '&:hover': {
                                                                                    backgroundColor: 'error.main',
                                                                                    color: colors.lightTextColor
                                                                                }
                                                                            }}
                                                                        >
                                                                            Delete Element
                                                                        </MenuItem>
                                                                    </Box>,
                                                                    { top: rect.top, left: rect.right + 5 }
                                                                );
                                                            }
                                                        }}
                                                        onMouseLeave={() => {
                                                            if (!isReadOnly) {
                                                                TooltipManager.Instance.hideTooltipWithDelay(300);
                                                            }
                                                        }}
                                                        sx={{
                                                            display: 'inline-flex',
                                                            alignItems: 'center',
                                                            gap: 0.5,
                                                            '&:hover': {
                                                                backgroundColor: `${colors.primaryColor}10`,
                                                                borderRadius: 1,
                                                                px: 0.5
                                                            }
                                                        }}
                                                    >
                                                        <ObserveState
                                                            key={`data-condition-${originalIndex}`}
                                                            listenTo={condition}
                                                            properties={['dataElement', 'comparisonOperator', 'memoryBitState', 'useConstant', 'comparisonValue', 'comparisonElement']}
                                                            control={() => condition.render(renderMode, targetProgramType)}
                                                        />
                                                    </Box>
                                                );
                                            });

                                            rows.push(
                                                <Box key="inline-conditions" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                    {inlineElements}
                                                    {nestedGroups.length > 0 && (
                                                        <Button
                                                            onClick={isReadOnly ? undefined : (e) => setGroupTypeMenuAnchor(e.currentTarget)}
                                                            size="small"
                                                            disabled={isReadOnly}
                                                            sx={{
                                                                fontFamily: 'monospace',
                                                                fontSize: '11px',
                                                                minWidth: 'auto',
                                                                px: 1,
                                                                py: 0.25,
                                                                textTransform: 'lowercase',
                                                                fontWeight: 'bold',
                                                                color: ConfigurationDataColors.Instance.mutedTextColor,
                                                                border: `1px solid ${ConfigurationDataColors.Instance.mutedTextColor}`,
                                                                backgroundColor: 'transparent',
                                                                '&:hover': {
                                                                    backgroundColor: `${colors.secondaryBorderColor}20`,
                                                                    borderColor: ConfigurationDataColors.Instance.mutedTextColor
                                                                }
                                                            }}
                                                        >
                                                            {conditionGroup.groupType.toLowerCase()}
                                                        </Button>
                                                    )}
                                                </Box>
                                            );
                                        }

                                        // Render nested groups, each on its own row with combiner
                                        nestedGroups.forEach((group, idx) => {
                                            const originalIndex = conditionGroup.conditions.indexOf(group);
                                            const isLastGroup = idx === nestedGroups.length - 1;

                                            rows.push(
                                                <Box key={originalIndex} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                    <Box
                                                        onMouseEnter={(e) => {
                                                            if (!isReadOnly) {
                                                                const rect = e.currentTarget.getBoundingClientRect();
                                                                TooltipManager.Instance.showTooltip(
                                                                    <Box sx={{
                                                                        display: 'flex',
                                                                        flexDirection: 'column',
                                                                        minWidth: 150,
                                                                        bgcolor: 'background.paper',
                                                                        borderRadius: 1,
                                                                        boxShadow: 2,
                                                                        border: `1px solid ${colors.borderColor}`
                                                                    }}>
                                                                        <MenuItem
                                                                            onClick={() => {
                                                                                handleAddCondition('single');
                                                                                TooltipManager.Instance.hideTooltip();
                                                                            }}
                                                                            sx={{
                                                                                py: 1,
                                                                                px: 2,
                                                                                fontSize: '14px',
                                                                                '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                                                            }}
                                                                        >
                                                                            Add Data Element
                                                                        </MenuItem>
                                                                        <MenuItem
                                                                            onClick={() => {
                                                                                handleAddCondition('group');
                                                                                TooltipManager.Instance.hideTooltip();
                                                                            }}
                                                                            sx={{
                                                                                py: 1,
                                                                                px: 2,
                                                                                fontSize: '14px',
                                                                                '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                                                            }}
                                                                        >
                                                                            Add Group
                                                                        </MenuItem>
                                                                        <MenuItem
                                                                            onClick={() => {
                                                                                handleRemoveCondition(group);
                                                                                TooltipManager.Instance.hideTooltip();
                                                                            }}
                                                                            sx={{
                                                                                py: 1,
                                                                                px: 2,
                                                                                fontSize: '14px',
                                                                                color: 'error.main',
                                                                                '&:hover': {
                                                                                    backgroundColor: 'error.main',
                                                                                    color: colors.lightTextColor
                                                                                }
                                                                            }}
                                                                        >
                                                                            Delete Group
                                                                        </MenuItem>
                                                                    </Box>,
                                                                    { top: rect.top, left: rect.right + 5 }
                                                                );
                                                            }
                                                        }}
                                                        onMouseLeave={() => {
                                                            if (!isReadOnly) {
                                                                TooltipManager.Instance.hideTooltipWithDelay(300);
                                                            }
                                                        }}
                                                        sx={{
                                                            ml: 2,
                                                            '&:hover': {
                                                                backgroundColor: `${colors.primaryColor}10`,
                                                                borderRadius: 1,
                                                                px: 0.5
                                                            }
                                                        }}
                                                    >
                                                        <ConditionGroupEditor
                                                            conditionGroup={group}
                                                            onChanged={handleConditionChanged}
                                                            depth={depth + 1}
                                                            isRoot={false}
                                                            renderMode={renderMode}
                                                            targetProgramType={targetProgramType}
                                                        />
                                                    </Box>
                                                    {!isLastGroup && (
                                                        <Button
                                                            onClick={(e) => setGroupTypeMenuAnchor(e.currentTarget)}
                                                            size="small"
                                                            sx={{
                                                                fontFamily: 'monospace',
                                                                fontSize: '11px',
                                                                minWidth: 'auto',
                                                                px: 1,
                                                                py: 0.25,
                                                                textTransform: 'lowercase',
                                                                fontWeight: 'bold',
                                                                color: ConfigurationDataColors.Instance.mutedTextColor,
                                                                border: `1px solid ${ConfigurationDataColors.Instance.mutedTextColor}`,
                                                                backgroundColor: 'transparent',
                                                                '&:hover': {
                                                                    backgroundColor: `${colors.secondaryBorderColor}20`,
                                                                    borderColor: ConfigurationDataColors.Instance.mutedTextColor
                                                                }
                                                            }}
                                                        >
                                                            {conditionGroup.groupType.toLowerCase()}
                                                        </Button>
                                                    )}
                                                </Box>
                                            );
                                        });

                                        return rows;
                                    })()
                                )}
                            </Box>
                            <Box sx={{
                                fontFamily: 'monospace',
                                fontSize: '24px',
                                ml: 0.5,
                                width: '10px',
                                borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                display: 'flex',
                                flexDirection: 'column',
                                alignItems: 'center',
                                justifyContent: 'center'
                            }}></Box>
                        </Box>
                    );
                }}
            />
            <Menu
                anchorEl={groupTypeMenuAnchor}
                open={Boolean(groupTypeMenuAnchor)}
                onClose={() => setGroupTypeMenuAnchor(null)}
                anchorOrigin={{
                    vertical: 'bottom',
                    horizontal: 'left',
                }}
                transformOrigin={{
                    vertical: 'top',
                    horizontal: 'left',
                }}
            >
                <MenuItem
                    onClick={() => {
                        conditionGroup.groupType = GroupType.And;
                        setGroupTypeMenuAnchor(null);
                        onChanged?.();
                    }}
                >
                    and
                </MenuItem>
                <MenuItem
                    onClick={() => {
                        conditionGroup.groupType = GroupType.Or;
                        setGroupTypeMenuAnchor(null);
                        onChanged?.();
                    }}
                >
                    or
                </MenuItem>
                <MenuItem
                    onClick={() => {
                        conditionGroup.groupType = GroupType.Xor;
                        setGroupTypeMenuAnchor(null);
                        onChanged?.();
                    }}
                >
                    xor
                </MenuItem>
            </Menu>
            <Menu
                anchorEl={addMenuAnchor}
                open={Boolean(addMenuAnchor)}
                onClose={() => {
                    setAddMenuAnchor(null);
                }}
                anchorOrigin={{
                    vertical: 'bottom',
                    horizontal: 'right',
                }}
                transformOrigin={{
                    vertical: 'top',
                    horizontal: 'right',
                }}
            >
                <MenuItem onClick={() => handleAddCondition('single')}>
                    Single Condition
                </MenuItem>
                <MenuItem onClick={() => handleAddCondition('group')}>
                    Condition Group
                </MenuItem>
            </Menu>
        </>
    );
}

