import { ConfigurationState, JogIncrementSpeed } from '../data/ConfigurationState';
import { IOStateData } from '../data/IOStateData';
import { MessageEvent, OutputStateChangedEvent } from '../data/SignalR/SignalREventTypes';
import { LogCategory, Logger } from './Logger';
import { SignalRManager } from './SignalRManager';

/**
 * SignalRIOUpdater - Listens for I/O status messages and updates IOStateData
 * Handles messages like:
 * - "S198 Output 7 On" 
 * - "S134 Input 7 Closed"
 * - "S135 Input 7 Open"
 */
export class SignalRIOUpdater {
    private static _instance: SignalRIOUpdater;
    private _isListening: boolean = false;

    private constructor() {
        // Private constructor for singleton pattern
    }

    /**
     * Get the singleton instance
     */
    public static get Instance(): SignalRIOUpdater {
        if (!SignalRIOUpdater._instance) {
            SignalRIOUpdater._instance = new SignalRIOUpdater();
        }
        return SignalRIOUpdater._instance;
    }

    /**
     * Start listening for I/O status messages
     */
    public startListening(): void {
        if (this._isListening) {
            return;
        }

        SignalRManager.Instance.addEventListener('MessageEvent', this._handleMessageEvent);
        SignalRManager.Instance.addEventListener('OutputStateChanged', this._handleOutputStateChanged);
        this._isListening = true;

        Logger.Instance.log(LogCategory.DataManager, 'SignalRIOUpdater started listening for I/O status messages');
    }

    /**
     * Stop listening for I/O status messages
     */
    public stopListening(): void {
        if (!this._isListening) {
            return;
        }

        SignalRManager.Instance.removeEventListener('MessageEvent', this._handleMessageEvent);
        SignalRManager.Instance.removeEventListener('OutputStateChanged', this._handleOutputStateChanged);
        this._isListening = false;

        Logger.Instance.log(LogCategory.DataManager, 'SignalRIOUpdater stopped listening for I/O status messages');
    }

    /**
     * Handle MessageEvent from SignalR and parse I/O status messages
     */
    private _handleMessageEvent = (event: MessageEvent): void => {
        try {
            const message = event.data.message;
            if (!message) {
                return;
            }


            // Check for reset required message (error code 490)
            // Also check eventCode from the event data if available
            const eventCode = event.data.eventCode;
            if (eventCode === 490 || message.match(/^(S)?490\b/)) {
                Logger.Instance.logError(
                    LogCategory.System,
                    `⚠️ RESET REQUIRED (Code 490): Machine requires reset before operations can continue: "${message}"`
                );
                ConfigurationState.Instance.requiresReset = true;
            }

            // Handle jog configuration messages from PLC (Display: ASYNC INFO)
            this._handleJogMessage(message);

            // Parse I/O status messages
            const ioUpdate = this._parseIOStatusMessage(message);
            if (ioUpdate) {
                // Update I/O state immediately
                this._updateIOState(ioUpdate);
            }
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Error handling I/O message event:', error);
        }
    };

    /**
     * Handle OutputStateChanged event from SignalR
     */
    private _handleOutputStateChanged = (event: OutputStateChangedEvent): void => {
        try {
            const { outputNumber, state, forceState, isForced } = event.data;


            if (!IOStateData.Instance.isInitialized) {
                return;
            }

            // Update output state and forced status
            IOStateData.Instance.updateOutputForcedState(outputNumber, forceState, state);

            const output = IOStateData.Instance.getOutputByNumber(outputNumber);
            const outputName = output?.name || output?.centroidName;
            const displayName = outputName ? `${outputName}` : `Output ${outputNumber}`;

            Logger.Instance.log(
                LogCategory.DataManager,
                `${displayName}: ${state ? 'ON' : 'OFF'} (${isForced ? `FORCED - ${forceState}` : 'Program Control'})`
            );
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Error handling OutputStateChanged event:', error);
        }
    };

    /**
     * Handle jog configuration messages sent by PLC via Display: ASYNC INFO predicates.
     * Updates ConfigurationState with the appropriate jog settings.
     * Checks X100 before X10 before X1 to avoid substring match issues.
     */
    private _handleJogMessage(message: string): void {
        if (message.includes('Jog Speed: X100')) {
            ConfigurationState.Instance.jogIncrementSpeed = JogIncrementSpeed.X100;
        } else if (message.includes('Jog Speed: X10')) {
            ConfigurationState.Instance.jogIncrementSpeed = JogIncrementSpeed.X10;
        } else if (message.includes('Jog Speed: X1')) {
            ConfigurationState.Instance.jogIncrementSpeed = JogIncrementSpeed.X1;
        } else if (message.includes('Jog: Incremental')) {
            ConfigurationState.Instance.jogContinuousMode = false;
        } else if (message.includes('Jog: Continuous')) {
            ConfigurationState.Instance.jogContinuousMode = true;
        } else if (message.includes('Jog: Fast')) {
            ConfigurationState.Instance.jogFastMode = true;
        } else if (message.includes('Jog: Slow')) {
            ConfigurationState.Instance.jogFastMode = false;
        }
    }

    /**
     * Parse I/O status messages into structured data
     * @param message The raw message string
     * Format: "9009 [I7+] Emergency Stop is ON" or "9010 [O3-] Coolant is OFF"
     * @returns Parsed I/O update or null if not an I/O message
     */
    private _parseIOStatusMessage(message: string): IOStatusUpdate | null {
        // Format: 9009 [I7+] Name is ON  OR  9010 [O3-] Name is OFF
        // + indicates rising edge (ON), - indicates falling edge (OFF)
        // Allow optional message code prefix before the bracket
        const newFormatInput = /(?:^\d+\s+)?\[I(\d+)(\+|-)\]/;
        const newFormatOutput = /(?:^\d+\s+)?\[O(\d+)(\+|-)\]/;

        let match = message.match(newFormatInput);
        if (match) {
            const number = parseInt(match[1], 10);
            const isActive = match[2] === '+';

            return {
                type: 'input',
                number,
                isActive,
                originalMessage: message
            };
        }

        match = message.match(newFormatOutput);
        if (match) {
            const number = parseInt(match[1], 10);
            const isActive = match[2] === '+';

            return {
                type: 'output',
                number,
                isActive,
                originalMessage: message
            };
        }

        return null;
    }

    /**
     * Update IOStateData with the parsed I/O status
     * Messages from backend are already properly formatted with name and state
     */
    private _updateIOState(update: IOStatusUpdate): void {
        if (!IOStateData.Instance.isInitialized) {
            return;
        }

        try {
            if (update.type === 'input') {
                IOStateData.Instance.updateInputState(update.number, update.isActive);
            } else if (update.type === 'output') {
                IOStateData.Instance.updateOutputState(update.number, update.isActive);
            }
        } catch (error) {
            Logger.Instance.logError(
                LogCategory.DataManager,
                `Error updating ${update.type} ${update.number} state:`,
                error
            );
        }
    }

    /**
     * Get current listening status
     */
    public get isListening(): boolean {
        return this._isListening;
    }
}

/**
 * Parsed I/O status update
 */
interface IOStatusUpdate {
    type: 'input' | 'output';
    number: number;
    isActive: boolean;
    originalMessage: string;
}