import {
    Box,
    Button,
    Link,
    Menu,
    MenuItem,
    TextField,
    Typography
} from '@mui/material';
import { useEffect, useRef, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { TooltipManager } from '../../../utils/TooltipManager';
import { PLCRenderMode } from '../data/IPLCElement';
import { PLCProgramType } from '../data/PLCUtilities';
import { BasePLCPredicate } from '../predicates/BasePLCPredicate';
import { PredicateType, PredicateUtilities } from '../predicates/PredicateUtilities';
import { TimerStatement } from '../statements/TimerStatement';
import { ConditionGroupEditor } from './ConditionGroupEditor';
import { TimerStructureDialog } from './TimerStructureDialog';

interface TimerStatementEditorProps {
    logicStatement: TimerStatement;
    onChanged?: () => void;
    renderMode?: PLCRenderMode;
    targetProgramType: PLCProgramType;
}

/**
 * TimerStatementEditor - UI component for editing timer statements
 * Code-like minimal UI: if ( [conditions] ) then { [actions] }
 */
export function TimerStatementEditor(props: TimerStatementEditorProps) {
    const { logicStatement, onChanged, renderMode = PLCRenderMode.Edit, targetProgramType } = props;
    const [addPredicateMenuAnchor, setAddPredicateMenuAnchor] = useState<null | HTMLElement>(null);
    const [addStartPredicateMenuAnchor, setAddStartPredicateMenuAnchor] = useState<null | HTMLElement>(null);
    const [structureDialogOpen, setStructureDialogOpen] = useState(false);
    const anchorRef = useRef<HTMLElement | null>(null);
    const menuCloseTimeoutRef = useRef<NodeJS.Timeout | null>(null);
    const colors = ConfigurationDataColors.Instance;

    const isDisabled = renderMode === PLCRenderMode.Disabled || logicStatement.isDisabled(renderMode, targetProgramType);
    const isEditable = renderMode === PLCRenderMode.Edit;

    // Cleanup timeout on unmount
    useEffect(() => {
        return () => {
            if (menuCloseTimeoutRef.current) {
                clearTimeout(menuCloseTimeoutRef.current);
            }
        };
    }, []);

    const scheduleMenuClose = () => {
        // Clear any existing timeout
        if (menuCloseTimeoutRef.current) {
            clearTimeout(menuCloseTimeoutRef.current);
        }
        // Schedule close after delay
        menuCloseTimeoutRef.current = setTimeout(() => {
            setAddPredicateMenuAnchor(null);
        }, 300);
    };

    const cancelMenuClose = () => {
        if (menuCloseTimeoutRef.current) {
            clearTimeout(menuCloseTimeoutRef.current);
            menuCloseTimeoutRef.current = null;
        }
    };

    const handleConditionChanged = () => {
        onChanged?.();
    };

    const handleTimerLengthChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const value = parseInt(event.target.value, 10);
        if (!isNaN(value) && value >= 1) {
            logicStatement.timerLengthMs = value;
            onChanged?.();
        }
    };

    const handleAddPredicate = (predicateType: PredicateType) => {
        // Create predicate based on type
        let newPredicate: BasePLCPredicate | null = null;

        // Get predicate type info to determine if it can be created
        const predicateTypes = PredicateUtilities.getPredicateTypes();
        const typeInfo = predicateTypes.find(pt => pt.type === predicateType);

        if (typeInfo) {
            // Use PredicateUtilities factory to create the predicate
            try {
                newPredicate = PredicateUtilities.createPredicate(predicateType);
            } catch (error) {
                console.warn(`Predicate type ${predicateType} not yet implemented for creation:`, error);
            }
        }

        if (newPredicate) {
            logicStatement.addTimerCompletePredicate(newPredicate);
            onChanged?.();
        }

        setAddPredicateMenuAnchor(null);
    };

    const handleRemovePredicate = (predicate: BasePLCPredicate) => {
        logicStatement.removeTimerCompletePredicate(predicate);
        onChanged?.();
    };

    const handleAddStartPredicate = (predicateType: PredicateType) => {
        let newPredicate: BasePLCPredicate | null = null;

        const predicateTypes = PredicateUtilities.getPredicateTypes();
        const typeInfo = predicateTypes.find(pt => pt.type === predicateType);

        if (typeInfo) {
            try {
                newPredicate = PredicateUtilities.createPredicate(predicateType);
            } catch (error) {
                console.warn(`Predicate type ${predicateType} not yet implemented for creation:`, error);
            }
        }

        if (newPredicate) {
            logicStatement.addTimerStartPredicate(newPredicate);
            onChanged?.();
        }

        setAddStartPredicateMenuAnchor(null);
    };

    const handleRemoveStartPredicate = (predicate: BasePLCPredicate) => {
        logicStatement.removeTimerStartPredicate(predicate);
        onChanged?.();
    };

    // Get available predicate types for the menu
    const availablePredicateTypes = PredicateUtilities.getPredicateTypes();

    // Check if trigger condition is disabled (for strikethrough styling)
    const isTriggerDisabled = logicStatement.conditionGroup?.isDisabled(PLCRenderMode.Edit, targetProgramType) ?? false;

    // Check if cancel condition is disabled
    const isCancelDisabled = logicStatement.cancelConditionGroup?.isDisabled(PLCRenderMode.Edit, targetProgramType) ?? false;

    // Helper to check if all predicates in an array are disabled
    const areAllPredicatesDisabled = (predicates: BasePLCPredicate[]): boolean => {
        if (predicates.length === 0) return false;
        return predicates.every(p => p.isDisabled(PLCRenderMode.Edit, targetProgramType));
    };

    // Style for disabled mode - strikethrough text and reduced opacity
    // Use textDecorationLine which is harder to override than textDecoration
    const containerStyle = isDisabled ? {
        opacity: 0.6,
        textDecorationLine: 'line-through',
        '& *, & *::before, & *::after': {
            textDecorationLine: 'line-through !important',
            textDecoration: 'line-through !important'
        }
    } : {};

    return (
        <ObserveState
            key="timer-statement-editor"
            listenTo={logicStatement}
            properties={['conditionGroup', 'timerStartPredicates', 'timerCompletePredicates', 'timerLengthMs', 'cancelEnabled', 'cancelConditionGroup', 'hideTimerStartActions']}
            control={() => (
                <Box sx={{ fontFamily: 'monospace', fontSize: '14px', py: 1, ...containerStyle }}>
                    {/* when [condition] start timer for [milliseconds] */}
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Typography sx={{
                            color: colors.primaryColor,
                            fontWeight: 'bold',
                            fontFamily: 'monospace',
                            textDecoration: isTriggerDisabled ? 'line-through' : 'none'
                        }}>
                            when
                        </Typography>
                        <ConditionGroupEditor
                            conditionGroup={logicStatement.conditionGroup}
                            onChanged={handleConditionChanged}
                            isRoot={false}
                            renderMode={isTriggerDisabled ? PLCRenderMode.Disabled : renderMode}
                            targetProgramType={targetProgramType}
                        />
                        <Typography sx={{
                            color: colors.primaryColor,
                            fontWeight: 'bold',
                            fontFamily: 'monospace',
                            textDecoration: isTriggerDisabled ? 'line-through' : 'none'
                        }}>
                            for
                        </Typography>
                        <TextField
                            type="number"
                            value={logicStatement.timerLengthMs}
                            onChange={handleTimerLengthChange}
                            disabled={!isEditable || isTriggerDisabled}
                            inputProps={{
                                min: 1,
                                style: {
                                    fontFamily: 'monospace',
                                    fontSize: '14px',
                                    padding: '4px 8px',
                                    textAlign: 'right',
                                    width: '80px'
                                }
                            }}
                            sx={{
                                '& .MuiOutlinedInput-root': {
                                    '& fieldset': {
                                        borderColor: colors.borderColor,
                                    },
                                },
                            }}
                        />
                        <Typography sx={{
                            color: colors.primaryColor,
                            fontWeight: 'bold',
                            fontFamily: 'monospace',
                            textDecoration: isTriggerDisabled ? 'line-through' : 'none'
                        }}>
                            ms
                        </Typography>
                        {isEditable && (
                            <Link
                                component="button"
                                onClick={() => setStructureDialogOpen(true)}
                                sx={{
                                    color: colors.primaryColor,
                                    ml: 1,
                                    textDecoration: 'none',
                                    fontFamily: 'monospace',
                                    fontSize: '14px',
                                    cursor: 'pointer',
                                    '&:hover': {
                                        textDecoration: 'underline'
                                    }
                                }}
                                title="Configure timer structure"
                            >
                                edit branches
                            </Link>
                        )}
                    </Box>

                    {/* OnTimerStart actions - optional */}
                    {!logicStatement.hideTimerStartActions && (
                        <Box sx={{ display: 'flex', alignItems: 'stretch', gap: 1, mt: 1, ml: 2 }}>
                            <Typography sx={{
                                color: colors.primaryColor,
                                fontWeight: 'bold',
                                fontFamily: 'monospace',
                                mt: 0.5,
                                width: '200px',
                                textDecoration: (isTriggerDisabled || areAllPredicatesDisabled(logicStatement.timerStartPredicates)) ? 'line-through' : 'none'
                            }}>
                                OnTimerStart
                            </Typography>
                            <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                                <Box sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '24px',
                                    mr: 0.5,
                                    width: '10px',
                                    borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderBottom: `1.5px solid ${colors.secondaryBorderColor}`
                                }}></Box>
                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 0.5 }}>
                                    {logicStatement.timerStartPredicates.length === 0 ? (
                                        isEditable && (
                                            <Button
                                                size="small"
                                                onClick={(e) => setAddStartPredicateMenuAnchor(e.currentTarget)}
                                                sx={{
                                                    color: colors.mutedTextColor,
                                                    fontStyle: 'italic',
                                                    fontSize: '14px',
                                                    textTransform: 'none',
                                                    minHeight: '28px',
                                                    '&:hover': {
                                                        color: colors.primaryColor,
                                                        backgroundColor: `${colors.primaryColor}10`
                                                    }
                                                }}
                                            >
                                                click to add action
                                            </Button>
                                        )
                                    ) : (
                                        <Box>
                                            {logicStatement.timerStartPredicates.map((predicate: BasePLCPredicate, index: number) => (
                                                <Box
                                                    key={index}
                                                    onMouseDown={(e) => {
                                                        const target = e.target as HTMLElement;
                                                        if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.closest('button')) {
                                                            TooltipManager.Instance.hideTooltip();
                                                        }
                                                    }}
                                                    onMouseEnter={(e) => {
                                                        if (isEditable) {
                                                            anchorRef.current = e.currentTarget;
                                                            const rect = e.currentTarget.getBoundingClientRect();
                                                            const predicateTypeName = predicate.constructor.name.replace('Predicate', '');
                                                            TooltipManager.Instance.showTooltip(
                                                                <Box sx={{
                                                                    display: 'flex',
                                                                    flexDirection: 'column',
                                                                    minWidth: 150,
                                                                    bgcolor: 'background.paper',
                                                                    borderRadius: 1,
                                                                    boxShadow: 2,
                                                                    border: `1px solid ${colors.borderColor}`
                                                                }}>
                                                                    <MenuItem
                                                                        onClick={() => {
                                                                            if (anchorRef.current) {
                                                                                setAddStartPredicateMenuAnchor(anchorRef.current);
                                                                                TooltipManager.Instance.hideTooltip();
                                                                            }
                                                                        }}
                                                                        sx={{
                                                                            py: 1,
                                                                            px: 2,
                                                                            fontSize: '14px',
                                                                            '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                                                        }}
                                                                    >
                                                                        Add Action
                                                                    </MenuItem>
                                                                    <MenuItem
                                                                        onClick={() => {
                                                                            handleRemoveStartPredicate(predicate);
                                                                            TooltipManager.Instance.hideTooltip();
                                                                        }}
                                                                        sx={{
                                                                            py: 1,
                                                                            px: 2,
                                                                            fontSize: '14px',
                                                                            color: 'error.main',
                                                                            '&:hover': {
                                                                                backgroundColor: 'error.main',
                                                                                color: colors.lightTextColor
                                                                            }
                                                                        }}
                                                                    >
                                                                        Delete {predicateTypeName}
                                                                    </MenuItem>
                                                                </Box>,
                                                                { top: rect.top, left: rect.right + 5 }
                                                            );
                                                        }
                                                    }}
                                                    onMouseLeave={() => {
                                                        if (isEditable) {
                                                            TooltipManager.Instance.hideTooltipWithDelay(300);
                                                        }
                                                    }}
                                                    sx={{
                                                        mb: 0.5,
                                                        '&:hover': isEditable ? {
                                                            backgroundColor: `${colors.primaryColor}10`,
                                                            borderRadius: 1
                                                        } : {}
                                                    }}
                                                >
                                                    {predicate.render(isTriggerDisabled ? PLCRenderMode.Disabled : renderMode, targetProgramType)}
                                                </Box>
                                            ))}
                                        </Box>
                                    )}
                                </Box>
                                <Box sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '24px',
                                    ml: 0.5,
                                    width: '10px',
                                    borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                    borderBottom: `1.5px solid ${colors.secondaryBorderColor}`
                                }}></Box>
                            </Box>
                        </Box>
                    )}

                    {/* OnTimerComplete actions */}
                    <Box sx={{ display: 'flex', alignItems: 'stretch', gap: 1, mt: 1, ml: 2 }}>
                        <Typography sx={{
                            color: colors.primaryColor,
                            fontWeight: 'bold',
                            fontFamily: 'monospace',
                            mt: 0.5,
                            width: '200px',
                            textDecoration: (isTriggerDisabled || areAllPredicatesDisabled(logicStatement.timerCompletePredicates)) ? 'line-through' : 'none'
                        }}>
                            OnTimerComplete
                        </Typography>
                        <Box sx={{ display: 'inline-flex', alignItems: 'stretch', borderTop: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}`, borderBottom: `0.75px dashed ${ConfigurationDataColors.Instance.borderColor}` }}>
                            <Box sx={{
                                fontFamily: 'monospace',
                                fontSize: '24px',
                                mr: 0.5,
                                width: '10px',
                                borderLeft: `1.5px solid ${colors.secondaryBorderColor}`,
                                borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                display: 'flex',
                                flexDirection: 'column',
                                alignItems: 'center',
                                justifyContent: 'center'
                            }}></Box>
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, py: 0.5 }}
                            >
                                {logicStatement.timerCompletePredicates.length === 0 ? (
                                    isEditable && (
                                        <Button
                                            size="small"
                                            onClick={(e) => setAddPredicateMenuAnchor(e.currentTarget)}
                                            sx={{
                                                color: colors.mutedTextColor,
                                                fontStyle: 'italic',
                                                fontSize: '14px',
                                                textTransform: 'none',
                                                minHeight: '28px',
                                                '&:hover': {
                                                    color: colors.primaryColor,
                                                    backgroundColor: `${colors.primaryColor}10`
                                                }
                                            }}
                                        >
                                            click to add action
                                        </Button>
                                    )
                                ) : (
                                    <Box>
                                        {logicStatement.timerCompletePredicates.map((predicate: BasePLCPredicate, index: number) => (
                                            <Box
                                                key={index}
                                                onMouseDown={(e) => {
                                                    // Hide tooltip when clicking on interactive elements
                                                    const target = e.target as HTMLElement;
                                                    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.closest('button')) {
                                                        TooltipManager.Instance.hideTooltip();
                                                    }
                                                }}
                                                onMouseEnter={(e) => {
                                                    if (isEditable) {
                                                        anchorRef.current = e.currentTarget;
                                                        const rect = e.currentTarget.getBoundingClientRect();
                                                        const predicateTypeName = predicate.constructor.name.replace('Predicate', '');
                                                        TooltipManager.Instance.showTooltip(
                                                            <Box sx={{
                                                                display: 'flex',
                                                                flexDirection: 'column',
                                                                minWidth: 150,
                                                                bgcolor: 'background.paper',
                                                                borderRadius: 1,
                                                                boxShadow: 2,
                                                                border: `1px solid ${colors.borderColor}`
                                                            }}>
                                                                <MenuItem
                                                                    onClick={() => {
                                                                        if (anchorRef.current) {
                                                                            setAddPredicateMenuAnchor(anchorRef.current);
                                                                            TooltipManager.Instance.hideTooltip();
                                                                        }
                                                                    }}
                                                                    sx={{
                                                                        py: 1,
                                                                        px: 2,
                                                                        fontSize: '14px',
                                                                        '&:hover': { backgroundColor: `${colors.primaryColor}20` }
                                                                    }}
                                                                >
                                                                    Add Action
                                                                </MenuItem>
                                                                <MenuItem
                                                                    onClick={() => {
                                                                        handleRemovePredicate(predicate);
                                                                        TooltipManager.Instance.hideTooltip();
                                                                    }}
                                                                    sx={{
                                                                        py: 1,
                                                                        px: 2,
                                                                        fontSize: '14px',
                                                                        color: 'error.main',
                                                                        '&:hover': {
                                                                            backgroundColor: 'error.main',
                                                                            color: colors.lightTextColor
                                                                        }
                                                                    }}
                                                                >
                                                                    Delete {predicateTypeName}
                                                                </MenuItem>
                                                            </Box>,
                                                            { top: rect.top, left: rect.right + 5 }
                                                        );
                                                    }
                                                }}
                                                onMouseLeave={() => {
                                                    if (isEditable) {
                                                        TooltipManager.Instance.hideTooltipWithDelay(300);
                                                    }
                                                }}
                                                sx={{
                                                    mb: 0.5,
                                                    '&:hover': isEditable ? {
                                                        backgroundColor: `${colors.primaryColor}10`,
                                                        borderRadius: 1
                                                    } : {}
                                                }}
                                            >
                                                {predicate.render(isTriggerDisabled ? PLCRenderMode.Disabled : renderMode, targetProgramType)}
                                            </Box>
                                        ))}
                                    </Box>
                                )}
                            </Box>
                            <Box sx={{
                                fontFamily: 'monospace',
                                fontSize: '24px',
                                ml: 0.5,
                                width: '10px',
                                borderRight: `1.5px solid ${colors.secondaryBorderColor}`,
                                borderTop: `1.5px solid ${colors.secondaryBorderColor}`,
                                borderBottom: `1.5px solid ${colors.secondaryBorderColor}`,
                                display: 'flex',
                                flexDirection: 'column',
                                alignItems: 'center',
                                justifyContent: 'center'
                            }}></Box>
                        </Box>
                    </Box>

                    {/* unless [cancel condition] - configured in structure dialog */}
                    {logicStatement.cancelEnabled && logicStatement.cancelConditionGroup && (
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1, ml: 2 }}>
                            <Typography sx={{
                                color: colors.primaryColor,
                                fontWeight: 'bold',
                                fontFamily: 'monospace',
                                textDecoration: isCancelDisabled ? 'line-through' : 'none'
                            }}>
                                unless
                            </Typography>
                            <ConditionGroupEditor
                                conditionGroup={logicStatement.cancelConditionGroup}
                                onChanged={handleConditionChanged}
                                isRoot={false}
                                renderMode={isCancelDisabled ? PLCRenderMode.Disabled : renderMode}
                                targetProgramType={targetProgramType}
                            />
                        </Box>
                    )}

                    {/* Add Action Menu */}
                    <Menu
                        anchorEl={addPredicateMenuAnchor}
                        open={Boolean(addPredicateMenuAnchor)}
                        onClose={() => {
                            setAddPredicateMenuAnchor(null);
                        }}
                        slotProps={{
                            paper: {
                                onMouseEnter: cancelMenuClose,
                                onMouseLeave: scheduleMenuClose
                            }
                        }}
                        anchorOrigin={{
                            vertical: 'bottom',
                            horizontal: 'left',
                        }}
                        transformOrigin={{
                            vertical: 'top',
                            horizontal: 'left',
                        }}
                    >
                        {availablePredicateTypes.map((typeInfo) => (
                            <MenuItem
                                key={typeInfo.type}
                                onClick={() => handleAddPredicate(typeInfo.type)}
                            >
                                <Box>
                                    <Typography variant="body2">{typeInfo.displayName}</Typography>
                                    {typeInfo.description && (
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                            {typeInfo.description}
                                        </Typography>
                                    )}
                                </Box>
                            </MenuItem>
                        ))}
                    </Menu>

                    {/* Add OnTimerStart Action Menu */}
                    <Menu
                        anchorEl={addStartPredicateMenuAnchor}
                        open={Boolean(addStartPredicateMenuAnchor)}
                        onClose={() => {
                            setAddStartPredicateMenuAnchor(null);
                        }}
                        slotProps={{
                            paper: {
                                onMouseEnter: cancelMenuClose,
                                onMouseLeave: scheduleMenuClose
                            }
                        }}
                        anchorOrigin={{
                            vertical: 'bottom',
                            horizontal: 'left',
                        }}
                        transformOrigin={{
                            vertical: 'top',
                            horizontal: 'left',
                        }}
                    >
                        {availablePredicateTypes.map((typeInfo) => (
                            <MenuItem
                                key={typeInfo.type}
                                onClick={() => handleAddStartPredicate(typeInfo.type)}
                            >
                                <Box>
                                    <Typography variant="body2">{typeInfo.displayName}</Typography>
                                    {typeInfo.description && (
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                            {typeInfo.description}
                                        </Typography>
                                    )}
                                </Box>
                            </MenuItem>
                        ))}
                    </Menu>

                    {/* Timer Structure Dialog */}
                    <TimerStructureDialog
                        timerStatement={logicStatement}
                        open={structureDialogOpen}
                        onClose={() => setStructureDialogOpen(false)}
                    />
                </Box>
            )}
        />
    );
}
