import { CheckCircle as SuccessIcon } from '@mui/icons-material';
import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { TouchOffTarget } from '../../../../machine/ICNCSystem';
import { CoordinateOperations } from '../../../../utils/CoordinateOperations';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { JogControls } from '../../../Common/JogControls';
import { WizardStep } from '../../../Wizard/WizardStep';
import { TouchOffWizard } from '../TouchOffWizard';
import { OffsetType } from './SelectOffsetTypeStep';

/**
 * Step for manual touch-off with jog controls
 */
export class ManualTouchOffStep extends WizardStep {

    getTitle(): string {
        const wizard = this.wizard as TouchOffWizard;
        const targetName = wizard.state.target === TouchOffTarget.WorkZero
            ? 'Work Zero'
            : wizard.state.target === TouchOffTarget.SpoilBoard
                ? 'Spoilboard'
                : 'Machine Bed';
        return `Manual Touch Off - ${targetName}`;
    }

    nextStep(): WizardStep | null {
        return null; // Last step
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="manual-touchoff-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <ManualTouchOffStepComponent step={this} />}
            />
        );
    }
}

interface ManualTouchOffStepComponentProps {
    step: ManualTouchOffStep;
}

function ManualTouchOffStepComponent({ step }: ManualTouchOffStepComponentProps) {
    const wizard = step.wizard as TouchOffWizard;
    const colors = ConfigurationDataColors.Instance;
    const [isProcessing, setIsProcessing] = React.useState(false);

    const target = wizard.state.target === TouchOffTarget.WorkZero
        ? 'work zero'
        : wizard.state.target === TouchOffTarget.SpoilBoard
            ? 'spoilboard'
            : 'machine bed';
    const targetName = wizard.state.target === TouchOffTarget.WorkZero
        ? 'Work Zero'
        : wizard.state.target === TouchOffTarget.SpoilBoard
            ? 'Spoilboard'
            : 'Machine Bed';

    const handleSetZ = async () => {
        try {
            setIsProcessing(true);

            // Get current machine Z position
            const currentMachineZ = ConfigurationState.Instance.currentMachinePoint.z;

            // Determine what to set based on target and offsetType
            if (wizard.state.target === TouchOffTarget.MachineBed) {
                CoordinateOperations.setMachineBedReferenceZ(currentMachineZ);
            } else if (wizard.state.target === TouchOffTarget.WorkZero) {
                // Material - set material height and work zero Z
                CoordinateOperations.setMaterialTopReferenceZ(currentMachineZ);
            } else if (wizard.state.offsetType === OffsetType.SpoilboardReference) {
                // Spoilboard reference only
                CoordinateOperations.setSpoilboardReferenceZ(currentMachineZ, false);
            } else {
                // Spoilboard reference AND work zero Z
                CoordinateOperations.setSpoilboardReferenceZ(currentMachineZ, true);
            }


            // Complete wizard successfully
            wizard.completeWizard();
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, `Failed to set ${targetName} Z:`, error);
            UserMessageQueue.Instance.addMessage(`❌ Failed to set ${targetName} Z position`);
        } finally {
            setIsProcessing(false);
        }
    };

    const handleBack = () => {
        wizard.goToPreviousStep();
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', gap: 2, p: 3 }}>
            {/* Header */}
            <Box>
                <Typography variant="h5" gutterBottom sx={{ color: colors.primaryColor, fontWeight: 'bold' }}>
                    Position Tool Touching {targetName}
                </Typography>
            </Box>

            {/* Main content area - side by side layout */}
            <Box sx={{ flex: 1, display: 'flex', gap: 3, minHeight: 0 }}>
                {/* Instructions - left side */}
                <Box sx={{
                    width: '300px',
                    flexShrink: 0,
                    p: 2,
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    borderLeft: `4px solid ${colors.infoColor}`,
                    display: 'flex',
                    flexDirection: 'column'
                }}>
                    <Typography variant="subtitle2" sx={{ color: colors.primaryColor, fontWeight: 'bold', mb: 1 }}>
                        Instructions:
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        1. Use the jog controls to position the tool directly above the {target}
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        2. Slowly jog the Z axis down until the tool lightly touches the {target} surface
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        3. Use a piece of paper to check - it should drag with slight resistance
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                        4. Click "Set Z Position" to save the current Z position as the {target} reference
                    </Typography>
                </Box>

                {/* Jog Controls - right side, centered */}
                <Box sx={{
                    flex: 1,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center'
                }}>
                    <JogControls />
                </Box>
            </Box>

            {/* Bottom buttons */}
            <Box sx={{
                pt: 2,
                borderTop: `1px solid ${colors.borderColor}`,
                display: 'flex',
                justifyContent: 'space-between'
            }}>
                <Button
                    variant="outlined"
                    onClick={handleBack}
                    disabled={isProcessing}
                >
                    Back
                </Button>
                <Button
                    variant="contained"
                    onClick={handleSetZ}
                    disabled={isProcessing}
                    startIcon={<SuccessIcon />}
                    sx={{ backgroundColor: colors.primaryColor }}
                >
                    {isProcessing ? 'Setting Z Position...' : 'Set Z Position'}
                </Button>
            </Box>
        </Box>
    );
}
