import { MachineData } from '../Machine/MachineData';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item to verify machine name and board type are configured
 * This is a basic validation that ensures the machine has essential configuration
 */
export class MachineNameAndBoardChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Machine Name and Board Type',
            'Configure the machine name and control board type'
        );
    }

    /**
     * This item does not require manual confirmation
     */
    public needsManualConfirmation(): boolean {
        return false;
    }

    /**
     * Check if machine name and board type are configured
     */
    public completionCheck(): boolean {
        const machineData = MachineData.Instance;

        // Check if machine name is set and not empty
        const machineName = machineData.machineName;
        const hasMachineName = typeof machineName === 'string' && machineName.trim().length > 0;

        // Check if board type is set and not empty
        const boardType = machineData.boardType;
        const hasBoardType = typeof boardType === 'string' && boardType.trim().length > 0;

        return hasMachineName && hasBoardType;
    }

    /**
     * Create a deep copy of this checklist item
     */
    public clone(): SetupChecklistItem {
        const cloned = new MachineNameAndBoardChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
