import { Tooltip } from '@mui/material';
import React, { useState } from 'react';
import { SystemIcons } from '../../../SystemIcons';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { DataElement } from './DataElement';
import { DataElementDropdown } from './DataElementDropdown';
import { DataElementPickerDialog } from './DataElementPickerDialog';
import { DataElementPickerDialogController } from './DataElementPickerDialogController';
import { DataType } from './Declaration';
import { DeclarationTooltipBuilder } from './DeclarationTooltipBuilder';
import { PLCRenderMode } from './IPLCElement';
import { PLCUtilities } from './PLCUtilities';

interface DataElementButtonProps {
    dataElement: DataElement;
    renderMode?: PLCRenderMode;
    renderAs?: 'button' | 'dropdown' | 'auto';  // 'auto' uses dropdown for Stage/Timer, button for others
    dropdownLabel?: string;
}

/**
 * Function component to render a DataElement as a button with dialog or as a dropdown
 * Uses ObserveState for reactive updates and useState for dialog state
 */
export function DataElementButton({
    dataElement,
    renderMode = PLCRenderMode.Edit,
    renderAs = 'button',
    dropdownLabel
}: DataElementButtonProps) {
    const [dialogOpen, setDialogOpen] = useState(false);
    const [controller, setController] = useState<DataElementPickerDialogController | null>(null);

    // Determine actual render mode based on renderAs and data type
    const actualRenderMode = (): 'button' | 'dropdown' => {
        if (renderAs === 'dropdown') return 'dropdown';
        if (renderAs === 'button') return 'button';

        // Auto mode: use dropdown for Stage and Timer types
        if (dataElement.requiresType === DataType.Stage || dataElement.requiresType === DataType.Timer) {
            return 'dropdown';
        }
        return 'button';
    };

    const handleClick = () => {
        // Don't open dialog in ReadOnly or Disabled modes
        if (renderMode !== PLCRenderMode.Edit) return;

        // Create a new controller instance for the dialog
        const newController = new DataElementPickerDialogController(dataElement);
        setController(newController);
        setDialogOpen(true);
    };

    const handleSelect = (selectedElement: DataElement) => {
        // If it's the same instance (dropdown mode), it's already updated
        // If it's a different instance (dialog mode), copy the properties
        if (selectedElement !== dataElement) {
            dataElement.declarationName = selectedElement.declarationName;
            dataElement.declaration = selectedElement.declaration;
        }

        // Invalidate program cache when picking a declaration
        PLCUtilities.invalidateProgramCache();
    };

    // If rendering as dropdown, use the dropdown component
    if (actualRenderMode() === 'dropdown') {
        return (
            <DataElementDropdown
                dataElement={dataElement}
                onSelect={handleSelect}
                label={dropdownLabel}
                requiresType={dataElement.requiresType}
                disabled={renderMode !== PLCRenderMode.Edit}
                size="small"
                variant="standard"
            />
        );
    }

    // Otherwise render as button with dialog
    return (
        <ObserveState
            key="data-element-button"
            profilerName="DataElementButton-render"
            listenTo={dataElement}
            properties={['declarationName', 'declaration']}
            control={() => {
                const isEmpty = !dataElement.isDefinition && !dataElement.isReference;
                const displayText = dataElement.effectiveName || 'Pick';
                const isDefinition = dataElement.isDefinition; // Has a declaration object

                // Get the full declaration details for tooltip
                const program = dataElement.getPLCProgram();
                const declaration = dataElement.declaration ||
                    (dataElement.declarationName && program ?
                        PLCUtilities.getDeclarationByName(program, dataElement.declarationName) :
                        undefined);

                // Build tooltip content using shared utility class
                const tooltipContent = DeclarationTooltipBuilder.buildTooltip(declaration, program, isEmpty);

                return (
                    <>
                        <Tooltip
                            title={tooltipContent}
                            placement="top"
                            arrow
                            {...DeclarationTooltipBuilder.getTooltipProps()}
                            disableInteractive
                        >
                            <span
                                onClick={handleClick}
                                style={{
                                    fontFamily: 'monospace',
                                    fontSize: '14px',
                                    fontWeight: 400,
                                    textDecoration: 'underline',
                                    textDecorationThickness: '1px',
                                    textUnderlineOffset: '2px',
                                    cursor: 'pointer',
                                    color: isEmpty ? ConfigurationDataColors.Instance.errorColor : ConfigurationDataColors.Instance.primaryColor,
                                    textTransform: 'uppercase',
                                    display: 'inline-block',
                                    minHeight: '28px',
                                    lineHeight: '28px',
                                    padding: '0 4px',
                                    backgroundColor: 'transparent',
                                    transition: 'background-color 0.2s ease',
                                    whiteSpace: 'nowrap',
                                    boxSizing: 'border-box',
                                    verticalAlign: 'middle',
                                    borderRadius: '2px',
                                    WebkitFontSmoothing: 'antialiased',
                                    MozOsxFontSmoothing: 'grayscale'
                                }}
                                onMouseEnter={(e) => {
                                    e.currentTarget.style.backgroundColor = `${ConfigurationDataColors.Instance.primaryColor}15`;
                                }}
                                onMouseLeave={(e) => {
                                    e.currentTarget.style.backgroundColor = 'transparent';
                                }}
                            >
                                {displayText}
                                {isDefinition && (
                                    <span style={{ display: 'inline-block', marginLeft: '4px', verticalAlign: 'middle' }}>
                                        {React.cloneElement(SystemIcons.star, {
                                            style: {
                                                fontSize: '14px',
                                                color: ConfigurationDataColors.Instance.primaryColor,
                                                opacity: 0.8
                                            }
                                        })}
                                    </span>
                                )}
                            </span>
                        </Tooltip>
                        {controller && (
                            <DataElementPickerDialog
                                open={dialogOpen}
                                onClose={() => setDialogOpen(false)}
                                onSelect={handleSelect}
                                controller={controller}
                                allowNew={dataElement.allowNew}
                                requiresType={dataElement.requiresType}
                            />
                        )}
                    </>
                );
            }}
        />
    );
}
