import { Box, Typography } from '@mui/material';
import React from 'react';
import { MachineData } from '../../../data/Machine/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';

export const CoordinateSystemTab: React.FC = () => {
  const machine = MachineData.Instance;

  // Build listenTo array to watch MachineData and individual axis configs
  const listenToObjects: Array<{ object: any; properties: string[] }> = [
    {
      object: MachineStateData.Instance,
      properties: [
        'spoilBoardWidth', 'spoilBoardYLength', 'spoilBoardHeight', 'spoilboardX', 'spoilboardY'
      ]
    },
    {
      object: machine,
      properties: [
        'machineName', 'unitOfMeasure', 'xDirection', 'zLocation',
        'machineZeroCoordinatesFromMachineHomeX',
        'machineZeroCoordinatesFromMachineHomeY',
        'machineZeroCoordinatesFromMachineHomeZ',
        'machineBaseTopCornerFromMachineZeroX',
        'machineBaseTopCornerFromMachineZeroY',
        'machineBaseTopCornerFromMachineZeroZ',
        'baseHeight',
        'xLowerSoftLimitFromMachineZero', 'xUpperSoftLimitFromMachineZero',
        'yLowerSoftLimitFromMachineZero', 'yUpperSoftLimitFromMachineZero',
        'zLowerSoftLimitFromMachineZero', 'zUpperSoftLimitFromMachineZero',
        'hasATC', 'atcNumberOfTools', 'atcToolClamps',
        'xyMoveToATC', 'zMoveToATC', 'xyApproachSpeed', 'zApproachSpeed', 'xyDockSpeed', 'zDockSpeed', 'atcClampDwellTime',
        'atcVerticalClearance', 'atcHorizontalClearance', 'atcApproachAxis',
        'atcShareHorizontalCoordinate', 'atcShareZCoordinate', 'atcSharedHorizontalValue', 'atcSharedZValue',
        'hasFixedTouchPlate', 'fixedTouchPlateX', 'fixedTouchPlateY', 'fixedTouchPlateZ',
        'fixedTouchPlateFastSpeed', 'fixedTouchPlateSlowSpeed',
        'hasMovableTouchPlate', 'movableTouchPlateFastSpeed', 'movableTouchPlateSlowSpeed', 'movableTouchPlateHeight',
        'manualToolChangeLocationFromMZX', 'manualToolChangeLocationFromMZY', 'manualToolChangeLocationFromMZZ',
        'fixedToolMeasurementPointEnabled', 'fixedToolMeasurementPointX', 'fixedToolMeasurementPointY', 'fixedToolMeasurementPointZ',
        'spoilboardToolMeasurementPointEnabled', 'spoilboardToolMeasurementPointX', 'spoilboardToolMeasurementPointY', 'spoilboardToolMeasurementPointZ',
        'machineBedToolMeasurementPointEnabled', 'machineBedToolMeasurementPointX', 'machineBedToolMeasurementPointY', 'machineBedToolMeasurementPointZ',
        'xHomingDirection', 'yHomingDirection', 'zHomingDirection', 'homingOrder', 'xyHomingSpeed', 'zHomingSpeed',
        'enableAutoSquare', 'autoSquareMasterAxis', 'autoSquareDistance'
      ]
    },
    // Add each ATC tool clamp for individual property watching
    ...machine.atcToolClamps.map(clamp => ({
      object: clamp,
      properties: ['offsetX', 'offsetY', 'offsetZ']
    }))
  ];

  return (
    <>
      <ObserveMultiProperties
        key="coordinate-system-tab"
        listenTo={listenToObjects}
        control={() => (
          <Box sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom>
              Coordinate System Configuration
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
              All coordinate system sections have been moved to other tabs.
            </Typography>
          </Box>
        )}
      />
    </>
  );
};
