/**
 * Memory bit states for boolean condition checking
 */
export enum MemoryBitState {
    Set = 'SET',
    Reset = 'RESET'
}

/**
 * Get human-readable label for memory bit state
 */
export function getMemoryBitStateLabel(state: MemoryBitState): string {
    switch (state) {
        case MemoryBitState.Set:
            return 'SET';
        case MemoryBitState.Reset:
            return 'RESET';
        default:
            return state;
    }
}
