import CancelIcon from '@mui/icons-material/Cancel';
import CommentIcon from '@mui/icons-material/Comment';
import SaveIcon from '@mui/icons-material/Save';
import { Box, Button, IconButton, Stack, TextField, Typography } from '@mui/material';
import { useState } from 'react';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';

interface EditableCommentProps {
    comment: string;
    onCommentChange: (comment: string) => void;
    placeholder?: string;
    readOnly?: boolean;
}

/**
 * EditableComment - A component that displays a comment and allows editing when clicked
 * Shows a comment icon when empty, displays comment text when present
 */
export function EditableComment(props: EditableCommentProps) {
    const { comment, onCommentChange, placeholder = 'Add comment...', readOnly = false } = props;
    const [isEditing, setIsEditing] = useState(false);
    const [editValue, setEditValue] = useState(comment);
    const config = ConfigurationData.Instance;
    const colors = ConfigurationDataColors.Instance;

    const handleStartEdit = () => {
        if (readOnly) return;
        setEditValue(comment);
        setIsEditing(true);
    };

    const handleSave = () => {
        onCommentChange(editValue);
        setIsEditing(false);
    };

    const handleCancel = () => {
        setEditValue(comment);
        setIsEditing(false);
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Escape') {
            e.preventDefault();
            handleCancel();
        }
    };

    if (isEditing) {
        return (
            <Stack direction="column" spacing={1} sx={{ width: '100%' }}>
                <TextField
                    size="small"
                    value={editValue}
                    onChange={(e) => setEditValue(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder={placeholder}
                    autoFocus
                    multiline
                    rows={3}
                    sx={{
                        flex: 1,
                        '& .MuiInputBase-root': {
                            fontSize: '0.875rem',
                            fontStyle: 'italic',
                            color: colors.infoColor
                        }
                    }}
                />
                <Stack direction="row" spacing={1} justifyContent="flex-end">
                    <Button
                        size="small"
                        variant="outlined"
                        startIcon={<CancelIcon />}
                        onClick={handleCancel}
                    >
                        Cancel
                    </Button>
                    <Button
                        size="small"
                        variant="contained"
                        startIcon={<SaveIcon />}
                        onClick={handleSave}
                    >
                        Save
                    </Button>
                </Stack>
            </Stack>
        );
    }

    if (comment) {
        return (
            <Box
                onClick={handleStartEdit}
                sx={{
                    cursor: readOnly ? 'default' : 'pointer',
                    py: 0.25,
                    px: 0.5,
                    borderRadius: 1,
                    '&:hover': readOnly ? {} : {
                        backgroundColor: `${colors.primaryColor}10`
                    }
                }}
            >
                <Typography
                    variant="body2"
                    sx={{
                        fontStyle: 'italic',
                        color: colors.infoColor,
                        fontSize: '0.875rem',
                        whiteSpace: 'pre-wrap',
                        wordBreak: 'break-word'
                    }}
                >
                    {comment}
                </Typography>
            </Box>
        );
    }

    // Empty state - show icon button
    if (readOnly) return null;

    return (
        <IconButton
            size="small"
            onClick={handleStartEdit}
            title="Add comment"
            sx={{
                opacity: 0.4,
                '&:hover': {
                    opacity: 1
                }
            }}
        >
            <CommentIcon fontSize="small" />
        </IconButton>
    );
}
