import { StateManager } from '../../utils/statemanager/StateManager';
import { MachineData } from '../Machine/MachineData';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for Measurement Setup configuration
 * Auto-validates - checks if at least one touch-off method is configured:
 * - Fixed Touch Plate
 * - Movable Touch Plate
 * - Manual Tool Measurement (Fixed Point, Spoilboard, or Machine Bed)
 */
export class MeasurementSetupChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Measurement Setup',
            'Configure at least one tool measurement method (touch plate or manual measurement point)'
        );

        // Listen for changes to MachineData properties that affect measurement setup
        const machine = MachineData.Instance;
        StateManager.addObserver(machine, () => {
            StateManager.propertyChanged(this, 'manuallyConfirmed');
        }, [
            'hasFixedTouchPlate',
            'hasMovableTouchPlate',
            'fixedToolMeasurementPointEnabled',
            'spoilboardToolMeasurementPointEnabled',
            'machineBedToolMeasurementPointEnabled'
        ]);
    }

    public needsManualConfirmation(): boolean {
        return false; // Auto-validation only
    }

    public completionCheck(): boolean {
        const machine = MachineData.Instance;

        // Check if any touch plate is configured
        const hasFixedTouchPlate = machine.hasFixedTouchPlate;
        const hasMovableTouchPlate = machine.hasMovableTouchPlate;

        // Check if any manual measurement point is enabled
        const hasFixedPoint = machine.fixedToolMeasurementPointEnabled;
        const hasSpoilboard = machine.spoilboardToolMeasurementPointEnabled;
        const hasMachineBed = machine.machineBedToolMeasurementPointEnabled;

        // At least one method must be configured
        return hasFixedTouchPlate || hasMovableTouchPlate || hasFixedPoint || hasSpoilboard || hasMachineBed;
    }

    public clone(): MeasurementSetupChecklistItem {
        const cloned = new MeasurementSetupChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
