import { ConfigurationState } from '../data/ConfigurationState';
import { JogDirection } from '../machine/JogDirection';
import { Machine } from '../machine/Machine';
import { LogCategory, Logger } from './Logger';

/**
 * JogRenewalManager - Manages continuous jog renewal pattern
 * 
 * Handles the 100ms renewal requirement for continuous jog operations
 * to prevent the 250ms timeout on the backend. Each jog direction gets
 * its own renewal timer that is automatically cleaned up on stop.
 */
export class JogRenewalManager {
    private static _instance: JogRenewalManager;
    private _renewalTimers: Map<JogDirection, NodeJS.Timeout> = new Map();
    private _activeDirections: Set<JogDirection> = new Set();
    private readonly RENEWAL_INTERVAL = 100; // 100ms renewal interval

    private constructor() {
        // Private constructor for singleton
    }

    public static get Instance(): JogRenewalManager {
        if (!JogRenewalManager._instance) {
            JogRenewalManager._instance = new JogRenewalManager();
        }
        return JogRenewalManager._instance;
    }

    /**
     * Start jogging in a direction with automatic renewal for continuous mode
     * @param direction Direction to jog
     */
    public async startJog(direction: JogDirection): Promise<void> {
        try {
            // Stop any existing jog in this direction first
            this.stopJog(direction);

            // Mark direction as active
            this._activeDirections.add(direction);

            // Check if we're in continuous mode
            const isContinuous = ConfigurationState.Instance.jogContinuousMode;

            // Start the jog
            await Machine.getInstance().movement.StartJog(direction);

            // Only set up renewal timer for continuous mode
            if (isContinuous) {
                // Set up renewal timer for continuous mode
                // The timer will call KeepJogging every 100ms
                const timer = setInterval(async () => {
                    try {
                        if (this._activeDirections.has(direction)) {
                            await Machine.getInstance().movement.KeepJogging(direction);
                        } else {
                            // Direction no longer active, clear the timer
                            this.stopJog(direction);
                        }
                    } catch (error) {
                        Logger.Instance.logError(LogCategory.UserInterface, `Failed to renew jog for ${direction}:`, error);
                        // Stop jog on renewal error
                        this.stopJog(direction);
                    }
                }, this.RENEWAL_INTERVAL);

                this._renewalTimers.set(direction, timer);
            } else {
                // In incremental mode, jog completes automatically on backend
                // Remove from active directions since we're not managing its lifecycle
                this._activeDirections.delete(direction);
            }
        } catch (error) {
            // Clean up on error
            this._activeDirections.delete(direction);
            throw error;
        }
    }

    /**
     * Stop jogging in a specific direction
     * @param direction Direction to stop (if not provided, stops all directions)
     */
    public stopJog(direction?: JogDirection): void {
        if (direction) {
            // Stop specific direction
            const timer = this._renewalTimers.get(direction);
            if (timer) {
                clearInterval(timer);
                this._renewalTimers.delete(direction);
            }
            this._activeDirections.delete(direction);

            // Call StopJog on the machine
            Machine.getInstance().movement.StopJog().catch(error => {
                Logger.Instance.logError(LogCategory.UserInterface, `Failed to stop jog for ${direction}:`, error);
            });
        } else {
            // Stop all directions
            this._renewalTimers.forEach((timer, dir) => {
                clearInterval(timer);
                this._activeDirections.delete(dir);
            });
            this._renewalTimers.clear();

            // Call StopJog on the machine
            Machine.getInstance().movement.StopJog().catch(error => {
                Logger.Instance.logError(LogCategory.UserInterface, 'Failed to stop all jog movements:', error);
            });
        }
    }

    /**
     * Stop all jog movements (convenience method)
     */
    public stopAll(): void {
        this.stopJog();
    }

    /**
     * Check if a direction is currently active
     */
    public isActive(direction: JogDirection): boolean {
        return this._activeDirections.has(direction);
    }

    /**
     * Get all active directions
     */
    public getActiveDirections(): JogDirection[] {
        return Array.from(this._activeDirections);
    }

    /**
     * Clean up all timers (call on unmount)
     */
    public cleanup(): void {
        this.stopAll();
    }
}
