import { Construction as ClampIcon } from '@mui/icons-material';
import { Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, Typography } from '@mui/material';
import React from 'react';
import { ClampEditorForm } from '../../components/Views/ClampEditorForm';
import { ConfigurationState } from '../../data/ConfigurationState';
import { ModalManager } from '../ModalManager';
import { IUserAction } from './IUserAction';

export class EditClampsUserAction implements IUserAction {
    public readonly id = 'home_page_edit_clamps';
    public readonly category = 'Machine Actions';

    public isAvailable(): boolean {
        const config = ConfigurationState.Instance;
        return config.isHomed && !config.isJobRunning;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        if (asLink) {
            return (
                <React.Fragment>
                    <ClampIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                    <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                        Edit Clamps
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <ClampIcon />
                    <Typography>Edit Clamps</Typography>
                </Box>
            );
        }
    }

    public run(): void {
        const modalId = 'clamp-editor-dialog';
        ModalManager.Instance.showModal({
            id: modalId,
            render: () => (
                <Dialog
                    open
                    onClose={() => ModalManager.Instance.closeModal(modalId)}
                    maxWidth="lg"
                    fullWidth
                    PaperProps={{ sx: { height: '80vh' } }}
                >
                    <DialogTitle>Clamp Setup</DialogTitle>
                    <DialogContent sx={{ p: 2, height: 'calc(100% - 120px)', overflow: 'auto' }}>
                        <ClampEditorForm
                            onSaveToLibrary={() => { }}
                            onLoadFromLibrary={() => { }}
                            height="100%"
                        />
                    </DialogContent>
                    <DialogActions sx={{ p: 2, justifyContent: 'flex-end' }}>
                        <Button onClick={() => ModalManager.Instance.closeModal(modalId)} variant="contained">
                            Done
                        </Button>
                    </DialogActions>
                </Dialog>
            )
        });
    }
}
