import { BaseCNCProgramStorage } from '../machine/BaseCNCProgramStorage';
import { Storage, StorageType } from '../machine/ICNCProgramStorage';
import { CNCProgramStorageApi } from '../services/src/apis/CNCProgramStorageApi';
import { StorageType as ApiStorageType, ProgramStorage } from '../services/src/models/index';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';

export class CentroidCNCProgramStorage extends BaseCNCProgramStorage {
    private readonly api: CNCProgramStorageApi;

    constructor() {
        super();
        const config = MachineInterfaceManager.Instance.getServiceConfiguration();
        this.api = new CNCProgramStorageApi(config || undefined);
    }

    async getStorageNames(): Promise<string[]> {
        try {
            const response = await this.api.apiCNCProgramStorageAllNamesGet();
            return response;
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to get storage names:', error);
            throw error;
        }
    }

    async getAllStorageNames(): Promise<string[]> {
        return this.getStorageNames();
    }

    async getStorageData(name: string): Promise<Storage | null> {
        try {
            const response = await this.api.apiCNCProgramStorageNameGet({ name });
            if (!response) return null;

            // Convert API model to our Storage class
            const storage = this.convertFromApiModel(response);
            return storage;
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, `Failed to get storage data for ${name}:`, error);
            return null;
        }
    }

    async saveStorageData(storage: Storage): Promise<void> {
        try {
            // Convert our Storage class to API model
            const apiModel = this.convertToApiModel(storage);
            await this.api.apiCNCProgramStorageSavePost({ programStorage: apiModel });
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, `Failed to save storage data for ${storage.name}:`, error);
            throw error;
        }
    }

    async deleteStorageData(name: string): Promise<void> {
        try {
            await this.api.apiCNCProgramStorageNameDelete({ name });
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, `Failed to delete storage data for ${name}:`, error);
            throw error;
        }
    }

    // Utility methods for specific storage types
    async getFlowStorageNames(): Promise<string[]> {
        try {
            const response = await this.api.apiCNCProgramStorageFlowNamesGet();
            return response;
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to get Flow storage names:', error);
            throw error;
        }
    }

    async getMDIStorageNames(): Promise<string[]> {
        try {
            const response = await this.api.apiCNCProgramStorageMDINamesGet();
            return response;
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to get MDI storage names:', error);
            throw error;
        }
    }

    // Conversion methods between our Storage class and API models
    private convertFromApiModel(apiModel: ProgramStorage): Storage {
        const storage = new Storage();
        storage.name = apiModel.name || '';
        storage.createdAt = apiModel.createdAt || new Date();
        storage.updatedAt = apiModel.updatedAt || new Date();
        storage.exposeAsAction = apiModel.exposeAsAction || false;
        storage.categoryName = apiModel.actionCategoryName || '';
        storage.data = apiModel.data || '';

        // Convert API StorageType to our StorageType
        // ApiStorageType uses numeric values: 0 = Flow, 1 = MDI
        if (apiModel.storageType === ApiStorageType.NUMBER_0) {
            storage.storageType = StorageType.Flow;
        } else if (apiModel.storageType === ApiStorageType.NUMBER_1) {
            storage.storageType = StorageType.MDI;
        } else {
            storage.storageType = StorageType.Flow; // Default
        }

        return storage;
    }

    private convertToApiModel(storage: Storage): ProgramStorage {
        // Convert our StorageType to API StorageType
        // ApiStorageType uses numeric values: 0 = Flow, 1 = MDI
        let apiStorageType: ApiStorageType;
        if (storage.storageType === StorageType.Flow) {
            apiStorageType = ApiStorageType.NUMBER_0;
        } else if (storage.storageType === StorageType.MDI) {
            apiStorageType = ApiStorageType.NUMBER_1;
        } else {
            apiStorageType = ApiStorageType.NUMBER_0; // Default
        }

        return {
            name: storage.name,
            createdAt: storage.createdAt,
            updatedAt: storage.updatedAt,
            exposeAsAction: storage.exposeAsAction,
            actionCategoryName: storage.categoryName,
            data: storage.data,
            storageType: apiStorageType
        };
    }
}