import { Color, Vector3 } from 'three';

/**
 * Represents a point in a line with position, radius (width), color, and G-code metadata
 */
export class LinePoint {
  public position: Vector3;        // End position of this segment
  public radius: number;
  public color: Color;

  // G-code segment metadata
  public segmentStart?: Vector3;   // Start position of this segment
  public gCommand?: string;        // G-code command: 'G0', 'G1', 'G2', 'G3'
  public lineNumber?: number;      // Original G-code line number
  public originalGCodeLine?: string; // Original G-code line text from file
  public parameters?: {            // Parsed G-code parameters
    x?: number;
    y?: number;
    z?: number;
    i?: number;
    j?: number;
    k?: number;
    r?: number;
    f?: number;
    s?: number;
  };

  // Arc-specific metadata (for G2/G3 segments)
  public isArcSegment?: boolean;   // True if this came from G2/G3 interpolation
  public arcCenter?: { x: number, y: number, z: number }; // Arc center point
  public arcRadius?: number;       // Arc radius
  public isClockwise?: boolean;    // G2 = true, G3 = false
  public arcStartAngle?: number;   // Starting angle of arc
  public arcEndAngle?: number;     // Ending angle of arc
  public arcSegmentIndex?: number; // Which interpolated segment (0-based) within the arc
  public arcTotalSegments?: number;// Total segments in this arc

  constructor(position: Vector3, radius: number, color: Color) {
    this.position = position;
    this.radius = radius;
    this.color = color;
  }
}
