import React, { useMemo } from 'react';
import { CutterType, Tool as ToolData } from '../../../data/Common/Tool';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';

interface ToolProps {
  tool: ToolData;
  position: [number, number, number];
  rotation?: [number, number, number];
  visible?: boolean;
  transparent?: boolean;
  opacity?: number;
}

/**
 * 3D Tool visualization component
 * Renders a tool with shaft and cutter based on tool properties
 */
export const Tool: React.FC<ToolProps> = ({
  tool,
  position,
  rotation = [0, 0, 0],
  visible = true,
  transparent = false,
  opacity = 1
}) => {
  const colors = ConfigurationDataColors.Instance;

  const toolGeometry = useMemo(() => {
    if (!tool) return null;

    // Use the tool's effectiveCuttingLength getter for consistent calculation
    const effectiveCuttingLength = tool.effectiveCuttingLength;

    // Calculate dimensions using effective cutting length
    // lengthBelowHolder is now negative (extends below spindle), so use absolute value
    const totalToolLength = Math.abs(tool.lengthBelowHolder);
    const shaftLength = Math.max(0, totalToolLength - effectiveCuttingLength);
    const cutterLength = effectiveCuttingLength;
    const shaftRadius = tool.shankWidth / 2;
    const cutterRadius = tool.cuttingDiameter / 2;

    // Debug logging
    // //// console.log('Tool geometry calculation:', {
    //   toolName: tool.toolName,
    //   lengthBelowHolder: tool.lengthBelowHolder,
    //   originalCuttingLength: tool.cuttingLength,
    //   effectiveCuttingLength,
    //   shaftLength,
    //   cutterLength,
    //   shankWidth: tool.shankWidth,
    //   cuttingDiameter: tool.cuttingDiameter,
    //   shaftRadius,
    //   cutterRadius,
    //   cutterType: tool.cutterType,
    //   vCuttingEdgeAngle: tool.vCuttingEdgeAngle
    // });

    // Ensure we have valid dimensions (shaft can be 0 if entire length is cutting)
    // lengthBelowHolder is now negative, so check absolute value
    if (cutterLength <= 0 || Math.abs(tool.lengthBelowHolder) <= 0 || tool.cuttingDiameter <= 0) {
      console.warn('Invalid tool dimensions - tool will not render:', {
        toolName: tool.toolName,
        toolNumber: tool.toolNumber,
        shaftLength,
        cutterLength,
        lengthBelowHolder: tool.lengthBelowHolder,
        cuttingDiameter: tool.cuttingDiameter,
        shankWidth: tool.shankWidth
      });
      return null;
    }

    return {
      shaftLength,
      cutterLength,
      shaftRadius,
      cutterRadius,
      totalLength: totalToolLength
    };
  }, [tool]);

  if (!visible || !toolGeometry) {
    // //// console.log('Tool not rendering:', { visible, toolGeometry: !!toolGeometry });
    return null;
  }

  const { shaftLength, cutterLength, shaftRadius, cutterRadius } = toolGeometry;

  // Position shaft above cutter
  const shaftY = cutterLength + shaftLength / 2;
  const cutterY = cutterLength / 2;

  return (
    <ObserveState
      listenTo={colors}
      properties={['toolColor', 'cutterColor', 'toolTransparency']}
      control={() => (
        <group position={position} rotation={rotation}>
          {/* Tool Shaft - only render if shaft has length */}
          {shaftLength > 0 && (
            <mesh position={[0, shaftY, 0]}>
              <cylinderGeometry args={[shaftRadius, shaftRadius, shaftLength, 16]} />
              <meshStandardMaterial
                color={ConfigurationDataColors.toThreeJsColor(colors.toolColor)}
                transparent={transparent}
                opacity={opacity}
              />
            </mesh>
          )}

          {/* Tool Cutter - different shapes based on cutter type */}
          {tool.cutterType === CutterType.FlatEndMill && (
            <mesh position={[0, cutterY, 0]}>
              <cylinderGeometry args={[cutterRadius, cutterRadius, cutterLength, 16]} />
              <meshStandardMaterial
                color={colors.cutterColor}
                transparent={transparent}
                opacity={opacity}
              />
            </mesh>
          )}

          {tool.cutterType === CutterType.BallEndMill && (
            <group position={[0, 0, 0]}>
              {/* Cylindrical part - positioned above the ball */}
              <mesh position={[0, cutterRadius + (cutterLength - cutterRadius) / 2, 0]}>
                <cylinderGeometry args={[cutterRadius, cutterRadius, cutterLength - cutterRadius, 16]} />
                <meshStandardMaterial
                  color={colors.cutterColor}
                  transparent={transparent}
                  opacity={opacity}
                />
              </mesh>
              {/* Ball end - positioned at the bottom */}
              <mesh position={[0, cutterRadius, 0]}>
                <sphereGeometry args={[cutterRadius, 16, 8, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2]} />
                <meshStandardMaterial
                  color={colors.cutterColor}
                  transparent={transparent}
                  opacity={opacity}
                />
              </mesh>
            </group>
          )}

          {tool.cutterType === CutterType.VBit && (
            <group position={[0, 0, 0]}>
              {/* V-shaped cone - calculate radius based on angle and cutting length */}
              <mesh position={[0, cutterLength / 2, 0]} rotation={[Math.PI, 0, 0]}>
                <coneGeometry args={[
                  Math.max(cutterRadius, cutterLength * Math.tan((tool.vCuttingEdgeAngle / 2) * Math.PI / 180)),
                  cutterLength,
                  16
                ]} />
                <meshStandardMaterial
                  color={colors.cutterColor}
                  transparent={transparent}
                  opacity={opacity}
                />
              </mesh>
            </group>
          )}

          {tool.cutterType === CutterType.Surfacing && (
            <mesh position={[0, cutterY, 0]}>
              <cylinderGeometry args={[cutterRadius, cutterRadius, cutterLength, 16]} />
              <meshStandardMaterial
                color={colors.cutterColor}
                transparent={transparent}
                opacity={opacity}
              />
            </mesh>
          )}
        </group>
      )}
    />
  );
};
