/**
 * Utility for extracting the outline of G-code toolpaths using raycasting.
 * 
 * Strategy:
 * 1. Use existing GCodeParser to parse into Three.js Vector3 line points
 * 2. Cast rays from all four directions (left, right, top, bottom)
 * 3. Find the first segment hit by each ray (closest collision)
 * 4. Collect unique segments that form the outer boundary
 * 5. Map back to original G-code lines
 * 
 * This leverages Three.js geometry utilities that GCodeParser already uses.
 */

import { GCodeParser, GCodeParseResult } from '../components/Views/Milling/gcode/GCodeParser';
import { SimpleColorizer } from '../components/Views/Milling/gcode/SegmentColorizer';

export class OutlineDetection {
    /**
     * Preprocess G-code for outline detection by flattening Z and removing Z-only moves.
     * This creates clean XY-only G-code for raycasting.
     */
    private static preprocessGCodeForOutline(gcode: string): string {
        const lines = gcode.split('\n');
        const processedLines: string[] = [];
        const zHeight = 0; // Flatten to Z=0 for outline detection

        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed || trimmed.startsWith('(') || trimmed.startsWith(';')) {
                // Skip empty lines and comments
                continue;
            }

            // Check if line has X or Y movement
            const hasX = /X-?[\d.]+/i.test(trimmed);
            const hasY = /Y-?[\d.]+/i.test(trimmed);

            if (!hasX && !hasY) {
                // Z-only move or other command - skip it
                continue;
            }

            // Replace Z with flattened height, or add Z if missing
            let processedLine = trimmed;
            if (/Z-?[\d.]+/i.test(processedLine)) {
                processedLine = processedLine.replace(/Z-?[\d.]+/i, `Z${zHeight}`);
            } else if (/G0?[01]/i.test(processedLine)) {
                // Add Z height to G0/G1 moves that don't have it
                processedLine = `${processedLine} Z${zHeight}`;
            }

            processedLines.push(processedLine);
        }

        return processedLines.join('\n');
    }

    /**
     * Extract outline segments from G-code using raycasting approach.
     * Returns indices of segments that form the outer boundary.
     * Parses full G-code (including G00) for correct positioning, then filters out G0 segments.
     */
    public static extractOutlineSegmentIndices(gcode: string, rayStep: number = 0.1): number[] {
        if (!gcode) {
            return [];
        }

        // Preprocess: Flatten Z and remove Z-only moves
        const preprocessedGCode = this.preprocessGCodeForOutline(gcode);

        // Parse FULL G-code (including G00) to get correct positions
        const parser = new GCodeParser(new SimpleColorizer());
        const result: GCodeParseResult = parser.parse(preprocessedGCode);

        if (result.linePoints.length < 2) {
            return [];
        }

        // Identify which segments are G0 rapid moves (to exclude later)
        // We need to track G-commands and map them to actual segments in the parsed result
        // CRITICAL: Parse the PREPROCESSED lines to match the actual segments created
        const preprocessedLines = preprocessedGCode.split('\n');
        const isG0Segment = new Array(result.linePoints.length - 1).fill(false);

        let segmentIndex = 0;
        let lastGCommand = '';
        let prevPos = { x: 0, y: 0, z: 0 };

        for (const line of preprocessedLines) {
            const trimmed = line.trim().toUpperCase();
            if (!trimmed || trimmed.startsWith(';') || trimmed.startsWith('(')) {
                continue;
            }

            // Track the G command for THIS line (before parsing coordinates)
            const gMatch = trimmed.match(/^G(\d{1,2})\b/);
            if (gMatch) {
                const gNum = gMatch[1].padStart(2, '0');
                lastGCommand = 'G' + gNum;
            }

            // Parse coordinates from this line
            const xMatch = trimmed.match(/X([-+]?\d*\.?\d+)/);
            const yMatch = trimmed.match(/Y([-+]?\d*\.?\d+)/);
            const zMatch = trimmed.match(/Z([-+]?\d*\.?\d+)/);

            // Update position
            const newPos = { ...prevPos };
            if (xMatch) newPos.x = parseFloat(xMatch[1]);
            if (yMatch) newPos.y = parseFloat(yMatch[1]);
            if (zMatch) newPos.z = parseFloat(zMatch[1]);

            // Check if position actually changed (this creates a segment)
            const posChanged = newPos.x !== prevPos.x || newPos.y !== prevPos.y || newPos.z !== prevPos.z;

            if (posChanged && segmentIndex < isG0Segment.length) {
                // Mark as G0 segment - ALL rapid moves should be excluded from outline
                const isG0 = lastGCommand === 'G00' || lastGCommand === 'G0';
                isG0Segment[segmentIndex] = isG0;

                segmentIndex++;
                prevPos = newPos;
            }
        }

        // Helper: Check if ray intersects line segment
        const rayIntersectsSegment = (
            rayOrigin: { x: number, y: number },
            rayDir: { x: number, y: number },
            segStart: { x: number, y: number },
            segEnd: { x: number, y: number }
        ): { hit: boolean, distance: number } => {
            const segDir = { x: segEnd.x - segStart.x, y: segEnd.y - segStart.y };
            const denominator = rayDir.x * segDir.y - rayDir.y * segDir.x;

            if (Math.abs(denominator) < 0.0001) {
                return { hit: false, distance: Infinity };
            }

            const diff = { x: segStart.x - rayOrigin.x, y: segStart.y - rayOrigin.y };
            const t = (diff.x * segDir.y - diff.y * segDir.x) / denominator;
            const s = (diff.x * rayDir.y - diff.y * rayDir.x) / denominator;

            if (t >= 0 && s >= 0 && s <= 1) {
                return { hit: true, distance: t };
            }

            return { hit: false, distance: Infinity };
        };

        // Cast rays from all four directions
        const outerSegmentIndices = new Set<number>();

        // Calculate bounds and expand further for ray origins to ensure we catch boundary segments
        const boundsMargin = 5; // Cast from further away
        const minX = result.bounds.min.x - boundsMargin;
        const maxX = result.bounds.max.x + boundsMargin;
        const minY = result.bounds.min.y - boundsMargin;
        const maxY = result.bounds.max.y + boundsMargin;

        // Calculate centroid for determining radial ray direction
        let sumX = 0, sumY = 0, count = 0;
        for (let i = 0; i < result.linePoints.length; i++) {
            const pos = result.linePoints[i].position;
            sumX += pos.x;
            sumY += pos.y;
            count++;
        }
        const centroidX = sumX / count;
        const centroidY = sumY / count;

        // Collect all unique Y coordinates to ensure we hit every vertex
        const uniqueYCoords = new Set<number>();
        const uniqueXCoords = new Set<number>();
        for (let i = 0; i < result.linePoints.length; i++) {
            const pos = result.linePoints[i].position;
            uniqueYCoords.add(pos.y);
            uniqueXCoords.add(pos.x);
        }

        // Cast horizontal rays from left at regular intervals AND at each unique Y
        // Also cast slightly above/below each vertex to catch all boundary segments
        const yPositions = new Set<number>();
        for (let y = minY; y <= maxY; y += rayStep) {
            yPositions.add(y);
        }
        uniqueYCoords.forEach(y => {
            yPositions.add(y);
            yPositions.add(y + 0.001); // Slightly above
            yPositions.add(y - 0.001); // Slightly below
        });

        for (const y of yPositions) {
            let closestDist = Infinity;
            const segmentsAtDistance: number[] = [];

            for (let i = 0; i < result.linePoints.length - 1; i++) {
                const start = result.linePoints[i].position;
                const end = result.linePoints[i + 1].position;
                const intersection = rayIntersectsSegment(
                    { x: minX, y },
                    { x: 1, y: 0 },
                    { x: start.x, y: start.y },
                    { x: end.x, y: end.y }
                );

                if (intersection.hit) {
                    if (intersection.distance < closestDist - 0.001) {
                        // Found closer segment - replace list
                        closestDist = intersection.distance;
                        segmentsAtDistance.length = 0;
                        segmentsAtDistance.push(i);
                    } else if (Math.abs(intersection.distance - closestDist) < 0.001) {
                        // Same distance - add to list
                        segmentsAtDistance.push(i);
                    }
                }
            }

            // Add all segments at the closest distance
            segmentsAtDistance.forEach(seg => outerSegmentIndices.add(seg));
        }

        // Cast horizontal rays from right at regular intervals AND at each unique Y
        for (const y of yPositions) {
            let closestDist = Infinity;
            const segmentsAtDistance: number[] = [];

            for (let i = 0; i < result.linePoints.length - 1; i++) {
                const start = result.linePoints[i].position;
                const end = result.linePoints[i + 1].position;
                const intersection = rayIntersectsSegment(
                    { x: maxX, y },
                    { x: -1, y: 0 },
                    { x: start.x, y: start.y },
                    { x: end.x, y: end.y }
                );

                if (intersection.hit) {
                    if (intersection.distance < closestDist - 0.001) {
                        closestDist = intersection.distance;
                        segmentsAtDistance.length = 0;
                        segmentsAtDistance.push(i);
                    } else if (Math.abs(intersection.distance - closestDist) < 0.001) {
                        segmentsAtDistance.push(i);
                    }
                }
            }

            segmentsAtDistance.forEach(seg => outerSegmentIndices.add(seg));
        }

        // Cast vertical rays from bottom at regular intervals AND at each unique X
        // Also cast slightly left/right of each vertex
        const xPositions = new Set<number>();
        for (let x = minX; x <= maxX; x += rayStep) {
            xPositions.add(x);
        }
        uniqueXCoords.forEach(x => {
            xPositions.add(x);
            xPositions.add(x + 0.001); // Slightly right
            xPositions.add(x - 0.001); // Slightly left
        });

        for (const x of xPositions) {
            let closestDist = Infinity;
            const segmentsAtDistance: number[] = [];

            for (let i = 0; i < result.linePoints.length - 1; i++) {
                const start = result.linePoints[i].position;
                const end = result.linePoints[i + 1].position;
                const intersection = rayIntersectsSegment(
                    { x, y: minY },
                    { x: 0, y: 1 },
                    { x: start.x, y: start.y },
                    { x: end.x, y: end.y }
                );

                if (intersection.hit) {
                    if (intersection.distance < closestDist - 0.001) {
                        closestDist = intersection.distance;
                        segmentsAtDistance.length = 0;
                        segmentsAtDistance.push(i);
                    } else if (Math.abs(intersection.distance - closestDist) < 0.001) {
                        segmentsAtDistance.push(i);
                    }
                }
            }

            segmentsAtDistance.forEach(seg => outerSegmentIndices.add(seg));
        }

        // Cast vertical rays from top at regular intervals AND at each unique X
        for (const x of xPositions) {
            let closestDist = Infinity;
            const segmentsAtDistance: number[] = [];

            for (let i = 0; i < result.linePoints.length - 1; i++) {
                const start = result.linePoints[i].position;
                const end = result.linePoints[i + 1].position;
                const intersection = rayIntersectsSegment(
                    { x, y: maxY },
                    { x: 0, y: -1 },
                    { x: start.x, y: start.y },
                    { x: end.x, y: end.y }
                );

                if (intersection.hit) {
                    if (intersection.distance < closestDist - 0.001) {
                        closestDist = intersection.distance;
                        segmentsAtDistance.length = 0;
                        segmentsAtDistance.push(i);
                    } else if (Math.abs(intersection.distance - closestDist) < 0.001) {
                        segmentsAtDistance.push(i);
                    }
                }
            }

            segmentsAtDistance.forEach(seg => outerSegmentIndices.add(seg));
        }

        // Filter out G0 rapid move segments
        const cuttingOutlineIndices = Array.from(outerSegmentIndices)
            .filter(i => !isG0Segment[i]);

        return cuttingOutlineIndices.sort((a, b) => a - b);
    }

    /**
     * Map segment indices to their corresponding G-code line numbers.
     * Works with preprocessed G-code (flat Z, no Z-only moves).
     * 
     * @param gcode Preprocessed G-code string
     * @returns Map from segment index to 1-based line number
     */
    public static mapSegmentIndicesToLines(gcode: string): Map<number, number> {
        if (!gcode) {
            return new Map();
        }

        const lines = gcode.split('\n');
        const segmentToLineMap = new Map<number, number>();

        let segmentIndex = 0;
        let prevPos = { x: 0, y: 0, z: 0 };

        for (let i = 0; i < lines.length; i++) {
            const trimmed = lines[i].trim().toUpperCase();
            if (!trimmed || trimmed.startsWith(';') || trimmed.startsWith('(')) {
                continue;
            }

            const xMatch = trimmed.match(/X([-+]?\d*\.?\d+)/);
            const yMatch = trimmed.match(/Y([-+]?\d*\.?\d+)/);
            const zMatch = trimmed.match(/Z([-+]?\d*\.?\d+)/);

            const newPos = { ...prevPos };
            if (xMatch) newPos.x = parseFloat(xMatch[1]);
            if (yMatch) newPos.y = parseFloat(yMatch[1]);
            if (zMatch) newPos.z = parseFloat(zMatch[1]);

            // Since preprocessing removed Z-only moves, all position changes have XY movement
            const posChanged = newPos.x !== prevPos.x || newPos.y !== prevPos.y || newPos.z !== prevPos.z;

            if (posChanged) {
                segmentToLineMap.set(segmentIndex, i + 1); // 1-based line number
                segmentIndex++;
                prevPos = newPos;
            }
        }

        return segmentToLineMap;
    }

    /**
     * Extract G-code lines corresponding to segment indices.
     * 
     * @param gcode Original G-code text
     * @param segmentIndices Array of segment indices to extract
     * @returns Array of G-code lines corresponding to the segments
     * @throws Error if any segment index cannot be mapped to a G-code line
     */
    public static extractGCodeLinesForSegments(gcode: string, segmentIndices: number[]): string[] {
        if (!gcode || segmentIndices.length === 0) {
            return [];
        }

        const segmentToLineMap = this.mapSegmentIndicesToLines(gcode);
        const lines = gcode.split('\n');
        const outlineGCodeLines: string[] = [];
        const unmappedSegments: number[] = [];

        for (const idx of Array.from(segmentIndices).sort((a, b) => a - b)) {
            const lineNum = segmentToLineMap.get(idx);
            if (lineNum && lineNum <= lines.length) {
                outlineGCodeLines.push(lines[lineNum - 1]);
            } else {
                unmappedSegments.push(idx);
            }
        }

        // If any segments couldn't be mapped, throw error with diagnostics
        if (unmappedSegments.length > 0) {
            // Parse G-code to get segment coordinates for unmapped segments
            const parser = new GCodeParser(new SimpleColorizer());
            const result: GCodeParseResult = parser.parse(gcode);

            const unmappedDetails = unmappedSegments.map(idx => {
                if (idx < result.linePoints.length - 1) {
                    const start = result.linePoints[idx].position;
                    const end = result.linePoints[idx + 1].position;
                    return `     Segment ${idx}: (${start.x.toFixed(2)}, ${start.y.toFixed(2)}) → (${end.x.toFixed(2)}, ${end.y.toFixed(2)})`;
                }
                return `     Segment ${idx}: [out of range]`;
            }).join('\n');

            // Show what segments WERE successfully mapped
            const mappedSegments = segmentIndices.filter(idx => !unmappedSegments.includes(idx));
            const mappedDetails = mappedSegments.map(idx => {
                const lineNum = segmentToLineMap.get(idx);
                const lineContent = lineNum ? lines[lineNum - 1] : '[not found]';
                if (idx < result.linePoints.length - 1) {
                    const start = result.linePoints[idx].position;
                    const end = result.linePoints[idx + 1].position;
                    return `     Segment ${idx}: (${start.x.toFixed(2)}, ${start.y.toFixed(2)}) → (${end.x.toFixed(2)}, ${end.y.toFixed(2)}) = Line ${lineNum}: ${lineContent}`;
                }
                return `     Segment ${idx}: Line ${lineNum}: ${lineContent}`;
            }).join('\n');

            const diagnosticMessage = [
                '❌ OUTLINE DETECTION ERROR: Failed to map segment indices to G-code lines',
                '',
                `   Unmapped segment count: ${unmappedSegments.length}`,
                `   Unmapped segment details:`,
                unmappedDetails,
                '',
                `   Successfully mapped segments:`,
                mappedDetails,
                '',
                `   Total segments requested: ${segmentIndices.length}`,
                `   Parsed segment count: ${result.linePoints.length - 1}`,
                `   Segment-to-line map size: ${segmentToLineMap.size}`,
                `   G-code line count: ${lines.length}`,
                `   Segment indices range: [${Math.min(...segmentIndices)} - ${Math.max(...segmentIndices)}]`,
                `   Available segment indices in map: [${Array.from(segmentToLineMap.keys()).sort((a, b) => a - b).join(', ')}]`,
                '',
                `   Full G-code:`,
                ...lines.map((line, i) => `     ${(i + 1).toString().padStart(2, ' ')}: ${line}`)
            ].join('\n');

            console.error(diagnosticMessage);

            throw new Error(
                `Failed to map ${unmappedSegments.length} segment(s) to G-code lines. ` +
                `Unmapped segments: [${unmappedSegments.join(', ')}]. ` +
                `This indicates a mismatch between parsed segments and G-code line mapping. ` +
                `Check console for detailed diagnostics.`
            );
        }

        return outlineGCodeLines;
    }

    /**
     * Find G-code lines that move to a specific coordinate.
     * Returns array of line numbers (1-based) that match.
     * 
     * CRITICAL: This method tracks position across lines to handle single-axis moves correctly.
     * For example, if we're looking for (11.75, 0.25) and encounter "G01 X11.75" after "G01 Y0.25",
     * the X line is the one that creates the target coordinate.
     */
    public static findGCodeLinesForCoordinate(
        gcode: string,
        x: number,
        y: number,
        z?: number,
        tolerance: number = 0.01
    ): number[] {
        const lines = gcode.split('\n');
        const matchingLines: number[] = [];

        // Track current position to handle single-axis moves
        let currentX = 0;
        let currentY = 0;
        let currentZ = 0;

        for (let i = 0; i < lines.length; i++) {
            const line = lines[i].trim().toUpperCase();

            // Skip comments and empty lines
            if (!line || line.startsWith(';') || line.startsWith('(')) {
                continue;
            }

            // Parse coordinates from this line
            const xMatch = line.match(/X([-+]?\d*\.?\d+)/);
            const yMatch = line.match(/Y([-+]?\d*\.?\d+)/);
            const zMatch = line.match(/Z([-+]?\d*\.?\d+)/);

            // Update position based on coordinates in this line
            if (xMatch) {
                currentX = parseFloat(xMatch[1]);
            }
            if (yMatch) {
                currentY = parseFloat(yMatch[1]);
            }
            if (zMatch) {
                currentZ = parseFloat(zMatch[1]);
            }

            // Check if current position matches target after this line
            const xMatches = Math.abs(currentX - x) <= tolerance;
            const yMatches = Math.abs(currentY - y) <= tolerance;
            const zMatches = z === undefined || Math.abs(currentZ - z) <= tolerance;

            // This line creates the target coordinate if all axes match
            if (xMatches && yMatches && zMatches && (xMatch || yMatch || zMatch)) {
                matchingLines.push(i + 1); // 1-based line number
            }
        }

        return matchingLines;
    }

    /**
     * Extract the G-code lines that form the outline of the cutting path.
     * Uses raycasting to identify outer segments and adds coordinate comments for easy tracking.
     * Preprocesses G-code to flatten Z and remove Z-only moves for clean boundary detection.
     * 
     * @param gcode Original G-code text
     * @param rayStep Distance between rays (smaller = more accurate but slower)
     * @returns Array of G-code lines with coordinate comments
     */
    public static extractOutlineGCode(gcode: string, rayStep: number = 0.1): string[] {
        if (!gcode) {
            return [];
        }

        // Preprocess: Flatten Z and remove Z-only moves for clean raycasting
        const preprocessedGCode = this.preprocessGCodeForOutline(gcode);

        // Step 1: Use raycasting to find outer cutting segment indices
        const outlineIndices = this.extractOutlineSegmentIndices(preprocessedGCode, rayStep);

        if (outlineIndices.length === 0) {
            return [];
        }

        // Step 2: Parse to get segment coordinates and metadata
        const parser = new GCodeParser(new SimpleColorizer());
        const result: GCodeParseResult = parser.parse(preprocessedGCode);

        // Step 3: Group segments by arc and extract G-code with smart reconstruction
        const annotatedLines: string[] = [];
        const processedLineNumbers = new Set<number>();

        for (const idx of outlineIndices) {
            if (idx >= result.linePoints.length - 1) continue;

            const linePoint = result.linePoints[idx + 1]; // End point of segment
            const lineNumber = linePoint.lineNumber;

            // Skip if we've already processed this G-code line (multiple segments from same arc)
            if (lineNumber && processedLineNumbers.has(lineNumber)) {
                continue;
            }

            // Get original G-code line if available
            const originalLine = linePoint.originalGCodeLine;

            if (linePoint.isArcSegment && originalLine && lineNumber) {
                // This is an arc segment - check if segments from this arc are in outline
                const arcSegments = outlineIndices.filter(i => {
                    if (i >= result.linePoints.length - 1) return false;
                    const pt = result.linePoints[i + 1];
                    return pt.lineNumber === lineNumber && pt.isArcSegment;
                });

                // If we have arc segments from this command, use the original G2/G3 line
                if (arcSegments.length > 0) {
                    // Get start and end points from the arc
                    const firstArcSegIdx = Math.min(...arcSegments);
                    const lastArcSegIdx = Math.max(...arcSegments);
                    const start = result.linePoints[firstArcSegIdx].position;
                    const end = result.linePoints[lastArcSegIdx + 1].position;

                    // Verify segment start matches - segmentStart is on the END point (idx+1)
                    const segmentStart = result.linePoints[firstArcSegIdx + 1].segmentStart;
                    const positionMatches = segmentStart &&
                        Math.abs(segmentStart.x - start.x) < 0.001 &&
                        Math.abs(segmentStart.y - start.y) < 0.001;

                    if (positionMatches) {
                        const comment = `; ${start.x.toFixed(2)},${start.y.toFixed(2)} -> ${end.x.toFixed(2)},${end.y.toFixed(2)} (arc, ${arcSegments.length} segments)`;
                        const cleanLine = originalLine.split(';')[0].trim();
                        annotatedLines.push(`${cleanLine} ${comment}`);
                        processedLineNumbers.add(lineNumber);
                    }
                }
            } else if (originalLine) {
                // Linear move - verify position match before using original G-code
                const start = result.linePoints[idx].position;
                const end = result.linePoints[idx + 1].position;
                const segmentStart = linePoint.segmentStart;

                // Verify segment geometry matches
                const positionMatches = segmentStart &&
                    Math.abs(segmentStart.x - start.x) < 0.001 &&
                    Math.abs(segmentStart.y - start.y) < 0.001;

                if (positionMatches) {
                    const comment = `; ${start.x.toFixed(2)},${start.y.toFixed(2)} -> ${end.x.toFixed(2)},${end.y.toFixed(2)}`;
                    const cleanLine = originalLine.split(';')[0].trim();
                    annotatedLines.push(`${cleanLine} ${comment}`);
                    if (lineNumber) processedLineNumbers.add(lineNumber);
                } else {
                    // Position mismatch - reconstruct from coordinates
                    const gCmd = linePoint.gCommand || 'G1';
                    const comment = `; ${start.x.toFixed(2)},${start.y.toFixed(2)} -> ${end.x.toFixed(2)},${end.y.toFixed(2)}`;
                    annotatedLines.push(`${gCmd} X${end.x.toFixed(4)} Y${end.y.toFixed(4)} Z${end.z.toFixed(4)} ${comment}`);
                }
            } else {
                // Fallback: reconstruct from coordinates
                const start = result.linePoints[idx].position;
                const end = result.linePoints[idx + 1].position;
                const gCmd = linePoint.gCommand || 'G1';
                const comment = `; ${start.x.toFixed(2)},${start.y.toFixed(2)} -> ${end.x.toFixed(2)},${end.y.toFixed(2)}`;
                annotatedLines.push(`${gCmd} X${end.x.toFixed(4)} Y${end.y.toFixed(4)} Z${end.z.toFixed(4)} ${comment}`);
            }
        }

        return annotatedLines;
    }
}
