import { Grid, Typography } from '@mui/material';
import { MachineStateData } from '../../../../data/MachineStateData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';

export function SpoilBoardSection() {
    const machineState = MachineStateData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12}>
                <SetupChecklistIndicator name="Spoil Board" />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="spoil-board-width"
                    listenTo={machineState}
                    properties={['spoilBoardWidth']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="Spoil Board Width"
                                value={machineState.spoilBoardWidth}
                                onChange={(value) => machineState.spoilBoardWidth = value}
                                margin="normal"
                                precision={3}
                            />
                            <Typography variant="caption" color="text.secondary">
                                Width of the spoil board (X dimension)
                            </Typography>
                        </>
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="spoil-board-length"
                    listenTo={machineState}
                    properties={['spoilBoardYLength']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="Spoil Board Length"
                                value={machineState.spoilBoardYLength}
                                onChange={(value) => machineState.spoilBoardYLength = value}
                                margin="normal"
                                precision={3}
                            />
                            <Typography variant="caption" color="text.secondary">
                                Length of the spoil board (Y dimension)
                            </Typography>
                        </>
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="spoil-board-height"
                    listenTo={machineState}
                    properties={['spoilBoardHeight']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="Spoil Board Height"
                                value={machineState.spoilBoardHeight}
                                onChange={(value) => machineState.spoilBoardHeight = value}
                                margin="normal"
                                precision={3}
                            />
                            <Typography variant="caption" color="text.secondary">
                                Thickness/height of the spoil board (Z dimension)
                            </Typography>
                        </>
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="spoil-board-x-offset"
                    listenTo={machineState}
                    properties={['spoilboardX']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="Spoil Board X Offset"
                                value={machineState.spoilboardX}
                                onChange={(value) => machineState.spoilboardX = value}
                                margin="normal"
                                precision={3}
                            />
                            <Typography variant="caption" color="text.secondary">
                                X position offset from Machine Zero
                            </Typography>
                        </>
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="spoil-board-y-offset"
                    listenTo={machineState}
                    properties={['spoilboardY']}
                    control={() => (
                        <>
                            <NumberInput
                                fullWidth
                                label="Spoil Board Y Offset"
                                value={machineState.spoilboardY}
                                onChange={(value) => machineState.spoilboardY = value}
                                margin="normal"
                                precision={3}
                            />
                            <Typography variant="caption" color="text.secondary">
                                Y position offset from Machine Zero
                            </Typography>
                        </>
                    )}
                />
            </Grid>
        </Grid>
    );
}
