import { Home as HomeMachineIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../machine/Machine';
import { LogCategory, Logger } from '../Logger';
import { IUserAction } from './IUserAction';

export class HomeMachineUserAction implements IUserAction {
    public readonly id = 'home_page_home_machine';
    public readonly category = 'Machine Actions';
    public readonly isDefaultHomeAction = true;

    public isAvailable(): boolean {
        // Home Machine is always available
        return true;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        if (asLink) {
            return (
                <React.Fragment>
                    <HomeMachineIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                    <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                        Home Machine
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <HomeMachineIcon />
                    <Typography>Home Machine</Typography>
                </Box>
            );
        }
    }

    public async run(): Promise<void> {
        try {
            const machine = Machine.getInstance();
            await machine.system.HomeMachine();
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to home machine:', error);
        }
    }
}
