import { Box, FormControlLabel, Grid, Switch, Typography } from '@mui/material';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { ATCLocationComponent } from '../../../Common/ATCLocationComponent';
import { ATCStructureComponent } from '../../../Common/ATCStructureComponent';

export function ATCSetupSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            {/* ATC Configuration - Only show if hasATC is true */}
            {machine.hasATC && (
                <>
                    {/* Auto-Calculate Bar Location Switch */}
                    <Grid item xs={12}>
                        <ObserveState
                            key="atc-auto-calculate"
                            listenTo={machine}
                            properties={['atcAutoCalculateBarLocation']}
                            control={() => (
                                <>
                                    <FormControlLabel
                                        control={
                                            <Switch
                                                checked={machine.atcAutoCalculateBarLocation}
                                                onChange={(e) => machine.atcAutoCalculateBarLocation = e.target.checked}
                                            />
                                        }
                                        label="Auto-Calculate Bar Location from Tool Holders"
                                    />
                                    <Typography variant="caption" color="text.secondary" sx={{ display: 'block', ml: 4 }}>
                                        When enabled, bar location is automatically recalculated whenever tool holder positions change
                                    </Typography>
                                </>
                            )}
                        />
                    </Grid>

                    {/* ATC Location Component */}
                    <ObserveState
                        key="atc-location-observer"
                        listenTo={machine}
                        properties={['atcLocation']}
                        control={() => (
                            <ATCLocationComponent
                                atcLocation={machine.atcLocation}
                                onChange={() => {
                                    StateManager.propertyChanged(machine, 'atcLocation');
                                }}
                            />
                        )}
                    />

                    {/* Calculate Bar from Tool Holders Button - only show if auto-calculate is off */}
                    <ObserveState
                        key="atc-calculate-button"
                        listenTo={machine}
                        properties={['atcAutoCalculateBarLocation']}
                        control={() => (
                            <>
                                {!machine.atcAutoCalculateBarLocation && (
                                    <Grid item xs={12}>
                                        <Box sx={{ mb: 2 }}>
                                            <button
                                                onClick={() => {
                                                    machine.calculateATCBarFromToolHolders();
                                                }}
                                                style={{
                                                    backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                                                    color: ConfigurationDataColors.Instance.lightTextColor,
                                                    border: 'none',
                                                    borderRadius: '4px',
                                                    padding: '8px 16px',
                                                    cursor: 'pointer',
                                                    fontSize: '14px'
                                                }}
                                            >
                                                Calculate Bar from Tool Holders
                                            </button>
                                            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
                                                Manually calculate bar location and dimensions to fit all tool holders with 6" margins
                                            </Typography>
                                        </Box>
                                    </Grid>
                                )}
                            </>
                        )}
                    />

                    {/* ATC Structure Component */}
                    <ObserveState
                        key="atc-structure-observer"
                        listenTo={machine}
                        properties={['atcStructure']}
                        control={() => (
                            <ATCStructureComponent
                                atcStructure={machine.atcStructure}
                                onChange={() => {
                                    StateManager.propertyChanged(machine, 'atcStructure');
                                }}
                            />
                        )}
                    />
                </>
            )}
        </Grid>
    );
}
