import { ConnectionState } from '../utils/SignalRManager';
import { StateManager } from '../utils/statemanager/StateManager';
import { ConfigurationDataColors } from './ConfigurationDataColors';

/**
 * SignalR connection state data structure
 * Singleton class for reactive UI updates via StateManager
 */
export class SignalRStateData {
    private static _instance: SignalRStateData;

    // SignalR connection state
    private _connectionState: ConnectionState = ConnectionState.Disconnected;
    private _reconnectAttempts: number = 0;
    private _lastMessageReceived: Date | null = null;
    private _serverUrl: string = '';

    private constructor() {
        // Private constructor for singleton pattern
    }

    /**
     * Get the singleton instance
     */
    public static get Instance(): SignalRStateData {
        if (!SignalRStateData._instance) {
            SignalRStateData._instance = new SignalRStateData();
        }
        return SignalRStateData._instance;
    }

    /**
     * Current connection state
     */
    public get connectionState(): ConnectionState {
        return this._connectionState;
    }

    public set connectionState(value: ConnectionState) {
        if (this._connectionState !== value) {
            this._connectionState = value;
            StateManager.propertyChanged(this, 'connectionState');
        }
    }

    /**
     * Whether SignalR is currently connected
     */
    public get isConnected(): boolean {
        return this._connectionState === ConnectionState.Connected;
    }

    /**
     * Number of reconnection attempts
     */
    public get reconnectAttempts(): number {
        return this._reconnectAttempts;
    }

    public set reconnectAttempts(value: number) {
        if (this._reconnectAttempts !== value) {
            this._reconnectAttempts = value;
            StateManager.propertyChanged(this, 'reconnectAttempts');
        }
    }

    /**
     * Timestamp of last received message
     */
    public get lastMessageReceived(): Date | null {
        return this._lastMessageReceived;
    }

    public set lastMessageReceived(value: Date | null) {
        this._lastMessageReceived = value;
        StateManager.propertyChanged(this, 'lastMessageReceived');
    }

    /**
     * Server URL for SignalR connection
     */
    public get serverUrl(): string {
        return this._serverUrl;
    }

    public set serverUrl(value: string) {
        if (this._serverUrl !== value) {
            this._serverUrl = value;
            StateManager.propertyChanged(this, 'serverUrl');
        }
    }

    /**
     * Get connection status display text
     */
    public get connectionStatusText(): string {
        switch (this._connectionState) {
            case ConnectionState.Connected:
                return 'Connected';
            case ConnectionState.Connecting:
                return 'Connecting...';
            case ConnectionState.Reconnecting:
                return `Reconnecting... (${this._reconnectAttempts})`;
            case ConnectionState.Failed:
                return 'Failed';
            case ConnectionState.Disconnected:
            default:
                return 'Disconnected';
        }
    }

    /**
     * Get connection status color
     */
    public get connectionStatusColor(): string {
        const colors = ConfigurationDataColors.Instance;
        switch (this._connectionState) {
            case ConnectionState.Connected:
                return colors.successColor; // Green
            case ConnectionState.Connecting:
            case ConnectionState.Reconnecting:
                return colors.warningColor;
            case ConnectionState.Failed:
                return colors.errorColor; // Red
            case ConnectionState.Disconnected:
            default:
                return colors.mutedTextColor; // Gray
        }
    }
}