import { IStorable } from '../../common/IStorable';
import { StateManager } from '../../utils/statemanager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { CNCOffset } from '../CNCOffset';
import { CNCPoint } from '../CNCPoint';
import { CoordinateType } from '../Common/CoordinateType';
import { ConfigurationState } from '../ConfigurationState';
import { MachineData } from './MachineData';

/**
 * ATC Tool Clamp class
 * Represents an individual tool clamp in the ATC system
 */



export class ATCToolClamp implements IStorable {
    private _clampNumber: number;
    private _offset: CNCOffset;

    constructor(clampNumber: number, offsetX: number = 0, offsetY: number = 0, offsetZ: number = 0) {
        this._clampNumber = clampNumber;
        this._offset = new CNCOffset(offsetX, offsetY, offsetZ);
        this.registerSubObjectListeners();
    }

    /**
     * Register listeners on sub-objects to propagate changes up
     */
    protected registerSubObjectListeners(): void {
        StateManager.addObserver(this._offset, () => {
            StateManager.propertyChanged(this, 'offset');
            // Trigger auto-calculation when offset changes
            MachineData.triggerATCBarAutoCalculation();
        }, [], `ATCToolClamp-${this._clampNumber}-Offset`);
    }

    /**
     * Unregister listeners on sub-objects before they are replaced
     */
    protected unregisterSubObjectListeners(): void {
        if (this._offset) {
            StateManager.removeObserverByName(this._offset, `ATCToolClamp-${this._clampNumber}-Offset`);
        }
    }

    public get clampNumber(): number {
        return this._clampNumber;
    }

    public set clampNumber(value: number) {
        this._clampNumber = value;
    }

    // Main CNCOffset accessor
    public get offset(): CNCOffset {
        if (!this._offset) {
            this._offset = new CNCOffset(0, 0, 0);
        }
        return this._offset;
    }

    // Individual accessors for backward compatibility
    public get offsetX(): number {
        return this.offset.x;
    }

    public set offsetX(value: number) {
        if (this.offset.x !== value) {
            this.offset.x = value;
            StateManager.propertyChanged(this, 'offsetX');
        }
    }

    public get offsetY(): number {
        return this.offset.y;
    }

    public set offsetY(value: number) {
        if (this.offset.y !== value) {
            this.offset.y = value;
            StateManager.propertyChanged(this, 'offsetY');
        }
    }

    public get offsetZ(): number {
        return this.offset.z;
    }

    public set offsetZ(value: number) {
        if (this.offset.z !== value) {
            this.offset.z = value;
            StateManager.propertyChanged(this, 'offsetZ');
        }
    }

    /**
     * Set offset to current machine position (XY only)
     */
    public setXYFromMachine(): void {
        // This will be called from UI components that have access to machine state
        // Implementation will be in the UI layer where MachineStateData is accessible
    }

    /**
     * Set offset to current machine position (XYZ)
     */
    public setXYZFromMachine(): void {
        // This will be called from UI components that have access to machine state
        // Implementation will be in the UI layer where MachineStateData is accessible
    }

    /**
     * Get the forward staging point for this tool holder
     * Applies horizontal clearance based on the machine's configured approach axis
     * Always uses tool holder Z position
     */
    public getForwardStagingPoint(): CNCPoint {
        const machineData = MachineData.Instance;
        const isYApproach = machineData.atcApproachAxis === 'Y';
        const x = isYApproach ? this.offsetX : this.offsetX + machineData.atcHorizontalClearance;
        const y = isYApproach ? this.offsetY + machineData.atcHorizontalClearance : this.offsetY;
        const z = this.offsetZ;
        return new CNCPoint(x, y, z, CoordinateType.MachineZero);
    }

    /**
     * Get the exact tool holder point
     */
    public getToolHolderPoint(): CNCPoint {
        return new CNCPoint(this.offsetX, this.offsetY, this.offsetZ, CoordinateType.MachineZero);
    }

    /**
     * Get the above staging point (above tool holder with vertical clearance)
     */
    public getAboveStagingPoint(): CNCPoint {
        const machineData = MachineData.Instance;
        const z = this.offsetZ + machineData.atcVerticalClearance;
        return new CNCPoint(this.offsetX, this.offsetY, z, CoordinateType.MachineZero);
    }

    /**
     * Generate G-code to move to forward staging point (Movement 1)
     * Returns array of G-code lines for safe approach to forward staging
     * @param feedRatePercent Optional feed rate percentage (default 100%)
     */
    public async generateMoveToForwardStagingGCode(feedRatePercent: number = 100): Promise<string[]> {
        const { CoordinateUtil } = await import('../../utils/CoordinateUtil');

        const machineData = MachineData.Instance;
        const current = ConfigurationState.Instance.currentMachinePoint;
        const target = this.getForwardStagingPoint();
        const zMax = CoordinateUtil.getZMax(CoordinateType.MachineZero);
        const z0Step = new CNCPoint(current.x, current.y, zMax, CoordinateType.MachineZero);
        const xyStep = new CNCPoint(target.x, target.y, zMax, CoordinateType.MachineZero);

        const z0StepMH = CoordinateUtil.toMachineHome(z0Step);
        const xyStepMH = CoordinateUtil.toMachineHome(xyStep);
        const targetMH = CoordinateUtil.toMachineHome(target);

        const feedMultiplier = feedRatePercent / 100;
        return [
            `G53 Z${z0StepMH.z.toFixed(4)} L${(machineData.zMoveToATC * feedMultiplier).toFixed(0)}`,
            `G53 X${xyStepMH.x.toFixed(4)} Y${xyStepMH.y.toFixed(4)} L${(machineData.xyMoveToATC * feedMultiplier).toFixed(0)}`,
            `G53 Z${targetMH.z.toFixed(4)} L${(machineData.zMoveToATC * feedMultiplier).toFixed(0)}`
        ];
    }

    /**
     * Generate G-code to move from forward staging to tool holder (Movement 2)
     * Returns array of G-code lines for slow approach to exact tool position
     * @param feedRatePercent Optional feed rate percentage (default 100%)
     */
    public async generateMoveToToolHolderGCode(feedRatePercent: number = 100): Promise<string[]> {
        const { CoordinateUtil } = await import('../../utils/CoordinateUtil');

        const machineData = MachineData.Instance;
        const target = this.getToolHolderPoint();
        const targetMH = CoordinateUtil.toMachineHome(target);

        const feedMultiplier = feedRatePercent / 100;
        return [
            `G53 X${targetMH.x.toFixed(4)} Y${targetMH.y.toFixed(4)} Z${targetMH.z.toFixed(4)} L${(machineData.xyDockSpeed * feedMultiplier).toFixed(0)}`
        ];
    }

    /**
     * Generate G-code to retract from tool holder to above staging (Movement 3)
     * Returns array of G-code lines for retract sequence
     * @param feedRatePercent Optional feed rate percentage (default 100%)
     */
    public async generateRetractFromToolHolderGCode(feedRatePercent: number = 100): Promise<string[]> {
        const { CoordinateUtil } = await import('../../utils/CoordinateUtil');

        const machineData = MachineData.Instance;
        const aboveStaging = this.getAboveStagingPoint();
        const forwardStaging = this.getForwardStagingPoint();
        const aboveStagingMH = CoordinateUtil.toMachineHome(aboveStaging);
        const forwardStagingXYMH = CoordinateUtil.toMachineHome(new CNCPoint(forwardStaging.x, forwardStaging.y, aboveStaging.z, CoordinateType.MachineZero));

        const feedMultiplier = feedRatePercent / 100;
        return [
            `G53 Z${aboveStagingMH.z.toFixed(4)} L${(machineData.zDockSpeed * feedMultiplier).toFixed(0)}`,
            `G53 X${forwardStagingXYMH.x.toFixed(4)} Y${forwardStagingXYMH.y.toFixed(4)} L${(machineData.xyDockSpeed * feedMultiplier).toFixed(0)}`
        ];
    }

    /**
     * Generate G-code to move to above staging point (Movement 4)
     * Returns array of G-code lines for safe approach to above staging
     * @param feedRatePercent Optional feed rate percentage (default 100%)
     */
    public async generateMoveToAboveStagingGCode(feedRatePercent: number = 100): Promise<string[]> {
        const { CoordinateUtil } = await import('../../utils/CoordinateUtil');

        const machineData = MachineData.Instance;
        const target = this.getAboveStagingPoint();
        const zMax = CoordinateUtil.getZMax(CoordinateType.MachineHome);

        const targetMH = CoordinateUtil.toMachineHome(target);

        const feedMultiplier = feedRatePercent / 100;
        return [
            `G53 Z${zMax.toFixed(4)} L${(machineData.zMoveToATC * feedMultiplier).toFixed(0)}`,
            `G53 X${targetMH.x.toFixed(4)} Y${targetMH.y.toFixed(4)} L${(machineData.xyMoveToATC * feedMultiplier).toFixed(0)}`,
            `G53 Z${targetMH.z.toFixed(4)} L${(machineData.zMoveToATC * feedMultiplier).toFixed(0)}`
        ];
    }

    /**
     * Generate G-code to move down from above staging to tool holder (Movement 5)
     * Returns array of G-code lines for Z-only move to pick up tool
     * @param feedRatePercent Optional feed rate percentage (default 100%)
     */
    public async generateMoveDownToToolHolderGCode(feedRatePercent: number = 100): Promise<string[]> {
        const { CoordinateUtil } = await import('../../utils/CoordinateUtil');

        const machineData = MachineData.Instance;
        const target = this.getToolHolderPoint();
        const targetMH = CoordinateUtil.toMachineHome(target);

        const feedMultiplier = feedRatePercent / 100;
        return [
            `G53 Z${targetMH.z.toFixed(4)} L${(machineData.zDockSpeed * feedMultiplier).toFixed(0)}`
        ];
    }

    /**
     * Generate G-code to retract with tool to forward staging and safe height (Movement 6)
     * Returns array of G-code lines for complete retract sequence
     * @param feedRatePercent Optional feed rate percentage (default 100%)
     */
    public async generateRetractWithToolGCode(feedRatePercent: number = 100): Promise<string[]> {
        const { CoordinateUtil } = await import('../../utils/CoordinateUtil');

        const machineData = MachineData.Instance;
        const forwardStaging = this.getForwardStagingPoint();
        const forwardStagingMH = CoordinateUtil.toMachineHome(forwardStaging);
        const zMax = CoordinateUtil.getZMax(CoordinateType.MachineHome);

        const feedMultiplier = feedRatePercent / 100;
        return [
            `G53 X${forwardStagingMH.x.toFixed(4)} Y${forwardStagingMH.y.toFixed(4)} Z${forwardStagingMH.z.toFixed(4)} L${(machineData.xyDockSpeed * feedMultiplier).toFixed(0)}`,
            `G53 Z${zMax.toFixed(4)} L${(machineData.zApproachSpeed * feedMultiplier).toFixed(0)}`
        ];
    }

    /**
     * Generate G-code to retract to Z safe height
     * Returns single G-code line for Z retract
     * @param feedRatePercent Optional feed rate percentage (default 100%)
     */
    public async generateRetractToZSafeGCode(feedRatePercent: number = 100): Promise<string[]> {
        const { CoordinateUtil } = await import('../../utils/CoordinateUtil');

        const machineData = MachineData.Instance;
        const zMax = CoordinateUtil.getZMax(CoordinateType.MachineHome);
        const feedMultiplier = feedRatePercent / 100;

        return [
            `G53 Z${zMax.toFixed(4)} L${(machineData.zApproachSpeed * feedMultiplier).toFixed(0)}`
        ];
    }

    /**
     * IStorable implementation
     */
    public toJSON(): object {
        const baseData = DataUtilities.getStorageData(this, ['_offset']);
        return {
            ...baseData,
            offset: this._offset.toJSON()
        };
    }

    public fromJSON(data: any): void {
        this.unregisterSubObjectListeners();
        DataUtilities.loadStorageData(this, data, ['_offset', 'offset']);
        const offsetData = data.offset || data._offset;
        if (offsetData) {
            this._offset.fromJSON(offsetData);
        }
        this.registerSubObjectListeners();
    }
}
