import { Box, Button, ButtonGroup } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { DataElement } from '../data/DataElement';
import { DataElementButton } from '../data/DataElementButton';
import { DataType, Declaration } from '../data/Declaration';
import { IPLCElement, PLCRenderMode, PLCValidationIssue } from '../data/IPLCElement';
import { PLCStage } from '../data/PLCStage';
import { IPLCSource, PLCProgramType, PLCSerializationHelper, PLCUtilities } from '../data/PLCUtilities';
import { BasePLCPredicate } from './BasePLCPredicate';

/**
 * Toggle actions for stages
 */
export enum StageToggleAction {
    TurnOn = 'Turn On',
    TurnOff = 'Turn Off',
    JumpTo = 'Jump To'
}

/**
 * Toggle stage predicate - controls stage activation (turn on/off/jump to)
 */
export class ToggleStagePredicate extends BasePLCPredicate {
    private _stageElement: DataElement;
    private _action: StageToggleAction = StageToggleAction.TurnOn;

    constructor() {
        super();
        this._stageElement = new DataElement();
        this._stageElement.requiresType = DataType.Stage;
        this._stageElement.allowNew = false;
        this._stageElement.needsWrite = true;  // We're writing to the stage (SET/RST/JMP)
        this._stageElement.setParentElement(this);
    }

    /**
     * Get the stage element
     */
    public get stageElement(): DataElement {
        return this._stageElement;
    }

    /**
     * Get the stage name (for backward compatibility and convenience)
     */
    public get stageName(): string {
        return this._stageElement.effectiveName || '';
    }

    /**
     * Set the stage name (for backward compatibility)
     */
    public set stageName(value: string) {
        this._stageElement.declarationName = value;
        StateManager.propertyChanged(this, 'stageName');
    }

    /**
     * Get the toggle action
     */
    public get action(): StageToggleAction {
        return this._action;
    }

    /**
     * Set the toggle action
     */
    public set action(value: StageToggleAction) {
        this._action = value;
        StateManager.propertyChanged(this, 'action');
    }

    /**
     * Get a short, single-line description for display in tree views
     * Example: "Turn on Setup stage"
     * @returns A human-readable summary of the stage action
     */
    public getShortDescription(): string {
        const stageName = this.stageName || '(no stage)';
        switch (this._action) {
            case StageToggleAction.TurnOn:
                return `Turn on ${stageName}`;
            case StageToggleAction.TurnOff:
                return `Turn off ${stageName}`;
            case StageToggleAction.JumpTo:
                return `Jump to ${stageName}`;
            default:
                return `Toggle ${stageName}`;
        }
    }

    /**
     * Get the PLC source for this element
     */
    public get plcSource(): IPLCSource | undefined {
        return super.plcSource;
    }

    /**
     * Override setParentElement to cascade to child DataElements
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        super.setParentElement(parent);
        if (this._stageElement) {
            this._stageElement.setParentElement(this);
        }
    }

    /**
     * Get the inline comment for this predicate based on stage and action
     */
    public getComment(): string {
        // If there's a manual comment, use that
        const manualComment = super.getComment();
        if (manualComment) {
            return manualComment;
        }

        // Otherwise, generate from action and stage name
        const stageName = this.stageName;
        if (stageName) {
            switch (this._action) {
                case StageToggleAction.TurnOn:
                    return `Turn on ${stageName} stage`;
                case StageToggleAction.TurnOff:
                    return `Turn off ${stageName} stage`;
                case StageToggleAction.JumpTo:
                    return `Jump to ${stageName} stage`;
            }
        }

        return '';
    }

    /**
     * Get all data elements used by this predicate
     */
    public getDataElements(): DataElement[] {
        return [this._stageElement];
    }

    /**
     * Render the predicate to JSX
     * @param mode Optional rendering mode (Edit, ReadOnly, or Disabled)
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        return <ToggleStagePredicateRenderer predicate={this} renderMode={mode} />;
    }

    /**
     * Get declarations that are used/referenced by this predicate
     */
    public getUsedDeclarations(): Declaration[] {
        // Stage operations reference stage names directly, not declarations
        return [];
    }

    /**
     * Get declarations that are added/defined by this predicate
     */
    public getAddedDeclarations(): Declaration[] {
        // Stage operations don't add declarations - they reference stage names directly
        return [];
    }

    /**
     * Get the PLC logic code for this predicate
     */
    public getPLCLogic(): string[] {
        if (!this.stageName) {
            return [];
        }

        switch (this._action) {
            case StageToggleAction.TurnOn:
                return [`SET ${this.stageName}`];
            case StageToggleAction.TurnOff:
                return [`RST ${this.stageName}`];
            case StageToggleAction.JumpTo:
                // Jump to uses JMP instruction
                return [`JMP ${this.stageName}`];
            default:
                return [];
        }
    }

    /**
     * Get available stages from the PLC program
     */
    private getAvailableStages(): PLCStage[] {
        const program = PLCUtilities.resolvePLCSource(this);
        if (program && 'stages' in program) {
            return (program as any).stages || [];
        }
        return [];
    }

    /**
     * Get validation issues for this predicate
     */
    public getValidationIssues(): PLCValidationIssue[] {
        const issues: PLCValidationIssue[] = [];
        const stageName = this.stageName;
        if (!stageName || stageName.trim() === '') {
            issues.push(new PLCValidationIssue(this, 'Stage name is required'));
        }
        return issues;
    }

    /**
     * Validate the predicate
     */
    public validate(): string | undefined {
        const stageName = this.stageName;
        if (!stageName || stageName.trim() === '') {
            return 'Stage name is required';
        }
        return undefined;
    }

    /**
     * Clone the predicate
     */
    public clone(): ToggleStagePredicate {
        const cloned = new ToggleStagePredicate();
        cloned.stageName = this.stageName;
        cloned.action = this._action;
        return cloned;
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        const baseData = PLCSerializationHelper.getStorageData(this, ['_stageElement']);
        return {
            type: 'ToggleStagePredicate',
            ...baseData,
            stageElement: this._stageElement.toJSON(),
            stageName: this.stageName,  // Keep for backward compatibility with tests
            action: this._action
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        if (!data) return;

        // Handle stageElement (new format)
        if (data.stageElement) {
            this._stageElement.fromJSON(data.stageElement);
            this._stageElement.setParentElement(this);
        }
        // Backward compatibility - support old stageName format
        else if (data.stageName !== undefined || data._stageName !== undefined) {
            const stageName = data.stageName || data._stageName;
            this._stageElement.declarationName = stageName;
            this._stageElement.setParentElement(this);
        }

        // Handle action
        if (data._action !== undefined) {
            this._action = data._action;
        } else if (data.action !== undefined) {
            this._action = data.action;
        }

        DataUtilities.loadStorageData(this, data, ['_stageName', '_action', 'stageName', 'action', 'stageElement']);
    }
}

/**
 * Functional component wrapper for ToggleStagePredicate rendering to allow hooks
 */
function ToggleStagePredicateRenderer({ predicate, renderMode }: { predicate: ToggleStagePredicate; renderMode?: PLCRenderMode }) {
    const colors = ConfigurationDataColors.Instance;
    const effectiveRenderMode = renderMode || PLCRenderMode.Edit;

    // Check if this predicate should be disabled:
    // 1. If renderMode is Disabled (parent condition is disabled), OR
    // 2. If predicate itself is disabled due to unavailable declarations
    const targetProgramType = predicate.plcSource?.getProgramType() || PLCProgramType.System;
    const isPredicateDisabled = effectiveRenderMode === PLCRenderMode.Disabled || predicate.isDisabled(PLCRenderMode.Edit, targetProgramType);
    const disabledStyle = isPredicateDisabled ? {
        opacity: 0.5,
        textDecoration: 'line-through',
        color: colors.mutedTextColor
    } : {};

    return (
        <ObserveState
            key="toggle-stage-predicate-render"
            profilerName="ToggleStagePredicate-render"
            listenTo={predicate}
            properties={['action']}

            control={() => {
                const currentAction = predicate.action;

                return (
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, ...disabledStyle }}>
                        {/* Action button group */}
                        <ButtonGroup
                            size="small"
                            disabled={renderMode === PLCRenderMode.ReadOnly || renderMode === PLCRenderMode.Disabled}
                        >
                            <Button
                                variant={currentAction === StageToggleAction.TurnOn ? 'contained' : 'outlined'}
                                onClick={() => predicate.action = StageToggleAction.TurnOn}
                                sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '12px',
                                    minWidth: 'auto',
                                    px: 1.5,
                                    py: 0.5,
                                    textTransform: 'uppercase',
                                    backgroundColor: currentAction === StageToggleAction.TurnOn ? colors.successColor : undefined,
                                    color: currentAction === StageToggleAction.TurnOn ? colors.lightTextColor : undefined,
                                    border: currentAction === StageToggleAction.TurnOn ? 'none' : `1px solid ${colors.mutedTextColor}`,
                                    '&:hover': {
                                        opacity: 0.9,
                                    }
                                }}
                            >
                                Turn On
                            </Button>
                            <Button
                                variant={currentAction === StageToggleAction.TurnOff ? 'contained' : 'outlined'}
                                onClick={() => predicate.action = StageToggleAction.TurnOff}
                                sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '12px',
                                    minWidth: 'auto',
                                    px: 1.5,
                                    py: 0.5,
                                    textTransform: 'uppercase',
                                    backgroundColor: currentAction === StageToggleAction.TurnOff ? colors.errorColor : undefined,
                                    color: currentAction === StageToggleAction.TurnOff ? colors.lightTextColor : undefined,
                                    border: currentAction === StageToggleAction.TurnOff ? 'none' : `1px solid ${colors.mutedTextColor}`,
                                    '&:hover': {
                                        opacity: 0.9,
                                    }
                                }}
                            >
                                Turn Off
                            </Button>
                            <Button
                                variant={currentAction === StageToggleAction.JumpTo ? 'contained' : 'outlined'}
                                onClick={() => predicate.action = StageToggleAction.JumpTo}
                                sx={{
                                    fontFamily: 'monospace',
                                    fontSize: '12px',
                                    minWidth: 'auto',
                                    px: 1.5,
                                    py: 0.5,
                                    textTransform: 'uppercase',
                                    backgroundColor: currentAction === StageToggleAction.JumpTo ? colors.primaryColor : undefined,
                                    color: currentAction === StageToggleAction.JumpTo ? colors.lightTextColor : undefined,
                                    border: currentAction === StageToggleAction.JumpTo ? 'none' : `1px solid ${colors.mutedTextColor}`,
                                    '&:hover': {
                                        opacity: 0.9,
                                    }
                                }}
                            >
                                Jump To
                            </Button>
                        </ButtonGroup>

                        {/* Stage label and dropdown */}
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                            <span style={{ fontSize: '14px', fontWeight: 500 }}>Stage:</span>
                            <Box sx={{ minWidth: 120 }}>
                                <DataElementButton
                                    dataElement={predicate.stageElement}
                                    renderMode={renderMode}
                                    renderAs="dropdown"
                                    dropdownLabel=""
                                />
                            </Box>
                        </Box>
                    </Box>
                );
            }}
        />
    );
}
