import { Grid, Typography } from '@mui/material';
import { ATCStructure } from '../../data/Machine/ATCStructure';
import { NumberInput } from './NumberInput';

interface ATCStructureComponentProps {
  atcStructure: ATCStructure;
  onChange: () => void;
}

export function ATCStructureComponent({
  atcStructure,
  onChange
}: ATCStructureComponentProps) {

  return (
    <>
      <Grid item xs={12}>
        <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>ATC Structural Dimensions</Typography>
      </Grid>

      {/* Post Dimensions */}
      <Grid item xs={12} md={4}>
        <NumberInput
          fullWidth
          label="Post Width"
          value={atcStructure.postWidth}
          onChange={(value) => {
            atcStructure.postWidth = value;
            onChange();
          }}
          margin="normal"
          precision={1}
        />
        <Typography variant="caption" color="text.secondary">
          Width of support posts
        </Typography>
      </Grid>

      <Grid item xs={12} md={4}>
        <NumberInput
          fullWidth
          label="Post Length"
          value={atcStructure.postLength}
          onChange={(value) => {
            atcStructure.postLength = value;
            onChange();
          }}
          margin="normal"
          precision={1}
        />
        <Typography variant="caption" color="text.secondary">
          Length of support posts
        </Typography>
      </Grid>

      {/* Bar Dimensions */}
      <Grid item xs={12} md={4}>
        <NumberInput
          fullWidth
          label="Bar Height"
          value={atcStructure.barHeight}
          onChange={(value) => {
            atcStructure.barHeight = value;
            onChange();
          }}
          margin="normal"
          precision={1}
        />
        <Typography variant="caption" color="text.secondary">
          Height of tool holder bar
        </Typography>
      </Grid>

      <Grid item xs={12} md={4}>
        <NumberInput
          fullWidth
          label="Bar Width"
          value={atcStructure.barWidth}
          onChange={(value) => {
            atcStructure.barWidth = value;
            onChange();
          }}
          margin="normal"
          precision={1}
        />
        <Typography variant="caption" color="text.secondary">
          Width of tool holder bar
        </Typography>
      </Grid>

      <Grid item xs={12} md={4}>
        <NumberInput
          fullWidth
          label="Bar Length"
          value={atcStructure.barLength}
          onChange={(value) => {
            atcStructure.barLength = value;
            onChange();
          }}
          margin="normal"
          precision={1}
        />
        <Typography variant="caption" color="text.secondary">
          Length of tool holder bar
        </Typography>
      </Grid>

      {/* Post Offset */}
      <Grid item xs={12} md={6}>
        <NumberInput
          fullWidth
          label="Post Offset from Rails"
          value={atcStructure.postOffsetFromRails}
          onChange={(value) => {
            atcStructure.postOffsetFromRails = value;
            onChange();
          }}
          margin="normal"
          precision={1}
        />
        <Typography variant="caption" color="text.secondary">
          Distance posts are offset from machine rails
        </Typography>
      </Grid>
    </>
  );
}
