import { Close as CloseIcon } from '@mui/icons-material';
import { Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, Divider, Grid, IconButton, Paper, Typography } from '@mui/material';
import { useState } from 'react';
import { CNCPoint } from '../../data/CNCPoint';
import { CoordinateType } from '../../data/Common/CoordinateType';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { IOStateData } from '../../data/IOStateData';
import { ATCToolClamp } from '../../data/Machine/ATCToolClamp';
import { MachineData } from '../../data/Machine/MachineData';
import { PLCOutputName } from '../../data/PLCIONames';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { Machine } from '../../machine/Machine';
import { ConfirmDialogManager } from '../../utils/ConfirmDialogManager';
import { CoordinateUtil } from '../../utils/CoordinateUtil';
import { NumberInput } from './NumberInput';

interface ATCToolClampComponentProps {
  toolClamp: ATCToolClamp;
  onChange: () => void;
  disableHorizontal?: boolean;
  disableZ?: boolean;
  approachAxis?: 'X' | 'Y';
}

export function ATCToolClampComponent({
  toolClamp,
  onChange,
  disableHorizontal = false,
  disableZ = false,
  approachAxis = 'Y'
}: ATCToolClampComponentProps) {

  const machine = MachineData.Instance;
  const config = ConfigurationData.Instance;
  const colors = ConfigurationDataColors.Instance;
  const [testDialogOpen, setTestDialogOpen] = useState(false);

  const handleSetXY = () => {
    toolClamp.offsetX = ConfigurationState.Instance.currentMachinePoint.x;
    toolClamp.offsetY = ConfigurationState.Instance.currentMachinePoint.y;
    onChange();
  };

  // Utility control handlers
  const handleToggleDustBoot = async () => {
    const output = IOStateData.Instance.getOutputByName(PLCOutputName.DustFootActivate);
    if (!output) {
      return;
    }

    const newState = !output.isActive;
    const gCode = newState ? output.getOnGCode() : output.getOffGCode();

    await Machine.getInstance().program.RunGCode([gCode], true);
  };

  const handleUnclampTool = async () => {
    const output = IOStateData.Instance.getOutputByName(PLCOutputName.UnclampTool);
    if (!output) {
      UserMessageQueue.Instance.addMessage('❌ Unclamp tool output not found');
      return;
    }

    // Turn on unclamp
    await Machine.getInstance().program.RunGCode([output.getOnGCode()], true);
  };

  const handleClampTool = async () => {
    const output = IOStateData.Instance.getOutputByName(PLCOutputName.UnclampTool);
    if (!output) {
      UserMessageQueue.Instance.addMessage('❌ Unclamp tool output not found');
      return;
    }

    // Turn off unclamp = clamped
    await Machine.getInstance().program.RunGCode([output.getOffGCode()], true);
  };

  const handleSetXYZ = () => {
    toolClamp.offsetX = ConfigurationState.Instance.currentMachinePoint.x;
    toolClamp.offsetY = ConfigurationState.Instance.currentMachinePoint.y;
    toolClamp.offsetZ = ConfigurationState.Instance.currentMachinePoint.z;
    onChange();
  };

  // Calculate approach points for testing
  const getForwardStagingPoint = (): CNCPoint => {
    return toolClamp.getForwardStagingPoint();
  };

  const getToolHolderPoint = (): CNCPoint => {
    return toolClamp.getToolHolderPoint();
  };

  const getAboveStagingPoint = (): CNCPoint => {
    return toolClamp.getAboveStagingPoint();
  };

  // Test 1: Go to forward staging point
  const handleGoToForwardStaging = async (feedRatePercent: number = 100) => {
    const target = getForwardStagingPoint();
    const zMax = CoordinateUtil.getZMax(CoordinateType.MachineZero);
    const xyStep = new CNCPoint(target.x, target.y, zMax, CoordinateType.MachineZero);

    const xyStepMH = CoordinateUtil.toMachineHome(xyStep);
    const targetMH = CoordinateUtil.toMachineHome(target);

    const feedMultiplier = feedRatePercent / 100;
    const gcodeLines = [
      `G53 Z${zMax.toFixed(4)} L${(machine.zMoveToATC * feedMultiplier).toFixed(0)}`,
      `G53 X${xyStepMH.x.toFixed(4)} Y${xyStepMH.y.toFixed(4)} L${(machine.xyMoveToATC * feedMultiplier).toFixed(0)}`,
      `G53 Z${targetMH.z.toFixed(4)} L${(machine.zMoveToATC * feedMultiplier).toFixed(0)}`
    ];

    const config = ConfigurationData.Instance;
    if (config.previewGCode) {
      setTestDialogOpen(false);
      ConfigurationState.Instance.showGCodePreview(`Test 1: Go to Forward Staging (${feedRatePercent}%) - Tool ${toolClamp.clampNumber}`, gcodeLines);
    } else {
      const confirmed = await ConfirmDialogManager.Instance.showConfirm({
        title: `Test 1: Go to Forward Staging (${feedRatePercent}%)`,
        message: `Move to forward staging point:\nX: ${target.x.toFixed(3)}, Y: ${target.y.toFixed(3)}, Z: ${target.z.toFixed(3)}`,
        confirmText: 'Execute',
        severity: 'warning'
      });
      if (confirmed) {
        setTestDialogOpen(false);
        await Machine.getInstance().program.RunGCode(gcodeLines, true);
      }
    }
  };

  // Test 2: Forward staging to tool holder position
  const handleForwardStagingToToolHolder = async (feedRatePercent: number = 100) => {
    const target = getToolHolderPoint();
    const targetMH = CoordinateUtil.toMachineHome(target);

    const feedMultiplier = feedRatePercent / 100;
    const gcodeLines = [
      `G53 X${targetMH.x.toFixed(4)} Y${targetMH.y.toFixed(4)} Z${targetMH.z.toFixed(4)} L${(machine.xyDockSpeed * feedMultiplier).toFixed(0)}`
    ];

    const config = ConfigurationData.Instance;
    if (config.previewGCode) {
      setTestDialogOpen(false);
      ConfigurationState.Instance.showGCodePreview(`Test 2: Forward Staging → Tool Holder (${feedRatePercent}%) - Tool ${toolClamp.clampNumber}`, gcodeLines);
    } else {
      const confirmed = await ConfirmDialogManager.Instance.showConfirm({
        title: `Test 2: Forward Staging → Tool Holder (${feedRatePercent}%)`,
        message: `Slow move to tool holder position:\nX: ${target.x.toFixed(3)}, Y: ${target.y.toFixed(3)}, Z: ${target.z.toFixed(3)}\n\nSpeed: ${(machine.xyDockSpeed * feedMultiplier).toFixed(0)} in/min`,
        confirmText: 'Execute',
        severity: 'warning'
      });
      if (confirmed) {
        setTestDialogOpen(false);
        await Machine.getInstance().program.RunGCode(gcodeLines, true);
      }
    }
  };

  // Test 3: Tool holder position to above staging
  const handleToolHolderToAboveStaging = async (feedRatePercent: number = 100) => {
    const aboveStaging = getAboveStagingPoint();
    const forwardStaging = getForwardStagingPoint();
    const aboveStagingMH = CoordinateUtil.toMachineHome(aboveStaging);
    const forwardStagingXYMH = CoordinateUtil.toMachineHome(new CNCPoint(forwardStaging.x, forwardStaging.y, aboveStaging.z, CoordinateType.MachineZero));

    const feedMultiplier = feedRatePercent / 100;
    const gcodeLines = [
      `G53 Z${aboveStagingMH.z.toFixed(4)} L${(machine.zDockSpeed * feedMultiplier).toFixed(0)}`,
      `G53 X${forwardStagingXYMH.x.toFixed(4)} Y${forwardStagingXYMH.y.toFixed(4)} L${(machine.xyDockSpeed * feedMultiplier).toFixed(0)}`
    ];

    const config = ConfigurationData.Instance;
    if (config.previewGCode) {
      setTestDialogOpen(false);
      ConfigurationState.Instance.showGCodePreview(`Test 3: Tool Holder → Above Staging (${feedRatePercent}%) - Tool ${toolClamp.clampNumber}`, gcodeLines);
    } else {
      const confirmed = await ConfirmDialogManager.Instance.showConfirm({
        title: `Test 3: Tool Holder → Above Staging (${feedRatePercent}%)`,
        message: `Retract to above staging and move XY to forward staging:\nZ: ${aboveStaging.z.toFixed(3)}\nX: ${forwardStaging.x.toFixed(3)}, Y: ${forwardStaging.y.toFixed(3)}\n\nSpeed: ${machine.zDockSpeed} in/min (Z), ${machine.xyDockSpeed} in/min (XY)`,
        confirmText: 'Execute',
        severity: 'warning'
      });
      if (confirmed) {
        setTestDialogOpen(false);
        await Machine.getInstance().program.RunGCode(gcodeLines, true);
      }
    }
  };

  // Test 4: Go to above staging
  const handleGoToAboveStaging = async (feedRatePercent: number = 100) => {
    const current = ConfigurationState.Instance.currentMachinePoint;
    const target = getAboveStagingPoint();
    const zMax = CoordinateUtil.getZMax(CoordinateType.MachineZero);
    const z0Step = new CNCPoint(current.x, current.y, zMax, CoordinateType.MachineZero);
    const xyStep = new CNCPoint(target.x, target.y, zMax, CoordinateType.MachineZero);

    const z0StepMH = CoordinateUtil.toMachineHome(z0Step);
    const xyStepMH = CoordinateUtil.toMachineHome(xyStep);
    const targetMH = CoordinateUtil.toMachineHome(target);

    const feedMultiplier = feedRatePercent / 100;
    const gcodeLines = [
      `G53 Z${z0StepMH.z.toFixed(4)} L${(machine.zMoveToATC * feedMultiplier).toFixed(0)}`,
      `G53 X${xyStepMH.x.toFixed(4)} Y${xyStepMH.y.toFixed(4)} L${(machine.xyMoveToATC * feedMultiplier).toFixed(0)}`,
      `G53 Z${targetMH.z.toFixed(4)} L${(machine.zMoveToATC * feedMultiplier).toFixed(0)}`
    ];

    const config = ConfigurationData.Instance;
    if (config.previewGCode) {
      setTestDialogOpen(false);
      ConfigurationState.Instance.showGCodePreview(`Test 4: Go to Above Staging (${feedRatePercent}%) - Tool ${toolClamp.clampNumber}`, gcodeLines);
    } else {
      const confirmed = await ConfirmDialogManager.Instance.showConfirm({
        title: `Test 4: Go to Above Staging (${feedRatePercent}%)`,
        message: `Move to above staging point:\nX: ${target.x.toFixed(3)}, Y: ${target.y.toFixed(3)}, Z: ${target.z.toFixed(3)}`,
        confirmText: 'Execute',
        severity: 'warning'
      });
      if (confirmed) {
        setTestDialogOpen(false);
        await Machine.getInstance().program.RunGCode(gcodeLines, true);
      }
    }
  };

  // Test 5: Above staging to tool holder position
  const handleAboveStagingToToolHolder = async (feedRatePercent: number = 100) => {
    const toolHolder = getToolHolderPoint();
    const toolHolderMH = CoordinateUtil.toMachineHome(toolHolder);

    const feedMultiplier = feedRatePercent / 100;
    const gcodeLines = [
      `G53 Z${toolHolderMH.z.toFixed(4)} L${(machine.zDockSpeed * feedMultiplier).toFixed(0)}`
    ];

    const config = ConfigurationData.Instance;
    if (config.previewGCode) {
      setTestDialogOpen(false);
      ConfigurationState.Instance.showGCodePreview(`Test 5: Above Staging → Tool Holder (${feedRatePercent}%) - Tool ${toolClamp.clampNumber}`, gcodeLines);
    } else {
      const confirmed = await ConfirmDialogManager.Instance.showConfirm({
        title: `Test 5: Above Staging → Tool Holder (${feedRatePercent}%)`,
        message: `Lower Z to tool holder position:\nZ: ${toolHolder.z.toFixed(3)}\n\nSpeed: ${(machine.zDockSpeed * feedMultiplier).toFixed(0)} in/min`,
        confirmText: 'Execute',
        severity: 'warning'
      });
      if (confirmed) {
        setTestDialogOpen(false);
        await Machine.getInstance().program.RunGCode(gcodeLines, true);
      }
    }
  };

  // Test 6: Tool holder position to forward staging
  const handleToolHolderToForwardStaging = async (feedRatePercent: number = 100) => {
    const forwardStaging = getForwardStagingPoint();
    const forwardStagingMH = CoordinateUtil.toMachineHome(forwardStaging);
    const zMax = CoordinateUtil.getZMax(CoordinateType.MachineZero);
    const zMaxMH = CoordinateUtil.toMachineHome(new CNCPoint(forwardStaging.x, forwardStaging.y, zMax, CoordinateType.MachineZero));

    const feedMultiplier = feedRatePercent / 100;
    const gcodeLines = [
      `G53 X${forwardStagingMH.x.toFixed(4)} Y${forwardStagingMH.y.toFixed(4)} Z${forwardStagingMH.z.toFixed(4)} L${(machine.xyDockSpeed * feedMultiplier).toFixed(0)}`,
      `G53 Z${zMaxMH.z.toFixed(4)} L${(machine.zApproachSpeed * feedMultiplier).toFixed(0)}`
    ];

    const config = ConfigurationData.Instance;
    if (config.previewGCode) {
      setTestDialogOpen(false);
      ConfigurationState.Instance.showGCodePreview(`Test 6: Tool Holder → Forward Staging (${feedRatePercent}%) - Tool ${toolClamp.clampNumber}`, gcodeLines);
    } else {
      const confirmed = await ConfirmDialogManager.Instance.showConfirm({
        title: `Test 6: Tool Holder → Forward Staging (${feedRatePercent}%)`,
        message: `Slow move to forward staging, then retract:\nX: ${forwardStaging.x.toFixed(3)}, Y: ${forwardStaging.y.toFixed(3)}, Z: ${forwardStaging.z.toFixed(3)}\nThen Z: ${zMax.toFixed(3)}\n\nSpeed: ${machine.xyDockSpeed} in/min (slow), ${machine.zApproachSpeed} in/min (fast)`,
        confirmText: 'Execute',
        severity: 'warning'
      });
      if (confirmed) {
        setTestDialogOpen(false);
        await Machine.getInstance().program.RunGCode(gcodeLines, true);
      }
    }
  };  // Determine which coordinate is the approach axis (X or Y)
  const isYApproach = approachAxis === 'Y';
  const approachAxisLabel = approachAxis;
  const perpendicularAxisLabel = isYApproach ? 'X' : 'Y';

  return (
    <Grid item xs={12}>
      <Paper elevation={1} sx={{ p: 2, mb: 1 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={2}>
            <Typography variant="subtitle2">
              Tool {toolClamp.clampNumber}
            </Typography>
          </Grid>

          {/* Approach axis (shared when enabled) */}
          <Grid item xs={12} md={3}>
            <NumberInput
              fullWidth
              label={`${approachAxisLabel} Offset (approach axis)`}
              value={isYApproach ? toolClamp.offsetY : toolClamp.offsetX}
              onChange={(value) => {
                if (isYApproach) {
                  toolClamp.offsetY = value;
                } else {
                  toolClamp.offsetX = value;
                }
                onChange();
              }}
              margin="normal"
              precision={3}
              size="small"
              disabled={disableHorizontal}
            />
          </Grid>

          {/* Perpendicular axis (always editable) */}
          <Grid item xs={12} md={3}>
            <NumberInput
              fullWidth
              label={`${perpendicularAxisLabel} Offset (perpendicular)`}
              value={isYApproach ? toolClamp.offsetX : toolClamp.offsetY}
              onChange={(value) => {
                if (isYApproach) {
                  toolClamp.offsetX = value;
                } else {
                  toolClamp.offsetY = value;
                }
                onChange();
              }}
              margin="normal"
              precision={3}
              size="small"
            />
          </Grid>

          {/* Z Offset - disabled if sharing */}
          <Grid item xs={12} md={4}>
            <NumberInput
              fullWidth
              label="Z Offset"
              value={toolClamp.offsetZ}
              onChange={(value) => {
                toolClamp.offsetZ = value;
                onChange();
              }}
              margin="normal"
              precision={3}
              size="small"
              disabled={disableZ}
            />
          </Grid>

          <Grid item xs={12} sx={{ display: 'flex', gap: 2, justifyContent: 'flex-start', mt: -1 }}>
            <Button
              variant="text"
              size="small"
              onClick={handleSetXY}
            >
              Set XY
            </Button>
            <Button
              variant="text"
              size="small"
              onClick={handleSetXYZ}
            >
              Set XYZ
            </Button>
            <Button
              variant="outlined"
              size="small"
              onClick={() => setTestDialogOpen(true)}
              sx={{ ml: 2 }}
            >
              Test Movements
            </Button>
          </Grid>
        </Grid>
      </Paper>

      {/* Test Movements Dialog */}
      <Dialog
        open={testDialogOpen}
        onClose={() => setTestDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          backgroundColor: colors.primaryColor,
          color: colors.lightTextColor,
          py: 2,
          px: 3
        }}>
          Test Movements - Tool {toolClamp.clampNumber}
          <IconButton
            onClick={() => setTestDialogOpen(false)}
            sx={{
              color: colors.lightTextColor,
              '&:hover': {
                backgroundColor: `${colors.lightTextColor}1A`
              }
            }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent>
          <Box sx={{ mt: 3, mb: 3 }}>
            <Typography variant="subtitle2" gutterBottom>Current Position:</Typography>
            <Typography variant="body2" sx={{ fontFamily: 'monospace', mb: 2 }}>
              X: {ConfigurationState.Instance.currentMachinePoint.x.toFixed(3)},
              Y: {ConfigurationState.Instance.currentMachinePoint.y.toFixed(3)},
              Z: {ConfigurationState.Instance.currentMachinePoint.z.toFixed(3)}
            </Typography>

            <Typography variant="subtitle2" gutterBottom>Key Positions:</Typography>
            <Box sx={{ pl: 2, mb: 3 }}>
              <Typography variant="body2" sx={{ fontFamily: 'monospace', color: 'primary.main', mb: 0.5 }}>
                Tool Holder (MH): X: {CoordinateUtil.toMachineHome(getToolHolderPoint()).x.toFixed(3)}, Y: {CoordinateUtil.toMachineHome(getToolHolderPoint()).y.toFixed(3)}, Z: {CoordinateUtil.toMachineHome(getToolHolderPoint()).z.toFixed(3)}
              </Typography>
              <Typography variant="body2" sx={{ fontFamily: 'monospace', color: 'primary.main', fontSize: '0.75rem', mb: 1, opacity: 0.6 }}>
                Tool Holder (MZ): X: {getToolHolderPoint().x.toFixed(3)}, Y: {getToolHolderPoint().y.toFixed(3)}, Z: {getToolHolderPoint().z.toFixed(3)}
              </Typography>
              <Divider sx={{ my: 1 }} />
              <Typography variant="body2" sx={{ fontFamily: 'monospace', color: 'secondary.main', mb: 0.5 }}>
                Forward Staging (MH): X: {CoordinateUtil.toMachineHome(getForwardStagingPoint()).x.toFixed(3)}, Y: {CoordinateUtil.toMachineHome(getForwardStagingPoint()).y.toFixed(3)}, Z: {CoordinateUtil.toMachineHome(getForwardStagingPoint()).z.toFixed(3)}
              </Typography>
              <Typography variant="body2" sx={{ fontFamily: 'monospace', color: 'secondary.main', fontSize: '0.75rem', mb: 1, opacity: 0.6 }}>
                Forward Staging (MZ): X: {getForwardStagingPoint().x.toFixed(3)}, Y: {getForwardStagingPoint().y.toFixed(3)}, Z: {getForwardStagingPoint().z.toFixed(3)}
              </Typography>
              <Divider sx={{ my: 1 }} />
              <Typography variant="body2" sx={{ fontFamily: 'monospace', color: 'success.main', mb: 0.5 }}>
                Above Staging (MH): X: {CoordinateUtil.toMachineHome(getAboveStagingPoint()).x.toFixed(3)}, Y: {CoordinateUtil.toMachineHome(getAboveStagingPoint()).y.toFixed(3)}, Z: {CoordinateUtil.toMachineHome(getAboveStagingPoint()).z.toFixed(3)}
              </Typography>
              <Typography variant="body2" sx={{ fontFamily: 'monospace', color: 'success.main', fontSize: '0.75rem', opacity: 0.6 }}>
                Above Staging (MZ): X: {getAboveStagingPoint().x.toFixed(3)}, Y: {getAboveStagingPoint().y.toFixed(3)}, Z: {getAboveStagingPoint().z.toFixed(3)}
              </Typography>
            </Box>

            <Divider sx={{ my: 2 }} />

            {/* Test 1: Go to forward staging */}
            <Paper elevation={2} sx={{ p: 2, mb: 2, backgroundColor: ConfigurationDataColors.Instance.selectionColor }}>
              <Typography variant="h6" gutterBottom>Test 1: Go to Forward Staging</Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                Safe movement: Z0 → XY → Z down
              </Typography>
              <Box sx={{ mb: 2, pl: 2, borderLeft: `3px solid ${colors.infoColor}`, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, p: 1, fontFamily: 'monospace', fontSize: '0.75rem' }}>
                {(() => {
                  const current = ConfigurationState.Instance.currentMachinePoint;
                  const target = getForwardStagingPoint();
                  const zMax = CoordinateUtil.getZMax(CoordinateType.MachineZero);
                  const z0Step = new CNCPoint(current.x, current.y, zMax, CoordinateType.MachineZero);
                  const xyStep = new CNCPoint(target.x, target.y, zMax, CoordinateType.MachineZero);
                  const z0StepMH = CoordinateUtil.toMachineHome(z0Step);
                  const xyStepMH = CoordinateUtil.toMachineHome(xyStep);
                  const targetMH = CoordinateUtil.toMachineHome(target);
                  return (
                    <>
                      <div>G53 Z{z0StepMH.z.toFixed(4)} L{machine.zMoveToATC.toFixed(0)}</div>
                      <div>G53 X{xyStepMH.x.toFixed(4)} Y{xyStepMH.y.toFixed(4)} L{machine.xyMoveToATC.toFixed(0)}</div>
                      <div>G53 Z{targetMH.z.toFixed(4)} L{machine.zMoveToATC.toFixed(0)}</div>
                    </>
                  );
                })()}
              </Box>
              <Grid container spacing={1}>
                <Grid item xs={4}>
                  <Button variant="contained" onClick={() => handleGoToForwardStaging(100)} fullWidth size="small">
                    Run 100%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" onClick={() => handleGoToForwardStaging(50)} fullWidth size="small">
                    Run 50%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" onClick={() => handleGoToForwardStaging(25)} fullWidth size="small">
                    Run 25%
                  </Button>
                </Grid>
              </Grid>
            </Paper>

            {/* Test 2: Forward staging to tool holder */}
            <Paper elevation={2} sx={{ p: 2, mb: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor }}>
              <Typography variant="h6" gutterBottom>Test 2: Forward Staging → Tool Holder</Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                Direct slow move to exact tool holder position (Speed: {machine.xyDockSpeed} in/min)
              </Typography>
              <Box sx={{ mb: 2, pl: 2, borderLeft: `3px solid ${colors.warningColor}`, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, p: 1, fontFamily: 'monospace', fontSize: '0.75rem' }}>
                {(() => {
                  const target = getToolHolderPoint();
                  const targetMH = CoordinateUtil.toMachineHome(target);
                  return (
                    <div>G53 X{targetMH.x.toFixed(4)} Y{targetMH.y.toFixed(4)} Z{targetMH.z.toFixed(4)} L{machine.xyDockSpeed.toFixed(0)}</div>
                  );
                })()}
              </Box>
              <Grid container spacing={1}>
                <Grid item xs={4}>
                  <Button variant="contained" color="warning" onClick={() => handleForwardStagingToToolHolder(100)} fullWidth size="small">
                    Run 100%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" color="warning" onClick={() => handleForwardStagingToToolHolder(50)} fullWidth size="small">
                    Run 50%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" color="warning" onClick={() => handleForwardStagingToToolHolder(25)} fullWidth size="small">
                    Run 25%
                  </Button>
                </Grid>
              </Grid>
            </Paper>

            {/* Test 3: Tool holder to above staging */}
            <Paper elevation={2} sx={{ p: 2, mb: 2, backgroundColor: ConfigurationDataColors.Instance.selectionColor }}>
              <Typography variant="h6" gutterBottom>Test 3: Tool Holder → Above Staging</Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                Retract Z, then move XY to forward staging - Speed: {machine.zDockSpeed} in/min (Z), {machine.xyDockSpeed} in/min (XY)
              </Typography>
              <Box sx={{ mb: 2, pl: 2, borderLeft: `3px solid ${colors.successColor}`, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, p: 1, fontFamily: 'monospace', fontSize: '0.75rem' }}>
                {(() => {
                  const aboveStaging = getAboveStagingPoint();
                  const forwardStaging = getForwardStagingPoint();
                  const aboveStagingMH = CoordinateUtil.toMachineHome(aboveStaging);
                  const forwardStagingXYMH = CoordinateUtil.toMachineHome(new CNCPoint(forwardStaging.x, forwardStaging.y, aboveStaging.z, CoordinateType.MachineZero));
                  return (
                    <>
                      <div>G53 Z{aboveStagingMH.z.toFixed(4)} L{machine.zDockSpeed.toFixed(0)}</div>
                      <div>G53 X{forwardStagingXYMH.x.toFixed(4)} Y{forwardStagingXYMH.y.toFixed(4)} L{machine.xyDockSpeed.toFixed(0)}</div>
                    </>
                  );
                })()}
              </Box>
              <Grid container spacing={1}>
                <Grid item xs={4}>
                  <Button variant="contained" color="success" onClick={() => handleToolHolderToAboveStaging(100)} fullWidth size="small">
                    Run 100%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" color="success" onClick={() => handleToolHolderToAboveStaging(50)} fullWidth size="small">
                    Run 50%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" color="success" onClick={() => handleToolHolderToAboveStaging(25)} fullWidth size="small">
                    Run 25%
                  </Button>
                </Grid>
              </Grid>
            </Paper>

            {/* Test 4: Go to above staging */}
            <Paper elevation={2} sx={{ p: 2, mb: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor }}>
              <Typography variant="h6" gutterBottom>Test 4: Go to Above Staging</Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                Safe movement: Z0 → XY → Z down
              </Typography>
              <Box sx={{ mb: 2, pl: 2, borderLeft: `3px solid ${colors.errorColor}`, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, p: 1, fontFamily: 'monospace', fontSize: '0.75rem' }}>
                {(() => {
                  const current = ConfigurationState.Instance.currentMachinePoint;
                  const target = getAboveStagingPoint();
                  const zMax = CoordinateUtil.getZMax(CoordinateType.MachineZero);
                  const z0Step = new CNCPoint(current.x, current.y, zMax, CoordinateType.MachineZero);
                  const xyStep = new CNCPoint(target.x, target.y, zMax, CoordinateType.MachineZero);
                  const z0StepMH = CoordinateUtil.toMachineHome(z0Step);
                  const xyStepMH = CoordinateUtil.toMachineHome(xyStep);
                  const targetMH = CoordinateUtil.toMachineHome(target);
                  return (
                    <>
                      <div>G53 Z{z0StepMH.z.toFixed(4)} L{machine.zMoveToATC.toFixed(0)}</div>
                      <div>G53 X{xyStepMH.x.toFixed(4)} Y{xyStepMH.y.toFixed(4)} L{machine.xyMoveToATC.toFixed(0)}</div>
                      <div>G53 Z{targetMH.z.toFixed(4)} L{machine.zMoveToATC.toFixed(0)}</div>
                    </>
                  );
                })()}
              </Box>
              <Grid container spacing={1}>
                <Grid item xs={4}>
                  <Button variant="contained" color="secondary" onClick={() => handleGoToAboveStaging(100)} fullWidth size="small">
                    Run 100%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" color="secondary" onClick={() => handleGoToAboveStaging(50)} fullWidth size="small">
                    Run 50%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" color="secondary" onClick={() => handleGoToAboveStaging(25)} fullWidth size="small">
                    Run 25%
                  </Button>
                </Grid>
              </Grid>
            </Paper>

            {/* Test 5: Above staging to tool holder */}
            <Paper elevation={2} sx={{ p: 2, mb: 2, backgroundColor: ConfigurationDataColors.Instance.selectionColor }}>
              <Typography variant="h6" gutterBottom>Test 5: Above Staging → Tool Holder</Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                Lower Z to tool holder (assumes already at above staging XY) - Speed: {machine.zDockSpeed} in/min
              </Typography>
              <Box sx={{ mb: 2, pl: 2, borderLeft: `3px solid ${colors.primaryColor}`, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, p: 1, fontFamily: 'monospace', fontSize: '0.75rem' }}>
                {(() => {
                  const toolHolder = getToolHolderPoint();
                  const toolHolderMH = CoordinateUtil.toMachineHome(toolHolder);
                  return (
                    <div>G53 Z{toolHolderMH.z.toFixed(4)} L{machine.zDockSpeed.toFixed(0)}</div>
                  );
                })()}
              </Box>
              <Grid container spacing={1}>
                <Grid item xs={4}>
                  <Button variant="contained" sx={{ bgcolor: ConfigurationDataColors.Instance.infoColor }} onClick={() => handleAboveStagingToToolHolder(100)} fullWidth size="small">
                    Run 100%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" sx={{ color: ConfigurationDataColors.Instance.infoColor, borderColor: ConfigurationDataColors.Instance.infoColor }} onClick={() => handleAboveStagingToToolHolder(50)} fullWidth size="small">
                    Run 50%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" sx={{ color: ConfigurationDataColors.Instance.infoColor, borderColor: ConfigurationDataColors.Instance.infoColor }} onClick={() => handleAboveStagingToToolHolder(25)} fullWidth size="small">
                    Run 25%
                  </Button>
                </Grid>
              </Grid>
            </Paper>

            {/* Test 6: Tool holder to forward staging */}
            <Paper elevation={2} sx={{ p: 2, mb: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor }}>
              <Typography variant="h6" gutterBottom>Test 6: Tool Holder → Forward Staging</Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                Slow move to forward staging, then fast retract to zMax
              </Typography>
              <Box sx={{ mb: 2, pl: 2, borderLeft: `3px solid ${colors.warningColor}`, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, p: 1, fontFamily: 'monospace', fontSize: '0.75rem' }}>
                {(() => {
                  const forwardStaging = getForwardStagingPoint();
                  const forwardStagingMH = CoordinateUtil.toMachineHome(forwardStaging);
                  const zMax = CoordinateUtil.getZMax(CoordinateType.MachineZero);
                  const zMaxMH = CoordinateUtil.toMachineHome(new CNCPoint(forwardStaging.x, forwardStaging.y, zMax, CoordinateType.MachineZero));
                  return (
                    <>
                      <div>G53 X{forwardStagingMH.x.toFixed(4)} Y{forwardStagingMH.y.toFixed(4)} Z{forwardStagingMH.z.toFixed(4)} L{machine.xyDockSpeed.toFixed(0)}</div>
                      <div>G53 Z{zMaxMH.z.toFixed(4)} L{machine.zApproachSpeed.toFixed(0)}</div>
                    </>
                  );
                })()}
              </Box>
              <Grid container spacing={1}>
                <Grid item xs={4}>
                  <Button variant="contained" sx={{ bgcolor: ConfigurationDataColors.Instance.warningColor }} onClick={() => handleToolHolderToForwardStaging(100)} fullWidth size="small">
                    Run 100%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" sx={{ color: ConfigurationDataColors.Instance.warningColor, borderColor: ConfigurationDataColors.Instance.warningColor }} onClick={() => handleToolHolderToForwardStaging(50)} fullWidth size="small">
                    Run 50%
                  </Button>
                </Grid>
                <Grid item xs={4}>
                  <Button variant="outlined" sx={{ color: ConfigurationDataColors.Instance.warningColor, borderColor: ConfigurationDataColors.Instance.warningColor }} onClick={() => handleToolHolderToForwardStaging(25)} fullWidth size="small">
                    Run 25%
                  </Button>
                </Grid>
              </Grid>
            </Paper>

            <Divider sx={{ my: 3 }} />

            {/* Utility Controls */}
            <Typography variant="h6" gutterBottom>Utility Controls</Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              Control dust boot and tool clamping mechanism
            </Typography>

            <Grid container spacing={2}>
              <Grid item xs={12} md={4}>
                <Button
                  variant="outlined"
                  onClick={handleToggleDustBoot}
                  fullWidth
                  sx={{ py: 1.5 }}
                >
                  Toggle Dust Boot
                </Button>
              </Grid>
              <Grid item xs={12} md={4}>
                <Button
                  variant="outlined"
                  color="error"
                  onClick={handleUnclampTool}
                  fullWidth
                  sx={{ py: 1.5 }}
                >
                  Unclamp Tool
                </Button>
              </Grid>
              <Grid item xs={12} md={4}>
                <Button
                  variant="outlined"
                  color="success"
                  onClick={handleClampTool}
                  fullWidth
                  sx={{ py: 1.5 }}
                >
                  Clamp Tool
                </Button>
              </Grid>
            </Grid>
          </Box>
        </DialogContent>
        <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
          <Button
            onClick={() => setTestDialogOpen(false)}
            variant="contained"
            sx={{
              backgroundColor: colors.primaryColor,
              '&:hover': {
                backgroundColor: colors.primaryColor,
                filter: 'brightness(0.9)'
              }
            }}
          >
            Close
          </Button>
        </DialogActions>
      </Dialog>
    </Grid>
  );
}
