import { LogCategory, Logger } from '../utils/Logger';
import { SingletonRegistry } from '../utils/SingletonRegistry';
import { StateManager } from '../utils/statemanager/StateManager';
import { DataUtilities } from '../utils/storage/DataUtilities';
import { SaveableDataBase } from './Common/SaveableDataBase';
import { DataFileConstants } from './DataFileConstants';

/**
 * Interface for tracking action usage statistics
 */
export interface ActionUsageStats {
  actionId: string;
  count: number;
  lastUsed: Date;
}

/**
 * Data class for storing user action preferences and usage statistics
 * Uses the same SaveableDataBase pattern as ConfigurationData for persistence
 */
export class UserActionData extends SaveableDataBase {
  /**
   * Filename for saving/loading user action data
   */
  protected get filename(): string {
    return DataFileConstants.USER_ACTION_DATA;
  }

  /**
   * Array of favorite action IDs
   */
  private _favoriteActionIds: string[] = [];

  /**
   * Array of home page action IDs
   */
  private _homePageActionIds: string[] = [];

  /**
   * Map of action usage statistics by action ID
   */
  private _actionUsageStats: Map<string, ActionUsageStats> = new Map();

  /**
   * Array of user-defined action definitions (not code-defined actions)
   * Only stores actions created by users through the UI
   */
  private _userDefinedActions: any[] = [];

  /**
   * Singleton instance
   */
  public static get Instance(): UserActionData {
    if (!SingletonRegistry.UserActionData) {
      const instance = new UserActionData();
      // Setup auto-save after instance is fully created
      instance.setupAutoSave();
    }
    return SingletonRegistry.UserActionData!;
  }

  private constructor() {
    super();

    // Register this singleton - will throw if a duplicate is created
    SingletonRegistry.UserActionData = this;

    // Note: setupAutoSave() will be called after instance creation to avoid constructor issues
  }

  /**
   * Get all favorite action IDs
   */
  public get favoriteActionIds(): string[] {
    return [...this._favoriteActionIds];
  }

  /**
   * Check if an action is marked as favorite
   * @param actionId The action ID to check
   * @returns True if the action is a favorite
   */
  public isFavorite(actionId: string): boolean {
    return this._favoriteActionIds.includes(actionId);
  }

  /**
   * Add an action to favorites
   * @param actionId The action ID to add to favorites
   */
  public addFavorite(actionId: string): void {
    if (!this._favoriteActionIds.includes(actionId)) {
      this._favoriteActionIds.push(actionId);
      StateManager.propertyChanged(this, 'favoriteActionIds');
    }
  }

  /**
   * Remove an action from favorites
   * @param actionId The action ID to remove from favorites
   */
  public removeFavorite(actionId: string): void {
    const index = this._favoriteActionIds.indexOf(actionId);
    if (index !== -1) {
      this._favoriteActionIds.splice(index, 1);
      StateManager.propertyChanged(this, 'favoriteActionIds');
    }
  }

  /**
   * Toggle an action's favorite status
   * @param actionId The action ID to toggle
   */
  public toggleFavorite(actionId: string): void {
    if (this.isFavorite(actionId)) {
      this.removeFavorite(actionId);
    } else {
      this.addFavorite(actionId);
    }
  }

  /**
   * Clear all favorites
   */
  public clearAllFavorites(): void {
    if (this._favoriteActionIds.length > 0) {
      this._favoriteActionIds = [];
      this.manualSave();
      StateManager.propertyChanged(this, 'favoriteActionIds');
    }
  }

  /**
   * Get the number of favorite actions
   */
  public get favoriteCount(): number {
    return this._favoriteActionIds.length;
  }

  /**
   * Get all user-defined actions
   */
  public get userDefinedActions(): any[] {
    return [...this._userDefinedActions];
  }

  /**
   * Add a user-defined action
   * @param actionDefinition The action definition to add
   */
  public addUserDefinedAction(actionDefinition: any): void {
    if (!this._userDefinedActions.find(a => a.id === actionDefinition.id)) {
      this._userDefinedActions.push(actionDefinition);
      StateManager.propertyChanged(this, 'userDefinedActions');
    }
  }

  /**
   * Update a user-defined action
   * @param actionDefinition The updated action definition
   */
  public updateUserDefinedAction(actionDefinition: any): void {
    const index = this._userDefinedActions.findIndex(a => a.id === actionDefinition.id);
    if (index !== -1) {
      this._userDefinedActions[index] = actionDefinition;
      StateManager.propertyChanged(this, 'userDefinedActions');
    }
  }

  /**
   * Remove a user-defined action
   * @param actionId The action ID to remove
   */
  public removeUserDefinedAction(actionId: string): void {
    const index = this._userDefinedActions.findIndex(a => a.id === actionId);
    if (index !== -1) {
      this._userDefinedActions.splice(index, 1);
      // Also remove from favorites and home page
      this.removeFavorite(actionId);
      this.removeFromHomePage(actionId);
      StateManager.propertyChanged(this, 'userDefinedActions');
    }
  }

  /**
   * Get all home page action IDs
   */
  public get homePageActionIds(): string[] {
    return [...this._homePageActionIds];
  }

  /**
   * Check if an action is marked for home page
   * @param actionId The action ID to check
   * @returns True if the action is on the home page
   */
  public isOnHomePage(actionId: string): boolean {
    return this._homePageActionIds.includes(actionId);
  }

  /**
   * Add an action to home page
   * @param actionId The action ID to add to home page
   */
  public addToHomePage(actionId: string): void {
    if (!this._homePageActionIds.includes(actionId)) {
      this._homePageActionIds.push(actionId);
      StateManager.propertyChanged(this, 'homePageActionIds');
    }
  }

  /**
   * Remove an action from home page
   * @param actionId The action ID to remove from home page
   */
  public removeFromHomePage(actionId: string): void {
    const index = this._homePageActionIds.indexOf(actionId);
    if (index !== -1) {
      this._homePageActionIds.splice(index, 1);
      StateManager.propertyChanged(this, 'homePageActionIds');
    }
  }

  /**
   * Toggle an action's home page status
   * @param actionId The action ID to toggle
   */
  public toggleHomePage(actionId: string): void {
    if (this.isOnHomePage(actionId)) {
      this.removeFromHomePage(actionId);
    } else {
      this.addToHomePage(actionId);
    }
  }

  /**
   * Clear all home page actions
   */
  public clearAllHomePageActions(): void {
    if (this._homePageActionIds.length > 0) {
      this._homePageActionIds = [];
      this.manualSave();
      StateManager.propertyChanged(this, 'homePageActionIds');
    }
  }

  /**
   * Get the number of home page actions
   */
  public get homePageCount(): number {
    return this._homePageActionIds.length;
  }

  /**
   * Record that an action was executed
   * @param actionId The action ID that was executed
   */
  public recordActionUsage(actionId: string): void {
    // Defensive check - ensure _actionUsageStats is a Map
    if (!this._actionUsageStats || typeof this._actionUsageStats.get !== 'function') {
      Logger.Instance.logError(LogCategory.DataManager, 'UserActionData: _actionUsageStats is not a Map, reinitializing. Current value:', this._actionUsageStats);
      this._actionUsageStats = new Map();
    }

    const existing = this._actionUsageStats.get(actionId);
    if (existing) {
      existing.count++;
      existing.lastUsed = new Date();
    } else {
      this._actionUsageStats.set(actionId, {
        actionId,
        count: 1,
        lastUsed: new Date()
      });
    }
    StateManager.propertyChanged(this, 'actionUsageStats');
  }

  /**
   * Get usage statistics for an action
   * @param actionId The action ID to get stats for
   * @returns Usage statistics or undefined if never used
   */
  public getActionUsage(actionId: string): ActionUsageStats | undefined {
    // Defensive check - ensure _actionUsageStats is a Map
    if (!this._actionUsageStats || typeof this._actionUsageStats.get !== 'function') {
      Logger.Instance.logError(LogCategory.DataManager, 'UserActionData: _actionUsageStats is not a Map, reinitializing. Current value:', this._actionUsageStats);
      this._actionUsageStats = new Map();
      return undefined;
    }
    return this._actionUsageStats.get(actionId);
  }

  /**
   * Get all action usage statistics
   * @returns Array of all usage statistics
   */
  public getAllActionUsage(): ActionUsageStats[] {
    return Array.from(this._actionUsageStats.values());
  }

  /**
   * Get the most popular actions (by usage count)
   * @param limit Maximum number of actions to return
   * @returns Array of most popular actions sorted by usage count
   */
  public getMostPopularActions(limit: number = 10): ActionUsageStats[] {
    return Array.from(this._actionUsageStats.values())
      .sort((a, b) => b.count - a.count)
      .slice(0, limit);
  }

  /**
   * Get recently used actions (by last used date)
   * @param limit Maximum number of actions to return
   * @returns Array of recently used actions sorted by last used date
   */
  public getRecentlyUsedActions(limit: number = 10): ActionUsageStats[] {
    return Array.from(this._actionUsageStats.values())
      .sort((a, b) => b.lastUsed.getTime() - a.lastUsed.getTime())
      .slice(0, limit);
  }

  /**
   * Clear all usage statistics
   */
  public clearUsageStats(): void {
    this._actionUsageStats.clear();
    StateManager.propertyChanged(this, 'actionUsageStats');
  }

  /**
   * Serialize to JSON
   */
  public toJSON(): any {
    const baseData = DataUtilities.getStorageData(this, ['_actionUsageStats', '_userDefinedActions']);

    // Convert Map to array for serialization
    const usageStatsArray = Array.from(this._actionUsageStats.values()).map(stats => ({
      ...stats,
      lastUsed: stats.lastUsed.toISOString() // Convert Date to string
    }));

    return {
      ...baseData,
      actionUsageStats: usageStatsArray,  // Clean name without underscore
      userDefinedActions: this._userDefinedActions
    };
  }

  /**
   * Deserialize from JSON
   */
  public fromJSON(data: any): void {
    DataUtilities.loadStorageData(this, data, ['_actionUsageStats', '_userDefinedActions', 'actionUsageStats', 'userDefinedActions']);

    // Ensure _actionUsageStats is initialized
    if (!this._actionUsageStats || typeof this._actionUsageStats.clear !== 'function') {
      this._actionUsageStats = new Map();
    }

    // Support both old (_actionUsageStats) and new (actionUsageStats) property names for backward compatibility
    const usageStatsData = data?.actionUsageStats || data?._actionUsageStats;

    // Handle Map deserialization separately
    if (Array.isArray(usageStatsData)) {
      this._actionUsageStats.clear();
      usageStatsData.forEach((stats: any) => {
        this._actionUsageStats.set(stats.actionId, {
          actionId: stats.actionId,
          count: stats.count || 0,
          lastUsed: new Date(stats.lastUsed || Date.now())
        });
      });
    } else {
      // Clear the map if no data provided (reset scenario)
      this._actionUsageStats.clear();
    }

    // Handle user-defined actions - support both property names
    const userDefinedData = data?.userDefinedActions || data?._userDefinedActions;
    if (userDefinedData) {
      this._userDefinedActions = userDefinedData;
    }

    // Load user-defined actions
    if (data && Array.isArray(data._userDefinedActions)) {
      this._userDefinedActions = data._userDefinedActions;
    }
  }

  /**
   * Override reset() for singleton pattern
   * Manually resets properties without creating a new instance
   */
  public async reset(): Promise<void> {
    // Reset all properties to default values
    this._favoriteActionIds = [];
    this._homePageActionIds = [];
    this._actionUsageStats = new Map();
    this._userDefinedActions = [];

    // Save the defaults to file
    await this.manualSave();

    // Notify listeners of changes
    StateManager.changed(this);
  }
}
