import { ArrowForward, Clear, Save } from '@mui/icons-material';
import { Box, ButtonGroup, IconButton, ToggleButton, Tooltip, Typography } from '@mui/material';
import { AxisCoordinateState, CoordinateDisplayType } from '../../data/AxisCoordinateState';
import { CNCPoint } from '../../data/CNCPoint';
import { CoordinateType } from '../../data/Common/CoordinateType';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { Machine } from '../../machine/Machine';
import { ActionBus } from '../../utils/actions/ActionBus';
import { CoordinateUtil } from '../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';
import { StateManager } from '../../utils/statemanager/StateManager';
import { NumberInput } from './NumberInput';

// Module-level state for machine mode timer
let machineTimerHandle: NodeJS.Timeout | null = null;
let machineTimerUpdateHandle: NodeJS.Timeout | null = null;

/**
 * Props for AxisCoordinateDisplay component
 */
interface AxisCoordinateDisplayProps {
    /** Array of axis names to display (e.g., ['X', 'Y', 'Z', 'A']) */
    axes?: string[];
    /** Whether to show Set/Go buttons (default: true) */
    showButtons?: boolean;
    /** Whether to show Set button (default: true) */
    showSetButton?: boolean;
    /** Whether to reserve space for buttons even when hidden (default: false) */
    reserveButtonSpace?: boolean;
    /** Width of the coordinate input (default: '150px') */
    inputWidth?: string;
    /** Font size for axis label (default: '1.5rem') */
    labelFontSize?: string;
    /** Font size for coordinate value (default: '2.5rem') */
    valueFontSize?: string;
    /** Button width (default: '80px') */
    buttonWidth?: string;
    /** Button height (default: '56px') */
    buttonHeight?: string;
    /** Gap between elements (default: 2) */
    gap?: number;
    /** Vertical gap between axes (default: 2) */
    axisGap?: number;
    /** Custom label prefix (default: axis name + ':') */
    getLabelText?: (axis: string) => string;
    /** Callback when coordinate changes (optional - uses CoordinateOperations by default) */
    onCoordinateChange?: (axis: string, value: number) => void;
    /** Callback when Set button clicked (optional - uses CoordinateOperations by default) */
    onSetWorkZero?: (axis: string) => void;
    /** Callback when Go button clicked (optional - uses CoordinateOperations by default) */
    onGoToPosition?: (axis: string) => void;
    /** Unique key for this instance (default: 'axis-coordinate-display') */
    instanceKey?: string;
    /** Whether to show the Fast/Slow jog speed toggle button (default: false) */
    showSpeedToggle?: boolean;
    /** Whether to show the Work/Machine coordinate type toggle button (default: false) */
    showCoordinateTypeToggle?: boolean;
}

/**
 * Reusable component for displaying and editing axis coordinates
 * Shows work coordinates with NumberInput controls and Set/Go buttons
 * 
 * Set button: Appears when work coordinate is not at zero - sets work zero to current position
 * Go button: Appears when user has entered a proposed position - moves to that position
 * 
 * @example
 * // Basic usage with X, Y, Z axes
 * <AxisCoordinateDisplay axes={['X', 'Y', 'Z']} />
 * 
 * @example
 * // Custom styling without buttons
 * <AxisCoordinateDisplay 
 *   axes={['X', 'Y']} 
 *   showButtons={false}
 *   inputWidth="150px"
 *   valueFontSize="2rem"
 * />
 */
export function AxisCoordinateDisplay({
    axes = ['X', 'Y', 'Z', 'A'],
    showButtons = true,
    showSetButton = true,
    reserveButtonSpace = false,
    inputWidth = '150px',
    labelFontSize = '1.5rem',
    valueFontSize = '2.5rem',
    buttonWidth = '80px',
    buttonHeight = '56px',
    gap = 2,
    axisGap = 2,
    getLabelText = (axis: string) => `${axis}:`,
    onCoordinateChange,
    onSetWorkZero,
    onGoToPosition,
    instanceKey = 'axis-coordinate-display',
    showSpeedToggle = false,
    showCoordinateTypeToggle = false,
}: AxisCoordinateDisplayProps): React.JSX.Element {
    const colors = ConfigurationDataColors.Instance;
    const machineState = MachineStateData.Instance;
    const axisState = AxisCoordinateState.Instance;

    const handleCoordinateChange = (axis: string, value: number) => {
        // This is called when user commits value (Enter/Tab/Blur)
        axisState.setUserValue(axis, value);
        if (onCoordinateChange) {
            onCoordinateChange(axis, value);
        }
    };

    const handleEditStart = (axis: string) => {
        // This is called when user starts typing
        axisState.startEditing(axis);
    };

    const getButtonType = (axis: string): 'none' | 'set' | 'go' => {
        if (!showButtons) return 'none';

        const state = axisState.getAxisState(axis);

        // If user has entered a value or is editing, show Go buttons
        if (state.userEnteredValue !== null || state.isUserEditing) {
            return 'go';
        }

        // Check if we should show Set button based on work coordinate value
        const currentMachinePos = ConfigurationState.Instance.currentMachinePoint;
        const workCoordinates = CoordinateUtil.toWorkZeroWithOffsets(currentMachinePos);

        // Get the work coordinate for the axis
        let workCoordinate: number;
        switch (axis.toUpperCase()) {
            case 'X':
                workCoordinate = workCoordinates.x;
                break;
            case 'Y':
                workCoordinate = workCoordinates.y;
                break;
            case 'Z':
                workCoordinate = workCoordinates.z;
                break;
            case 'A':
                workCoordinate = 0; // A-axis placeholder
                break;
            default:
                return 'none';
        }

        // If work coordinate is close to 0, don't show Set button
        const tolerance = 0.001;
        const isAtWorkZero = Math.abs(workCoordinate) < tolerance;

        return (isAtWorkZero || !showSetButton) ? 'none' : 'set';
    };

    const handleSetWorkZero = async (axis: string) => {
        if (onSetWorkZero) {
            onSetWorkZero(axis);
        } else {
            // Set work zero to current machine position for this axis
            const currentMachinePos = ConfigurationState.Instance.currentMachinePoint;
            const currentWorkZero = machineState.currentWorkZero;
            const currentWorkCoords = CoordinateUtil.toWorkZeroWithOffsets(currentMachinePos);

            // To make current tool tip position become 0, we need to adjust currentWorkZero
            // by the current work coordinate value
            // Formula: newWorkZero = currentWorkZero + currentWorkCoords
            let newWorkZero: CNCPoint;
            switch (axis.toUpperCase()) {
                case 'X':
                    newWorkZero = new CNCPoint(
                        currentWorkZero.x + currentWorkCoords.x,
                        currentWorkZero.y,
                        currentWorkZero.z,
                        CoordinateType.MachineZero
                    );
                    break;
                case 'Y':
                    newWorkZero = new CNCPoint(
                        currentWorkZero.x,
                        currentWorkZero.y + currentWorkCoords.y,
                        currentWorkZero.z,
                        CoordinateType.MachineZero
                    );
                    break;
                case 'Z':
                    newWorkZero = new CNCPoint(
                        currentWorkZero.x,
                        currentWorkZero.y,
                        currentWorkZero.z + currentWorkCoords.z,
                        CoordinateType.MachineZero
                    );
                    break;
                case 'A':
                    // A-axis placeholder - for now just keep current work zero
                    newWorkZero = currentWorkZero;
                    break;
                default:
                    newWorkZero = currentWorkZero;
            }

            // Update the machine state (updates local fixture data)
            machineState.currentWorkZero = newWorkZero;

            // Notify the server about the fixture point change
            try {
                await Machine.getInstance().movement.SetCurrentFixturePoint();
                // Note: Fixture auto-save is triggered by StateManager.propertyChanged in Fixture setters
            } catch (error) {
                UserMessageQueue.Instance.addMessage(`❌ Failed to update fixture on server: ${error}`);
            }
        }
        axisState.clearAxis(axis);
    };

    const handleGoToPosition = (axis: string) => {
        if (onGoToPosition) {
            onGoToPosition(axis);
        } else {
            // Create MoveAction using AxisCoordinateState method
            // ActionBus will automatically combine this with any existing MoveAction
            const moveAction = axisState.createMoveActionForAxis(axis);
            ActionBus.Instance.addAction(moveAction);
        }

        // Clear only the axis that was moved
        axisState.clearAxis(axis);
    };

    const handleClear = () => {
        axisState.clearAll();
    };

    const handleJogSpeedChange = async () => {
        try {
            const machine = Machine.getInstance();
            await machine.movement.SetFastJog(!ConfigurationState.Instance.jogFastMode);
        } catch (error) {
            console.error('Failed to set jog speed:', error);
        }
    };

    const handleCoordinateTypeChange = () => {
        const isCurrentlyWork = axisState.displayType === CoordinateDisplayType.Work;
        const newType = isCurrentlyWork ? CoordinateDisplayType.Machine : CoordinateDisplayType.Work;

        // Clear any existing timer
        if (machineTimerHandle) {
            clearTimeout(machineTimerHandle);
            machineTimerHandle = null;
        }
        if (machineTimerUpdateHandle) {
            clearInterval(machineTimerUpdateHandle);
            machineTimerUpdateHandle = null;
        }

        // If switching to Machine mode, start countdown timer
        if (isCurrentlyWork) {
            const duration = ConfigurationData.Instance.machineModeDuration * 1000; // Convert seconds to milliseconds
            axisState.machineModeStartTime = Date.now();

            // Update progress every 50ms for smooth animation
            machineTimerUpdateHandle = setInterval(() => {
                // Force re-render by notifying state change
                StateManager.propertyChanged(axisState, 'machineModeStartTime');
            }, 50);

            // Auto-switch back to Work mode after duration
            machineTimerHandle = setTimeout(() => {
                if (machineTimerUpdateHandle) {
                    clearInterval(machineTimerUpdateHandle);
                    machineTimerUpdateHandle = null;
                }
                machineTimerHandle = null;
                axisState.machineModeStartTime = null;
                axisState.displayType = CoordinateDisplayType.Work;
            }, duration);
        } else {
            axisState.machineModeStartTime = null;
        }

        axisState.displayType = newType;
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: axisGap }}>
            <ObserveMultiProperties
                key={instanceKey}
                listenTo={[
                    { object: machineState, properties: ['currentWorkZero', 'currentToolOffsets', 'currentToolNumber'] },
                    { object: ConfigurationState.Instance, properties: ['isHomed', 'proposedSpindlePosition', 'currentMachinePoint'] },
                    { object: axisState, properties: ['X', 'Y', 'Z', 'A'] }
                ]}
                control={() => {
                    return (
                        <>
                            {axes.map((axis) => {
                                const currentMachinePos = ConfigurationState.Instance.currentMachinePoint;
                                // eslint-disable-next-line @typescript-eslint/no-unused-vars
                                const workCoordinates = CoordinateUtil.toWorkZeroWithOffsets(currentMachinePos);

                                // Get proposed position if it exists
                                const proposedPos = ConfigurationState.Instance.proposedSpindlePosition;
                                // eslint-disable-next-line @typescript-eslint/no-unused-vars
                                const proposedWorkCoordinates = proposedPos ? CoordinateUtil.toWorkZeroWithOffsets(proposedPos) : null;

                                // let currentWorkValue: number;
                                // let proposedWorkValue: number | null = null;

                                switch (axis.toUpperCase()) {
                                    case 'X':
                                        // currentWorkValue = workCoordinates.x;
                                        // proposedWorkValue = proposedWorkCoordinates?.x ?? null;
                                        break;
                                    case 'Y':
                                        // currentWorkValue = workCoordinates.y;
                                        // proposedWorkValue = proposedWorkCoordinates?.y ?? null;
                                        break;
                                    case 'Z':
                                        // currentWorkValue = workCoordinates.z;
                                        // proposedWorkValue = proposedWorkCoordinates?.z || null;
                                        break;
                                    case 'A':
                                        // currentWorkValue = 0;
                                        // proposedWorkValue = null; // A-axis not implemented yet
                                        break;
                                    default:
                                        // currentWorkValue = 0;
                                        // proposedWorkValue = null;
                                        break;
                                }

                                const displayValue = axisState.getDisplayValue(axis);
                                const buttonType = getButtonType(axis);
                                const hasUserValue = axisState.hasUserValue(axis);

                                return (
                                    <Box key={axis} sx={{ display: 'flex', alignItems: 'center', gap }}>
                                        <Typography sx={{ minWidth: '40px', fontSize: labelFontSize, fontWeight: 'bold' }}>
                                            {getLabelText(axis)}
                                        </Typography>
                                        {ConfigurationState.Instance.isHomed ? (
                                            <NumberInput
                                                value={displayValue}
                                                onChange={(value) => handleCoordinateChange(axis, value)}
                                                onEditStart={() => handleEditStart(axis)}
                                                precision={3}
                                                allowNegative={true}
                                                allowPositive={true}
                                                allowFractions={true}
                                                showHelperText={false}
                                                beforeText={`${axisState.displayType === CoordinateDisplayType.Machine ? 'Machine' : 'Work'} coordinate ${axis} - position relative to ${axisState.displayType === CoordinateDisplayType.Machine ? 'machine zero' : 'work zero'}`}
                                                afterText="Press Enter/Tab to move, or use Set button to set work zero to current position."
                                                size="medium"
                                                variant="outlined"
                                                textColor={hasUserValue ? colors.successColor : undefined}
                                                sx={{
                                                    width: inputWidth,
                                                    '& .MuiOutlinedInput-input': {
                                                        fontFamily: 'monospace',
                                                        fontSize: valueFontSize,
                                                        fontWeight: 'bold',
                                                        padding: '12px 16px',
                                                        textAlign: 'right'
                                                    },
                                                    '& .MuiOutlinedInput-root': {
                                                        backgroundColor: axisState.displayType === CoordinateDisplayType.Machine
                                                            ? `${colors.primaryColor}15`
                                                            : colors.lightTextColor,
                                                        '& fieldset': {
                                                            borderWidth: '2px',
                                                            borderColor: axisState.displayType === CoordinateDisplayType.Machine ? colors.primaryColor : colors.borderColor,
                                                        },
                                                        '&:hover fieldset': {
                                                            borderColor: axisState.displayType === CoordinateDisplayType.Machine ? colors.primaryColor : colors.borderColor,
                                                        },
                                                        '&.Mui-focused fieldset': {
                                                            borderColor: axisState.displayType === CoordinateDisplayType.Machine ? colors.primaryColor : colors.borderColor,
                                                        }
                                                    }
                                                }}
                                            />
                                        ) : (
                                            <Typography
                                                sx={{
                                                    width: inputWidth,
                                                    fontFamily: 'monospace',
                                                    fontSize: '1.2rem',
                                                    fontWeight: 'bold',
                                                    padding: '12px 16px',
                                                    textAlign: 'right',
                                                    backgroundColor: colors.lightBackgroundColor,
                                                    border: `2px solid ${colors.borderColor}`,
                                                    borderRadius: '4px',
                                                    color: colors.borderColor,
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'flex-end',
                                                    lineHeight: 1,
                                                    whiteSpace: 'nowrap'
                                                }}
                                            >
                                                ---.--
                                            </Typography>
                                        )}

                                        {/* Button container - always rendered when reserveButtonSpace is true */}
                                        {ConfigurationState.Instance.isHomed && (showButtons || reserveButtonSpace) && (
                                            <Box sx={{ minWidth: reserveButtonSpace ? '180px' : 'auto', display: 'flex', alignItems: 'center', justifyContent: 'flex-start' }}>
                                                {buttonType === 'go' && (
                                                    <ButtonGroup variant="contained" sx={{ height: buttonHeight }}>
                                                        <Tooltip title="Go to position">
                                                            <IconButton
                                                                size="medium"
                                                                onClick={() => handleGoToPosition(axis)}
                                                                tabIndex={-1}
                                                                sx={{
                                                                    backgroundColor: colors.primaryColor,
                                                                    color: colors.lightTextColor,
                                                                    borderRadius: '4px 0 0 4px',
                                                                    '&:hover': {
                                                                        backgroundColor: colors.primaryColor,
                                                                        opacity: 0.9
                                                                    }
                                                                }}
                                                            >
                                                                <ArrowForward />
                                                            </IconButton>
                                                        </Tooltip>
                                                        <Tooltip title="Clear">
                                                            <IconButton
                                                                size="medium"
                                                                onClick={() => handleClear()}
                                                                tabIndex={-1}
                                                                sx={{
                                                                    backgroundColor: colors.secondaryColor,
                                                                    color: colors.lightTextColor,
                                                                    borderRadius: '0 4px 4px 0',
                                                                    '&:hover': {
                                                                        backgroundColor: colors.secondaryColor,
                                                                        opacity: 0.9
                                                                    }
                                                                }}
                                                            >
                                                                <Clear />
                                                            </IconButton>
                                                        </Tooltip>
                                                    </ButtonGroup>
                                                )}
                                                {buttonType === 'set' && (
                                                    <Tooltip title="Set work zero">
                                                        <IconButton
                                                            size="medium"
                                                            onClick={() => handleSetWorkZero(axis)}
                                                            tabIndex={-1}
                                                            sx={{
                                                                backgroundColor: colors.primaryColor,
                                                                color: colors.lightTextColor,
                                                                borderRadius: '4px',
                                                                '&:hover': {
                                                                    backgroundColor: colors.primaryColor,
                                                                    opacity: 0.9
                                                                }
                                                            }}
                                                        >
                                                            <Save />
                                                        </IconButton>
                                                    </Tooltip>
                                                )}
                                            </Box>
                                        )}
                                    </Box>
                                );
                            })}
                        </>
                    );
                }}
            />

            {/* Toggle Buttons */}
            {(showSpeedToggle || showCoordinateTypeToggle) && (
                <ObserveMultiProperties
                    key={`${instanceKey}-toggle-buttons`}
                    listenTo={[
                        { object: ConfigurationState.Instance, properties: ['jogFastMode'] },
                        { object: axisState, properties: ['displayType', 'machineModeStartTime'] }
                    ]}
                    control={() => {
                        const isFast = ConfigurationState.Instance.jogFastMode;
                        const isWork = axisState.displayType === CoordinateDisplayType.Work;

                        // Calculate progress percentage
                        let progressPercent = 0;
                        if (!isWork && axisState.machineModeStartTime) {
                            const elapsed = Date.now() - axisState.machineModeStartTime;
                            const duration = ConfigurationData.Instance.machineModeDuration * 1000; // Convert seconds to milliseconds
                            progressPercent = Math.min(100, (elapsed / duration) * 100);
                        }

                        return (
                            <Box
                                sx={{
                                    mt: 1,
                                    display: 'flex',
                                    gap: 1,
                                }}
                            >
                                {showSpeedToggle && (
                                    <Tooltip title={isFast ? 'Click to switch to Slow Jog' : 'Click to switch to Fast Jog'} arrow>
                                        <ToggleButton
                                            value="fast"
                                            selected={isFast}
                                            onChange={handleJogSpeedChange}
                                            sx={{
                                                minWidth: '60px',
                                                fontWeight: 'bold',
                                                fontSize: '0.75rem',
                                                padding: '4px 8px',
                                                backgroundColor: isFast ? colors.primaryColor : colors.secondaryColor,
                                                color: colors.lightTextColor,
                                                border: 'none',
                                                '&:hover': {
                                                    backgroundColor: isFast ? colors.primaryColor : colors.secondaryColor,
                                                    opacity: 0.85
                                                },
                                                '&.Mui-selected': {
                                                    backgroundColor: isFast ? colors.primaryColor : colors.secondaryColor,
                                                    color: colors.lightTextColor,
                                                    '&:hover': {
                                                        backgroundColor: isFast ? colors.primaryColor : colors.secondaryColor,
                                                        opacity: 0.85
                                                    }
                                                }
                                            }}
                                        >
                                            Speed: {isFast ? 'Fast' : 'Slow'}
                                        </ToggleButton>
                                    </Tooltip>
                                )}

                                {showCoordinateTypeToggle && (
                                    <Tooltip title={isWork ? 'Click to switch to Machine Coordinates' : 'Click to switch to Work Coordinates'} arrow>
                                        <Box sx={{ position: 'relative', display: 'inline-block' }}>
                                            <ToggleButton
                                                value="work"
                                                selected={isWork}
                                                onChange={handleCoordinateTypeChange}
                                                sx={{
                                                    minWidth: '70px',
                                                    fontWeight: 'bold',
                                                    fontSize: '0.75rem',
                                                    padding: '4px 8px',
                                                    backgroundColor: isWork ? colors.secondaryColor : colors.primaryColor,
                                                    color: colors.lightTextColor,
                                                    border: 'none',
                                                    position: 'relative',
                                                    overflow: 'hidden',
                                                    '&:hover': {
                                                        backgroundColor: isWork ? colors.secondaryColor : colors.primaryColor,
                                                        opacity: 0.85
                                                    },
                                                    '&.Mui-selected': {
                                                        backgroundColor: isWork ? colors.secondaryColor : colors.primaryColor,
                                                        color: colors.lightTextColor,
                                                        '&:hover': {
                                                            backgroundColor: isWork ? colors.secondaryColor : colors.primaryColor,
                                                            opacity: 0.85
                                                        }
                                                    }
                                                }}
                                            >
                                                {/* Progress overlay showing transition to Work mode color */}
                                                {!isWork && axisState.machineModeStartTime && (
                                                    <Box
                                                        sx={{
                                                            position: 'absolute',
                                                            top: 0,
                                                            left: 0,
                                                            height: '100%',
                                                            width: `${progressPercent}%`,
                                                            backgroundColor: colors.secondaryColor,
                                                            transition: 'width 50ms linear',
                                                            pointerEvents: 'none'
                                                        }}
                                                    />
                                                )}
                                                <span style={{ position: 'relative', zIndex: 1 }}>
                                                    Display: {isWork ? 'Work' : 'Machine'}
                                                </span>
                                            </ToggleButton>
                                        </Box>
                                    </Tooltip>
                                )}
                            </Box>
                        );
                    }}
                />
            )}
        </Box>
    );
}
