import { IStorable } from '../../common/IStorable';
import { StateManager } from '../../utils/statemanager';
import { DataUtilities } from '../../utils/storage/DataUtilities';

/**
 * Spindle configuration class
 * Maps to the SpindleConfiguration API model: maxSpeed, minSpeed, okDelay.
 */
export class SpindleConfig implements IStorable {
    private _maxSpeed: number | null = 24000;
    private _minSpeed: number | null = 3000;
    private _okDelay: number | null = 0;

    public get maxSpeed(): number | null { return this._maxSpeed; }
    public set maxSpeed(value: number | null) { this._maxSpeed = value; StateManager.propertyChanged(this, 'maxSpeed'); }

    public get minSpeed(): number | null { return this._minSpeed; }
    public set minSpeed(value: number | null) { this._minSpeed = value; StateManager.propertyChanged(this, 'minSpeed'); }

    public get okDelay(): number | null { return this._okDelay; }
    public set okDelay(value: number | null) { this._okDelay = value; StateManager.propertyChanged(this, 'okDelay'); }

    // IStorable implementation
    public toJSON(): object {
        return DataUtilities.getStorageData(this);
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}
