import StopIcon from '@mui/icons-material/Stop';
import { Box, Button, LinearProgress, List, ListItem, ListItemText, Typography } from '@mui/material';
import React from 'react';
import { ToolLibrary } from '../../../../data/Common/ToolLibrary';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { MeasureAllToolsWizard } from '../MeasureAllToolsWizard';

export class MeasuringStep extends WizardStep {
    constructor(wizard: MeasureAllToolsWizard, priorStep: WizardStep | null = null) {
        super(wizard, priorStep);
    }

    getTitle(): string {
        return 'Measure All Tools - Measuring';
    }

    nextStep(): WizardStep | null {
        return null; // Final step
    }

    backStep(): WizardStep | null {
        return null; // Can't go back during measurement
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="measuring-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <MeasuringStepComponent step={this} />}
            />
        );
    }
}

interface MeasuringStepComponentProps {
    step: MeasuringStep;
}

function MeasuringStepComponent({ step }: MeasuringStepComponentProps) {
    const colors = ConfigurationDataColors.Instance;
    const toolLibrary = ToolLibrary.Instance;
    const wizard = step.wizard as MeasureAllToolsWizard;
    const { selectedTools, isRunning, currentToolIndex, completedTools, failedTools } = wizard.state;

    const [isCancelling, setIsCancelling] = React.useState(false);

    const startMeasuring = React.useCallback(async () => {
        try {
            wizard.state = { ...wizard.state, isRunning: true, currentToolIndex: 0 };
            StateManager.propertyChanged(wizard, 'state');

            const machine = Machine.getInstance();

            for (let i = 0; i < selectedTools.length; i++) {
                if (isCancelling) {
                    break;
                }

                const toolNumber = selectedTools[i];

                wizard.state = { ...wizard.state, currentToolIndex: i };
                StateManager.propertyChanged(wizard, 'state');

                try {
                    // Load tool (which will measure it)
                    await machine.system.loadTool(toolNumber);

                    wizard.state = {
                        ...wizard.state,
                        completedTools: [...wizard.state.completedTools, toolNumber]
                    };
                    StateManager.propertyChanged(wizard, 'state');

                } catch (error) {
                    // Check if this was a cancellation (user clicked cancel in the operation dialog)
                    const isCancellation = error instanceof Error && error.message.startsWith('Operation canceled:');

                    if (isCancellation) {
                        UserMessageQueue.Instance.addMessage('⚠ Tool measurement cancelled');
                        break; // Exit the loop - don't continue measuring remaining tools
                    }

                    // Regular error - mark as failed and continue to next tool
                    Logger.Instance.logError(LogCategory.System, `Failed to measure tool ${toolNumber}:`, error);
                    wizard.state = {
                        ...wizard.state,
                        failedTools: [...wizard.state.failedTools, toolNumber]
                    };
                    StateManager.propertyChanged(wizard, 'state');
                }
            }

            wizard.state = { ...wizard.state, isRunning: false };
            StateManager.propertyChanged(wizard, 'state');

            const totalCompleted = wizard.state.completedTools.length;
            const totalFailed = wizard.state.failedTools.length;

            if (totalFailed === 0) {
                UserMessageQueue.Instance.addMessage(`✓ Successfully measured all ${totalCompleted} tools`);
            } else {
                UserMessageQueue.Instance.addMessage(`⚠ Measured ${totalCompleted} tools, ${totalFailed} failed`);
            }

        } catch (error) {
            wizard.state = { ...wizard.state, isRunning: false };
            StateManager.propertyChanged(wizard, 'state');
            Logger.Instance.logError(LogCategory.System, 'Tool measurement failed:', error);
            UserMessageQueue.Instance.addMessage('❌ Tool measurement failed');
        }
    }, [wizard, selectedTools, isCancelling]);

    // Start measuring when component mounts
    React.useEffect(() => {
        if (!isRunning && completedTools.length === 0 && failedTools.length === 0) {
            startMeasuring();
        }
    }, [isRunning, completedTools.length, failedTools.length, startMeasuring]);

    const handleCancel = () => {
        setIsCancelling(true);
        wizard.state = { ...wizard.state, isRunning: false };
        StateManager.propertyChanged(wizard, 'state');
        UserMessageQueue.Instance.addMessage('⚠ Tool measurement cancelled');
        wizard.cancelWizard();
    };

    const handleClose = () => {
        wizard.completeWizard();
    };

    const currentTool = selectedTools[currentToolIndex];
    const currentToolInfo = currentTool ? toolLibrary.getToolByNumber(currentTool) : null;
    const progress = selectedTools.length > 0 ? ((completedTools.length + failedTools.length) / selectedTools.length) * 100 : 0;

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2, minHeight: 0 }}>
                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    {isRunning ? 'Measuring tools...' : 'Measurement complete'}
                </Typography>

                {isRunning && currentToolInfo && (
                    <Box sx={{
                        p: 2,
                        border: `1px solid ${colors.borderColor}`,
                        borderRadius: 1,
                        backgroundColor: colors.lightBackgroundColor
                    }}>
                        <Typography variant="body1" sx={{ color: colors.darkTextColor, fontWeight: 600 }}>
                            Currently Measuring:
                        </Typography>
                        <Typography variant="body2" sx={{ color: colors.mutedTextColor, mt: 1 }}>
                            T{currentTool} - {currentToolInfo.displayName}
                        </Typography>
                    </Box>
                )}

                <Box sx={{ mt: 2 }}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                        <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                            Progress: {completedTools.length + failedTools.length} / {selectedTools.length}
                        </Typography>
                        <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                            {progress.toFixed(0)}%
                        </Typography>
                    </Box>
                    <LinearProgress variant="determinate" value={progress} sx={{ height: 8, borderRadius: 1 }} />
                </Box>

                <Box sx={{
                    flex: 1,
                    border: `1px solid ${colors.borderColor}`,
                    borderRadius: 1,
                    overflow: 'hidden',
                    display: 'flex',
                    flexDirection: 'column'
                }}>
                    <Box sx={{ p: 2, borderBottom: `1px solid ${colors.borderColor}`, backgroundColor: colors.lightBackgroundColor }}>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>
                            Tool Status
                        </Typography>
                    </Box>
                    <List sx={{ flex: 1, overflow: 'auto', p: 0 }}>
                        {selectedTools.map((toolNumber) => {
                            const tool = toolLibrary.getToolByNumber(toolNumber);
                            const isCompleted = completedTools.includes(toolNumber);
                            const isFailed = failedTools.includes(toolNumber);
                            const isCurrent = isRunning && toolNumber === currentTool;

                            let status = '';
                            let statusColor = colors.mutedTextColor;

                            if (isCompleted) {
                                status = '✓ Complete';
                                statusColor = colors.successColor;
                            } else if (isFailed) {
                                status = '✗ Failed';
                                statusColor = colors.errorColor;
                            } else if (isCurrent) {
                                status = 'Measuring...';
                                statusColor = colors.primaryColor;
                            } else {
                                status = 'Pending';
                            }

                            return (
                                <ListItem
                                    key={toolNumber}
                                    sx={{
                                        borderBottom: `1px solid ${colors.borderColor}`,
                                        backgroundColor: isCurrent ? colors.hoverColor : 'transparent'
                                    }}
                                >
                                    <ListItemText
                                        primary={`T${toolNumber} - ${tool?.displayName || 'Unknown'}`}
                                        secondary={status}
                                        secondaryTypographyProps={{
                                            sx: { color: statusColor, fontWeight: 500 }
                                        }}
                                    />
                                </ListItem>
                            );
                        })}
                    </List>
                </Box>
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 2, pt: 2, borderTop: `1px solid ${colors.borderColor}` }}>
                {isRunning ? (
                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', width: '100%' }}>
                        <Button
                            variant="contained"
                            color="error"
                            startIcon={<StopIcon />}
                            onClick={handleCancel}
                        >
                            Cancel
                        </Button>
                    </Box>
                ) : (
                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', width: '100%' }}>
                        <Button
                            variant="contained"
                            onClick={handleClose}
                        >
                            Close
                        </Button>
                    </Box>
                )}
            </Box>
        </Box>
    );
}
