import StopIcon from '@mui/icons-material/Stop';
import { Box, Button, Grid, LinearProgress, Typography } from '@mui/material';
import React from 'react';
import { ToolLibrary } from '../../../../data/Common/ToolLibrary';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineData } from '../../../../data/Machine/MachineData';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { SurfaceSpoilboardWizard } from '../SurfaceSpoilboardWizard';

export class SurfacingStep extends WizardStep {
    constructor(wizard: SurfaceSpoilboardWizard, priorStep: WizardStep | null = null) {
        super(wizard, priorStep);
    }

    getTitle(): string {
        return 'Surface Spoilboard - Surfacing';
    }

    nextStep(): WizardStep | null {
        return null; // Final step
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="surfacing-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <SurfacingStepComponent step={this} />}
            />
        );
    }
}

interface SurfacingStepComponentProps {
    step: SurfacingStep;
}

function SurfacingStepComponent({ step }: SurfacingStepComponentProps) {
    const colors = ConfigurationDataColors.Instance;
    const machineData = MachineData.Instance;
    const toolLibrary = ToolLibrary.Instance;
    const wizard = step.wizard as SurfaceSpoilboardWizard;
    const { isRunning, selectedToolNumber, spindleSpeed, stepover, amountToRemove } = wizard.state;

    const selectedTool = selectedToolNumber ? toolLibrary.getToolByNumber(selectedToolNumber) : null;

    const handleStart = async () => {
        try {
            wizard.state = { ...wizard.state, isRunning: true };
            StateManager.propertyChanged(wizard, 'state');


            // TODO: Generate and run G-code for surfacing
            // This will be implemented later
            // For now, just show a message
            UserMessageQueue.Instance.addMessage('⚠ G-code generation not yet implemented');

            // Simulate completion after a delay
            await new Promise(resolve => setTimeout(resolve, 2000));

            wizard.state = { ...wizard.state, isRunning: false };
            StateManager.propertyChanged(wizard, 'state');

            wizard.completeWizard();

        } catch (error) {
            wizard.state = { ...wizard.state, isRunning: false };
            StateManager.propertyChanged(wizard, 'state');
            UserMessageQueue.Instance.addMessage('❌ Surfacing failed: ' + (error instanceof Error ? error.message : String(error)));
            wizard.errorWizard(error instanceof Error ? error : new Error(String(error)));
        }
    };

    const handleStop = () => {
        // TODO: Stop the running G-code program
        wizard.state = { ...wizard.state, isRunning: false };
        StateManager.propertyChanged(wizard, 'state');
        wizard.cancelWizard();
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    Ready to surface the spoilboard.
                </Typography>

                <Box sx={{
                    border: `1px solid ${colors.borderColor}`,
                    borderRadius: 1,
                    p: 3,
                    backgroundColor: colors.lightBackgroundColor
                }}>
                    <Typography variant="h6" sx={{ color: colors.darkTextColor, mb: 2, fontWeight: 600 }}>
                        Parameters:
                    </Typography>
                    <Grid container spacing={2}>
                        <Grid item xs={12}>
                            <Typography variant="body2" sx={{ color: colors.mutedTextColor, fontSize: '0.875rem' }}>
                                Tool
                            </Typography>
                            <Typography variant="body1" sx={{ color: colors.darkTextColor, fontWeight: 500 }}>
                                {selectedTool ? `${selectedTool.toolNumber} - ${selectedTool.toolName}` : `Tool ${selectedToolNumber}`}
                            </Typography>
                        </Grid>
                        <Grid item xs={6}>
                            <Typography variant="body2" sx={{ color: colors.mutedTextColor, fontSize: '0.875rem' }}>
                                Spindle Speed
                            </Typography>
                            <Typography variant="body1" sx={{ color: colors.darkTextColor, fontWeight: 500 }}>
                                {spindleSpeed.toLocaleString()} RPM
                            </Typography>
                        </Grid>
                        <Grid item xs={6}>
                            <Typography variant="body2" sx={{ color: colors.mutedTextColor, fontSize: '0.875rem' }}>
                                Stepover
                            </Typography>
                            <Typography variant="body1" sx={{ color: colors.darkTextColor, fontWeight: 500 }}>
                                {stepover}" ({(stepover * 25.4).toFixed(2)} mm)
                            </Typography>
                        </Grid>
                        <Grid item xs={6}>
                            <Typography variant="body2" sx={{ color: colors.mutedTextColor, fontSize: '0.875rem' }}>
                                Amount to Remove
                            </Typography>
                            <Typography variant="body1" sx={{ color: colors.darkTextColor, fontWeight: 500 }}>
                                {amountToRemove}" ({(amountToRemove * 25.4).toFixed(2)} mm)
                            </Typography>
                        </Grid>
                        <Grid item xs={6}>
                            <Typography variant="body2" sx={{ color: colors.mutedTextColor, fontSize: '0.875rem' }}>
                                Area
                            </Typography>
                            <Typography variant="body1" sx={{ color: colors.darkTextColor, fontWeight: 500 }}>
                                {machineData.bedWidth.toFixed(2)}" × {machineData.bedLength.toFixed(2)}"
                            </Typography>
                        </Grid>
                    </Grid>
                </Box>

                {isRunning && (
                    <Box sx={{ mt: 2 }}>
                        <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 1 }}>
                            Surfacing in progress...
                        </Typography>
                        <LinearProgress />
                    </Box>
                )}
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 2, pt: 2, borderTop: `1px solid ${colors.borderColor}` }}>
                {!isRunning ? (
                    <>
                        <Button
                            variant="text"
                            onClick={() => wizard.goToPreviousStep()}
                        >
                            Back
                        </Button>
                        <Button
                            variant="contained"
                            onClick={handleStart}
                        >
                            Start Surfacing
                        </Button>
                    </>
                ) : (
                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', width: '100%' }}>
                        <Button
                            variant="contained"
                            color="error"
                            startIcon={<StopIcon />}
                            onClick={handleStop}
                        >
                            Stop
                        </Button>
                    </Box>
                )}
            </Box>
        </Box>
    );
}
