import { UserMessageQueue } from '../data/UserMessageQueue';
import { GCodeExecutionCallback } from '../machine/ICNCProgram';
import { Machine } from '../machine/Machine';
import { LogCategory, Logger } from './Logger';
import { RetryState } from './RetryState';
import { StateManager } from './statemanager/StateManager';

/**
 * Manages job execution retry logic with observable state
 * Handles the transition from queued jobs to single job execution model
 */
export class JobRetryManager {
    private static _instance: JobRetryManager;

    private _isRetrying: boolean = false;
    private _retryCount: number = 0;
    private _maxRetries: number = 20;
    private _retryIntervalMs: number = 500;

    private constructor() { }

    public static get Instance(): JobRetryManager {
        if (!JobRetryManager._instance) {
            JobRetryManager._instance = new JobRetryManager();
        }
        return JobRetryManager._instance;
    }

    public get isRetrying(): boolean {
        return this._isRetrying;
    }

    public set isRetrying(value: boolean) {
        if (this._isRetrying !== value) {
            this._isRetrying = value;
            StateManager.propertyChanged(this, 'isRetrying');
        }
    }

    public get retryCount(): number {
        return this._retryCount;
    }

    public set retryCount(value: number) {
        if (this._retryCount !== value) {
            this._retryCount = value;
            StateManager.propertyChanged(this, 'retryCount');
        }
    }

    public get maxRetries(): number {
        return this._maxRetries;
    }

    public get retryIntervalMs(): number {
        return this._retryIntervalMs;
    }

    /**
     * Execute G-code with automatic retry logic if another job is running
     * @param gCodeLines G-code lines to execute
     * @param description Description for logging/notifications
     * @param callback Optional callback for tracking execution progress
     * @param retryState Optional local retry state for UI tracking (if not provided, uses singleton state)
     * @returns Promise that resolves when job starts successfully
     * @throws Error if job cannot start after maximum retries
     */
    public async executeWithRetry(
        gCodeLines: string[],
        description: string = 'Job',
        callback?: GCodeExecutionCallback,
        retryState?: RetryState
    ): Promise<void> {
        // Use provided retry state or fall back to singleton state
        const state = retryState || this;
        
        state.isRetrying = true;
        state.retryCount = 0;

        try {
            for (let attempt = 0; attempt < this._maxRetries; attempt++) {
                state.retryCount = attempt + 1;

                try {
                    // Check if job is currently running
                    const isRunning = await Machine.getInstance().program.IsJobRunning();

                    if (!isRunning) {
                        // No job running, attempt to start
                        await Machine.getInstance().program.RunGCode(gCodeLines, true, undefined, callback);

                        // Success!
                        state.isRetrying = false;
                        state.retryCount = 0;
                        return;
                    } else {
                        // Job is running, wait and retry
                        if (attempt < this._maxRetries - 1) {
                            await this.delay(this._retryIntervalMs);
                        }
                    }
                } catch (error) {
                    // Check if error is "already running" error
                    const errorMsg = error instanceof Error ? error.message : String(error);
                    if (errorMsg.includes('already running') || errorMsg.includes('Job already running')) {
                        if (attempt < this._maxRetries - 1) {
                            await this.delay(this._retryIntervalMs);
                            continue;
                        }
                    } else {
                        // Different error, rethrow immediately
                        Logger.Instance.logError(LogCategory.System, `Failed to start ${description}:`, error);
                        throw error;
                    }
                }
            }

            // All retries exhausted
            state.isRetrying = false;
            state.retryCount = 0;
            const errorMsg = `Failed to start ${description}: Another job is running. Exhausted ${this._maxRetries} retry attempts over ${(this._maxRetries * this._retryIntervalMs) / 1000} seconds.`;
            Logger.Instance.logError(LogCategory.System, errorMsg);
            throw new Error(errorMsg);

        } catch (error) {
            state.isRetrying = false;
            state.retryCount = 0;
            throw error;
        }
    }

    /**
     * Execute G-code command with automatic retry logic
     * @param command Single G-code command to execute
     * @param description Description for logging/notifications
     * @returns Promise that resolves when command starts successfully
     * @throws Error if command cannot start after maximum retries
     */
    public async executeCommandWithRetry(
        command: string,
        description: string = 'Command'
    ): Promise<void> {
        this.isRetrying = true;
        this.retryCount = 0;

        try {
            for (let attempt = 0; attempt < this._maxRetries; attempt++) {
                this.retryCount = attempt + 1;

                try {
                    // Check if job is currently running
                    const isRunning = await Machine.getInstance().program.IsJobRunning();

                    if (!isRunning) {
                        // No job running, attempt to start
                        Logger.Instance.log(
                            LogCategory.System,
                            `Attempting to execute ${description} (attempt ${attempt + 1}/${this._maxRetries})`
                        );

                        await Machine.getInstance().program.RunGCodeCommand(command);

                        // Success!
                        Logger.Instance.log(LogCategory.System, `${description} executed successfully`);
                        this.isRetrying = false;
                        this.retryCount = 0;
                        return;
                    } else {
                        // Job is running, wait and retry
                        if (attempt < this._maxRetries - 1) {
                            Logger.Instance.log(
                                LogCategory.System,
                                `Job already running, waiting ${this._retryIntervalMs}ms before retry ${attempt + 1}/${this._maxRetries}`
                            );
                            await this.delay(this._retryIntervalMs);
                        }
                    }
                } catch (error) {
                    // Check if error is "already running" error
                    const errorMsg = error instanceof Error ? error.message : String(error);
                    if (errorMsg.includes('already running') || errorMsg.includes('Job already running')) {
                        if (attempt < this._maxRetries - 1) {
                            Logger.Instance.log(
                                LogCategory.System,
                                `Command execution rejected (already running), retry ${attempt + 1}/${this._maxRetries}`
                            );
                            await this.delay(this._retryIntervalMs);
                            continue;
                        }
                    } else {
                        // Different error, rethrow immediately
                        Logger.Instance.logError(LogCategory.System, `Failed to execute ${description}:`, error);
                        throw error;
                    }
                }
            }

            // All retries exhausted
            this.isRetrying = false;
            this.retryCount = 0;
            const errorMsg = `Failed to execute ${description}: Another job is running. Exhausted ${this._maxRetries} retry attempts over ${(this._maxRetries * this._retryIntervalMs) / 1000} seconds.`;
            Logger.Instance.logError(LogCategory.System, errorMsg);
            throw new Error(errorMsg);

        } catch (error) {
            this.isRetrying = false;
            this.retryCount = 0;
            throw error;
        }
    }

    /**
     * Helper method to delay execution
     */
    private delay(ms: number): Promise<void> {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    /**
     * Reset retry state (useful for cancellation)
     */
    public reset(): void {
        this.isRetrying = false;
        this.retryCount = 0;
    }
}

/**
 * Helper utility for code outside of dialogs
 * Automatically shows user notification on failure
 */
export async function executeJobWithRetryAndNotify(
    gCodeLines: string[],
    description: string = 'Job'
): Promise<boolean> {
    try {
        await JobRetryManager.Instance.executeWithRetry(gCodeLines, description);
        UserMessageQueue.Instance.addMessage(`✓ ${description} started successfully`);
        return true;
    } catch (error) {
        const errorMsg = error instanceof Error ? error.message : String(error);
        UserMessageQueue.Instance.addMessage(`❌ ${errorMsg}`);
        return false;
    }
}

/**
 * Helper utility for executing commands outside of dialogs
 * Automatically shows user notification on failure
 */
export async function executeCommandWithRetryAndNotify(
    command: string,
    description: string = 'Command'
): Promise<boolean> {
    try {
        await JobRetryManager.Instance.executeCommandWithRetry(command, description);
        UserMessageQueue.Instance.addMessage(`✓ ${description} executed successfully`);
        return true;
    } catch (error) {
        const errorMsg = error instanceof Error ? error.message : String(error);
        UserMessageQueue.Instance.addMessage(`❌ ${errorMsg}`);
        return false;
    }
}
